  $q4988${"topic":"technology","wordCount":107,"questionCount":5}$q4988$::jsonb,
  $q66007${"mode":"reading","level":"B1","format":"text","topic":"Technology","title":"The Tablet That Would Not Start","story":"Jules needed the tablet for a video call with his cousin. He pressed the button, but the screen stayed black. A small light showed the battery was empty. He plugged in the cable and waited. Nothing changed. Jules checked the wall socket and tried a different cable from the drawer. The screen lit up at once. He smiled and turned the brightness down to save power. Before the call he closed extra apps. His cousin Maya appeared and waved. They talked about school and a film they both liked. Near the end the battery warning returned. Jules told Maya he would call again after a full charge.","dialogue":[],"vocabulary":[{"word":"tablet","definition":"a flat computer you can hold"},{"word":"battery","definition":"the part that stores power"},{"word":"cable","definition":"a wire that connects a device"},{"word":"socket","definition":"a place in the wall for a plug"},{"word":"brightness","definition":"how strong the light of a screen is"},{"word":"apps","definition":"small programs on a device"}],"quiz":[{"question":"Why did the screen stay black at first?","options":["The battery was empty","The film would not play","Maya ended the call","The drawer was locked"],"correctAnswer":"The battery was empty","explanation":"A small light showed the battery was empty.","supportingSentence":"A small light showed the battery was empty.","skill":"detail"},{"question":"What did Jules try from the drawer?","options":["A paper map","A different cable","A glass of water","A second tablet"],"correctAnswer":"A different cable","explanation":"He tried a different cable from the drawer.","supportingSentence":"Jules checked the wall socket and tried a different cable from the drawer.","skill":"detail"},{"question":"Why did Jules lower the brightness?","options":["To save power","To open more apps","To end the call","To hide the screen"],"correctAnswer":"To save power","explanation":"He turned the brightness down to save power.","supportingSentence":"He smiled and turned the brightness down to save power.","skill":"detail"},{"question":"In this story, what is a socket?","options":["A pocket in a coat","A kind of video","A warning sound","A place in the wall for a plug"],"correctAnswer":"A place in the wall for a plug","explanation":"Jules checked the wall socket when the first cable did nothing.","supportingSentence":"Jules checked the wall socket and tried a different cable from the drawer.","skill":"vocabulary"},{"question":"Why did Jules plan to call Maya again later?","options":["The tablet needed a full charge","The screen was still black","Maya asked him to visit","He wanted a different film"],"correctAnswer":"The tablet needed a full charge","explanation":"He said he would call again after a full charge.","supportingSentence":"Jules told Maya he would call again after a full charge.","skill":"inference"}],"wordCount":107,"questionCount":5}$q66007$::jsonb,
  '72d4c89aa32b07e893543cdd065ea304bf63d5e14fefdd88957adef1ea3ff381',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f0cb51cc-4b10-4918-a9f9-d2e8ef8a7b71'::uuid,
  'reading',
  'B1',
  'text',
  $q4630${"topic":"science","wordCount":103,"questionCount":5}$q4630$::jsonb,
  $q67720${"mode":"reading","level":"B1","format":"text","topic":"Science","title":"The Jar of Rainwater","story":"Teacher Adeyemi asked the class to measure rain for one week. Priya put a clear jar in the school garden each morning. She marked the water level with a pen before lunch. On Monday the jar held only a thin line. On Wednesday a storm filled it much higher. Priya wrote the results in a notebook and drew a simple chart. She noticed the jar was lower on Thursday. A classmate named Ben said birds might have drunk from it. Priya covered the jar with a loose net that still let rain in. On Friday the level matched the puddles on the path.","dialogue":[],"vocabulary":[{"word":"measure","definition":"to find the size or amount of something"},{"word":"jar","definition":"a glass or plastic container"},{"word":"level","definition":"the height reached by a liquid"},{"word":"storm","definition":"strong rain and wind"},{"word":"chart","definition":"a simple drawing that shows results"},{"word":"net","definition":"material with holes, used as a cover"}],"quiz":[{"question":"Where did Priya place the jar each morning?","options":["On the classroom floor","Under her bed","In the school garden","In the kitchen sink"],"correctAnswer":"In the school garden","explanation":"She put a clear jar in the school garden each morning.","supportingSentence":"Priya put a clear jar in the school garden each morning.","skill":"detail"},{"question":"What happened to the jar on Wednesday?","options":["Priya lost the pen","It stayed empty","A storm filled it much higher","The class stopped the test"],"correctAnswer":"A storm filled it much higher","explanation":"On Wednesday a storm filled the jar much higher.","supportingSentence":"On Wednesday a storm filled it much higher.","skill":"detail"},{"question":"What idea did Ben give for the lower water?","options":["The pen had leaked","The chart was wrong","Another storm was coming","Birds might have drunk from the jar"],"correctAnswer":"Birds might have drunk from the jar","explanation":"Ben said birds might have drunk from the jar.","supportingSentence":"A classmate named Ben said birds might have drunk from it.","skill":"detail"},{"question":"In this story, what does level mean?","options":["The height of the water","A school test score","A kind of storm","A floor in a building"],"correctAnswer":"The height of the water","explanation":"Priya marked the water level, which means how high the water stood.","supportingSentence":"She marked the water level with a pen before lunch.","skill":"vocabulary"},{"question":"Why did Priya cover the jar?","options":["To move the jar indoors","To hide the chart","To stop birds drinking the water","To make the storm stronger"],"correctAnswer":"To stop birds drinking the water","explanation":"Ben thought birds had drunk from it, and Priya then covered the jar.","supportingSentence":"A classmate named Ben said birds might have drunk from it.","skill":"inference"}],"wordCount":103,"questionCount":5}$q67720$::jsonb,
  'f0cb51cc4b10791829f9d2e8ef8a7b7198cf8fde4aaa3680461e15e4946aa945',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '482d3e86-13e2-49f9-a646-60ba86113537'::uuid,
  'reading',
  'B1',
  'text',
  $q5485${"topic":"economy_finance","wordCount":107,"questionCount":5}$q5485$::jsonb,
  $q71007${"mode":"reading","level":"B1","format":"text","topic":"Economy / Finance","title":"The Receipt in the Pocket","story":"Lila bought a blue jumper at the Saturday market. At home she saw a hole near the sleeve. She still had the receipt and the paper tag. On Monday she took the jumper back to the same stall. The seller, Owen, checked the receipt and the hole. He said he could not mend it that day. He offered a refund or a different colour. Lila chose the refund because she needed the money for the bus that week. Owen counted the notes into her hand. Lila checked the amount against the receipt before she walked away. She kept the receipt until the money was safe at home.","dialogue":[],"vocabulary":[{"word":"jumper","definition":"a warm knitted top"},{"word":"receipt","definition":"paper that shows what you paid"},{"word":"stall","definition":"a small shop table at a market"},{"word":"mend","definition":"to repair something that is damaged"},{"word":"refund","definition":"money given back after a return"},{"word":"notes","definition":"paper money"}],"quiz":[{"question":"What was wrong with the jumper?","options":["A missing receipt","A broken zip","A hole near the sleeve","The wrong colour"],"correctAnswer":"A hole near the sleeve","explanation":"At home she saw a hole near the sleeve.","supportingSentence":"At home she saw a hole near the sleeve.","skill":"detail"},{"question":"What two choices did Owen offer?","options":["A free bus ticket or a hat","A new stall or a loan","Soup or a paper tag","A refund or a different colour"],"correctAnswer":"A refund or a different colour","explanation":"He offered a refund or a different colour.","supportingSentence":"He offered a refund or a different colour.","skill":"detail"},{"question":"Why did Lila choose the money back?","options":["She needed it for the bus that week","Owen asked her to leave","She disliked every other colour","The receipt was blank"],"correctAnswer":"She needed it for the bus that week","explanation":"She chose the refund because she needed the money for the bus that week.","supportingSentence":"Lila chose the refund because she needed the money for the bus that week.","skill":"detail"},{"question":"In this story, what is a refund?","options":["A hole in a sleeve","Money given back after a return","A blue paper tag","A market table"],"correctAnswer":"Money given back after a return","explanation":"Owen offered a refund, and then he counted the notes into her hand.","supportingSentence":"He offered a refund or a different colour.","skill":"vocabulary"},{"question":"Why did Lila check the amount before she left?","options":["To mend the sleeve herself","To pay Owen again","To be sure the notes matched the receipt","To choose a new colour"],"correctAnswer":"To be sure the notes matched the receipt","explanation":"She checked the amount against the receipt, which showed what she had paid.","supportingSentence":"Lila checked the amount against the receipt before she walked away.","skill":"inference"}],"wordCount":107,"questionCount":5}$q71007$::jsonb,
  '482d3e8613e269f9564660ba86113537ba3bf72861800cc52628e572e984e7a7',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'cd6b8259-278d-4fb7-a0e0-0baf65fb702d'::uuid,
  'reading',
  'B1',
  'text',
  $q5487${"topic":"economy_finance","wordCount":109,"questionCount":5}$q5487$::jsonb,
  $q64770${"mode":"reading","level":"B1","format":"text","topic":"Economy / Finance","title":"Two Prices for One Loaf","story":"The bakery on Mill Street raised the price of a loaf on Monday. Tomas usually bought bread there after work. He compared the new price with the supermarket down the hill. The supermarket loaf cost less, but it was a longer walk. Tomas checked his weekly budget in a notes app. He could still buy the bakery loaf if he skipped a magazine. He liked supporting the small shop, so he chose that. He paid with cash and put the coins from his change into a jar at home. His sister Ines said the supermarket was smarter. Tomas explained that the bakery used local flour and stayed open late.","dialogue":[],"vocabulary":[{"word":"bakery","definition":"a shop that makes and sells bread"},{"word":"loaf","definition":"bread baked in one piece"},{"word":"supermarket","definition":"a large shop that sells many kinds of food"},{"word":"budget","definition":"a plan for how to spend money"},{"word":"cash","definition":"money in notes or coins"},{"word":"flour","definition":"powder made from grain and used to make bread"}],"quiz":[{"question":"What did the bakery do to the loaf price on Monday?","options":["Raised it","Dropped it to nothing","Hid it from Tomas","Made it the same as a magazine"],"correctAnswer":"Raised it","explanation":"The bakery raised the price of a loaf on Monday.","supportingSentence":"The bakery on Mill Street raised the price of a loaf on Monday.","skill":"detail"},{"question":"Which loaf cost less?","options":["The bakery loaf","The jar of coins","The supermarket loaf","The magazine"],"correctAnswer":"The supermarket loaf","explanation":"The supermarket loaf cost less.","supportingSentence":"The supermarket loaf cost less, but it was a longer walk.","skill":"detail"},{"question":"What did Tomas say the bakery used?","options":["Local flour","Magazine paper","Supermarket boxes","Frozen fruit"],"correctAnswer":"Local flour","explanation":"He explained that the bakery used local flour.","supportingSentence":"Tomas explained that the bakery used local flour and stayed open late.","skill":"detail"},{"question":"In this story, what is a budget?","options":["A type of bread","A jar for coins","A long walk downhill","A plan for spending money"],"correctAnswer":"A plan for spending money","explanation":"Tomas checked his weekly budget before he decided what he could buy.","supportingSentence":"Tomas checked his weekly budget in a notes app.","skill":"vocabulary"},{"question":"Why did Tomas still choose the bakery?","options":["He wanted to support the small shop","Ines told him to go there","The supermarket cost more","He had no cash that day"],"correctAnswer":"He wanted to support the small shop","explanation":"He liked supporting the small shop, so he chose the bakery.","supportingSentence":"He liked supporting the small shop, so he chose that.","skill":"inference"}],"wordCount":109,"questionCount":5}$q64770$::jsonb,
  'cd6b8259278d5fb770e00baf65fb702dfac5e486dca16f0d70ea41e1e2865d8c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'a67a13b3-c01a-4f59-ab15-fc1cc687cecc'::uuid,
  'reading',
  'B1',
  'text',
  $q4700${"topic":"mystery","wordCount":106,"questionCount":5}$q4700$::jsonb,
  $q57366${"mode":"reading","level":"B1","format":"text","topic":"Mystery","title":"The Key on the Library Steps","story":"After closing, the librarian found a brass key on the front steps. It did not fit the main door or the office. She placed it in a labelled box and wrote the time. The next morning Caleb asked about a key with a green tag. The tag was missing, but the shape matched his drawing. Caleb said he had used it for the music room cupboard. The librarian walked with him to check. The key opened the cupboard at once. Inside, his flute case was safe. Caleb thanked her and tied a new tag on the ring. The librarian added a line to the lost-property book.","dialogue":[],"vocabulary":[{"word":"librarian","definition":"a person who looks after a library"},{"word":"brass","definition":"a yellow-brown metal"},{"word":"labelled","definition":"marked with a note that says what something is"},{"word":"cupboard","definition":"a cabinet with a door for storing things"},{"word":"flute","definition":"a musical instrument you play by blowing"},{"word":"tag","definition":"a small label tied to an object"}],"quiz":[{"question":"Where did the librarian find the key?","options":["On the front steps","On the office desk","Inside the flute case","In the music room"],"correctAnswer":"On the front steps","explanation":"She found a brass key on the front steps.","supportingSentence":"After closing, the librarian found a brass key on the front steps.","skill":"detail"},{"question":"What did the key open when they checked?","options":["The main door","The labelled box","The office door","The cupboard"],"correctAnswer":"The cupboard","explanation":"The key opened the cupboard at once.","supportingSentence":"The key opened the cupboard at once.","skill":"detail"},{"question":"What was safe inside the cupboard?","options":["His flute case","A green tag","The office money","A lost library book"],"correctAnswer":"His flute case","explanation":"Inside, his flute case was safe.","supportingSentence":"Inside, his flute case was safe.","skill":"detail"},{"question":"In this story, what does brass mean?","options":["A kind of music","A green paper label","A yellow-brown metal","A library job"],"correctAnswer":"A yellow-brown metal","explanation":"The key is described as brass, which is the metal it is made of.","supportingSentence":"After closing, the librarian found a brass key on the front steps.","skill":"vocabulary"},{"question":"Why did they go to check the cupboard?","options":["The key shape matched Caleb's drawing","The green tag was still on it","The key fit the main door","Caleb worked in the office"],"correctAnswer":"The key shape matched Caleb's drawing","explanation":"The shape matched his drawing of the key he used for that cupboard.","supportingSentence":"The tag was missing, but the shape matched his drawing.","skill":"inference"}],"wordCount":106,"questionCount":5}$q57366$::jsonb,
  'a67a13b3c01a1f59cb15fc1cc687cecce8caa285097d53a18e7729651ea0a7f4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '24fa4283-72e9-451e-a5c1-708ac8a3eba3'::uuid,
  'reading',
  'B1',
  'text',
  $q4702${"topic":"mystery","wordCount":108,"questionCount":5}$q4702$::jsonb,
  $q52827${"mode":"reading","level":"B1","format":"text","topic":"Mystery","title":"Lights in the Empty Classroom","story":"The caretaker, Rosa, locked the science room at six. An hour later she saw light under the door. She had the only key on her belt. Rosa opened the door slowly and found nobody inside. The lamp on the side bench was on. A window was open a little, and the blind was moving. She turned the lamp off and checked the cupboards. Nothing was missing. Then she noticed a timer plug behind a plant tray. The lamp was set to switch on at seven for a bean experiment. A note from the teacher explained the timer. Rosa closed the window and left the timer as it was.","dialogue":[],"vocabulary":[{"word":"caretaker","definition":"a person who looks after a building"},{"word":"lamp","definition":"a light that can be switched on"},{"word":"blind","definition":"a cover for a window"},{"word":"cupboards","definition":"cabinets used for storing things"},{"word":"timer","definition":"a device that turns something on at a set time"},{"word":"experiment","definition":"a test done to learn something"}],"quiz":[{"question":"What did Rosa see under the door an hour later?","options":["Smoke","A light","A pool of water","A lost key"],"correctAnswer":"A light","explanation":"She saw light under the door.","supportingSentence":"An hour later she saw light under the door.","skill":"detail"},{"question":"Who did Rosa find in the science room?","options":["A student","The teacher","Nobody","Two visitors"],"correctAnswer":"Nobody","explanation":"She opened the door and found nobody inside.","supportingSentence":"Rosa opened the door slowly and found nobody inside.","skill":"detail"},{"question":"When was the lamp set to come on?","options":["At six","At noon","At midnight","At seven"],"correctAnswer":"At seven","explanation":"The lamp was set to switch on at seven.","supportingSentence":"The lamp was set to switch on at seven for a bean experiment.","skill":"detail"},{"question":"In this story, what is a caretaker?","options":["A person who looks after the building","A plant experiment","A type of lamp","The science teacher"],"correctAnswer":"A person who looks after the building","explanation":"Rosa is the caretaker, and she locks and checks the room.","supportingSentence":"The caretaker, Rosa, locked the science room at six.","skill":"vocabulary"},{"question":"Why was the lamp on after Rosa had locked the room?","options":["Rosa left it on at six","A timer turned it on for an experiment","Someone broke the lock","The blind started the lamp"],"correctAnswer":"A timer turned it on for an experiment","explanation":"The lamp was set to switch on at seven for a bean experiment.","supportingSentence":"The lamp was set to switch on at seven for a bean experiment.","skill":"inference"}],"wordCount":108,"questionCount":5}$q52827$::jsonb,
  '24fa428372e9051ef5c1708ac8a3eba3fff8ed30531cb51c691fb1b6a3897f2c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'bf1d2214-4d9a-40fa-a5c4-1c8b7fa87222'::uuid,
  'reading',
  'B1',
  'text',
  $q4878${"topic":"adventure","wordCount":107,"questionCount":5}$q4878$::jsonb,
  $q49030${"mode":"reading","level":"B1","format":"text","topic":"Adventure","title":"The Rope across the Stream","story":"Nia and her uncle followed red markers up the valley. The path ended at a fast stream. A rope was tied between two trees for walkers to hold. Nia tested the first stone with her boot. It felt firm. She crossed slowly, one hand on the rope, and kept her eyes on the far bank. Her uncle came next with the packs. Halfway across he slipped, but the rope held him. They reached a dry rock and laughed with relief. On the other side the markers led into pine trees. Nia checked the map and saw the hut was close. They walked on before the light faded.","dialogue":[],"vocabulary":[{"word":"markers","definition":"signs that show the way"},{"word":"stream","definition":"a small fast river"},{"word":"rope","definition":"a strong thick cord"},{"word":"slipped","definition":"lost footing and started to fall"},{"word":"relief","definition":"a glad feeling after a worry ends"},{"word":"hut","definition":"a small simple shelter"}],"quiz":[{"question":"Why was a rope tied between the trees?","options":["For walkers to hold","To keep the packs shut","To mark the pine trees","To pull the hut door"],"correctAnswer":"For walkers to hold","explanation":"The rope was tied there for walkers to hold.","supportingSentence":"A rope was tied between two trees for walkers to hold.","skill":"detail"},{"question":"What happened to Nia's uncle halfway across?","options":["He lost the map","He slipped","He cut the rope","He turned back"],"correctAnswer":"He slipped","explanation":"Halfway across he slipped, but the rope held him.","supportingSentence":"Halfway across he slipped, but the rope held him.","skill":"detail"},{"question":"What did the map show about the hut?","options":["It was closed","It was behind them","It was close","It was across the sea"],"correctAnswer":"It was close","explanation":"Nia saw that the hut was close.","supportingSentence":"Nia checked the map and saw the hut was close.","skill":"detail"},{"question":"In this story, what does relief mean?","options":["A fast stream","A heavy pack","A place on a map","A glad feeling after a worry"],"correctAnswer":"A glad feeling after a worry","explanation":"They laughed with relief after the dangerous crossing was over.","supportingSentence":"They reached a dry rock and laughed with relief.","skill":"vocabulary"},{"question":"Why did Nia test the first stone with her boot?","options":["To see if it was firm enough to step on","To wash mud off the boot","To mark the tree","To call her uncle back"],"correctAnswer":"To see if it was firm enough to step on","explanation":"She tested the stone, and it felt firm, before she crossed.","supportingSentence":"It felt firm.","skill":"inference"}],"wordCount":107,"questionCount":5}$q49030$::jsonb,
  'bf1d22144d9a20fa25c41c8b7fa8722217e12f88fee0a1d7fb60567401750588',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '2ea82a42-4af4-4509-ad89-fdf5937c7c07'::uuid,
  'reading',
  'B1',
  'text',
  $q4880${"topic":"adventure","wordCount":109,"questionCount":5}$q4880$::jsonb,
  $q69289${"mode":"reading","level":"B1","format":"text","topic":"Adventure","title":"Camp before the Ridge","story":"The group left the road at dawn and climbed toward a high ridge. Malik carried the tent, and Sofia carried the food bag. Clouds sat on the ridge, so they stopped early in a flat hollow. They put the tent up between two rocks that blocked the wind. Sofia boiled water for soup and shared bread. A ranger had told them not to cross the ridge in fog. Malik wanted to push on, but the cloud was too thick. They agreed to wait until morning. During the night the wind pulled at the tent, yet the ropes held. At sunrise the ridge was clear. They started the last climb.","dialogue":[],"vocabulary":[{"word":"ridge","definition":"the long high top of a hill"},{"word":"tent","definition":"a cloth shelter you can put up and take down"},{"word":"hollow","definition":"a lower flat place in the land"},{"word":"ranger","definition":"a person who looks after a wild area"},{"word":"fog","definition":"thick cloud near the ground that is hard to see through"},{"word":"sunrise","definition":"the time when the sun first appears"}],"quiz":[{"question":"Why did the group stop before they reached the top?","options":["The tent was torn","Clouds sat on the ridge","The road was closed","Sofia lost the food"],"correctAnswer":"Clouds sat on the ridge","explanation":"Clouds sat on the ridge, so they stopped early.","supportingSentence":"Clouds sat on the ridge, so they stopped early in a flat hollow.","skill":"detail"},{"question":"What warning had the ranger given?","options":["Not to cross the ridge in fog","To leave the tent behind","To climb all night","To stay on the road"],"correctAnswer":"Not to cross the ridge in fog","explanation":"A ranger had told them not to cross the ridge in fog.","supportingSentence":"A ranger had told them not to cross the ridge in fog.","skill":"detail"},{"question":"What was the ridge like at sunrise?","options":["It was blocked by rocks","It was too dark to see","It was still covered in fog","It was clear"],"correctAnswer":"It was clear","explanation":"At sunrise the ridge was clear.","supportingSentence":"At sunrise the ridge was clear.","skill":"detail"},{"question":"In this story, what is a hollow?","options":["A hole in the tent","A kind of thick cloud","A lower flat place in the land","An empty water bottle"],"correctAnswer":"A lower flat place in the land","explanation":"They stopped in a flat hollow, a lower place under the ridge.","supportingSentence":"Clouds sat on the ridge, so they stopped early in a flat hollow.","skill":"vocabulary"},{"question":"Why did Malik not keep climbing that evening?","options":["The ropes had already snapped","The cloud was too thick","Sunrise had not been clear all week","Sofia needed a shop"],"correctAnswer":"The cloud was too thick","explanation":"He wanted to push on, but the cloud was too thick.","supportingSentence":"Malik wanted to push on, but the cloud was too thick.","skill":"inference"}],"wordCount":109,"questionCount":5}$q69289$::jsonb,
  '2ea82a424af4a5095d89fdf5937c7c07d31fd5b01b1f5bf162fc9f8f24f2f7ed',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '2b0d3d54-262b-4b32-a6e8-5114ec5c4e12'::uuid,
  'reading',
  'B1',
  'text',
  $q4656${"topic":"fantasy","wordCount":110,"questionCount":5}$q4656$::jsonb,
  $q60963${"mode":"reading","level":"B1","format":"text","topic":"Fantasy","title":"The Gate behind the Ivy","story":"In the town of Pell, ivy covered a stone gate that nobody opened. One evening Tamsin saw a silver moth land on the lock. The gate swung in without a sound. Beyond it was a garden under a sky full of stars. Flowers glowed when Tamsin stepped near them. A hare with a bell on its neck led her to a pool. The water showed her street, but the moon there was green. Tamsin filled a cup and the picture faded. The hare nodded toward the gate. She understood she could visit, not stay. She stepped back through the ivy. In the morning a garden petal was in her pocket.","dialogue":[],"vocabulary":[{"word":"ivy","definition":"a climbing plant that covers walls"},{"word":"moth","definition":"a flying insect that is active at night"},{"word":"glowed","definition":"gave off a soft light"},{"word":"hare","definition":"a fast wild animal with long ears"},{"word":"faded","definition":"grew weak until it disappeared"},{"word":"petal","definition":"one coloured part of a flower"}],"quiz":[{"question":"What landed on the lock in the evening?","options":["A green moon","A white bird","A stone cup","A silver moth"],"correctAnswer":"A silver moth","explanation":"Tamsin saw a silver moth land on the lock.","supportingSentence":"One evening Tamsin saw a silver moth land on the lock.","skill":"detail"},{"question":"What led Tamsin to the pool?","options":["A hare with a bell","The wind in the leaves","A neighbour from town","The silver moth"],"correctAnswer":"A hare with a bell","explanation":"A hare with a bell on its neck led her to a pool.","supportingSentence":"A hare with a bell on its neck led her to a pool.","skill":"detail"},{"question":"What did Tamsin understand about staying in the garden?","options":["The hare could not leave","She could visit but not stay","She had to live there","The gate would never open again"],"correctAnswer":"She could visit but not stay","explanation":"She understood she could visit, not stay.","supportingSentence":"She understood she could visit, not stay.","skill":"detail"},{"question":"In this story, what does faded mean?","options":["Turned into an animal","Became louder","Grew weak and disappeared","Locked the gate"],"correctAnswer":"Grew weak and disappeared","explanation":"The picture in the water faded after she filled a cup.","supportingSentence":"Tamsin filled a cup and the picture faded.","skill":"vocabulary"},{"question":"What does the petal in her pocket suggest?","options":["She had never left her street","The gate was still open","The hare lived in her house","The garden visit had been real"],"correctAnswer":"The garden visit had been real","explanation":"A garden petal was in her pocket the next morning, after she had stepped back.","supportingSentence":"In the morning a garden petal was in her pocket.","skill":"inference"}],"wordCount":110,"questionCount":5}$q60963$::jsonb,
  '2b0d3d54262b6b3246e85114ec5c4e12805fbe3a41b9bd65cb52d16770cdbba3',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '996da275-a55b-4a6d-adff-78b278068f9c'::uuid,
  'reading',
  'B1',
  'text',
  $q4662${"topic":"fantasy","wordCount":107,"questionCount":5}$q4662$::jsonb,
  $q77596${"mode":"reading","level":"B1","format":"text","topic":"Fantasy","title":"The Clock That Called the Rain","story":"The village clock had been silent for years. When drought cracked the fields, a child named Pim climbed the tower. He found a blue gear that did not match the others. A note in the dust said to turn it once if the sky forgot. Pim turned the gear. The clock chimed, and clouds gathered over the hills. Rain fell before he reached the square. People set out buckets and laughed. The oldest farmer told Pim the clock was a bargain with the river spirit. It would ring only when someone asked kindly. Pim oiled the gear and closed the tower door. That night the streets shone.","dialogue":[],"vocabulary":[{"word":"drought","definition":"a long time with too little rain"},{"word":"gear","definition":"a toothed wheel in a machine"},{"word":"chimed","definition":"made a ringing sound"},{"word":"buckets","definition":"open containers for holding water"},{"word":"bargain","definition":"an agreement between two sides"},{"word":"spirit","definition":"a being that is not an ordinary person"}],"quiz":[{"question":"What problem in the fields sent Pim up the tower?","options":["Drought had cracked them","The farmer locked the gate","People had too many buckets","The square was flooded"],"correctAnswer":"Drought had cracked them","explanation":"He climbed the tower when drought cracked the fields.","supportingSentence":"When drought cracked the fields, a child named Pim climbed the tower.","skill":"detail"},{"question":"What did the dusty note tell Pim to do?","options":["Break the clock","Empty the buckets","Close the tower and leave","Turn the gear once"],"correctAnswer":"Turn the gear once","explanation":"The note said to turn it once if the sky forgot.","supportingSentence":"A note in the dust said to turn it once if the sky forgot.","skill":"detail"},{"question":"When did the farmer say the clock would ring?","options":["Whenever the buckets were full","Every morning at dawn","Only when someone asked kindly","Only during a silent year"],"correctAnswer":"Only when someone asked kindly","explanation":"It would ring only when someone asked kindly.","supportingSentence":"It would ring only when someone asked kindly.","skill":"detail"},{"question":"In this story, what is a drought?","options":["A loud clock sound","A blue machine part","A long time with too little rain","A river animal"],"correctAnswer":"A long time with too little rain","explanation":"The drought had left the fields cracked because rain had not come.","supportingSentence":"When drought cracked the fields, a child named Pim climbed the tower.","skill":"vocabulary"},{"question":"Why did clouds gather over the hills?","options":["The clock had chimed","The farmer had closed the door","The streets were already wet","People were laughing in the square"],"correctAnswer":"The clock had chimed","explanation":"The clock chimed, and clouds gathered over the hills.","supportingSentence":"The clock chimed, and clouds gathered over the hills.","skill":"inference"}],"wordCount":107,"questionCount":5}$q77596$::jsonb,
  '996da275a55baa6dedff78b278068f9c35015633d1f1e8821fafe5bc906a8084',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '931f1a97-7419-4a5a-a533-1dd5d9790f2a'::uuid,
  'reading',
  'B1',
  'text',
  $q4877${"topic":"daily life","wordCount":110,"questionCount":5}$q4877$::jsonb,
  $q75962${"mode":"reading","level":"B1","format":"text","topic":"Daily Life","title":"The Spare Key in the Plant Pot","story":"Jonah locked the flat and then saw his keys on the kitchen table, inside. His phone was in there too. He checked the plant pot by the door, where his sister kept a spare key. The pot was empty. A neighbour called Helen waved from the stairs. She was holding the spare key. Helen had watered the plant and taken the key indoors by mistake. She looked sorry and handed it over. Jonah thanked her and opened the door. He put the spare key on a hook inside a cupboard. Then he sent his sister a message about the new place. Helen laughed and said the plant was still thirsty.","dialogue":[],"vocabulary":[{"word":"spare","definition":"kept extra for when you need it"},{"word":"pot","definition":"a container for a plant"},{"word":"neighbour","definition":"a person who lives nearby"},{"word":"indoors","definition":"inside a building"},{"word":"cupboard","definition":"a cabinet used for storing things"},{"word":"thirsty","definition":"needing water"}],"quiz":[{"question":"Where did Jonah's sister usually keep the extra key?","options":["On the kitchen table","Under the stairs","In the plant pot by the door","In Helen's bag"],"correctAnswer":"In the plant pot by the door","explanation":"His sister kept a spare key in the plant pot by the door.","supportingSentence":"He checked the plant pot by the door, where his sister kept a spare key.","skill":"detail"},{"question":"Why was that key with Helen?","options":["She had taken it indoors by mistake","Jonah had given it to her","She had found it at a shop","The sister had posted it"],"correctAnswer":"She had taken it indoors by mistake","explanation":"Helen had watered the plant and taken the key indoors by mistake.","supportingSentence":"Helen had watered the plant and taken the key indoors by mistake.","skill":"detail"},{"question":"Where did Jonah put the extra key after he got in?","options":["On the kitchen table","In the neighbour's flat","Back in the plant pot","On a hook inside a cupboard"],"correctAnswer":"On a hook inside a cupboard","explanation":"He put the spare key on a hook inside a cupboard.","supportingSentence":"He put the spare key on a hook inside a cupboard.","skill":"detail"},{"question":"In this story, what does thirsty mean?","options":["Needing water","Feeling sorry","Speaking very loudly","Needing a key"],"correctAnswer":"Needing water","explanation":"Helen said the plant was still thirsty after it had been watered.","supportingSentence":"Helen laughed and said the plant was still thirsty.","skill":"vocabulary"},{"question":"Why did Jonah message his sister?","options":["To ask her to buy a plant","To invite Helen for lunch","To tell her the key had a new place","To say the flat was still locked"],"correctAnswer":"To tell her the key had a new place","explanation":"He sent a message about the new place after moving the key to the cupboard.","supportingSentence":"Then he sent his sister a message about the new place.","skill":"inference"}],"wordCount":110,"questionCount":5}$q75962$::jsonb,
  '931f1a9774191a5aa5331dd5d9790f2aa7aa9cb1483b2869c8bf68a327688b0c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'dfc50c4d-6fe6-4b43-afbd-7b154ddf9b75'::uuid,
  'reading',
  'B1',
  'text',
  $q5379${"topic":"school_college","wordCount":108,"questionCount":5}$q5379$::jsonb,
  $q70870${"mode":"reading","level":"B1","format":"text","topic":"School / College","title":"Office Hours before the Test","story":"The biology test was on Wednesday. Amir did not understand the chapter on cells. He wrote three questions in his notebook and went to office hours on Monday. Teacher Rahman sat with him at a side table. She asked Amir to explain the chapter in his own words. He stopped at the part about plant cells. The teacher drew a simple picture and labelled the wall, the centre, and the green parts. Amir copied it and answered his own questions aloud. Teacher Rahman told him to teach the picture to a friend that night. Amir met Noor in the common room and explained it. Amir left feeling ready.","dialogue":[],"vocabulary":[{"word":"biology","definition":"the school subject about living things"},{"word":"chapter","definition":"one section of a book"},{"word":"cells","definition":"tiny parts that living things are made of"},{"word":"aloud","definition":"in a voice that other people can hear"},{"word":"labelled","definition":"marked with names"},{"word":"common","definition":"shared by the people who use it"}],"quiz":[{"question":"When was Amir's biology test?","options":["On Wednesday","The following month","On Friday","On Monday"],"correctAnswer":"On Wednesday","explanation":"The biology test was on Wednesday.","supportingSentence":"The biology test was on Wednesday.","skill":"detail"},{"question":"Where did Amir go for help on Monday?","options":["To the gym","Onto the bus","To Noor's house","To office hours"],"correctAnswer":"To office hours","explanation":"He went to office hours on Monday.","supportingSentence":"He wrote three questions in his notebook and went to office hours on Monday.","skill":"detail"},{"question":"What did Teacher Rahman want Amir to do that night?","options":["Teach the picture to a friend","Copy the whole book","Skip the test","Close the common room"],"correctAnswer":"Teach the picture to a friend","explanation":"She told him to teach the picture to a friend that night.","supportingSentence":"Teacher Rahman told him to teach the picture to a friend that night.","skill":"detail"},{"question":"In this story, what are cells?","options":["Friends in a class","Tiny parts of living things","Rooms in the school","Questions in a notebook"],"correctAnswer":"Tiny parts of living things","explanation":"The biology chapter is about cells, and the picture shows parts of a plant cell.","supportingSentence":"Amir did not understand the chapter on cells.","skill":"vocabulary"},{"question":"Why did Amir leave feeling ready?","options":["He had explained the picture to a friend","The classroom had closed for the week","Noor was going to take the test for him","The test had been cancelled"],"correctAnswer":"He had explained the picture to a friend","explanation":"He explained the picture to Noor, as his teacher had asked him to do.","supportingSentence":"Amir met Noor in the common room and explained it.","skill":"inference"}],"wordCount":108,"questionCount":5}$q70870$::jsonb,
  'dfc50c4d6fe6bb437fbd7b154ddf9b75579990096059be69bb241f9c49b1c443',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '96788605-4560-4367-afe4-c87ea4f1777e'::uuid,
  'reading',
  'B1',
  'text',
  $q4559${"topic":"travel","wordCount":108,"questionCount":5}$q4559$::jsonb,
  $q66631${"mode":"reading","level":"B1","format":"text","topic":"Travel","title":"A Delay at the Ferry Gate","story":"The ferry to the island was already late when Dina reached the gate. A board said the new time was two hours later. Dina had a paper ticket and a small backpack. She asked a staff member named Colin what to do. He stamped her ticket and pointed to a waiting room with seats and a kettle. Dina sent a message to the guesthouse so they would not worry. She ate an apple and read a map of the island paths. When the ferry arrived, Colin called her group first. The water was calm, and the ride took forty minutes. Dina stood on deck and watched the harbour.","dialogue":[],"vocabulary":[{"word":"ferry","definition":"a boat that carries people on a set route"},{"word":"ticket","definition":"a paper that lets you travel"},{"word":"stamped","definition":"marked with an ink stamp"},{"word":"guesthouse","definition":"a small place where travellers sleep"},{"word":"deck","definition":"the floor of a boat where people can stand"},{"word":"harbour","definition":"a place where boats come in"}],"quiz":[{"question":"What did the board say about the new time?","options":["It was two hours later","It was ten minutes later","It was a full day later","The ferry had already left"],"correctAnswer":"It was two hours later","explanation":"The board said the new time was two hours later.","supportingSentence":"A board said the new time was two hours later.","skill":"detail"},{"question":"What did Colin do to Dina's ticket?","options":["Threw it away","Put it in the kettle","Stamped it","Sold it to someone else"],"correctAnswer":"Stamped it","explanation":"He stamped her ticket.","supportingSentence":"He stamped her ticket and pointed to a waiting room with seats and a kettle.","skill":"detail"},{"question":"Why did Dina message the guesthouse?","options":["To ask for another apple","To buy a new ticket","So they would not worry","To cancel the island trip"],"correctAnswer":"So they would not worry","explanation":"She sent the message so they would not worry.","supportingSentence":"Dina sent a message to the guesthouse so they would not worry.","skill":"detail"},{"question":"In this story, what is a ferry?","options":["A room with a kettle","A map of island paths","A paper ticket","A boat that carries people on a set route"],"correctAnswer":"A boat that carries people on a set route","explanation":"Dina is waiting for the ferry that will carry her to the island.","supportingSentence":"The ferry to the island was already late when Dina reached the gate.","skill":"vocabulary"},{"question":"What did Dina do with the island map while she waited?","options":["She read it","She gave it to Colin","She dropped it in the water","She used it as a ticket"],"correctAnswer":"She read it","explanation":"She read a map of the island paths while she waited.","supportingSentence":"She ate an apple and read a map of the island paths.","skill":"detail"}],"wordCount":108,"questionCount":5}$q66631$::jsonb,
  '9678860545601367bfe4c87ea4f1777eeaec865524341d25613bd5ffd6147592',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e932744d-9252-471e-a9ad-fa2ceb117be3'::uuid,
  'reading',
  'B1',
  'text',
  $q4636${"topic":"hobbies","wordCount":107,"questionCount":5}$q4636$::jsonb,
  $q55288${"mode":"reading","level":"B1","format":"text","topic":"Hobbies","title":"Clay after School","story":"Mina stayed after school for the clay club on Wednesdays. She wanted to make a cup for her father. The first cup leaned to one side and she had to start again. The leader, Paul, showed her how to keep her hands wet and steady. Mina pressed the walls until they were even. She scratched her name under the base. Paul said the cup would dry on a shelf until Friday. Then they would bake it in the kiln. Mina washed the grey clay off her fingers and smiled. A crooked cup had taught her to slow down. She could not wait to see the finished colour.","dialogue":[],"vocabulary":[{"word":"clay","definition":"a soft earth used for making pots"},{"word":"leaned","definition":"tipped to one side"},{"word":"steady","definition":"not shaking or moving about"},{"word":"base","definition":"the bottom of an object"},{"word":"kiln","definition":"a very hot oven for baking clay"},{"word":"crooked","definition":"not straight"}],"quiz":[{"question":"What did Mina want to make?","options":["A cup for her father","A plate for Paul","A tile for the hall","A bowl for the teacher"],"correctAnswer":"A cup for her father","explanation":"She wanted to make a cup for her father.","supportingSentence":"She wanted to make a cup for her father.","skill":"detail"},{"question":"What was wrong with the first cup?","options":["The clay was grey","The shelf was full","It was already baked","It leaned to one side"],"correctAnswer":"It leaned to one side","explanation":"The first cup leaned to one side and she had to start again.","supportingSentence":"The first cup leaned to one side and she had to start again.","skill":"detail"},{"question":"Where would the cup dry?","options":["On a shelf until Friday","In the kiln that day","At her father's office","Under the school gate"],"correctAnswer":"On a shelf until Friday","explanation":"Paul said the cup would dry on a shelf until Friday.","supportingSentence":"Paul said the cup would dry on a shelf until Friday.","skill":"detail"},{"question":"In this story, what is a kiln?","options":["A wet cloth for hands","A name scratched in clay","A very hot oven for clay","A shelf in the club"],"correctAnswer":"A very hot oven for clay","explanation":"They would bake the cup in the kiln, so it is the hot oven.","supportingSentence":"Then they would bake it in the kiln.","skill":"vocabulary"},{"question":"Why did Mina have to start the cup again?","options":["The first one was not straight","Friday had already passed","Her name would not fit","Paul had lost the clay"],"correctAnswer":"The first one was not straight","explanation":"The first cup leaned to one side, so she began again and made the walls even.","supportingSentence":"The first cup leaned to one side and she had to start again.","skill":"inference"}],"wordCount":107,"questionCount":5}$q55288$::jsonb,
  'e932744d9252b71e69adfa2ceb117be3e1cf4d40274c0096cbf7b850e6ebff3b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '10171394-98d6-45a0-a7e9-fe2ab167c7dc'::uuid,
  'reading',
  'B1',
  'text',
  $q4881${"topic":"daily life","wordCount":150,"questionCount":5}$q4881$::jsonb,
  $q2378${"mode":"reading","level":"B1","format":"text","topic":"Daily Life","title":"The Mixed Laundry Loads","story":"Lina carried a full laundry basket down to the shared machines on Sunday morning. She put her white shirts in one machine and her dark trousers in another. Her neighbour Rosa arrived with a red basket and asked which machine was free. Lina pointed to the small machine by the window. When the machines stopped, Lina opened a door. She pulled out a green sweater she had never owned. Rosa laughed and held up Lina's blue towel. They had swapped the wet loads by mistake. They spread everything on a big table and sorted each item by colour. Lina found her socks inside Rosa's basket. Rosa found a school shirt with Lina's name inside the collar. They folded the clean piles and thanked each other. Lina wrote her name on a piece of tape and stuck it to her basket. Next Sunday she checked the tape before she pressed start.","dialogue":[],"vocabulary":[{"word":"basket","definition":"a container used for carrying things"},{"word":"neighbour","definition":"a person who lives near you"},{"word":"swapped","definition":"exchanged one thing for another"},{"word":"sorted","definition":"put into groups"},{"word":"collar","definition":"the part of a shirt around the neck"},{"word":"tape","definition":"a sticky strip used for labels"}],"quiz":[{"question":"When did Lina take the laundry to the machines?","options":["During school lunch","On Sunday morning","On Friday night","On Monday afternoon"],"correctAnswer":"On Sunday morning","explanation":"She carried the basket down on Sunday morning.","supportingSentence":"Lina carried a full laundry basket down to the shared machines on Sunday morning.","skill":"detail"},{"question":"What did Lina pull out that she had never owned?","options":["A red basket","A blue towel","A green sweater","Her own school shirt"],"correctAnswer":"A green sweater","explanation":"She pulled out a green sweater she had never owned.","supportingSentence":"She pulled out a green sweater she had never owned.","skill":"detail"},{"question":"Where was Lina's name written on the school shirt?","options":["On a piece of tape","Under the big table","On the green sweater","Inside the collar"],"correctAnswer":"Inside the collar","explanation":"Rosa found the shirt with Lina's name inside the collar.","supportingSentence":"Rosa found a school shirt with Lina's name inside the collar.","skill":"detail"},{"question":"In this story, what does swapped mean?","options":["Exchanged one thing for another","Lost something in a pocket","Folded clothes into neat piles","Washed something a second time"],"correctAnswer":"Exchanged one thing for another","explanation":"They had swapped the loads, so each woman had the other's clothes.","supportingSentence":"They had swapped the wet loads by mistake.","skill":"vocabulary"},{"question":"Why did Lina put her name on the basket?","options":["So Rosa could keep the shirts","So she could tell her basket from Rosa's","So the machine would start faster","So the sweater would stay green"],"correctAnswer":"So she could tell her basket from Rosa's","explanation":"After mixing up the loads, a name would make her basket easy to recognise.","supportingSentence":"Lina wrote her name on a piece of tape and stuck it to her basket.","skill":"inference"}],"wordCount":150,"questionCount":5}$q2378$::jsonb,
  '1017139498d6b5a0f7e9fe2ab167c7dcf57f514b41d016ca94663caa274779a3',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '099b7899-bc40-41ed-a6dd-19ef58a4f90d'::uuid,
  'reading',
  'B1',
  'text',
  $q5384${"topic":"school_college","wordCount":149,"questionCount":5}$q5384$::jsonb,
  $q91972${"mode":"reading","level":"B1","format":"text","topic":"School / College","title":"Notes Left on the Shelf","story":"Nadia had to give a short history talk after lunch. She prepared pictures of an old bridge and put them in a yellow folder. At noon she revised in the library and left the folder on a low shelf. When the bell rang, she walked to class without it. Her friend Omar sent a message to say the folder was still there. Nadia asked the teacher for a later turn and hurried back. The librarian had moved the folder to the front desk. Nadia checked the pictures, thanked her, and returned to class. She spoke after the break, and the class could see the bridge clearly. The teacher said the talk was calm and easy to follow. That evening she clipped the folder inside her school bag. She also set a reminder on her phone for the next talk. She did not want to leave her notes behind again.","dialogue":[],"vocabulary":[{"word":"folder","definition":"a cover that holds loose papers"},{"word":"revised","definition":"looked at work again to prepare"},{"word":"shelf","definition":"a flat board used to store things"},{"word":"librarian","definition":"a person who works in a library"},{"word":"calm","definition":"quiet and not upset"},{"word":"reminder","definition":"a note that helps you remember"}],"quiz":[{"question":"When was Nadia supposed to give her history talk?","options":["After lunch","During the first lesson","Late at night","Before breakfast"],"correctAnswer":"After lunch","explanation":"She had to give the short history talk after lunch.","supportingSentence":"Nadia had to give a short history talk after lunch.","skill":"detail"},{"question":"Where did Nadia leave the yellow folder?","options":["On the teacher's chair","Under the classroom door","In Omar's bag","On a low shelf"],"correctAnswer":"On a low shelf","explanation":"She left the folder on a low shelf in the library.","supportingSentence":"At noon she revised in the library and left the folder on a low shelf.","skill":"detail"},{"question":"Who sent Nadia a message about the folder?","options":["The bus driver","The history teacher","Her friend Omar","A younger student"],"correctAnswer":"Her friend Omar","explanation":"Omar sent a message to say the folder was still there.","supportingSentence":"Her friend Omar sent a message to say the folder was still there.","skill":"detail"},{"question":"In this story, what does reminder mean?","options":["A picture of an old bridge","A loud bell in the hall","A note that helps you remember","A seat near a window"],"correctAnswer":"A note that helps you remember","explanation":"She set a reminder on her phone so she would remember the next talk.","supportingSentence":"She also set a reminder on her phone for the next talk.","skill":"vocabulary"},{"question":"Why did Nadia clip the folder inside her school bag?","options":["So she would not leave her notes behind","So Omar could give the talk","So the pictures would stay yellow","So the librarian could borrow it"],"correctAnswer":"So she would not leave her notes behind","explanation":"She did not want to leave her notes behind again.","supportingSentence":"She did not want to leave her notes behind again.","skill":"inference"}],"wordCount":149,"questionCount":5}$q91972$::jsonb,
  '099b7899bc4011ed96dd19ef58a4f90d184d020be693a4a92f244c5ddf20f5be',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'c109ec8a-ffbd-4f0c-ae92-dc2de59eecf2'::uuid,
  'reading',
  'B1',
  'text',
  $q4564${"topic":"travel","wordCount":149,"questionCount":5}$q4564$::jsonb,
  $q84822${"mode":"reading","level":"B1","format":"text","topic":"Travel","title":"The Last Bus from the Market","story":"After a morning at the town market, Yusuf had two heavy bags. The last bus home left from a stop behind the fish stalls. He looked at the main road and could not see a sign. A seller named Pilar pointed to a narrow lane. Yusuf thanked her and walked quickly with both bags. The bus was already at the stop, and the doors were open. He showed his pass, climbed on, and found a seat near the driver. A passenger held one bag while he sat down. Yusuf sent a text to his father to say he had caught the bus. At his stop he lifted both bags and nodded to the passenger. The bags were heavy, but he was glad he had asked for help. That evening he drew a small map of the lane for his next visit. He pinned the map inside the kitchen cupboard.","dialogue":[],"vocabulary":[{"word":"stalls","definition":"stands where people sell things"},{"word":"lane","definition":"a narrow road or path"},{"word":"pass","definition":"a card that lets you travel"},{"word":"passenger","definition":"a person riding, not the driver"},{"word":"text","definition":"a short phone message"},{"word":"cupboard","definition":"a piece of furniture with a door and shelves"}],"quiz":[{"question":"Where did the last bus leave from?","options":["A stop behind the fish stalls","The front door of the school","A stop beside the hospital","The market office"],"correctAnswer":"A stop behind the fish stalls","explanation":"The last bus home left from a stop behind the fish stalls.","supportingSentence":"The last bus home left from a stop behind the fish stalls.","skill":"detail"},{"question":"Who pointed Yusuf toward the bus?","options":["His father","A passenger with a map","A seller named Pilar","The bus driver"],"correctAnswer":"A seller named Pilar","explanation":"Pilar pointed to the narrow lane that led to the stop.","supportingSentence":"A seller named Pilar pointed to a narrow lane.","skill":"detail"},{"question":"Where did Yusuf sit on the bus?","options":["Beside the fish stalls","In the kitchen at home","Near the driver","On the roof"],"correctAnswer":"Near the driver","explanation":"He climbed on and found a seat near the driver.","supportingSentence":"He showed his pass, climbed on, and found a seat near the driver.","skill":"detail"},{"question":"In this story, what does text mean?","options":["A heavy shopping bag","A seat near the front","A paper map of a town","A short phone message"],"correctAnswer":"A short phone message","explanation":"Yusuf sent a text, a short phone message, to his father.","supportingSentence":"Yusuf sent a text to his father to say he had caught the bus.","skill":"vocabulary"},{"question":"Why did Yusuf draw a map that evening?","options":["So he could find the lane next time","So Pilar could sell more fish","So his father could drive the bus","So the bags would feel lighter"],"correctAnswer":"So he could find the lane next time","explanation":"He drew the lane for his next visit after nearly missing the stop.","supportingSentence":"That evening he drew a small map of the lane for his next visit.","skill":"inference"}],"wordCount":149,"questionCount":5}$q84822$::jsonb,
  'c109ec8affbdcf0c5e92dc2de59eecf240e25e37432e415fa383a366eda003b2',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '7ffdd4c1-9be5-4f83-a6cd-b06f59aae800'::uuid,
  'reading',
  'B1',
  'text',
  $q4556${"topic":"travel","wordCount":150,"questionCount":5}$q4556$::jsonb,
  $q82630${"mode":"reading","level":"B1","format":"text","topic":"Travel","title":"Sharing the Taxi Fare","story":"Three students reached the city station after dark with heavy backpacks. A taxi stood by the exit, but one ride looked expensive. Mina suggested they share the car and divide the fare. Hugo and Ade agreed, and Ade had the address on his phone. The driver nodded and put the bags in the back. On the way, Mina watched the street names to check the route. The hostel was a green building beside a quiet square. The square was empty, and the windows of the hostel were bright. The driver stopped at the door and told them the price. Hugo paid the full amount, and the others gave him their share in cash. They checked the receipt before the taxi left. Inside, the owner gave them keys and pointed to the stairs. Mina kept the receipt in her notebook. She wanted a clear record of what each person had paid.","dialogue":[],"vocabulary":[{"word":"backpacks","definition":"bags worn on the back"},{"word":"fare","definition":"the price of a ride"},{"word":"hostel","definition":"a cheap place where travellers sleep"},{"word":"receipt","definition":"paper that shows what you paid"},{"word":"expensive","definition":"costing a lot of money"},{"word":"square","definition":"an open town space with buildings around it"}],"quiz":[{"question":"Who suggested sharing the car?","options":["Mina","The driver","Hugo","The hostel owner"],"correctAnswer":"Mina","explanation":"Mina suggested they share the car and divide the fare.","supportingSentence":"Mina suggested they share the car and divide the fare.","skill":"detail"},{"question":"Where was the green hostel?","options":["On a river boat","Beside a quiet square","Inside the railway station","Next to a loud market"],"correctAnswer":"Beside a quiet square","explanation":"The hostel was a green building beside a quiet square.","supportingSentence":"The hostel was a green building beside a quiet square.","skill":"detail"},{"question":"Who paid the driver the full price?","options":["Hugo","The hostel owner","Mina","Ade"],"correctAnswer":"Hugo","explanation":"Hugo paid the full amount, and the others gave him their parts.","supportingSentence":"Hugo paid the full amount, and the others gave him their share in cash.","skill":"detail"},{"question":"In this story, what does receipt mean?","options":["A key to a bedroom","A list of street names","A bag for the back seat","Paper that shows what you paid"],"correctAnswer":"Paper that shows what you paid","explanation":"They checked the receipt, the paper that showed the price.","supportingSentence":"They checked the receipt before the taxi left.","skill":"vocabulary"},{"question":"Why did Mina suggest dividing the cost?","options":["One ride by itself looked expensive","The hostel was free for one guest","The station had already closed","Ade did not know the address"],"correctAnswer":"One ride by itself looked expensive","explanation":"She saw that one ride looked expensive, so the group could split it.","supportingSentence":"A taxi stood by the exit, but one ride looked expensive.","skill":"inference"}],"wordCount":150,"questionCount":5}$q82630$::jsonb,
  '7ffdd4c19be53f8386cdb06f59aae800b7d487c1401f24267e9036207ec2e543',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '47773bfa-28e6-4c0a-a2a8-25d88a0a0876'::uuid,
  'reading',
  'B1',
  'text',
  $q4640${"topic":"hobbies","wordCount":147,"questionCount":5}$q4640$::jsonb,
  $q70672${"mode":"reading","level":"B1","format":"text","topic":"Hobbies","title":"Painting the Garden Bench","story":"Mateo and his aunt decided to paint the old garden bench. They carried sandpaper, brushes, and a tin of green paint outside. First they rubbed the wood until it felt smooth. Mateo covered the grass with newspaper so drops would not fall there. His aunt showed him how to move the brush in one direction. They painted the legs and then the seat. A sudden breeze blew a leaf onto the wet paint. They lifted it off and smoothed the mark. Before lunch they finished the top and left the bench to dry. After lunch they painted the back and the arms. The colour looked bright against the grey wall. They washed the brushes in a bucket and closed the tin. Mateo wrote the date on a label and stuck it under the seat. The next day the bench was dry, and they sat there with tea.","dialogue":[],"vocabulary":[{"word":"sandpaper","definition":"rough paper used to rub wood smooth"},{"word":"breeze","definition":"a light wind"},{"word":"smoothed","definition":"made a surface even"},{"word":"label","definition":"a small note that gives information"},{"word":"brushes","definition":"tools used to spread paint"},{"word":"dry","definition":"not wet"}],"quiz":[{"question":"What colour was the paint in the tin?","options":["Green","Red","Blue","White"],"correctAnswer":"Green","explanation":"They carried a tin of green paint outside.","supportingSentence":"They carried sandpaper, brushes, and a tin of green paint outside.","skill":"detail"},{"question":"Which parts of the bench did they paint first?","options":["The back and the arms","The legs and then the seat","The kitchen door","Only the grey wall"],"correctAnswer":"The legs and then the seat","explanation":"They painted the legs and then the seat before the other parts.","supportingSentence":"They painted the legs and then the seat.","skill":"detail"},{"question":"Where did Mateo stick the label?","options":["Inside the paint tin","On the newspaper","Under the seat","On the grey wall"],"correctAnswer":"Under the seat","explanation":"He wrote the date on a label and stuck it under the seat.","supportingSentence":"Mateo wrote the date on a label and stuck it under the seat.","skill":"detail"},{"question":"In this story, what does breeze mean?","options":["A wooden leg","A bright colour","A wet brush","A light wind"],"correctAnswer":"A light wind","explanation":"A breeze, a light wind, blew a leaf onto the wet paint.","supportingSentence":"A sudden breeze blew a leaf onto the wet paint.","skill":"vocabulary"},{"question":"Why did they wait until the next day to sit down?","options":["The paint needed time to dry","The newspaper stayed on the seat","The aunt had sold the bench","The wall still needed paint"],"correctAnswer":"The paint needed time to dry","explanation":"They sat only the next day, when the bench was dry.","supportingSentence":"The next day the bench was dry, and they sat there with tea.","skill":"inference"}],"wordCount":147,"questionCount":5}$q70672$::jsonb,
  '47773bfa28e64c0a42a825d88a0a08768cdacdf7ca21f4ff057c00318861fec1',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e3f03f81-8e62-4f65-aaba-0fa0f167da3f'::uuid,
  'reading',
  'B1',
  'text',
  $q4641${"topic":"hobbies","wordCount":148,"questionCount":5}$q4641$::jsonb,
  $q95676${"mode":"reading","level":"B1","format":"text","topic":"Hobbies","title":"The Thursday Chess Corner","story":"Priya joined a chess corner in the community hall on Thursday. She had only played at home, so she felt nervous. Her first game ended quickly, and she lost. An older player named Helen sat beside her and smiled. Helen showed her how to protect the king before she attacked. Priya played a second game and thought before each move. The game lasted much longer, and the hall grew quiet. She still did not win, but Helen clapped once. Helen said Priya had improved because she was patient. Priya borrowed a small book of simple first moves. She promised to read one page each evening. On the way home she repeated the advice about the king. The next Thursday she arrived early and set up the board herself. Helen nodded when she saw the book on the table. Priya felt ready to learn, even if she lost again.","dialogue":[],"vocabulary":[{"word":"nervous","definition":"a little worried or afraid"},{"word":"protect","definition":"to keep someone or something safe"},{"word":"patient","definition":"able to wait and not rush"},{"word":"borrowed","definition":"took something for a while with permission"},{"word":"board","definition":"the flat surface used for a chess game"},{"word":"clapped","definition":"hit your hands together to show pleasure"}],"quiz":[{"question":"On which day did the chess corner meet?","options":["On Thursday","On Saturday night","On Monday","Every morning"],"correctAnswer":"On Thursday","explanation":"Priya joined the chess corner in the hall on Thursday.","supportingSentence":"Priya joined a chess corner in the community hall on Thursday.","skill":"detail"},{"question":"What did Helen show Priya to do before an attack?","options":["Hide the pieces","Protect the king","Leave the hall at once","Close her eyes"],"correctAnswer":"Protect the king","explanation":"Helen showed her how to protect the king before she attacked.","supportingSentence":"Helen showed her how to protect the king before she attacked.","skill":"detail"},{"question":"What did Priya borrow from the chess corner?","options":["A small book of simple first moves","A brand-new chess set","The keys to the hall","Helen's chair"],"correctAnswer":"A small book of simple first moves","explanation":"She borrowed a small book of simple first moves.","supportingSentence":"Priya borrowed a small book of simple first moves.","skill":"detail"},{"question":"In this story, what does patient mean?","options":["Angry about losing a game","Too tired to sit still","Ready to go home early","Able to wait and not rush"],"correctAnswer":"Able to wait and not rush","explanation":"Helen said Priya had improved because she was patient and did not rush.","supportingSentence":"Helen said Priya had improved because she was patient.","skill":"vocabulary"},{"question":"What does the ending show about Priya?","options":["She wants to keep learning","She is angry with Helen","She plans to stop playing","She wants to sell the book"],"correctAnswer":"She wants to keep learning","explanation":"She felt ready to learn even if she lost again, so she means to continue.","supportingSentence":"Priya felt ready to learn, even if she lost again.","skill":"inference"}],"wordCount":148,"questionCount":5}$q95676$::jsonb,
  'e3f03f818e62df65eaba0fa0f167da3f39dee3a07d45dc4b7ae7e7727c78dc0e',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '177372dc-2e05-48cc-a8b9-8d1c4fe8be04'::uuid,
  'reading',
  'B1',
  'text',
  $q5315${"topic":"health_sports","wordCount":146,"questionCount":5}$q5315$::jsonb,
  $q79268${"mode":"reading","level":"B1","format":"text","topic":"Health & Sports","title":"A Short Walk after a Cold","story":"Marco had stayed in bed for three days with a bad cold. The doctor said a short walk was fine if he went slowly. He put on a coat and soft shoes and stepped outside with his sister. They walked only as far as the park gate. Marco felt warm, so they stopped and drank water. He did not run, and he did not take the long path. On the way back he breathed easily and talked a little. At home he rested on the sofa and ate soup. His sister wrote the time and the distance in a notebook. The next day he walked to the gate and then around the small pond. He still stopped for water and came home before he felt tired. Marco told the doctor that the plan was working. He agreed to wait another week before he joined his team.","dialogue":[],"vocabulary":[{"word":"cold","definition":"an illness that makes you feel unwell"},{"word":"slowly","definition":"at a low speed"},{"word":"gate","definition":"a door in a fence or outside wall"},{"word":"rested","definition":"stopped activity in order to recover"},{"word":"distance","definition":"how far someone goes"},{"word":"team","definition":"a group that plays sport together"}],"quiz":[{"question":"How long had Marco stayed in bed?","options":["For two weeks","For a whole month","For one hour","For three days"],"correctAnswer":"For three days","explanation":"He had stayed in bed for three days with a bad cold.","supportingSentence":"Marco had stayed in bed for three days with a bad cold.","skill":"detail"},{"question":"How far did Marco walk on the first outing?","options":["Only as far as the park gate","Along the long path","All the way to team practice","Around the small pond"],"correctAnswer":"Only as far as the park gate","explanation":"On the first walk they went only as far as the park gate.","supportingSentence":"They walked only as far as the park gate.","skill":"detail"},{"question":"What did Marco do at home after the first walk?","options":["He joined his team","He went straight back out","He rested and ate soup","He ran up a hill"],"correctAnswer":"He rested and ate soup","explanation":"At home he rested on the sofa and ate soup.","supportingSentence":"At home he rested on the sofa and ate soup.","skill":"detail"},{"question":"In this story, what does slowly mean?","options":["At a low speed","Without any food","Only after dark","With a large group"],"correctAnswer":"At a low speed","explanation":"The doctor said the walk was fine if he went slowly, not fast.","supportingSentence":"The doctor said a short walk was fine if he went slowly.","skill":"vocabulary"},{"question":"Why did Marco agree to miss his team for another week?","options":["His sister hid his shoes","The park gate was locked","The team had left the town","His careful return was not finished"],"correctAnswer":"His careful return was not finished","explanation":"He was still following the slow plan, so he waited before joining the team.","supportingSentence":"He agreed to wait another week before he joined his team.","skill":"inference"}],"wordCount":146,"questionCount":5}$q79268$::jsonb,
  '177372dc2e0578ccc8b98d1c4fe8be040916a817560a207c68837d2c0920d50a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f5a884ba-f065-46c1-a040-e19a601815f1'::uuid,
  'reading',
  'B1',
  'text',
  $q5318${"topic":"health_sports","wordCount":149,"questionCount":5}$q5318$::jsonb,
  $q89827${"mode":"reading","level":"B1","format":"text","topic":"Health & Sports","title":"Rest for a Sore Knee","story":"During football practice, Amina felt a sharp pain in her left knee. She stopped running and told the coach at once. The coach moved her to a bench and brought a cold pack. Amina held the pack on her knee and kept her leg straight. She did not finish the match. Her teammate Jules brought her water and sat with her. After practice, the coach wrote a note for Amina's parents. The note said to rest and to use the cold pack at home. It also said to skip training for a week. Amina felt disappointed, but she followed the plan. She watched the next session from the side and cheered. Each evening she stretched gently, as the coach had shown her. By Friday the pain was mild, and she could walk without a limp. She asked to return, but the coach said one more rest day was wise.","dialogue":[],"vocabulary":[{"word":"pain","definition":"a feeling of hurt in the body"},{"word":"coach","definition":"the person who leads sports practice"},{"word":"pack","definition":"a cold bag placed on an injury"},{"word":"disappointed","definition":"sad because a hope did not happen"},{"word":"stretched","definition":"moved the body gently to loosen it"},{"word":"limp","definition":"an uneven walk when a leg hurts"}],"quiz":[{"question":"Where did Amina feel the sharp pain?","options":["In her left knee","In her shoulder","In her lower back","In her right hand"],"correctAnswer":"In her left knee","explanation":"She felt a sharp pain in her left knee during practice.","supportingSentence":"During football practice, Amina felt a sharp pain in her left knee.","skill":"detail"},{"question":"Which teammate brought Amina water?","options":["The coach","Her father","A player from another school","Jules"],"correctAnswer":"Jules","explanation":"Her teammate Jules brought her water and sat with her.","supportingSentence":"Her teammate Jules brought her water and sat with her.","skill":"detail"},{"question":"How long did the note say to skip training?","options":["For the whole season","For one hour","For a week","Until the same afternoon"],"correctAnswer":"For a week","explanation":"The note said to skip training for a week.","supportingSentence":"It also said to skip training for a week.","skill":"detail"},{"question":"In this story, what does limp mean?","options":["A win at the end of a match","An uneven walk when a leg hurts","A loud cheer from the side","A note written for parents"],"correctAnswer":"An uneven walk when a leg hurts","explanation":"She could walk without a limp, so her sore knee no longer made her walk unevenly.","supportingSentence":"By Friday the pain was mild, and she could walk without a limp.","skill":"vocabulary"},{"question":"Why did Amina watch the next session from the side?","options":["She was following the rest plan","The coach sent her away for the year","Jules asked her only to keep score","She had lost the way to the field"],"correctAnswer":"She was following the rest plan","explanation":"She followed the plan to skip training, so she watched and cheered instead.","supportingSentence":"Amina felt disappointed, but she followed the plan.","skill":"inference"}],"wordCount":149,"questionCount":5}$q89827$::jsonb,
  'f5a884baf06506c1e040e19a601815f1143d585aae1003031f81aa0c349a6154',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '232ad0b0-8eee-4719-adb5-f36ad667640b'::uuid,
  'reading',
  'B1',
  'text',
  $q5194${"topic":"culture_food","wordCount":142,"questionCount":5}$q5194$::jsonb,
  $q98125${"mode":"reading","level":"B1","format":"text","topic":"Culture & Food","title":"Honey Cake for the Guests","story":"On Sunday the family expected guests from their grandmother's village. Noor wanted to bake the honey cake that the village served at visits. Her uncle read the old card while Noor set out flour, eggs, and honey. They warmed the honey so it would mix more easily. Noor stirred slowly, and her uncle checked the oven. The cake rose, and the kitchen smelled sweet. Noor made tea and put small plates on the table. When the guests arrived, she offered the first slice to her grandmother's friend. The friend smiled and said the taste was familiar. People asked about the honey, and Noor explained each step. She did not rush, because the story of the cake mattered too. Later she copied the card in clear writing and stored it in a tin. She hoped to bake the same cake again next spring.","dialogue":[],"vocabulary":[{"word":"guests","definition":"people invited to visit"},{"word":"honey","definition":"a sweet food made by bees"},{"word":"stirred","definition":"mixed by moving a spoon around"},{"word":"rose","definition":"went upwards as it cooked"},{"word":"familiar","definition":"known from before"},{"word":"copied","definition":"wrote the same words again"}],"quiz":[{"question":"Where were the visitors coming from?","options":["Their grandmother's village","A hotel in the city","The school kitchen","A market by the sea"],"correctAnswer":"Their grandmother's village","explanation":"The family expected guests from their grandmother's village.","supportingSentence":"On Sunday the family expected guests from their grandmother's village.","skill":"detail"},{"question":"Who was offered the first slice of cake?","options":["Noor's uncle","The person who delivered post","Her grandmother's friend","A child from the school"],"correctAnswer":"Her grandmother's friend","explanation":"She offered the first slice to her grandmother's friend.","supportingSentence":"When the guests arrived, she offered the first slice to her grandmother's friend.","skill":"detail"},{"question":"What did Noor do while her uncle checked the oven?","options":["She hid the honey","She painted the plates","She stirred the mixture slowly","She left the house"],"correctAnswer":"She stirred the mixture slowly","explanation":"Noor stirred slowly while her uncle checked the oven.","supportingSentence":"Noor stirred slowly, and her uncle checked the oven.","skill":"detail"},{"question":"In this story, what does familiar mean?","options":["Burned at the edge","Written in tiny letters","Too hot to taste","Known from before"],"correctAnswer":"Known from before","explanation":"The friend said the taste was familiar, so she knew it from an earlier time.","supportingSentence":"The friend smiled and said the taste was familiar.","skill":"vocabulary"},{"question":"Why did Noor keep a clear copy of the card?","options":["She hoped to bake the cake again","She wanted to sell the tin","The guests asked her to stop","Her uncle had lost the oven"],"correctAnswer":"She hoped to bake the cake again","explanation":"She hoped to bake the same cake again, so she kept a copy of the card.","supportingSentence":"She hoped to bake the same cake again next spring.","skill":"inference"}],"wordCount":142,"questionCount":5}$q98125$::jsonb,
  '232ad0b08eee2719bdb5f36ad667640b95c0f7b696c377cbaf0278a6e9bb13bf',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1725e62f-1109-48cd-aed6-ef4dd856f70a'::uuid,
  'reading',
  'B1',
  'text',
  $q5194${"topic":"culture_food","wordCount":151,"questionCount":5}$q5194$::jsonb,
  $q73999${"mode":"reading","level":"B1","format":"text","topic":"Culture & Food","title":"A Bowl from the Clay Class","story":"Kenji joined a Saturday clay class at the town museum. The teacher gave each student a lump of soft clay and a cloth. Kenji wanted to make a bowl for his mother's birthday. He pressed the centre with his thumbs and turned the clay in his hands. The walls became thin, and a crack appeared. The teacher showed him how to smooth the crack with a wet finger. Kenji tried again and shaped a simple wide bowl. He carved a small leaf on the side so it would be easy to recognise. The bowls dried on a shelf and were baked in a hot oven later. The next week he painted the leaf green. He wrapped it in paper and carried it home on the bus. His mother filled it with fruit and put it on the table. Kenji felt proud, because he had repaired the crack instead of starting again.","dialogue":[],"vocabulary":[{"word":"clay","definition":"soft wet earth used to shape pots"},{"word":"thumbs","definition":"the short thick fingers"},{"word":"crack","definition":"a thin break in a surface"},{"word":"smooth","definition":"to make a rough place even"},{"word":"recognise","definition":"to know which one it is"},{"word":"proud","definition":"pleased about something you did well"}],"quiz":[{"question":"Where did Kenji attend the clay class?","options":["At the town museum","At the bus station","In his mother's kitchen","In a school gym"],"correctAnswer":"At the town museum","explanation":"He joined a Saturday clay class at the town museum.","supportingSentence":"Kenji joined a Saturday clay class at the town museum.","skill":"detail"},{"question":"Who was the finished bowl for?","options":["His teacher","His mother","The bus driver","A museum visitor"],"correctAnswer":"His mother","explanation":"He wanted to make a bowl for his mother's birthday.","supportingSentence":"Kenji wanted to make a bowl for his mother's birthday.","skill":"detail"},{"question":"What colour did Kenji paint the leaf?","options":["Green","Black","Red","Blue"],"correctAnswer":"Green","explanation":"The next week he painted the leaf green.","supportingSentence":"The next week he painted the leaf green.","skill":"detail"},{"question":"In this story, what does recognise mean?","options":["To bake a pot in an oven","To wrap a gift in paper","To fill a bowl with fruit","To know which one it is"],"correctAnswer":"To know which one it is","explanation":"He carved a leaf so the bowl would be easy to recognise as his.","supportingSentence":"He carved a small leaf on the side so it would be easy to recognise.","skill":"vocabulary"},{"question":"What does his mother's action show?","options":["She chose to use the bowl","She sent the bowl back to class","She hid the bowl in a cupboard","She asked him to crack it again"],"correctAnswer":"She chose to use the bowl","explanation":"She filled the bowl with fruit and put it on the table, so she was using it.","supportingSentence":"His mother filled it with fruit and put it on the table.","skill":"inference"}],"wordCount":151,"questionCount":5}$q73999$::jsonb,
  '1725e62f110988cdaed6ef4dd856f70a4ad5b8819a1525f7b3a9feaf1604692a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '7715865a-5fd0-4e82-a4f9-90e08e6b6861'::uuid,
  'reading',
  'B1',
  'text',
  $q4991${"topic":"technology","wordCount":146,"questionCount":5}$q4991$::jsonb,
  $q91739${"mode":"reading","level":"B1","format":"text","topic":"Technology","title":"The Page Stuck in the Printer","story":"Hana needed to print her story before the class bell. The school printer made a loud click and then stopped. A message on the screen showed a picture of a stuck page. Hana read the steps and opened the front panel. She pulled out a folded sheet and closed the panel gently. The printer started again, and her story came out on clean paper. She checked that every paragraph was there. The teacher had asked the class to keep a backup as well. Hana saved a copy on a memory stick and put the stick in her pencil case. She wrote her name on the printed page and placed it in the tray. A classmate named Rafi had the same problem a minute later. Hana showed him the picture and waited while he removed his page. Both stories printed, and they reached the classroom on time.","dialogue":[],"vocabulary":[{"word":"printer","definition":"a machine that puts words on paper"},{"word":"panel","definition":"a cover on a machine that opens"},{"word":"folded","definition":"bent so one part lies on another"},{"word":"backup","definition":"an extra copy kept to be safe"},{"word":"memory","definition":"the part that stores information"},{"word":"tray","definition":"a shallow place where papers are set"}],"quiz":[{"question":"What did Hana pull out of the printer?","options":["A pencil case","A folded sheet","The class bell","A memory stick"],"correctAnswer":"A folded sheet","explanation":"She pulled out a folded sheet and then closed the panel.","supportingSentence":"She pulled out a folded sheet and closed the panel gently.","skill":"detail"},{"question":"Where did Hana put the memory stick?","options":["In her pencil case","On the teacher's desk","In the paper tray","Behind the front panel"],"correctAnswer":"In her pencil case","explanation":"She saved a copy on a memory stick and put the stick in her pencil case.","supportingSentence":"Hana saved a copy on a memory stick and put the stick in her pencil case.","skill":"detail"},{"question":"Which classmate had the same problem?","options":["The teacher","Hana's sister","The office clerk","Rafi"],"correctAnswer":"Rafi","explanation":"A classmate named Rafi had the same problem a minute later.","supportingSentence":"A classmate named Rafi had the same problem a minute later.","skill":"detail"},{"question":"In this story, what does backup mean?","options":["A picture of a stuck page","A bell at the end of class","An extra copy kept to be safe","A loud click from a machine"],"correctAnswer":"An extra copy kept to be safe","explanation":"The teacher asked for a backup, an extra copy kept in case.","supportingSentence":"The teacher had asked the class to keep a backup as well.","skill":"vocabulary"},{"question":"Why did Hana open the front of the printer?","options":["She wanted the machine off forever","The screen showed a page stuck inside","The class bell had already rung","Rafi told her to hide the paper"],"correctAnswer":"The screen showed a page stuck inside","explanation":"The screen showed a stuck page, so she opened the panel and cleared it.","supportingSentence":"A message on the screen showed a picture of a stuck page.","skill":"inference"}],"wordCount":146,"questionCount":5}$q91739$::jsonb,
  '7715865a5fd07e8224f990e08e6b6861ef7f5c4d897711145d55a015e4c2428d',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '41e2dbc0-d827-42b2-a674-1bebbfe2058e'::uuid,
  'reading',
  'B1',
  'text',
  $q4990${"topic":"technology","wordCount":145,"questionCount":5}$q4990$::jsonb,
  $q3645${"mode":"reading","level":"B1","format":"text","topic":"Technology","title":"Copies before the Storm","story":"A radio warning said a storm might cut the power that night. The family wanted to protect their holiday photos. Dad copied the pictures from the computer onto a spare drive. Mum checked that the files opened before they continued. They copied the school projects as well. Then they shut down the computer and unplugged it from the wall. They also unplugged the router and the printer. The youngest child, Leila, charged a small lamp while the power was still on. She put the lamp and the spare drive on a high shelf. When the lights went out, the house was dark but the files were safe. They played a quiet card game by the lamp. In the morning the power returned. Dad plugged the computer in and opened the beach album. Every photo was there, including the one of Leila with the red kite.","dialogue":[],"vocabulary":[{"word":"warning","definition":"a message that tells you about danger"},{"word":"spare","definition":"extra and ready if needed"},{"word":"unplugged","definition":"pulled the plug out of the socket"},{"word":"router","definition":"a device that sends internet to computers"},{"word":"album","definition":"a collection of photographs"},{"word":"power","definition":"electricity that runs lights and machines"}],"quiz":[{"question":"Where did Dad copy the holiday pictures?","options":["Only into a paper book","Onto a spare drive","Into the small lamp","Onto the router"],"correctAnswer":"Onto a spare drive","explanation":"Dad copied the pictures from the computer onto a spare drive.","supportingSentence":"Dad copied the pictures from the computer onto a spare drive.","skill":"detail"},{"question":"What did Leila charge before the lights failed?","options":["A small lamp","The red kite","A pack of cards","The printer"],"correctAnswer":"A small lamp","explanation":"Leila charged a small lamp while the power was still on.","supportingSentence":"The youngest child, Leila, charged a small lamp while the power was still on.","skill":"detail"},{"question":"Which photo does the story name at the end?","options":["Mum at a desk","A broken router","Dad standing in snow","Leila with the red kite"],"correctAnswer":"Leila with the red kite","explanation":"Every photo was there, including the one of Leila with the red kite.","supportingSentence":"Every photo was there, including the one of Leila with the red kite.","skill":"detail"},{"question":"In this story, what does power mean?","options":["A holiday photograph","A shelf above the desk","Electricity for lights and machines","A quiet card game"],"correctAnswer":"Electricity for lights and machines","explanation":"The storm might cut the power, and later the lights went out.","supportingSentence":"A radio warning said a storm might cut the power that night.","skill":"vocabulary"},{"question":"Why did the family unplug the computer?","options":["The holiday photos were already lost","Leila had broken the album","A storm might cut the electricity","They needed the shelf for books"],"correctAnswer":"A storm might cut the electricity","explanation":"A storm might cut the power, so they shut the computer down and unplugged it.","supportingSentence":"Then they shut down the computer and unplugged it from the wall.","skill":"inference"}],"wordCount":145,"questionCount":5}$q3645$::jsonb,
  '41e2dbc0d82772b2f6741bebbfe2058e4fb54ca7cc44a07e045dac78dfd5541c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1a032eaf-b823-4797-a025-1261e00b6b55'::uuid,
  'reading',
  'B1',
  'text',
  $q4633${"topic":"science","wordCount":142,"questionCount":5}$q4633$::jsonb,
  $q3934${"mode":"reading","level":"B1","format":"text","topic":"Science","title":"Pulse after the Stairs","story":"In science class the students learned how to feel a pulse in the wrist. The teacher showed them a gentle touch with two fingers. Each pair counted beats for half a minute while sitting still. Then they climbed the stairs to the next floor and back. They sat down and counted again at once. The number was higher after the stairs. Paolo and his partner wrote both results on a sheet. The teacher asked why the pulse changed. A student said the body needed more blood when the muscles worked hard. The class agreed and wrote that sentence in their books. They repeated the count after two minutes of rest. The number fell, but it was still above the first result. The teacher said this was normal for healthy students. They did not run, because the test was about a normal climb.","dialogue":[],"vocabulary":[{"word":"pulse","definition":"the beat of blood you can feel"},{"word":"wrist","definition":"the joint between the hand and the arm"},{"word":"beats","definition":"regular movements you can count"},{"word":"muscles","definition":"body parts that help you move"},{"word":"repeated","definition":"did something again"},{"word":"normal","definition":"usual and not a problem"}],"quiz":[{"question":"Where did the students learn to feel the pulse?","options":["In the wrist","On the knee","In the ear","On the back"],"correctAnswer":"In the wrist","explanation":"They learned how to feel a pulse in the wrist.","supportingSentence":"In science class the students learned how to feel a pulse in the wrist.","skill":"detail"},{"question":"What was different about the count after the stairs?","options":["The number stayed the same","The number was higher","They stopped writing results","The number fell to zero"],"correctAnswer":"The number was higher","explanation":"The number was higher after the stairs.","supportingSentence":"The number was higher after the stairs.","skill":"detail"},{"question":"What did the count do after two minutes of rest?","options":["It did not change at all","It could no longer be felt","It fell but stayed above the first result","It dropped below the first result"],"correctAnswer":"It fell but stayed above the first result","explanation":"The number fell, but it was still above the first result.","supportingSentence":"The number fell, but it was still above the first result.","skill":"detail"},{"question":"In this story, what does muscles mean?","options":["The steps between floors","Numbers written on a sheet","Books used for science","Body parts that help you move"],"correctAnswer":"Body parts that help you move","explanation":"The student said the muscles worked hard when the body climbed.","supportingSentence":"A student said the body needed more blood when the muscles worked hard.","skill":"vocabulary"},{"question":"Why did Paolo write down both results?","options":["So the two counts could be compared","So nobody would climb again","So the class could skip the rest","So the teacher would hide the sheet"],"correctAnswer":"So the two counts could be compared","explanation":"Both results were on one sheet, so the sitting count and the stair count could be compared.","supportingSentence":"Paolo and his partner wrote both results on a sheet.","skill":"inference"}],"wordCount":142,"questionCount":5}$q3934$::jsonb,
  '1a032eafb823979760251261e00b6b552d360ff667c03cec70b35f61fed79395',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '96aa4d16-d884-44d6-acd7-7377ff15fc75'::uuid,
  'reading',
  'B1',
  'text',
  $q4632${"topic":"science","wordCount":150,"questionCount":5}$q4632$::jsonb,
  $q76366${"mode":"reading","level":"B1","format":"text","topic":"Science","title":"Nests along the Hedge","story":"The science club counted bird nests in the school grounds on a dry morning. They stayed on the path and used binoculars. The rule was clear to everyone. They could look and record, but they could not touch. In the oak they found two nests high above the path. In the long hedge they found four more. A student named Ruth marked each nest on a simple map. She used a circle for the oak and a square for the hedge. Nobody climbed, and nobody used a stick. The teacher praised the group for leaving the birds in peace. They stored the map in a folder in the lab. The plan was to return in spring and see which nests were busy. Ruth copied the map into her notebook that evening. She added the date and the weather at the top. The club hoped the same birds would come back.","dialogue":[],"vocabulary":[{"word":"grounds","definition":"the land around a school"},{"word":"binoculars","definition":"a tool that makes far things look closer"},{"word":"hedge","definition":"a line of bushes"},{"word":"praised","definition":"said that someone had done well"},{"word":"peace","definition":"a calm state without harm"},{"word":"folder","definition":"a cover that keeps papers together"}],"quiz":[{"question":"How many nests did they find in the oak?","options":["Four","Six","Ten","Two"],"correctAnswer":"Two","explanation":"In the oak they found two nests high above the path.","supportingSentence":"In the oak they found two nests high above the path.","skill":"detail"},{"question":"How many nests did they find in the long hedge?","options":["One","Eight","Four","Two"],"correctAnswer":"Four","explanation":"In the long hedge they found four more nests.","supportingSentence":"In the long hedge they found four more.","skill":"detail"},{"question":"What mark did Ruth use for the hedge?","options":["A circle","A square","A triangle","A star"],"correctAnswer":"A square","explanation":"She used a square for the hedge and a circle for the oak.","supportingSentence":"She used a circle for the oak and a square for the hedge.","skill":"detail"},{"question":"In this story, what does binoculars mean?","options":["A tool that makes far things look closer","A stick for climbing trees","A map of the school grounds","A notebook for the weather"],"correctAnswer":"A tool that makes far things look closer","explanation":"They stayed on the path and used binoculars to see the nests from far away.","supportingSentence":"They stayed on the path and used binoculars.","skill":"vocabulary"},{"question":"Why were the students told not to touch the nests?","options":["So the map would stay blank","So they could carry the nests inside","So Ruth could climb the oak","So the birds would be left in peace"],"correctAnswer":"So the birds would be left in peace","explanation":"The teacher praised them for leaving the birds in peace, which the no-touch rule protected.","supportingSentence":"The teacher praised the group for leaving the birds in peace.","skill":"inference"}],"wordCount":150,"questionCount":5}$q76366$::jsonb,
  '96aa4d16d884d4d6acd77377ff15fc7526a97420253977ddfd8eacce2d158081',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '6906e988-b46a-40a6-a815-fe152e96a991'::uuid,
  'reading',
  'B1',
  'text',
  $q5489${"topic":"economy_finance","wordCount":147,"questionCount":5}$q5489$::jsonb,
  $q86072${"mode":"reading","level":"B1","format":"text","topic":"Economy / Finance","title":"The Weekly Bus Pass","story":"Farah paid for a single bus ride every school day. By Friday her purse was almost empty. Her father sat with her and listed the five fares on paper. Then he wrote the price of a weekly pass beside them. The pass cost less than the five rides together. Farah was surprised, because she had never compared the choices. She checked her jar of saved coins and found she had enough. On Monday she bought the pass at the station window. The clerk printed her name and the dates on it. Farah kept the pass in a hard pocket of her bag. Each morning she showed it to the driver instead of searching for coins. On Friday she still had money left for lunch. She recorded the saving in a notebook so she could see it. Next month she planned to buy the pass again on Sunday.","dialogue":[],"vocabulary":[{"word":"purse","definition":"a small bag used for money"},{"word":"fares","definition":"money paid for journeys"},{"word":"pass","definition":"a ticket you can use for several rides"},{"word":"compared","definition":"looked at choices to see the difference"},{"word":"clerk","definition":"a worker who serves people at a counter"},{"word":"saving","definition":"money kept because you spent less"}],"quiz":[{"question":"Which choice cost less?","options":["The weekly pass","A taxi every morning","Lunch in a cafe","The five single rides"],"correctAnswer":"The weekly pass","explanation":"The pass cost less than the five single rides together.","supportingSentence":"The pass cost less than the five rides together.","skill":"detail"},{"question":"When did Farah buy the pass?","options":["On Friday","At midnight","On Sunday night","On Monday"],"correctAnswer":"On Monday","explanation":"On Monday she bought the pass at the station window.","supportingSentence":"On Monday she bought the pass at the station window.","skill":"detail"},{"question":"What did Farah still have money for at the end of the week?","options":["A new purse","A second pass","Lunch","A taxi home"],"correctAnswer":"Lunch","explanation":"On Friday she still had money left for lunch.","supportingSentence":"On Friday she still had money left for lunch.","skill":"detail"},{"question":"In this story, what does compared mean?","options":["Paid twice for the same ride","Printed a name on a ticket","Looked at choices to see the difference","Lost coins from a purse"],"correctAnswer":"Looked at choices to see the difference","explanation":"She had never compared the choices, so she had not looked at them side by side.","supportingSentence":"Farah was surprised, because she had never compared the choices.","skill":"vocabulary"},{"question":"Why did Farah plan to buy the pass again?","options":["It cost less than paying for every ride","Her father lost the paper list","Single rides had become free","The clerk told her to stop riding"],"correctAnswer":"It cost less than paying for every ride","explanation":"The pass cost less than five rides, so she planned to buy another one.","supportingSentence":"Next month she planned to buy the pass again on Sunday.","skill":"inference"}],"wordCount":147,"questionCount":5}$q86072$::jsonb,
  '6906e988b46a80a62815fe152e96a99111275f1a72cda65274f0486b0f2251b4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '44cb71ab-41f1-4913-af21-659c195597b7'::uuid,
  'reading',
  'B1',
  'text',
  $q5485${"topic":"economy_finance","wordCount":143,"questionCount":5}$q5485$::jsonb,
  $q87567${"mode":"reading","level":"B1","format":"text","topic":"Economy / Finance","title":"An Early Fare to the Museum","story":"Luis and his mother compared two train fares to the city. The early train was cheaper, but it left at dawn. The later train cost more and arrived at the same station. They chose the early train and kept the difference for museum tickets. They packed their bags the night before and set an alarm. At dawn they walked to the station and bought tea. The carriage was quiet, and Luis read a guide to the museum. When they arrived, they used the saved money for two student tickets. Inside, they saw tools, maps, and a model of the old port. Luis took notes because his class was studying the city. At lunch they still had a little money left for soup. His mother said the early start had paid for the visit. Luis agreed and circled the cheap fare in the leaflet.","dialogue":[],"vocabulary":[{"word":"fares","definition":"the prices of journeys"},{"word":"dawn","definition":"the time when daylight begins"},{"word":"difference","definition":"the amount left between two prices"},{"word":"guide","definition":"a small book that describes a place"},{"word":"notes","definition":"short writing made to remember facts"},{"word":"leaflet","definition":"a printed sheet of information"}],"quiz":[{"question":"When did the cheaper train leave?","options":["In the evening","At midnight","At dawn","At noon"],"correctAnswer":"At dawn","explanation":"The early train was cheaper, but it left at dawn.","supportingSentence":"The early train was cheaper, but it left at dawn.","skill":"detail"},{"question":"What did they buy with the money they had saved?","options":["Tea for the whole carriage","A model to take home","A different train","Two student tickets"],"correctAnswer":"Two student tickets","explanation":"They used the saved money for two student tickets.","supportingSentence":"When they arrived, they used the saved money for two student tickets.","skill":"detail"},{"question":"What was Luis's class studying?","options":["The city","Wild animals","Football rules","Home cooking"],"correctAnswer":"The city","explanation":"Luis took notes because his class was studying the city.","supportingSentence":"Luis took notes because his class was studying the city.","skill":"detail"},{"question":"In this story, what does dawn mean?","options":["A cheap paper ticket","The time when daylight begins","A small model of a port","A bowl of hot soup"],"correctAnswer":"The time when daylight begins","explanation":"They walked to the station at dawn, the early start of the day.","supportingSentence":"At dawn they walked to the station and bought tea.","skill":"vocabulary"},{"question":"What did his mother mean about the early start?","options":["The museum charged nobody","They should have chosen the later train","The money saved paid for the museum","The train journey was a waste"],"correctAnswer":"The money saved paid for the museum","explanation":"They kept the cheaper fare's difference for tickets, so the early start paid for the visit.","supportingSentence":"His mother said the early start had paid for the visit.","skill":"inference"}],"wordCount":143,"questionCount":5}$q87567$::jsonb,
  '44cb71ab41f18913ff21659c195597b7275f75fd88e14fe9f2ef382e8c3d4f26',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '75304e99-0ed5-44ab-a221-b0d4a68fad7c'::uuid,
  'reading',
  'B1',
  'text',
  $q4704${"topic":"mystery","wordCount":146,"questionCount":5}$q4704$::jsonb,
  $q96483${"mode":"reading","level":"B1","format":"text","topic":"Mystery","title":"The Open Kitchen Window","story":"Sara came home and found the kitchen window open. A chair was pulled out, and a cup lay on its side. She felt afraid and called her brother, Idris. Together they checked the rooms, and nothing valuable was missing. Then they heard a soft sound from the bedroom. Their cat, Pip, walked out with a leaf caught on his tail. The window had a wide sill, and the tree outside stood close to it. Pip must have climbed in and knocked the cup over. Sara laughed with relief and closed the window. Idris wiped the table and set the chair back. They looked at the latch and saw that it was loose. Sara wrote a note asking everyone to test the latch before leaving. She fixed it that evening with a small screwdriver. The next morning the window stayed shut, and Pip waited by the door.","dialogue":[],"vocabulary":[{"word":"afraid","definition":"feeling that something bad may happen"},{"word":"valuable","definition":"important and worth a lot"},{"word":"sill","definition":"the flat shelf at the bottom of a window"},{"word":"relief","definition":"a calm feeling after fear goes away"},{"word":"latch","definition":"the fastening that keeps a window shut"},{"word":"screwdriver","definition":"a tool used to turn screws"}],"quiz":[{"question":"How did Sara find the cup?","options":["Lying on its side","Outside under the tree","Broken into many pieces","Full of hot tea"],"correctAnswer":"Lying on its side","explanation":"A cup lay on its side when she came into the kitchen.","supportingSentence":"A chair was pulled out, and a cup lay on its side.","skill":"detail"},{"question":"What did they learn about the valuable things?","options":["The television was gone","A bedroom window was smashed","Money was missing from a drawer","Nothing valuable was missing"],"correctAnswer":"Nothing valuable was missing","explanation":"They checked the rooms, and nothing valuable was missing.","supportingSentence":"Together they checked the rooms, and nothing valuable was missing.","skill":"detail"},{"question":"What came out of the bedroom?","options":["A neighbour with a key","A stranger in a coat","Their cat Pip","Idris from the street"],"correctAnswer":"Their cat Pip","explanation":"Their cat, Pip, walked out of the bedroom.","supportingSentence":"Their cat, Pip, walked out with a leaf caught on his tail.","skill":"detail"},{"question":"In this story, what does latch mean?","options":["A chair pulled from a desk","The fastening that keeps a window shut","A cup lying on a table","A leaf caught on fur"],"correctAnswer":"The fastening that keeps a window shut","explanation":"The latch was loose, and Sara fixed that window fastening later.","supportingSentence":"They looked at the latch and saw that it was loose.","skill":"vocabulary"},{"question":"Why did Sara stop feeling afraid?","options":["The cat had knocked the cup over","The flat was full of visitors","Idris had opened the window for air","A neighbour said he took the cup"],"correctAnswer":"The cat had knocked the cup over","explanation":"Pip must have climbed in and knocked the cup over, so nobody had broken in.","supportingSentence":"Pip must have climbed in and knocked the cup over.","skill":"inference"}],"wordCount":146,"questionCount":5}$q96483$::jsonb,
  '75304e990ed5a4ab1221b0d4a68fad7c7e2fcf84e18b9b7f37b8316a684472e1',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f4a48286-6ec7-4d96-ae6f-6c5187b755a1'::uuid,
  'reading',
  'B1',
  'text',
  $q4707${"topic":"mystery","wordCount":149,"questionCount":5}$q4707$::jsonb,
  $q83839${"mode":"reading","level":"B1","format":"text","topic":"Mystery","title":"The Note under the Bowl","story":"Ben left a slice of cake on the kitchen table before football. He covered it with a plate and planned to eat it later. When he returned, the plate was empty and clean. He asked the people at home, and each one said they had not taken it. Ben felt cross and looked for crumbs. There were no crumbs on the table or the floor. Then he lifted the fruit bowl and found a folded note underneath. The note was from his little sister, Aya. She had taken the slice to school to share with a new student. She had washed the plate and hidden the note so it would be a surprise. Ben read it twice and stopped feeling cross. He left a reply under the same bowl. In the reply he thanked Aya and said the next slice would be hers. The mystery had a kind ending.","dialogue":[],"vocabulary":[{"word":"slice","definition":"a piece cut from a larger cake"},{"word":"crumbs","definition":"very small pieces that fall from food"},{"word":"folded","definition":"bent closed, like a piece of paper"},{"word":"surprise","definition":"something you do not expect"},{"word":"reply","definition":"an answer to a message"},{"word":"mystery","definition":"a strange event that needs explaining"}],"quiz":[{"question":"Where did Ben find the folded note?","options":["On top of the clean plate","In his football bag","Under the fruit bowl","Outside the kitchen door"],"correctAnswer":"Under the fruit bowl","explanation":"He lifted the fruit bowl and found the note underneath it.","supportingSentence":"Then he lifted the fruit bowl and found a folded note underneath.","skill":"detail"},{"question":"Who had written the note?","options":["His football coach","The new student","His little sister Aya","A neighbour"],"correctAnswer":"His little sister Aya","explanation":"The note was from his little sister, Aya.","supportingSentence":"The note was from his little sister, Aya.","skill":"detail"},{"question":"Who would get the next slice, according to Ben?","options":["Aya","His coach","Nobody","A visitor"],"correctAnswer":"Aya","explanation":"He said the next slice would be hers, and hers means Aya.","supportingSentence":"In the reply he thanked Aya and said the next slice would be hers.","skill":"detail"},{"question":"In this story, what does surprise mean?","options":["A clean empty plate","A second piece of cake","A game of football","Something you do not expect"],"correctAnswer":"Something you do not expect","explanation":"She hid the note so the news would be a surprise Ben did not expect.","supportingSentence":"She had washed the plate and hidden the note so it would be a surprise.","skill":"vocabulary"},{"question":"Why did Ben stop feeling cross?","options":["The family had eaten it as a joke","The cake was still on the plate","Aya had shared the cake kindly","Crumbs covered the kitchen floor"],"correctAnswer":"Aya had shared the cake kindly","explanation":"The note said Aya had shared the slice with a new student, so his anger passed.","supportingSentence":"She had taken the slice to school to share with a new student.","skill":"inference"}],"wordCount":149,"questionCount":5}$q83839$::jsonb,
  'f4a482866ec7dd96fe6f6c5187b755a1b98647c5fc21b40b4a5296703c3b76c9',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'd4b79b49-df48-4378-afa1-5aa84e10ba21'::uuid,
  'reading',
  'B1',
  'text',
  $q4878${"topic":"adventure","wordCount":143,"questionCount":5}$q4878$::jsonb,
  $q82407${"mode":"reading","level":"B1","format":"text","topic":"Adventure","title":"The Ledge behind the Waterfall","story":"On a school hike, the guide led the group to a small waterfall. A safe path went behind the water to a dry ledge. Everyone put on a jacket and held the guide rope. They stepped on wet stones one person at a time. Behind the falling water, the air was cool and loud. They could see the trees outside as a soft green blur. The guide said they must leave before the light faded. They returned the same way and moved slowly. At the bottom the guide counted every person. All twelve were present, and nobody had slipped. The group ate sandwiches on a warm rock in the sun. The guide marked the waterfall on the hike card as a careful place. Students wrote one sentence about what they had seen. They agreed the ledge was wonderful, but only with a guide.","dialogue":[],"vocabulary":[{"word":"waterfall","definition":"water falling from a high place"},{"word":"ledge","definition":"a narrow flat place like a rock shelf"},{"word":"rope","definition":"a thick strong cord"},{"word":"blur","definition":"a shape that is not clear"},{"word":"faded","definition":"became weaker, as evening light does"},{"word":"counted","definition":"found how many there were"}],"quiz":[{"question":"Where did the safe path lead?","options":["Across a busy road","To a dry ledge behind the water","Over the tops of the trees","Down into a dark cave"],"correctAnswer":"To a dry ledge behind the water","explanation":"A safe path went behind the water to a dry ledge.","supportingSentence":"A safe path went behind the water to a dry ledge.","skill":"detail"},{"question":"How many people were there when the guide counted?","options":["All twelve","Ten people","Only the guide","Nobody"],"correctAnswer":"All twelve","explanation":"All twelve were present, and nobody had slipped.","supportingSentence":"All twelve were present, and nobody had slipped.","skill":"detail"},{"question":"What did the group eat after leaving the waterfall?","options":["Hot soup","Cake from home","Nothing at all","Sandwiches"],"correctAnswer":"Sandwiches","explanation":"The group ate sandwiches on a warm rock in the sun.","supportingSentence":"The group ate sandwiches on a warm rock in the sun.","skill":"detail"},{"question":"In this story, what does blur mean?","options":["A thick guide rope","A warm seat in the sun","A shape that is not clear","A dry shelf of rock"],"correctAnswer":"A shape that is not clear","explanation":"The trees looked like a soft green blur, so their shapes were not clear.","supportingSentence":"They could see the trees outside as a soft green blur.","skill":"vocabulary"},{"question":"Why did the group move slowly on the way back?","options":["The sandwiches were too heavy","The wet stones needed careful steps","The sun had made the path too hot","The guide had lost the rope"],"correctAnswer":"The wet stones needed careful steps","explanation":"They had to step on wet stones one at a time, so the return was slow as well.","supportingSentence":"They stepped on wet stones one person at a time.","skill":"inference"}],"wordCount":143,"questionCount":5}$q82407$::jsonb,
  'd4b79b49df4813783fa15aa84e10ba21df540820bfd0f02f843f3cac3ecafeba',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '135ea585-a196-4fc2-ac22-6b020b20193e'::uuid,
  'reading',
  'B1',
  'text',
  $q4661${"topic":"fantasy","wordCount":151,"questionCount":5}$q4661$::jsonb,
  $q82252${"mode":"reading","level":"B1","format":"text","topic":"Fantasy","title":"The Cup That Stayed Warm","story":"In the village of Brindle, an old cup sat on the inn table. It stayed warm only when a drink was shared. If someone drank alone, the tea turned cold at once. A girl named Nia poured a full cup on a cold evening. A traveller came in with wet boots and no drink. Nia pushed the cup toward him and asked him to take half. The tea grew hot again, and a soft gold light rose from the cup. The owner smiled and explained the rule. The cup was not a trick for guests to fear. It reminded the village that comfort should be shared. Nia and the traveller talked until their boots were dry. Before he left, he poured a fresh cup and offered it back to her. The light returned, and the inn felt kind. Nia washed the cup each week so the glow was easy to see.","dialogue":[],"vocabulary":[{"word":"village","definition":"a small group of homes in the country"},{"word":"shared","definition":"used or given by more than one person"},{"word":"traveller","definition":"a person who is on a journey"},{"word":"glow","definition":"a soft light"},{"word":"comfort","definition":"a warm and safe feeling"},{"word":"inn","definition":"a small place where travellers can rest and eat"}],"quiz":[{"question":"When did the old cup stay warm?","options":["When the cup was empty","When a drink was shared","When someone drank alone","Only at noon"],"correctAnswer":"When a drink was shared","explanation":"It stayed warm only when a drink was shared.","supportingSentence":"It stayed warm only when a drink was shared.","skill":"detail"},{"question":"Who came into the inn needing a drink?","options":["A traveller with wet boots","Nia's teacher","The village mayor","A child from the school"],"correctAnswer":"A traveller with wet boots","explanation":"A traveller came in with wet boots and no drink.","supportingSentence":"A traveller came in with wet boots and no drink.","skill":"detail"},{"question":"What rose from the cup when the tea grew hot again?","options":["A cloud of smoke","A loud bell","A stream of cold water","A soft gold light"],"correctAnswer":"A soft gold light","explanation":"A soft gold light rose from the cup when the tea grew hot again.","supportingSentence":"The tea grew hot again, and a soft gold light rose from the cup.","skill":"detail"},{"question":"In this story, what does glow mean?","options":["A soft light","A long journey","A wet boot","A cold drink"],"correctAnswer":"A soft light","explanation":"Nia washed the cup so the glow, its soft light, was easy to see.","supportingSentence":"Nia washed the cup each week so the glow was easy to see.","skill":"vocabulary"},{"question":"Why did the light come back before the traveller left?","options":["The tea stayed cold on the table","He shared a fresh cup with Nia","Nia finished a full cup alone","The owner hid the cup away"],"correctAnswer":"He shared a fresh cup with Nia","explanation":"He offered Nia a fresh cup, and the light returns when a drink is shared.","supportingSentence":"Before he left, he poured a fresh cup and offered it back to her.","skill":"inference"}],"wordCount":151,"questionCount":5}$q82252$::jsonb,
  '135ea585a1965fc28c226b020b20193ee21d683f866b361e330b19f7c98c627f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '15bb230a-5add-41f8-afed-31114494aeef'::uuid,
  'reading',
  'B1',
  'text',
  $q4837${"topic":"daily life","wordCount":64,"questionCount":5}$q4837$::jsonb,
  $q54716${"mode":"reading","level":"B1","format":"text","topic":"Daily Life","title":"Keys on the Hook","story":"Every evening Nora hangs her keys on the hook by the door. Last night she left them in her coat pocket. In the morning she searched the table, the sofa, and her bag. Her sister found the keys and held them up. Nora thanked her and put the keys on the hook. She set a note on the door so she would remember tomorrow.","dialogue":[],"vocabulary":[{"word":"hook","definition":"A curved holder for hanging keys."},{"word":"pocket","definition":"A small bag sewn into clothing."},{"word":"searched","definition":"Looked carefully in several places."},{"word":"sofa","definition":"A long soft seat for two or more people."},{"word":"thanked","definition":"Told someone you are grateful."},{"word":"remember","definition":"To keep something in your mind."}],"quiz":[{"question":"Where does Nora usually hang her keys?","options":["On the kitchen sofa","In her coat pocket","On the hook by the door","Inside her sister's bag"],"correctAnswer":"On the hook by the door","explanation":"She hangs them on the hook by the door every evening.","supportingSentence":"Every evening Nora hangs her keys on the hook by the door.","skill":"detail"},{"question":"Where had the keys been during the night?","options":["In her sister's hand","In her coat pocket","On the hook by the door","Under the note"],"correctAnswer":"In her coat pocket","explanation":"Last night she left the keys in her coat pocket.","supportingSentence":"Last night she left them in her coat pocket.","skill":"detail"},{"question":"What did Nora do after she thanked her sister?","options":["She put the keys on the hook","She hid the keys in her bag","She gave the keys away","She left the keys in the coat"],"correctAnswer":"She put the keys on the hook","explanation":"After thanking her sister, Nora put the keys on the hook.","supportingSentence":"Nora thanked her and put the keys on the hook.","skill":"detail"},{"question":"What does searched mean in this story?","options":["Hung an object on a wall","Wrote a short reminder","Made a hot drink","Looked carefully for something"],"correctAnswer":"Looked carefully for something","explanation":"Nora searched the table, the sofa, and her bag because she was looking for the keys.","supportingSentence":"In the morning she searched the table, the sofa, and her bag.","skill":"vocabulary"},{"question":"Why did Nora set a note on the door?","options":["The sofa was blocking the door","Her sister could not reach the hook","She wanted a reminder for the next day","The keys were still missing"],"correctAnswer":"She wanted a reminder for the next day","explanation":"She set the note so she would remember tomorrow.","supportingSentence":"She set a note on the door so she would remember tomorrow.","skill":"inference"}],"wordCount":64,"questionCount":5}$q54716$::jsonb,
  '15bb230a5add21f84fed31114494aeeffe3a10df35dad5d450cf34ca489609d4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '302d8c53-5f2c-4a4b-a15b-bedc651abc70'::uuid,
  'reading',
  'B1',
  'text',
  $q4839${"topic":"daily life","wordCount":66,"questionCount":5}$q4839$::jsonb,
  $q55852${"mode":"reading","level":"B1","format":"text","topic":"Daily Life","title":"Rain before Breakfast","story":"It started to rain while Mateo made breakfast. He had left the windows open, so the curtains got wet. He closed them and wiped the floor with a towel. Then he saw his neighbour outside without a coat. Mateo took a spare umbrella from the hall and crossed the street. The neighbour smiled and promised to return it after work. Mateo went back to his toast.","dialogue":[],"vocabulary":[{"word":"curtains","definition":"Cloth covers that hang at a window."},{"word":"wiped","definition":"Rubbed a surface to make it dry."},{"word":"towel","definition":"A cloth used for drying."},{"word":"spare","definition":"Extra and not already in use."},{"word":"umbrella","definition":"A cover you hold to stay dry in rain."},{"word":"promised","definition":"Said firmly that you will do something."}],"quiz":[{"question":"What was Mateo doing when the rain began?","options":["Buying a coat","Walking to work","Making breakfast","Closing the shop"],"correctAnswer":"Making breakfast","explanation":"The rain started while Mateo made breakfast.","supportingSentence":"It started to rain while Mateo made breakfast.","skill":"detail"},{"question":"Why did the curtains get wet?","options":["The toast was still hot","The windows had been left open","The towel fell outside","The neighbour opened the door"],"correctAnswer":"The windows had been left open","explanation":"He had left the windows open, so the curtains got wet.","supportingSentence":"He had left the windows open, so the curtains got wet.","skill":"detail"},{"question":"What did Mateo carry across the street?","options":["A spare umbrella","His winter coat","A plate of toast","A wet towel"],"correctAnswer":"A spare umbrella","explanation":"He took a spare umbrella from the hall and crossed the street.","supportingSentence":"Mateo took a spare umbrella from the hall and crossed the street.","skill":"detail"},{"question":"What does spare mean in this story?","options":["Broken and useless","Already soaking wet","Too heavy to carry","Extra and ready if needed"],"correctAnswer":"Extra and ready if needed","explanation":"The spare umbrella was an extra one that Mateo could lend.","supportingSentence":"Mateo took a spare umbrella from the hall and crossed the street.","skill":"vocabulary"},{"question":"Why did the neighbour promise to return the umbrella?","options":["Mateo asked him to buy toast","The rain had already stopped","It belonged to Mateo","The windows were still open"],"correctAnswer":"It belonged to Mateo","explanation":"People return something they have borrowed, and the neighbour promised to return the umbrella after work.","supportingSentence":"The neighbour smiled and promised to return it after work.","skill":"inference"}],"wordCount":66,"questionCount":5}$q55852$::jsonb,
  '302d8c535f2cda4b915bbedc651abc704af08cb8288080dc5791c52e977eda43',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '83b1fc6f-96bd-4e41-ad73-9892b6ef87e0'::uuid,
  'reading',
  'B1',
  'text',
  $q5334${"topic":"school_college","wordCount":66,"questionCount":5}$q5334$::jsonb,
  $q53520${"mode":"reading","level":"B1","format":"text","topic":"School / College","title":"A Stamp from the Library","story":"Priya needed a book for history class. She went to the school library after lunch. The book was on a high shelf, so the librarian reached it for her. Priya did not have her card, and the librarian could not lend it. Priya ran to her locker and found the card in her pencil case. She returned, got the stamp, and still had time for class.","dialogue":[],"vocabulary":[{"word":"history","definition":"The study of past events."},{"word":"librarian","definition":"A person who works in a library."},{"word":"shelf","definition":"A flat board used for storing things."},{"word":"lend","definition":"To let someone borrow something."},{"word":"locker","definition":"A small cupboard with a lock at school."},{"word":"stamp","definition":"A mark that shows a book was borrowed."}],"quiz":[{"question":"Why did Priya need a book?","options":["To give to a friend","For history class","For a cooking test","To replace her pencil case"],"correctAnswer":"For history class","explanation":"Priya needed a book for history class.","supportingSentence":"Priya needed a book for history class.","skill":"detail"},{"question":"Where was the book before the librarian helped?","options":["On a high shelf","Inside the locker","In the pencil case","On the lunch table"],"correctAnswer":"On a high shelf","explanation":"The book was on a high shelf, so the librarian reached it.","supportingSentence":"The book was on a high shelf, so the librarian reached it for her.","skill":"detail"},{"question":"Why could the librarian not lend the book at first?","options":["The shelf was empty","Lunch was not over","The library was closed","Priya did not have her card"],"correctAnswer":"Priya did not have her card","explanation":"Priya did not have her card, so the librarian could not lend the book.","supportingSentence":"Priya did not have her card, and the librarian could not lend it.","skill":"detail"},{"question":"What does lend mean in this story?","options":["To let someone borrow an item","To eat lunch quickly","To run to a locker","To close a high shelf"],"correctAnswer":"To let someone borrow an item","explanation":"The librarian could not lend the book means she could not let Priya borrow it.","supportingSentence":"Priya did not have her card, and the librarian could not lend it.","skill":"vocabulary"},{"question":"Why did Priya run to her locker?","options":["Her lunch was getting cold","Her library card was there","Class had already finished","The stamp was in the locker"],"correctAnswer":"Her library card was there","explanation":"She ran to the locker and found the card in her pencil case.","supportingSentence":"Priya ran to her locker and found the card in her pencil case.","skill":"inference"}],"wordCount":66,"questionCount":5}$q53520$::jsonb,
  '83b1fc6f96bdae41ed739892b6ef87e096d501cc04c537b7c2890e2f48a5a6c6',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'a28eaacc-a597-4d69-a2a8-f8b77a187a76'::uuid,
  'reading',
  'B1',
  'text',
  $q5333${"topic":"school_college","wordCount":65,"questionCount":5}$q5333$::jsonb,
  $q38514${"mode":"reading","level":"B1","format":"text","topic":"School / College","title":"Finishing the Class Poster","story":"The class had to finish a poster before the bell. Amir drew the map, and Noor wrote the labels. Their glue was dry, so the corners would not stay down. Noor borrowed a new stick from the art room. They pressed each corner and checked the spelling. The teacher smiled and hung the poster by the door. They sat down just as the bell rang.","dialogue":[],"vocabulary":[{"word":"poster","definition":"A large sheet with words or pictures."},{"word":"labels","definition":"Short words that name parts of a picture."},{"word":"glue","definition":"A sticky substance used to join things."},{"word":"borrowed","definition":"Took something for a short time."},{"word":"spelling","definition":"The correct letters in a word."},{"word":"bell","definition":"A signal that a school lesson is over."}],"quiz":[{"question":"What did the class have to finish before the bell?","options":["A music show","A sports game","A long test","A poster"],"correctAnswer":"A poster","explanation":"The class had to finish a poster before the bell.","supportingSentence":"The class had to finish a poster before the bell.","skill":"detail"},{"question":"What was wrong with their glue?","options":["The teacher had taken it","It was the wrong colour","It was dry","It was too runny"],"correctAnswer":"It was dry","explanation":"Their glue was dry, so the corners would not stay down.","supportingSentence":"Their glue was dry, so the corners would not stay down.","skill":"detail"},{"question":"Where did the teacher hang the poster?","options":["In the art room","By the door","On Amir's desk","Under the bell"],"correctAnswer":"By the door","explanation":"The teacher hung the poster by the door.","supportingSentence":"The teacher smiled and hung the poster by the door.","skill":"detail"},{"question":"What does borrowed mean in this story?","options":["Took something to use and give back","Checked the letters in a word","Drew a map on paper","Sat down before the bell"],"correctAnswer":"Took something to use and give back","explanation":"Noor borrowed a new stick, which means she took it to use for a short time.","supportingSentence":"Noor borrowed a new stick from the art room.","skill":"vocabulary"},{"question":"What did they check after pressing the corners?","options":["The teacher's coat","The dry glue stick","The art room clock","The spelling"],"correctAnswer":"The spelling","explanation":"They pressed each corner and checked the spelling.","supportingSentence":"They pressed each corner and checked the spelling.","skill":"detail"}],"wordCount":65,"questionCount":5}$q38514$::jsonb,
  'a28eaacca597ad6992a8f8b77a187a766811bf96cb6d94839ad3fcddf2fa5c59',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'b0aadb65-51da-4849-a80f-639e533ba584'::uuid,
  'reading',
  'B1',
  'text',
  $q4514${"topic":"travel","wordCount":66,"questionCount":5}$q4514$::jsonb,
  $q57018${"mode":"reading","level":"B1","format":"text","topic":"Travel","title":"A Change of Platform","story":"Leila arrived at the station with ten minutes to spare. A screen said her train would leave from platform four, not platform two. She walked through the tunnel and found the right stairs. Her carriage was near the front. She showed her ticket, sat by the window, and sent a message to her uncle. The train left on time, and she watched the fields go by.","dialogue":[],"vocabulary":[{"word":"spare","definition":"Extra time before you must leave."},{"word":"platform","definition":"The place beside the tracks where you board."},{"word":"tunnel","definition":"A covered path that goes underground."},{"word":"carriage","definition":"A section of a train where people sit."},{"word":"ticket","definition":"A paper or pass that lets you travel."},{"word":"fields","definition":"Open areas of land, often with crops."}],"quiz":[{"question":"How much time did Leila have when she arrived?","options":["Ten minutes","Four minutes","Two minutes","No time at all"],"correctAnswer":"Ten minutes","explanation":"She arrived at the station with ten minutes to spare.","supportingSentence":"Leila arrived at the station with ten minutes to spare.","skill":"detail"},{"question":"Which platform did the screen give for her train?","options":["Platform two","Platform four","The open fields","The ticket office"],"correctAnswer":"Platform four","explanation":"The screen said the train would leave from platform four.","supportingSentence":"A screen said her train would leave from platform four, not platform two.","skill":"detail"},{"question":"Where did Leila sit in the carriage?","options":["In the tunnel","At the back of the station","By the window","Beside her uncle"],"correctAnswer":"By the window","explanation":"She sat by the window after showing her ticket.","supportingSentence":"She showed her ticket, sat by the window, and sent a message to her uncle.","skill":"detail"},{"question":"What is a carriage in this story?","options":["A road under the station","A paper that lets you travel","A message sent to family","A part of the train where people sit"],"correctAnswer":"A part of the train where people sit","explanation":"Her carriage was near the front of the train, where passengers sit.","supportingSentence":"Her carriage was near the front.","skill":"vocabulary"},{"question":"Why did Leila walk through the tunnel?","options":["She needed to reach the right platform","Her uncle was waiting there","She wanted to buy a new ticket","The train had already left"],"correctAnswer":"She needed to reach the right platform","explanation":"The platform had changed, and she walked through the tunnel to the right stairs.","supportingSentence":"She walked through the tunnel and found the right stairs.","skill":"inference"}],"wordCount":66,"questionCount":5}$q57018$::jsonb,
  'b0aadb6551da5849680f639e533ba58442c7bf0076ea55cb0d5c4467fede17ce',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '2c77474f-5348-4c27-a209-9a9f246df7a2'::uuid,
  'reading',
  'B1',
  'text',
  $q4514${"topic":"travel","wordCount":66,"questionCount":5}$q4514$::jsonb,
  $q27417${"mode":"reading","level":"B1","format":"text","topic":"Travel","title":"A Bed by the Window","story":"Jonah reached the guesthouse after dark. The owner gave him a key and pointed upstairs. His bed was the lower bunk beside the window. He put his backpack under the bed and filled a bottle in the hall. Another guest was asleep, so Jonah kept his voice low. In the morning he asked about the bus to town. The owner wrote the times on a card.","dialogue":[],"vocabulary":[{"word":"guesthouse","definition":"A small place where travellers can stay."},{"word":"bunk","definition":"A bed that is part of a stacked pair."},{"word":"backpack","definition":"A bag worn on the back."},{"word":"guest","definition":"A person staying at a place."},{"word":"voice","definition":"The sound a person makes when speaking."},{"word":"times","definition":"The hours when something happens."}],"quiz":[{"question":"When did Jonah reach the guesthouse?","options":["After dark","At noon","Before sunrise","During lunch"],"correctAnswer":"After dark","explanation":"Jonah reached the guesthouse after dark.","supportingSentence":"Jonah reached the guesthouse after dark.","skill":"detail"},{"question":"Which bed was Jonah's?","options":["A top bunk by the door","A seat on the bus","The lower bunk beside the window","A sofa in the hall"],"correctAnswer":"The lower bunk beside the window","explanation":"His bed was the lower bunk beside the window.","supportingSentence":"His bed was the lower bunk beside the window.","skill":"detail"},{"question":"Where did Jonah put his backpack?","options":["Under the bed","In the owner's office","Beside the sleeping guest","On the window ledge"],"correctAnswer":"Under the bed","explanation":"He put his backpack under the bed.","supportingSentence":"He put his backpack under the bed and filled a bottle in the hall.","skill":"detail"},{"question":"What is a bunk in this story?","options":["A bus into town","A card with written hours","A key for a room","A bed in a stacked pair"],"correctAnswer":"A bed in a stacked pair","explanation":"The lower bunk is the bottom bed of a stacked pair.","supportingSentence":"His bed was the lower bunk beside the window.","skill":"vocabulary"},{"question":"What did Jonah ask about in the morning?","options":["The bus to town","A second room key","The other guest's name","A new backpack"],"correctAnswer":"The bus to town","explanation":"In the morning he asked about the bus to town.","supportingSentence":"In the morning he asked about the bus to town.","skill":"detail"}],"wordCount":66,"questionCount":5}$q27417$::jsonb,
  '2c77474f53480c2772099a9f246df7a25597a4d2684feba5c2f31ff79119e3ea',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1aba52a0-11b2-4163-af6f-925e6c179d0b'::uuid,
  'reading',
  'B1',
  'text',
  $q4591${"topic":"hobbies","wordCount":65,"questionCount":5}$q4591$::jsonb,
  $q21029${"mode":"reading","level":"B1","format":"text","topic":"Hobbies","title":"Pages in a Sketchbook","story":"Hana draws in a sketchbook every Sunday. This week she sat in the park and drew the stone bridge. A child asked if he could watch, and Hana nodded. She showed him how to hold the pencil lightly. The child drew a duck and grinned. Hana gave him a spare page to take home. She stayed until the light faded and then closed the book.","dialogue":[],"vocabulary":[{"word":"sketchbook","definition":"A book of blank pages for drawing."},{"word":"bridge","definition":"A structure that lets people cross water."},{"word":"nodded","definition":"Moved the head up and down to say yes."},{"word":"pencil","definition":"A tool used for writing or drawing."},{"word":"grinned","definition":"Smiled widely."},{"word":"faded","definition":"Became weaker or less bright."}],"quiz":[{"question":"What does Hana do every Sunday?","options":["She draws in a sketchbook","She feeds the ducks","She teaches a park class","She sells stone bridges"],"correctAnswer":"She draws in a sketchbook","explanation":"Hana draws in a sketchbook every Sunday.","supportingSentence":"Hana draws in a sketchbook every Sunday.","skill":"detail"},{"question":"What did Hana draw in the park?","options":["A duck","The closed book","The stone bridge","A spare page"],"correctAnswer":"The stone bridge","explanation":"She sat in the park and drew the stone bridge.","supportingSentence":"This week she sat in the park and drew the stone bridge.","skill":"detail"},{"question":"What did the child draw?","options":["A duck","A pencil","The park gate","The stone bridge"],"correctAnswer":"A duck","explanation":"The child drew a duck and grinned.","supportingSentence":"The child drew a duck and grinned.","skill":"detail"},{"question":"What does nodded mean in this story?","options":["Closed a book slowly","Gave a page away","Drew a very light line","Moved her head to say yes"],"correctAnswer":"Moved her head to say yes","explanation":"When the child asked to watch, Hana nodded to show that he could.","supportingSentence":"A child asked if he could watch, and Hana nodded.","skill":"vocabulary"},{"question":"What did Hana give the child to take home?","options":["A spare page","Her whole sketchbook","The bridge drawing","A new pencil"],"correctAnswer":"A spare page","explanation":"Hana gave him a spare page to take home.","supportingSentence":"Hana gave him a spare page to take home.","skill":"detail"}],"wordCount":65,"questionCount":5}$q21029$::jsonb,
  '1aba52a011b251633f6f925e6c179d0bd6e322b0ecc42ee42a8f16f184f024da',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'cde10969-1ffe-4f4b-a391-202641e850d0'::uuid,
  'reading',
  'B1',
  'text',
  $q4589${"topic":"hobbies","wordCount":63,"questionCount":5}$q4589$::jsonb,
  $q37660${"mode":"reading","level":"B1","format":"text","topic":"Hobbies","title":"Practice in the Hall","story":"Rafi joined a small choir that meets on Thursdays. He did not know the new song, so he listened first. The leader asked him to sing the low part softly. Rafi marked the hard lines with a pencil. They recorded one verse on a phone to hear their mistakes. Rafi walked home humming the tune. He promised to practise before the next meeting.","dialogue":[],"vocabulary":[{"word":"choir","definition":"A group of people who sing together."},{"word":"softly","definition":"In a quiet and gentle way."},{"word":"marked","definition":"Made a sign on something."},{"word":"verse","definition":"One section of a song."},{"word":"mistakes","definition":"Things that are not correct."},{"word":"humming","definition":"Singing a tune with the mouth closed."}],"quiz":[{"question":"When does the choir meet?","options":["Every day after lunch","Once a year","On Sunday mornings","On Thursdays"],"correctAnswer":"On Thursdays","explanation":"Rafi joined a choir that meets on Thursdays.","supportingSentence":"Rafi joined a small choir that meets on Thursdays.","skill":"detail"},{"question":"Why did Rafi listen before he sang?","options":["His pencil was broken","The phone would not record","He did not know the new song","The leader was absent"],"correctAnswer":"He did not know the new song","explanation":"He did not know the new song, so he listened first.","supportingSentence":"He did not know the new song, so he listened first.","skill":"detail"},{"question":"Which part did the leader ask Rafi to sing?","options":["The high part","No part at all","The low part","The drum part"],"correctAnswer":"The low part","explanation":"The leader asked him to sing the low part softly.","supportingSentence":"The leader asked him to sing the low part softly.","skill":"detail"},{"question":"What does humming mean in this story?","options":["Singing a tune with a closed mouth","Writing notes on paper","Recording a song on a phone","Marking lines with a pencil"],"correctAnswer":"Singing a tune with a closed mouth","explanation":"Rafi walked home humming the tune, making the song without open words.","supportingSentence":"Rafi walked home humming the tune.","skill":"vocabulary"},{"question":"Why did the choir record a verse?","options":["To wake the neighbours","To teach the high part","To sell the song","To hear their mistakes"],"correctAnswer":"To hear their mistakes","explanation":"They recorded one verse to hear their mistakes.","supportingSentence":"They recorded one verse on a phone to hear their mistakes.","skill":"detail"}],"wordCount":63,"questionCount":5}$q37660$::jsonb,
  'cde109691ffedf4b1391202641e850d0ec98250c81ac8c14d9b7034768283e8f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
