  'text',
  $q5265${"topic":"health_sports","wordCount":63,"questionCount":5}$q5265$::jsonb,
  $q32340${"mode":"reading","level":"B1","format":"text","topic":"Health & Sports","title":"Water before the Match","story":"Before the match, Coach Elena told the team to drink water. Omar had forgotten his bottle, so a teammate shared hers. They stretched and jogged around the court twice. During the game Omar felt hot but kept going. At the break he sat in the shade and ate a banana. The team won by two points. Omar filled his bottle for next time.","dialogue":[],"vocabulary":[{"word":"match","definition":"A game between two sides."},{"word":"forgotten","definition":"Failed to remember something."},{"word":"stretched","definition":"Moved the body to loosen the muscles."},{"word":"court","definition":"The marked area where a game is played."},{"word":"shade","definition":"A cooler place out of the sun."},{"word":"points","definition":"The units used to keep a game score."}],"quiz":[{"question":"What did Coach Elena tell the team to drink?","options":["Cold tea","Nothing until the end","Juice","Water"],"correctAnswer":"Water","explanation":"Coach Elena told the team to drink water.","supportingSentence":"Before the match, Coach Elena told the team to drink water.","skill":"detail"},{"question":"Why did a teammate share her bottle?","options":["The court had no tap","The banana was too dry","Omar had forgotten his own","The coach banned every bottle"],"correctAnswer":"Omar had forgotten his own","explanation":"Omar had forgotten his bottle, so a teammate shared hers.","supportingSentence":"Omar had forgotten his bottle, so a teammate shared hers.","skill":"detail"},{"question":"Where did Omar sit at the break?","options":["In the middle of the court","In the shade","Beside the score table","On the team bus"],"correctAnswer":"In the shade","explanation":"At the break he sat in the shade and ate a banana.","supportingSentence":"At the break he sat in the shade and ate a banana.","skill":"detail"},{"question":"What does stretched mean in this story?","options":["Moved the body to loosen it","Drank water very slowly","Won a game by a small score","Sat down because of heat"],"correctAnswer":"Moved the body to loosen it","explanation":"They stretched before jogging, which means they loosened their bodies.","supportingSentence":"They stretched and jogged around the court twice.","skill":"vocabulary"},{"question":"By how many points did the team win?","options":["Ten points","They lost the match","One point","Two points"],"correctAnswer":"Two points","explanation":"The team won by two points.","supportingSentence":"The team won by two points.","skill":"detail"}],"wordCount":63,"questionCount":5}$q32340$::jsonb,
  '80d3b3fd04c67fb6f430a005e2dfa4d40a83e8e62b60c57cff1e98ae02776846',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '571180e0-8e09-44c5-a75b-0e3df8de4b50'::uuid,
  'reading',
  'B1',
  'text',
  $q5263${"topic":"health_sports","wordCount":61,"questionCount":5}$q5263$::jsonb,
  $q32230${"mode":"reading","level":"B1","format":"text","topic":"Health & Sports","title":"Back in the Pool","story":"After a cold, Yasmin's doctor said she could swim again, but gently. She went to the pool on Saturday. For ten minutes she kicked slowly at the shallow end. Then she swam one easy length and rested. Her arms felt tired, so she did not race her friend. She left before the busy hour and wrote the time in a notebook.","dialogue":[],"vocabulary":[{"word":"gently","definition":"In a careful and soft way."},{"word":"shallow","definition":"Not deep."},{"word":"length","definition":"One swim from one end of a pool to the other."},{"word":"rested","definition":"Stopped activity in order to recover."},{"word":"race","definition":"To compete to finish first."},{"word":"notebook","definition":"A small book for writing notes."}],"quiz":[{"question":"What did the doctor say Yasmin could do?","options":["Swim again, but gently","Stay home all month","Skip every Saturday","Race at the deep end"],"correctAnswer":"Swim again, but gently","explanation":"The doctor said she could swim again, but gently.","supportingSentence":"After a cold, Yasmin's doctor said she could swim again, but gently.","skill":"detail"},{"question":"Where did Yasmin kick at the start?","options":["At the deep end","Outside by the notebook","In the busy lane","At the shallow end"],"correctAnswer":"At the shallow end","explanation":"She kicked slowly at the shallow end for ten minutes.","supportingSentence":"For ten minutes she kicked slowly at the shallow end.","skill":"detail"},{"question":"Why did Yasmin decide not to race?","options":["Her arms felt tired","The pool was closed","Her friend had a cold","The doctor was watching"],"correctAnswer":"Her arms felt tired","explanation":"Her arms felt tired, so she did not race her friend.","supportingSentence":"Her arms felt tired, so she did not race her friend.","skill":"detail"},{"question":"What does shallow mean in this story?","options":["Very fast","Too cold for swimming","Not deep","Already crowded"],"correctAnswer":"Not deep","explanation":"The shallow end is the part of the pool that is not deep.","supportingSentence":"For ten minutes she kicked slowly at the shallow end.","skill":"vocabulary"},{"question":"What did Yasmin write in the notebook?","options":["The time","The doctor's address","A list of races","Her friend's score"],"correctAnswer":"The time","explanation":"She wrote the time in a notebook before she left.","supportingSentence":"She left before the busy hour and wrote the time in a notebook.","skill":"detail"}],"wordCount":61,"questionCount":5}$q32230$::jsonb,
  '571180e08e09b4c5975b0e3df8de4b508806d85ad7841d74b0a616155f8b513f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '290e187c-a0fe-48bd-a9d6-c6f6b4f8389c'::uuid,
  'reading',
  'B1',
  'text',
  $q5151${"topic":"culture_food","wordCount":66,"questionCount":5}$q5151$::jsonb,
  $q40532${"mode":"reading","level":"B1","format":"text","topic":"Culture & Food","title":"Bread for the Festival","story":"On festival morning, the square smelled of fresh bread. Luca helped his aunt at a table. They sold round loaves and a sweet rice dish from her region. A tourist asked about the red spice, and Luca said it was mild. His aunt wrapped a roll for a child with no money. When the music started, a few loaves were left. Luca saved one for dinner.","dialogue":[],"vocabulary":[{"word":"square","definition":"An open public space in a town."},{"word":"loaves","definition":"Whole pieces of baked bread."},{"word":"region","definition":"A particular area of a country."},{"word":"spice","definition":"A plant substance used to flavour food."},{"word":"mild","definition":"Not strong or hot in taste."},{"word":"wrapped","definition":"Covered something before giving it."}],"quiz":[{"question":"What smell filled the square that morning?","options":["Fresh bread","Sweet music","Wood smoke","Red spice only"],"correctAnswer":"Fresh bread","explanation":"The square smelled of fresh bread on festival morning.","supportingSentence":"On festival morning, the square smelled of fresh bread.","skill":"detail"},{"question":"What did Luca and his aunt sell?","options":["Only free rolls for children","Soup and grilled fish","Cakes from another town","Round loaves and a sweet rice dish"],"correctAnswer":"Round loaves and a sweet rice dish","explanation":"They sold round loaves and a sweet rice dish from her region.","supportingSentence":"They sold round loaves and a sweet rice dish from her region.","skill":"detail"},{"question":"How did Luca describe the red spice?","options":["It was mild","It was too salty","It was painfully hot","It came from the tourist"],"correctAnswer":"It was mild","explanation":"Luca said the red spice was mild.","supportingSentence":"A tourist asked about the red spice, and Luca said it was mild.","skill":"detail"},{"question":"What does mild mean in this story?","options":["Costing no money","Not strong or hot in taste","Covered in paper","Still warm from the oven"],"correctAnswer":"Not strong or hot in taste","explanation":"Luca said the spice was mild, meaning its taste was not hot.","supportingSentence":"A tourist asked about the red spice, and Luca said it was mild.","skill":"vocabulary"},{"question":"Who received a roll without paying?","options":["A child with no money","Luca's teacher","The musicians","The tourist"],"correctAnswer":"A child with no money","explanation":"His aunt wrapped a roll for a child with no money.","supportingSentence":"His aunt wrapped a roll for a child with no money.","skill":"detail"}],"wordCount":66,"questionCount":5}$q40532$::jsonb,
  '290e187ca0fec8bd79d6c6f6b4f8389c563c929ce2e02dee5243647bb86b7de0',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'cfeec173-3333-4269-a83e-ea9594847041'::uuid,
  'reading',
  'B1',
  'text',
  $q5151${"topic":"culture_food","wordCount":66,"questionCount":5}$q5151$::jsonb,
  $q51066${"mode":"reading","level":"B1","format":"text","topic":"Culture & Food","title":"Soup after the Dance","story":"After the harvest dance, people gathered in the hall for soup. Mina carried bowls from the kitchen while her cousin cut bread. An older neighbour told a story about the first dance there. Everyone listened, then clapped. Mina tried the soup and added a little pepper. She sat with her cousin and learned the steps she had missed. They agreed to practise before the next dance.","dialogue":[],"vocabulary":[{"word":"harvest","definition":"The time when crops are gathered."},{"word":"gathered","definition":"Came together in one place."},{"word":"bowls","definition":"Deep round dishes for soup."},{"word":"clapped","definition":"Hit their hands together to show pleasure."},{"word":"pepper","definition":"A spice with a sharp taste."},{"word":"steps","definition":"The movements of a dance."}],"quiz":[{"question":"Where did people go after the harvest dance?","options":["Back to the fields","To a shop in town","Onto the stage again","Into the hall for soup"],"correctAnswer":"Into the hall for soup","explanation":"After the dance, people gathered in the hall for soup.","supportingSentence":"After the harvest dance, people gathered in the hall for soup.","skill":"detail"},{"question":"What did Mina carry from the kitchen?","options":["Bowls","The neighbour's story","A pepper pot","Loaves of bread"],"correctAnswer":"Bowls","explanation":"Mina carried bowls from the kitchen.","supportingSentence":"Mina carried bowls from the kitchen while her cousin cut bread.","skill":"detail"},{"question":"What did the older neighbour share?","options":["Bread from the kitchen","A story about the first dance","A bowl of pepper soup","The steps Mina missed"],"correctAnswer":"A story about the first dance","explanation":"The neighbour told a story about the first dance there.","supportingSentence":"An older neighbour told a story about the first dance there.","skill":"detail"},{"question":"What does clapped mean in this story?","options":["Walked through dance steps","Cut bread into pieces","Hit their hands together happily","Added spice to the soup"],"correctAnswer":"Hit their hands together happily","explanation":"Everyone clapped after listening, which means they hit their hands together.","supportingSentence":"Everyone listened, then clapped.","skill":"vocabulary"},{"question":"What did Mina and her cousin agree to do?","options":["Cook soup every morning","Leave the hall early","Tell the story at school","Practise before the next dance"],"correctAnswer":"Practise before the next dance","explanation":"They agreed to practise before the next dance.","supportingSentence":"They agreed to practise before the next dance.","skill":"detail"}],"wordCount":66,"questionCount":5}$q51066$::jsonb,
  'cfeec17333330269683eea9594847041877e763557c12b9ebcc3e147ad9eadbe',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e42b52c6-9847-4fe8-adad-11116cec681b'::uuid,
  'reading',
  'B1',
  'text',
  $q4944${"topic":"technology","wordCount":66,"questionCount":5}$q4944$::jsonb,
  $q41411${"mode":"reading","level":"B1","format":"text","topic":"Technology","title":"A Password on Paper","story":"Dad's tablet would not open because he forgot the password. A paper copy was in the kitchen drawer. Nina found it, but the last two letters were missing. They tried an old code and then a newer one. The second try worked. Dad changed the password and stored the new code in a locked note on his phone. He thanked Nina and threw the paper away.","dialogue":[],"vocabulary":[{"word":"tablet","definition":"A flat computer you can hold."},{"word":"password","definition":"A secret word that opens a device."},{"word":"drawer","definition":"A box that slides out of a piece of furniture."},{"word":"letters","definition":"The written signs that make words."},{"word":"stored","definition":"Kept something in a chosen place."},{"word":"locked","definition":"Closed so that only some people can open it."}],"quiz":[{"question":"Why would the tablet not open?","options":["Nina changed the code","The phone had no power","The drawer was empty","Dad forgot the password"],"correctAnswer":"Dad forgot the password","explanation":"The tablet would not open because Dad forgot the password.","supportingSentence":"Dad's tablet would not open because he forgot the password.","skill":"detail"},{"question":"Where was the paper copy kept?","options":["Inside the tablet case","Under the missing letters","In the kitchen drawer","On the phone screen"],"correctAnswer":"In the kitchen drawer","explanation":"A paper copy was in the kitchen drawer.","supportingSentence":"A paper copy was in the kitchen drawer.","skill":"detail"},{"question":"Which attempt opened the tablet?","options":["The first try","A try made at a shop","The second try","Neither try"],"correctAnswer":"The second try","explanation":"The second try worked.","supportingSentence":"The second try worked.","skill":"detail"},{"question":"What does stored mean in this story?","options":["Kept in a chosen place","Threw into the bin","Forgot a secret word","Tore a piece of paper"],"correctAnswer":"Kept in a chosen place","explanation":"Dad stored the new code in a locked note, so he kept it there.","supportingSentence":"Dad changed the password and stored the new code in a locked note on his phone.","skill":"vocabulary"},{"question":"Where did Dad keep the new code?","options":["In the tablet box","In Nina's school bag","On the kitchen paper","In a locked note on his phone"],"correctAnswer":"In a locked note on his phone","explanation":"He stored the new code in a locked note on his phone.","supportingSentence":"Dad changed the password and stored the new code in a locked note on his phone.","skill":"detail"}],"wordCount":66,"questionCount":5}$q41411$::jsonb,
  'e42b52c69847cfe8ddad11116cec681b3f5a319dac7ff68f572aff3438d1999f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e4fe9971-04d5-41ed-a099-abd69af1319f'::uuid,
  'reading',
  'B1',
  'text',
  $q4944${"topic":"technology","wordCount":66,"questionCount":5}$q4944$::jsonb,
  $q47039${"mode":"reading","level":"B1","format":"text","topic":"Technology","title":"The Blinking Router","story":"The home internet stopped during a film. The router lights were blinking red, so Kenan turned it off. He waited one minute and turned it on again. The lights became green, but the film would not play. His sister checked the cables and pushed one plug in firmly. The film started at once. Kenan wrote the steps on a card and stuck it beside the router.","dialogue":[],"vocabulary":[{"word":"internet","definition":"The network that connects computers."},{"word":"router","definition":"A device that sends the internet around a home."},{"word":"blinking","definition":"Flashing on and off."},{"word":"cables","definition":"Thick wires that connect machines."},{"word":"plug","definition":"The part that fits into a socket."},{"word":"firmly","definition":"In a strong and secure way."}],"quiz":[{"question":"When did the home internet stop?","options":["During breakfast","While the lights were green","During a film","After the card was written"],"correctAnswer":"During a film","explanation":"The home internet stopped during a film.","supportingSentence":"The home internet stopped during a film.","skill":"detail"},{"question":"What were the router lights doing at first?","options":["Blinking red","Staying green","Staying dark","Shining blue"],"correctAnswer":"Blinking red","explanation":"The router lights were blinking red at first.","supportingSentence":"The router lights were blinking red, so Kenan turned it off.","skill":"detail"},{"question":"What did Kenan's sister push in?","options":["The paper card","The film disc","A red bulb","One plug"],"correctAnswer":"One plug","explanation":"She checked the cables and pushed one plug in firmly.","supportingSentence":"His sister checked the cables and pushed one plug in firmly.","skill":"detail"},{"question":"What does firmly mean in this story?","options":["In a strong and secure way","For one minute only","Without any light","Very slowly"],"correctAnswer":"In a strong and secure way","explanation":"She pushed the plug in firmly, so it was held strongly in place.","supportingSentence":"His sister checked the cables and pushed one plug in firmly.","skill":"vocabulary"},{"question":"Why did Kenan stick the card beside the router?","options":["So he could sell the router","So the cables could be hidden","So the steps would be easy to find later","So the film would start again"],"correctAnswer":"So the steps would be easy to find later","explanation":"He wrote the steps and stuck the card beside the router, where he would see it next time.","supportingSentence":"Kenan wrote the steps on a card and stuck it beside the router.","skill":"inference"}],"wordCount":66,"questionCount":5}$q47039$::jsonb,
  'e4fe997104d5d1ed8099abd69af1319f78026f02625e7de82a591adeec852035',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'fb2bd7f6-c10a-48d4-a828-31c028af0536'::uuid,
  'reading',
  'B1',
  'text',
  $q4585${"topic":"science","wordCount":61,"questionCount":5}$q4585$::jsonb,
  $q28751${"mode":"reading","level":"B1","format":"text","topic":"Science","title":"Cups on the Windowsill","story":"For a class test, Ben put three cups of water on the windowsill. One sat in the sun, one in the shade, and one under foil. He checked them every hour and wrote the results. The sun cup lost the most water. The foil cup lost the least. Ben learned that heat makes water evaporate faster. He drew a simple chart.","dialogue":[],"vocabulary":[{"word":"windowsill","definition":"The flat shelf at the bottom of a window."},{"word":"foil","definition":"A thin metal sheet used as a cover."},{"word":"results","definition":"What you find at the end of a test."},{"word":"least","definition":"The smallest amount."},{"word":"evaporate","definition":"To change from water into vapour."},{"word":"chart","definition":"A simple drawing that shows information."}],"quiz":[{"question":"How many cups did Ben put on the windowsill?","options":["Three cups","Two cups","One cup","Four cups"],"correctAnswer":"Three cups","explanation":"Ben put three cups of water on the windowsill.","supportingSentence":"For a class test, Ben put three cups of water on the windowsill.","skill":"detail"},{"question":"Which cup lost the most water?","options":["The cup in the shade","The cup in the sun","All three cups equally","The cup under foil"],"correctAnswer":"The cup in the sun","explanation":"The sun cup lost the most water.","supportingSentence":"The sun cup lost the most water.","skill":"detail"},{"question":"Which cup lost the least water?","options":["The cup in the shade","The cup he did not record","The cup under foil","The cup in the sun"],"correctAnswer":"The cup under foil","explanation":"The foil cup lost the least water.","supportingSentence":"The foil cup lost the least.","skill":"detail"},{"question":"What does evaporate mean in this story?","options":["To write numbers on a chart","To sit a cup in the shade","To cover a cup with foil","To turn from water into vapour"],"correctAnswer":"To turn from water into vapour","explanation":"Ben learned that heat makes water evaporate, or turn into vapour, faster.","supportingSentence":"Ben learned that heat makes water evaporate faster.","skill":"vocabulary"},{"question":"How often did Ben check the cups?","options":["Every hour","Only once at night","Every minute","He never checked them"],"correctAnswer":"Every hour","explanation":"He checked them every hour and wrote the results.","supportingSentence":"He checked them every hour and wrote the results.","skill":"detail"}],"wordCount":61,"questionCount":5}$q28751$::jsonb,
  'fb2bd7f6c10a18d4b82831c028af0536c36cde09c24fc23672261b1b634aa26b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '17420b74-b76d-4f73-a6ec-d4b8caecc782'::uuid,
  'reading',
  'B1',
  'text',
  $q4590${"topic":"science","wordCount":66,"questionCount":5}$q4590$::jsonb,
  $q30571${"mode":"reading","level":"B1","format":"text","topic":"Science","title":"Seeds in Two Pots","story":"Aisha planted bean seeds in two pots for science club. She put both pots by the same window. She watered the first pot every day and left the second dry. After a week, green shoots appeared only in the wet pot. The dry seeds did not change. Aisha wrote that plants need water to grow. She showed the pots to the club and labelled them clearly.","dialogue":[],"vocabulary":[{"word":"planted","definition":"Put seeds in soil so they can grow."},{"word":"shoots","definition":"Young growth from a plant."},{"word":"appeared","definition":"Became able to be seen."},{"word":"dry","definition":"Without water."},{"word":"labelled","definition":"Marked with a name or note."},{"word":"clearly","definition":"In a way that is easy to understand."}],"quiz":[{"question":"How many pots did Aisha use?","options":["One pot","Ten pots","Four pots","Two pots"],"correctAnswer":"Two pots","explanation":"Aisha planted bean seeds in two pots.","supportingSentence":"Aisha planted bean seeds in two pots for science club.","skill":"detail"},{"question":"Where did she put both pots?","options":["By the same window","Outside in the rain","Under the club table","In a dark cupboard"],"correctAnswer":"By the same window","explanation":"She put both pots by the same window.","supportingSentence":"She put both pots by the same window.","skill":"detail"},{"question":"Where did the green shoots appear?","options":["Only in the dry pot","On the labels","Only in the wet pot","In both pots"],"correctAnswer":"Only in the wet pot","explanation":"Green shoots appeared only in the wet pot.","supportingSentence":"After a week, green shoots appeared only in the wet pot.","skill":"detail"},{"question":"What does shoots mean in this story?","options":["Dry seeds that stay the same","Notes written for a club","Young parts of a growing plant","Labels stuck on pots"],"correctAnswer":"Young parts of a growing plant","explanation":"The green shoots were the new growth that appeared in the wet pot.","supportingSentence":"After a week, green shoots appeared only in the wet pot.","skill":"vocabulary"},{"question":"What conclusion did Aisha write?","options":["Plants need dry soil to grow","Windows stop seeds from growing","Seeds change without water","Plants need water to grow"],"correctAnswer":"Plants need water to grow","explanation":"Aisha wrote that plants need water to grow.","supportingSentence":"Aisha wrote that plants need water to grow.","skill":"detail"}],"wordCount":66,"questionCount":5}$q30571$::jsonb,
  '17420b74b76d1f7366ecd4b8caecc782b8a5647cead18d0cc828caa6a6b6fce0',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '54dd834e-e274-4118-a96a-35ee2d5e1b98'::uuid,
  'reading',
  'B1',
  'text',
  $q5439${"topic":"economy_finance","wordCount":64,"questionCount":5}$q5439$::jsonb,
  $q28395${"mode":"reading","level":"B1","format":"text","topic":"Economy / Finance","title":"Coins in a Jar","story":"Every Friday Selim puts spare coins into a glass jar. He wants a winter coat that costs forty pounds. This week he added three pounds from washing a car. His mother matched that amount, so the jar grew faster. Selim wrote the new total on a card. He is still short, but the goal is closer. He will not spend the money on snacks.","dialogue":[],"vocabulary":[{"word":"spare","definition":"Extra and not needed for something else."},{"word":"coins","definition":"Small round pieces of money."},{"word":"amount","definition":"How much money there is."},{"word":"matched","definition":"Added the same amount."},{"word":"total","definition":"The full amount after adding."},{"word":"snacks","definition":"Small things eaten between meals."}],"quiz":[{"question":"What does Selim want to buy?","options":["A winter coat","A glass jar","A new car","A box of snacks"],"correctAnswer":"A winter coat","explanation":"He wants a winter coat that costs forty pounds.","supportingSentence":"He wants a winter coat that costs forty pounds.","skill":"detail"},{"question":"How much did the car wash add this week?","options":["Forty pounds","No money","Three pounds","One coin"],"correctAnswer":"Three pounds","explanation":"This week he added three pounds from washing a car.","supportingSentence":"This week he added three pounds from washing a car.","skill":"detail"},{"question":"What did Selim's mother do with that amount?","options":["She added the same amount","She spent it on snacks","She hid the card","She bought the coat"],"correctAnswer":"She added the same amount","explanation":"His mother matched that amount, so she added the same sum.","supportingSentence":"His mother matched that amount, so the jar grew faster.","skill":"detail"},{"question":"What does matched mean in this story?","options":["Wrote a number on a card","Closed the jar tightly","Spent money on food","Added the same amount of money"],"correctAnswer":"Added the same amount of money","explanation":"His mother matched the amount, which means she put in the same money.","supportingSentence":"His mother matched that amount, so the jar grew faster.","skill":"vocabulary"},{"question":"What will Selim refuse to buy with this money?","options":["A new jar","The winter coat","Snacks","A blank card"],"correctAnswer":"Snacks","explanation":"He will not spend the money on snacks.","supportingSentence":"He will not spend the money on snacks.","skill":"detail"}],"wordCount":64,"questionCount":5}$q28395$::jsonb,
  '54dd834ee2742118f96a35ee2d5e1b98b6de70acfc5705300b7de69e4faa1789',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '9365e761-2c1e-48d1-aef6-6220812b8690'::uuid,
  'reading',
  'B1',
  'text',
  $q4657${"topic":"mystery","wordCount":66,"questionCount":5}$q4657$::jsonb,
  $q43154${"mode":"reading","level":"B1","format":"text","topic":"Mystery","title":"The Blue Glove","story":"Someone left a blue glove on the classroom radiator. It was not there before lunch. Nia asked, but nobody claimed it. She noticed green paint on the thumb. The art group had painted posters that morning, and only Jules wore green paint. Nia found him in the hall. He checked his bag and saw one glove was missing. He thanked her and pulled the pair on.","dialogue":[],"vocabulary":[{"word":"radiator","definition":"A heater fixed to a wall."},{"word":"claimed","definition":"Said that something belongs to you."},{"word":"thumb","definition":"The short thick finger on a hand."},{"word":"posters","definition":"Large sheets with pictures or words."},{"word":"missing","definition":"Not in the place where it should be."},{"word":"pair","definition":"Two matching things used together."}],"quiz":[{"question":"Where was the blue glove left?","options":["In Jules's bag","On an art poster","In the lunch hall","On the classroom radiator"],"correctAnswer":"On the classroom radiator","explanation":"Someone left a blue glove on the classroom radiator.","supportingSentence":"Someone left a blue glove on the classroom radiator.","skill":"detail"},{"question":"What did Nia notice on the thumb?","options":["Green paint","Blue thread","Red ink","A written name"],"correctAnswer":"Green paint","explanation":"She noticed green paint on the thumb.","supportingSentence":"She noticed green paint on the thumb.","skill":"detail"},{"question":"Who wore green paint that morning?","options":["Only Nia","Only Jules","Every art student","Nobody in the class"],"correctAnswer":"Only Jules","explanation":"Only Jules wore green paint that morning.","supportingSentence":"The art group had painted posters that morning, and only Jules wore green paint.","skill":"detail"},{"question":"What does claimed mean in this story?","options":["Lost one glove from a pair","Painted a poster green","Said that something was theirs","Put an object on a heater"],"correctAnswer":"Said that something was theirs","explanation":"Nobody claimed the glove, so nobody said it was theirs.","supportingSentence":"Nia asked, but nobody claimed it.","skill":"vocabulary"},{"question":"Why did Nia look for Jules?","options":["He had asked her to check the hall","The radiator belonged to him","Lunch was still in his bag","The paint suggested the glove was his"],"correctAnswer":"The paint suggested the glove was his","explanation":"Only Jules wore the same green paint that Nia found on the glove.","supportingSentence":"The art group had painted posters that morning, and only Jules wore green paint.","skill":"inference"}],"wordCount":66,"questionCount":5}$q43154$::jsonb,
  '9365e7612c1ea8d10ef66220812b869016ea308a48532f27b3457e668cf9b866',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'da4d9603-4c7b-487f-a8a9-1311ebe19a74'::uuid,
  'reading',
  'B1',
  'text',
  $q4832${"topic":"adventure","wordCount":64,"questionCount":5}$q4832$::jsonb,
  $q32878${"mode":"reading","level":"B1","format":"text","topic":"Adventure","title":"A Torch on the Path","story":"The cliff path was narrow, and the sun was low. Petra and her cousin shared one torch. They marked each fork with stones so they could return. Near the top the wind grew strong and the torch flickered. They crouched behind a rock until the gust passed. Then they reached the viewpoint and saw the sea. They started down before the light was gone.","dialogue":[],"vocabulary":[{"word":"narrow","definition":"Not wide."},{"word":"torch","definition":"A light you can carry."},{"word":"fork","definition":"A place where a path splits into two."},{"word":"flickered","definition":"Shone in an unsteady way."},{"word":"crouched","definition":"Bent low with the body close to the ground."},{"word":"gust","definition":"A sudden strong rush of wind."}],"quiz":[{"question":"What was the cliff path like?","options":["It was wide and flat","It was narrow","It ran under the sea","It was closed"],"correctAnswer":"It was narrow","explanation":"The cliff path was narrow, and the sun was low.","supportingSentence":"The cliff path was narrow, and the sun was low.","skill":"detail"},{"question":"How did they mark each fork?","options":["With stones","With the torch","With paint","With paper signs"],"correctAnswer":"With stones","explanation":"They marked each fork with stones so they could return.","supportingSentence":"They marked each fork with stones so they could return.","skill":"detail"},{"question":"What did they do until the gust passed?","options":["Switched the torch off","Climbed a tree","Ran down to the sea","Crouched behind a rock"],"correctAnswer":"Crouched behind a rock","explanation":"They crouched behind a rock until the gust passed.","supportingSentence":"They crouched behind a rock until the gust passed.","skill":"detail"},{"question":"What does fork mean in this story?","options":["A sudden blast of wind","A light you can carry","A place where a path splits","A tool used for eating"],"correctAnswer":"A place where a path splits","explanation":"They marked each fork so they could choose the right path on the way back.","supportingSentence":"They marked each fork with stones so they could return.","skill":"vocabulary"},{"question":"When did they start back down?","options":["At midday","Before the light was gone","When the torch broke","After midnight"],"correctAnswer":"Before the light was gone","explanation":"They started down before the light was gone.","supportingSentence":"They started down before the light was gone.","skill":"detail"}],"wordCount":64,"questionCount":5}$q32878$::jsonb,
  'da4d96034c7bb87fe8a91311ebe19a74a2cb476ec3d5417e3a32dd5af64a6af4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '02b68186-95f5-4455-ae60-03dcf9fe1bb7'::uuid,
  'reading',
  'B1',
  'text',
  $q4618${"topic":"fantasy","wordCount":66,"questionCount":5}$q4618$::jsonb,
  $q39179${"mode":"reading","level":"B1","format":"text","topic":"Fantasy","title":"The Lantern Fox","story":"In a misty wood, a small fox carried a lantern. The light never burned the fox, and it showed hidden stones across a black stream. Lila followed the stones to a tree with a silver door. The fox set the lantern down and the door opened. Inside, books whispered their titles. Lila read one page, thanked the fox, and promised to return the lantern at dawn.","dialogue":[],"vocabulary":[{"word":"misty","definition":"Full of thin cloud near the ground."},{"word":"lantern","definition":"A light inside a protective case."},{"word":"stream","definition":"A small flow of water."},{"word":"silver","definition":"Having a shiny grey-white colour."},{"word":"whispered","definition":"Spoke in a very quiet voice."},{"word":"dawn","definition":"The time when the day begins."}],"quiz":[{"question":"What did the fox carry through the wood?","options":["A lantern","A black stone","A silver book","A warm blanket"],"correctAnswer":"A lantern","explanation":"A small fox carried a lantern in the misty wood.","supportingSentence":"In a misty wood, a small fox carried a lantern.","skill":"detail"},{"question":"What did the light show across the stream?","options":["The titles of the books","Hidden stones","A silver bridge","A village road"],"correctAnswer":"Hidden stones","explanation":"The light showed hidden stones across a black stream.","supportingSentence":"The light never burned the fox, and it showed hidden stones across a black stream.","skill":"detail"},{"question":"What happened when the fox set the lantern down?","options":["The books caught fire","The wood became dark","The door opened","The stream dried up"],"correctAnswer":"The door opened","explanation":"The fox set the lantern down and the door opened.","supportingSentence":"The fox set the lantern down and the door opened.","skill":"detail"},{"question":"What does whispered mean in this story?","options":["Closed a door slowly","Followed stones across water","Burned with a bright flame","Spoke in a very quiet voice"],"correctAnswer":"Spoke in a very quiet voice","explanation":"The books whispered their titles, so they spoke those names very quietly.","supportingSentence":"Inside, books whispered their titles.","skill":"vocabulary"},{"question":"When did Lila promise to return the lantern?","options":["At dawn","At once","Next winter","Before she entered"],"correctAnswer":"At dawn","explanation":"She promised to return the lantern at dawn.","supportingSentence":"Lila read one page, thanked the fox, and promised to return the lantern at dawn.","skill":"detail"}],"wordCount":66,"questionCount":5}$q39179$::jsonb,
  '02b6818695f514554e6003dcf9fe1bb74ccc1a10594ba051288cc988acfae2a6',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '6993df6c-3e4f-4739-acb5-7d7c77ea8a07'::uuid,
  'reading',
  'B2',
  'text',
  $q4885${"topic":"daily life","wordCount":109,"questionCount":5}$q4885$::jsonb,
  $q47817${"mode":"reading","level":"B2","format":"text","topic":"Daily Life","title":"The Spare Key Drawer","story":"Hana kept a spare key in the kitchen drawer so her sister could water the plants when Hana worked late. On Thursday the key was gone, and the plants were dry. She almost called a locksmith before she checked the fruit bowl. Under a banana she found a note from her sister, saying the key had bent in the lock and was at the hardware shop. Hana felt foolish, then relieved. The note also asked her to buy milk, which made her laugh. She texted back that the plants mattered more than the milk, and that next time the note should sit where a tired person would see it.","dialogue":[],"vocabulary":[{"word":"spare","definition":"Kept ready in case the usual one is unavailable."},{"word":"locksmith","definition":"A person who fits and repairs locks and keys."},{"word":"bent","definition":"Pushed into a curve so it was no longer straight."},{"word":"hardware","definition":"Tools and household fixings sold in a shop."},{"word":"relieved","definition":"Glad because a worry has gone."},{"word":"texted","definition":"Sent a short written message from a phone."}],"quiz":[{"question":"Where did Hana normally keep the spare key?","options":["Under a banana in the fruit bowl","At the hardware shop from the start","In the locksmith's van","In the kitchen drawer"],"correctAnswer":"In the kitchen drawer","explanation":"She kept the spare key in the kitchen drawer so her sister could water the plants.","supportingSentence":"Hana kept a spare key in the kitchen drawer so her sister could water the plants when Hana worked late.","skill":"detail"},{"question":"What does nearly calling a locksmith suggest?","options":["Her sister had told her to change every lock","The plants had already died and could not be saved","The fruit bowl was locked and could not be opened","She reached for a drastic fix before looking carefully"],"correctAnswer":"She reached for a drastic fix before looking carefully","explanation":"She almost called a locksmith before the simple check that led her to the note.","supportingSentence":"She almost called a locksmith before she checked the fruit bowl.","skill":"inference"},{"question":"What had happened to the key, according to the note?","options":["It had been thrown away with the milk","It was still hidden in Hana's coat","It was lying beside the banana","It had bent in the lock and was at the hardware shop"],"correctAnswer":"It had bent in the lock and was at the hardware shop","explanation":"The note said the key had bent in the lock and was at the hardware shop.","supportingSentence":"Under a banana she found a note from her sister, saying the key had bent in the lock and was at the hardware shop.","skill":"detail"},{"question":"What does Hana's message suggest about where the note was left?","options":["She wanted the next note to ask only for milk","She never found a note from her sister","A tired person could easily miss it in that place","The plants mattered less to her than the milk"],"correctAnswer":"A tired person could easily miss it in that place","explanation":"She wants the next note where a tired person would see it, so this hiding place was too easy to miss.","supportingSentence":"She texted back that the plants mattered more than the milk, and that next time the note should sit where a tired person would see it.","skill":"inference"},{"question":"What does relieved mean in this story?","options":["Unable to find the fruit bowl","Ready to phone a locksmith at once","Glad because a worry has passed","Angry about a request for milk"],"correctAnswer":"Glad because a worry has passed","explanation":"Once the note explains the key, Hana is relieved, so the worry has gone.","supportingSentence":"Hana felt foolish, then relieved.","skill":"vocabulary"}],"wordCount":109,"questionCount":5}$q47817$::jsonb,
  '6993df6c3e4f17392cb57d7c77ea8a07b4aec02f3cb2f0dfd6fdf0c9180fe534',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '4a115791-c43d-4c2b-a871-33e44d7254be'::uuid,
  'reading',
  'B2',
  'text',
  $q5371${"topic":"school_college","wordCount":100,"questionCount":5}$q5371$::jsonb,
  $q45187${"mode":"reading","level":"B2","format":"text","topic":"School / College","title":"A Slot before the Shift","story":"Soraya arrived ten minutes after her tutorial had ended, still holding the essay she hoped to discuss. The office door was shut, and a note said the hour was over. She felt embarrassed, because a shift at the campus cafe had caused the delay. The next morning she emailed the tutor, explained the clash, and asked for another time. He replied that honesty was useful and offered a Thursday slot before her shift. Soraya accepted at once and set a phone reminder. At the new meeting she spoke more clearly, since she no longer had to apologise for being late.","dialogue":[],"vocabulary":[{"word":"tutorial","definition":"A meeting in which a tutor discusses your work."},{"word":"embarrassed","definition":"Uncomfortable because you feel you have slipped up."},{"word":"clash","definition":"A case where two events fall at the same time."},{"word":"honesty","definition":"The practice of telling the truth."},{"word":"reminder","definition":"Something that helps you remember a task."},{"word":"apologise","definition":"To say that you are sorry."}],"quiz":[{"question":"Why was Soraya late for the tutorial?","options":["A shift at the campus cafe had delayed her","The tutor had cancelled the hour by email","She had left the essay on the bus","The office had moved to another building"],"correctAnswer":"A shift at the campus cafe had delayed her","explanation":"She felt embarrassed because a shift at the campus cafe had caused the delay.","supportingSentence":"She felt embarrassed, because a shift at the campus cafe had caused the delay.","skill":"detail"},{"question":"What does the tutor's reply suggest about him?","options":["He would adapt the time after an honest explanation","He moved the whole course into the cafe","He refused to teach any student with a job","He wanted the essay thrown away unread"],"correctAnswer":"He would adapt the time after an honest explanation","explanation":"He calls her honesty useful and offers a slot before the shift, so he is willing to adapt.","supportingSentence":"He replied that honesty was useful and offered a Thursday slot before her shift.","skill":"inference"},{"question":"What did Soraya do just after accepting the new slot?","options":["She asked the cafe to close for the day","She set a reminder on her phone","She gave the essay to a classmate","She stopped attending tutorials"],"correctAnswer":"She set a reminder on her phone","explanation":"As soon as she accepted the Thursday slot, she set a phone reminder.","supportingSentence":"Soraya accepted at once and set a phone reminder.","skill":"detail"},{"question":"What does the morning email suggest about Soraya?","options":["She asked for the course to be cancelled","She refused to mention the cafe shift","She blamed the tutor for locking the door","She wanted another chance rather than dropping the matter"],"correctAnswer":"She wanted another chance rather than dropping the matter","explanation":"She writes to explain the clash and ask for another time, so she is trying to repair the missed meeting.","supportingSentence":"The next morning she emailed the tutor, explained the clash, and asked for another time.","skill":"inference"},{"question":"What does clash mean in this story?","options":["A low mark on the essay","A loud argument in the office","A broken lock on the tutorial door","Two commitments that fall at the same time"],"correctAnswer":"Two commitments that fall at the same time","explanation":"The clash is her cafe shift overlapping the tutorial, which is why she asks for a new time.","supportingSentence":"The next morning she emailed the tutor, explained the clash, and asked for another time.","skill":"vocabulary"}],"wordCount":100,"questionCount":5}$q45187$::jsonb,
  '4a115791c43d5c2bd87133e44d7254be1600ceae152968ad0644607ba56e440c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f08475ab-695e-478b-a2b0-94fb0f91af53'::uuid,
  'reading',
  'B2',
  'text',
  $q4556${"topic":"travel","wordCount":105,"questionCount":5}$q4556$::jsonb,
  $q75461${"mode":"reading","level":"B2","format":"text","topic":"Travel","title":"The Later Coastal Ferry","story":"When the coastal coach broke down, passengers were asked to wait beside a petrol station with almost no shade. Andres had packed water, so he shared it with a child whose bottle was empty. The driver explained that a replacement coach would arrive within the hour, though the delay would make some people miss a ferry. Andres checked his ticket and saw that his own ferry was the later one. He offered his seat on the first replacement to a couple who were rushing. They thanked him twice. He reached the port after sunset, tired but calm, and still caught the boat he had booked.","dialogue":[],"vocabulary":[{"word":"coastal","definition":"Along or near the coast."},{"word":"shade","definition":"A cooler place out of direct sun."},{"word":"replacement","definition":"Something sent to take the place of another."},{"word":"ferry","definition":"A boat that carries passengers on a set route."},{"word":"rushing","definition":"Hurrying because time is short."},{"word":"sunset","definition":"The time in the evening when the sun goes down."}],"quiz":[{"question":"Where were the passengers asked to wait?","options":["On the ferry they had already boarded","Beside a petrol station with almost no shade","At the port before the coach had left","Inside a replacement coach that was already there"],"correctAnswer":"Beside a petrol station with almost no shade","explanation":"When the coach broke down, they were asked to wait beside a petrol station with almost no shade.","supportingSentence":"When the coastal coach broke down, passengers were asked to wait beside a petrol station with almost no shade.","skill":"detail"},{"question":"What does sharing his water suggest about Andres?","options":["He drank the child's bottle and kept his own","He put a child's thirst ahead of keeping all the water","He had forgotten to pack anything to drink","The driver had banned drinks during the wait"],"correctAnswer":"He put a child's thirst ahead of keeping all the water","explanation":"He had packed water and shared it with a child whose bottle was empty, so he gave up some of his supply.","supportingSentence":"Andres had packed water, so he shared it with a child whose bottle was empty.","skill":"inference"},{"question":"What problem could the delay cause for some passengers?","options":["They might miss a ferry","They would have to walk back to the port at once","They would lose their seats at the petrol station","They would have to push the broken coach"],"correctAnswer":"They might miss a ferry","explanation":"The driver said the delay would make some people miss a ferry.","supportingSentence":"The driver explained that a replacement coach would arrive within the hour, though the delay would make some people miss a ferry.","skill":"detail"},{"question":"What does the ending suggest about the seat Andres gave away?","options":["The child had taken his ticket during the wait","He arrived angry because the couple refused to move","Helping the couple still left him on the boat he had booked","He missed every boat and stayed at the petrol station"],"correctAnswer":"Helping the couple still left him on the boat he had booked","explanation":"He reaches the port tired but calm and still catches the boat he booked, so the favour did not cost him the journey.","supportingSentence":"He reached the port after sunset, tired but calm, and still caught the boat he had booked.","skill":"inference"},{"question":"What does replacement mean in this story?","options":["A seat that passengers are forbidden to use","A coach sent to take the place of the broken one","A ticket for a journey in another country","A driver who will not explain the delay"],"correctAnswer":"A coach sent to take the place of the broken one","explanation":"The replacement is the later coach that will stand in for the one that broke down.","supportingSentence":"The driver explained that a replacement coach would arrive within the hour, though the delay would make some people miss a ferry.","skill":"vocabulary"}],"wordCount":105,"questionCount":5}$q75461$::jsonb,
  'f08475ab695eb78be2b094fb0f91af53a5c8414471b4d827d6c051031818d20a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '013bdcbc-0efc-4cf3-a7df-fc904e0ba7c4'::uuid,
  'reading',
  'B2',
  'text',
  $q4636${"topic":"hobbies","wordCount":107,"questionCount":5}$q4636$::jsonb,
  $q43759${"mode":"reading","level":"B2","format":"text","topic":"Hobbies","title":"The Bowl That Stayed Whole","story":"Imani had joined the evening pottery class to slow herself down after long days at a desk. For three weeks every bowl collapsed when she tried to lift it from the wheel. The instructor, Helen, told her to press less and to keep her elbows steady. Imani practised at home with a cheap clay set, though her kitchen table wobbled. On the fourth week a small bowl held its shape. Helen marked it for the kiln and warned that drying too fast would crack it. Imani waited, impatient but careful. When the shelf was opened, her bowl was whole, slightly uneven, and good enough to hold fruit.","dialogue":[],"vocabulary":[{"word":"pottery","definition":"The craft of making objects from clay."},{"word":"collapsed","definition":"Fell in and lost its shape."},{"word":"wobbled","definition":"Rocked unsteadily from side to side."},{"word":"kiln","definition":"A very hot oven used to harden clay."},{"word":"impatient","definition":"Wanting a result soon and finding the wait hard."},{"word":"uneven","definition":"Not smooth or not the same all the way round."}],"quiz":[{"question":"Why had Imani joined the pottery class?","options":["Her kitchen table needed a new clay top","She wanted to slow down after long days at a desk","She already earned her living by selling bowls","Helen had asked her to repair the kiln"],"correctAnswer":"She wanted to slow down after long days at a desk","explanation":"She joined the evening class to slow herself down after long days at a desk.","supportingSentence":"Imani had joined the evening pottery class to slow herself down after long days at a desk.","skill":"detail"},{"question":"What does practice on a wobbly table suggest?","options":["Helen had told her not to touch clay at home","She kept trying even though home was an awkward place","The kiln was kept under her kitchen table","She gave up after the first evening"],"correctAnswer":"She kept trying even though home was an awkward place","explanation":"She practised at home even though the table wobbled, so the poor setup did not stop her.","supportingSentence":"Imani practised at home with a cheap clay set, though her kitchen table wobbled.","skill":"inference"},{"question":"What did Helen tell Imani to change?","options":["Dry the clay in the sun that same night","Press less and keep her elbows steady","Skip the class for the next three weeks","Lift every bowl as fast as possible"],"correctAnswer":"Press less and keep her elbows steady","explanation":"Helen told her to press less and to keep her elbows steady.","supportingSentence":"The instructor, Helen, told her to press less and to keep her elbows steady.","skill":"detail"},{"question":"What do impatient and careful suggest about the wait?","options":["She wanted the bowl soon but still refused to rush the drying","She left the class before the fourth week","She broke the bowl on purpose","She opened the kiln while it was still hot"],"correctAnswer":"She wanted the bowl soon but still refused to rush the drying","explanation":"She is impatient but careful after a warning that fast drying would crack the bowl, so she waits.","supportingSentence":"Imani waited, impatient but careful.","skill":"inference"},{"question":"What is a kiln in this story?","options":["The shelf where the fruit was kept","The wheel used to shape the clay","The hot oven that would harden the bowl","The shop where she bought the clay set"],"correctAnswer":"The hot oven that would harden the bowl","explanation":"Helen marks the bowl for the kiln, the oven that fires clay so it becomes hard.","supportingSentence":"Helen marked it for the kiln and warned that drying too fast would crack it.","skill":"vocabulary"}],"wordCount":107,"questionCount":5}$q43759$::jsonb,
  '013bdcbc0efcacf307dffc904e0ba7c4a264124031f0f5cfb21473ab97bdb71d',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'eae7e23b-4ce8-4ea6-a75d-5d4ca91e9efe'::uuid,
  'reading',
  'B2',
  'text',
  $q5306${"topic":"health_sports","wordCount":101,"questionCount":5}$q5306$::jsonb,
  $q52400${"mode":"reading","level":"B2","format":"text","topic":"Health & Sports","title":"An Easy Pace on the Hill","story":"After a tight calf, Omar's coach cut his evening run in half and banned hills for two weeks. Omar was annoyed, because a charity race was a month away and he hated losing fitness. The coach said fitness could return, but a tear would cost him the race entirely. Omar followed the plan, added gentle stretches, and swam on the days when running was forbidden. By the second week the calf felt looser in the morning. He still wanted to sprint, yet he waited. When the coach finally allowed a short hill, Omar kept his pace easy and finished without pain.","dialogue":[],"vocabulary":[{"word":"calf","definition":"The muscle at the back of the lower leg."},{"word":"banned","definition":"Officially stopped for a period of time."},{"word":"tear","definition":"A rip in a muscle."},{"word":"stretches","definition":"Gentle movements that lengthen a muscle."},{"word":"forbidden","definition":"Not allowed."},{"word":"sprint","definition":"Run at full speed for a short burst."}],"quiz":[{"question":"What limit did the coach set after the tight calf?","options":["He cancelled the charity race that month","He told Omar to sprint up hills every day","He banned swimming as well as running","He cut the evening run in half and banned hills for two weeks"],"correctAnswer":"He cut the evening run in half and banned hills for two weeks","explanation":"After the tight calf, the coach halved the evening run and banned hills for two weeks.","supportingSentence":"After a tight calf, Omar's coach cut his evening run in half and banned hills for two weeks.","skill":"detail"},{"question":"What does the swimming suggest about Omar?","options":["He ignored the plan and ran the hills anyway","He swam only after the charity race was over","He gave up every kind of exercise","He stayed active without breaking the ban on running"],"correctAnswer":"He stayed active without breaking the ban on running","explanation":"He swam on days when running was forbidden, so he kept moving while obeying the limit.","supportingSentence":"Omar followed the plan, added gentle stretches, and swam on the days when running was forbidden.","skill":"inference"},{"question":"Why was Omar annoyed by the new plan?","options":["Swimming was banned for the whole month","The coach had cancelled the charity race","The stretches made his calf worse each morning","A charity race was near and he hated losing fitness"],"correctAnswer":"A charity race was near and he hated losing fitness","explanation":"He was annoyed because the charity race was a month away and he hated losing fitness.","supportingSentence":"Omar was annoyed, because a charity race was a month away and he hated losing fitness.","skill":"detail"},{"question":"What does the easy pace on the hill suggest?","options":["He sprinted as soon as the hill was allowed","The pain returned before he reached the top","The coach refused to let him finish","He held back even after a harder effort was allowed"],"correctAnswer":"He held back even after a harder effort was allowed","explanation":"When a short hill was finally allowed, he kept the pace easy, so he did not use the permission to sprint.","supportingSentence":"When the coach finally allowed a short hill, Omar kept his pace easy and finished without pain.","skill":"inference"},{"question":"What does forbidden mean in this story?","options":["Especially enjoyable for a runner","Done at full speed","Certain to heal a muscle overnight","Not allowed under the coach's plan"],"correctAnswer":"Not allowed under the coach's plan","explanation":"Running was forbidden on some days, which means the plan did not allow it then.","supportingSentence":"Omar followed the plan, added gentle stretches, and swam on the days when running was forbidden.","skill":"vocabulary"}],"wordCount":101,"questionCount":5}$q52400$::jsonb,
  'eae7e23b4ce8eea6775d5d4ca91e9efeeb00c79ea1f538469df798f50722191b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f665581c-22c1-4cd4-a7ff-a84e751d6a04'::uuid,
  'reading',
  'B2',
  'text',
  $q5194${"topic":"culture_food","wordCount":106,"questionCount":5}$q5194$::jsonb,
  $q45766${"mode":"reading","level":"B2","format":"text","topic":"Culture & Food","title":"A Napkin of New Recipes","story":"At the cultural evening, each family brought one dish and a short story about it. Noor carried a lentil stew that her aunt had taught her to season slowly. She had written the story on a card, but the room was noisy and she put the card in her pocket. People tried the stew and asked what gave it the warm smell. Noor forgot the formal story and simply named the spices and the aunt who never measured them. An older guest said that kind of memory was better than a speech. Noor left with an empty pot and three new recipes written on a napkin.","dialogue":[],"vocabulary":[{"word":"lentil","definition":"A small flat seed used in soups and stews."},{"word":"season","definition":"To add salt, herbs, or spices for flavour."},{"word":"formal","definition":"Prepared and official, rather than casual."},{"word":"spices","definition":"Strong flavourings used in cooking."},{"word":"recipes","definition":"Sets of instructions for making dishes."},{"word":"napkin","definition":"A piece of paper or cloth used at a meal."}],"quiz":[{"question":"What was each family asked to bring?","options":["Only a written card, with no food","A speech and nothing to eat","Three recipes on a napkin","One dish and a short story about it"],"correctAnswer":"One dish and a short story about it","explanation":"At the cultural evening, each family brought one dish and a short story about it.","supportingSentence":"At the cultural evening, each family brought one dish and a short story about it.","skill":"detail"},{"question":"Why did Noor's written story stay in her pocket?","options":["The card described someone else's dish","Her aunt had told her not to speak","She had forgotten to bring the stew","A noisy room was a poor place for a formal reading"],"correctAnswer":"A noisy room was a poor place for a formal reading","explanation":"The room was noisy, and she put the written card away before speaking in a simpler way.","supportingSentence":"She had written the story on a card, but the room was noisy and she put the card in her pocket.","skill":"inference"},{"question":"What did Noor say when people asked about the smell?","options":["She said the stew came from the older guest","She read the whole card aloud","She refused to name any ingredient","She named the spices and the aunt who never measured them"],"correctAnswer":"She named the spices and the aunt who never measured them","explanation":"She forgot the formal story and named the spices and the aunt who never measured them.","supportingSentence":"Noor forgot the formal story and simply named the spices and the aunt who never measured them.","skill":"detail"},{"question":"What does the ending suggest about the evening?","options":["She left before the event started","Nobody tasted the dish she had brought","Noor shared her stew and came away with recipes from other people","The napkin she carried home was blank"],"correctAnswer":"Noor shared her stew and came away with recipes from other people","explanation":"She leaves with an empty pot and three new recipes, so food and ideas were exchanged.","supportingSentence":"Noor left with an empty pot and three new recipes written on a napkin.","skill":"inference"},{"question":"What does season mean in this story?","options":["To flavour food, as her aunt had taught her","To measure every spice with a spoon","To write a story on a small card","To cook a dish only in one part of the year"],"correctAnswer":"To flavour food, as her aunt had taught her","explanation":"Her aunt taught her to season the stew slowly, meaning to build its flavour.","supportingSentence":"Noor carried a lentil stew that her aunt had taught her to season slowly.","skill":"vocabulary"}],"wordCount":106,"questionCount":5}$q45766$::jsonb,
  'f665581c22c1ecd427ffa84e751d6a041dd17ba7cf738fcef80395d4267d491c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e8a494b6-a10b-4ec9-a6d1-70d26145b7eb'::uuid,
  'reading',
  'B2',
  'text',
  $q4982${"topic":"technology","wordCount":110,"questionCount":5}$q4982$::jsonb,
  $q54271${"mode":"reading","level":"B2","format":"text","topic":"Technology","title":"Two Plans for One Car","story":"The family shared one car and one online calendar, but the calendar had not been updated after Dad's late meeting. On Saturday morning both parents arrived in the hall with keys and different plans. Mum needed the market, and Dad needed the clinic. Their son, Elias, opened the app and saw that the meeting change was still only in Dad's email. He added the new time, then suggested a simple order. Mum could take the car first, and Dad could go after the market run. They agreed, slightly annoyed with themselves. Elias also turned on a reminder so a change in one inbox would not surprise the whole household again.","dialogue":[],"vocabulary":[{"word":"calendar","definition":"A shared record of times and plans."},{"word":"updated","definition":"Changed so that the information is current."},{"word":"clinic","definition":"A place people visit for medical care."},{"word":"inbox","definition":"The place where new email messages arrive."},{"word":"reminder","definition":"An alert that helps someone remember."},{"word":"household","definition":"All the people who live in one home."}],"quiz":[{"question":"What were the two different plans that morning?","options":["Elias needed the car for a driving test","Both parents were going to the same clinic","Mum needed the market, and Dad needed the clinic","Dad was driving Mum to the market first"],"correctAnswer":"Mum needed the market, and Dad needed the clinic","explanation":"Mum needed the market, and Dad needed the clinic, so their plans were not the same.","supportingSentence":"Mum needed the market, and Dad needed the clinic.","skill":"detail"},{"question":"What does arriving with two sets of keys suggest?","options":["Each parent thought the one car was free for a different errand","The clinic was in the same building as the market","The family kept a spare car in the hall","Elias had already booked a taxi for both of them"],"correctAnswer":"Each parent thought the one car was free for a different errand","explanation":"Both parents bring keys for different plans, which shows each expected to drive the shared car.","supportingSentence":"On Saturday morning both parents arrived in the hall with keys and different plans.","skill":"inference"},{"question":"Where was the meeting change before Elias edited the calendar?","options":["On a paper note in the hall","Only in Dad's email","On a sign at the clinic","In Mum's shopping list"],"correctAnswer":"Only in Dad's email","explanation":"Elias saw that the meeting change was still only in Dad's email.","supportingSentence":"Their son, Elias, opened the app and saw that the meeting change was still only in Dad's email.","skill":"detail"},{"question":"What does being annoyed with themselves suggest?","options":["They decided the household should sell the car","They saw the mix-up as their own failure to share the news","They blamed the clinic for moving the meeting","They were cross that Elias had found a solution"],"correctAnswer":"They saw the mix-up as their own failure to share the news","explanation":"They agree to the plan but are annoyed with themselves, which points to their own missed update.","supportingSentence":"They agreed, slightly annoyed with themselves.","skill":"inference"},{"question":"What is an inbox in this story?","options":["The place where an email message arrives","A drawer in the hall where the keys are kept","A paper calendar stuck to the fridge","The market stall the family visits"],"correctAnswer":"The place where an email message arrives","explanation":"Elias turns on a reminder so a change sitting in one inbox, meaning one email folder, will not surprise everyone.","supportingSentence":"Elias also turned on a reminder so a change in one inbox would not surprise the whole household again.","skill":"vocabulary"}],"wordCount":110,"questionCount":5}$q54271$::jsonb,
  'e8a494b6a10b7ec916d170d26145b7eba7c48fcc919af468a859dc286b0276d7',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1dd69c51-041d-44f8-a55d-a9cc62550fa6'::uuid,
  'reading',
  'B2',
  'text',
  $q4630${"topic":"science","wordCount":103,"questionCount":5}$q4630$::jsonb,
  $q64308${"mode":"reading","level":"B2","format":"text","topic":"Science","title":"Water in Two Soil Beds","story":"The science club wanted to know why tomatoes grew better beside the shed than near the path. Lila took a sample from each bed, labelled the pots, and left them to dry on a classroom shelf. She mixed each sample with water and tested how quickly it drained. The shed soil held water for longer, while the path soil let it run through at once. A simple chart made the difference obvious. Their teacher said sunlight might still matter, so the result was not the whole story. Even so, the club decided to add compost to the path bed before the next planting.","dialogue":[],"vocabulary":[{"word":"sample","definition":"A small amount taken so it can be tested."},{"word":"labelled","definition":"Marked with a name so it will not be mixed up."},{"word":"drained","definition":"Flowed through and away."},{"word":"chart","definition":"A simple display that makes results easy to see."},{"word":"compost","definition":"Rotted plant material added to improve soil."},{"word":"planting","definition":"Putting plants or seeds into the ground."}],"quiz":[{"question":"Where did the tomatoes grow better?","options":["Beside the shed, compared with the path","Only in the classroom pots","Near the path, compared with the shed","On the shelf where the samples dried"],"correctAnswer":"Beside the shed, compared with the path","explanation":"The club wanted to know why tomatoes grew better beside the shed than near the path.","supportingSentence":"The science club wanted to know why tomatoes grew better beside the shed than near the path.","skill":"detail"},{"question":"How might the water test help explain the plants?","options":["Soil by the shed held water longer than soil by the path","Soil by the path kept water for much longer","Neither soil allowed any water to drain","Both soils let the water run through at the same speed"],"correctAnswer":"Soil by the shed held water longer than soil by the path","explanation":"The shed soil held water longer while the path soil let it run through, which may explain the healthier plants.","supportingSentence":"The shed soil held water for longer, while the path soil let it run through at once.","skill":"inference"},{"question":"What warning did the teacher add?","options":["The chart had been drawn incorrectly","The samples should never have been labelled","Sunlight might still matter, so the test was not the whole story","Compost would kill the tomatoes"],"correctAnswer":"Sunlight might still matter, so the test was not the whole story","explanation":"The teacher said sunlight might still matter, so the drainage result was not a complete explanation.","supportingSentence":"Their teacher said sunlight might still matter, so the result was not the whole story.","skill":"detail"},{"question":"What does the decision to add compost suggest?","options":["They decided sunlight was the only cause","They stopped growing tomatoes after the test","They threw both soil samples away","They thought the path bed was worth improving even without every answer"],"correctAnswer":"They thought the path bed was worth improving even without every answer","explanation":"Even after the teacher says the result is incomplete, they still add compost, so they think a change is worth trying.","supportingSentence":"Even so, the club decided to add compost to the path bed before the next planting.","skill":"inference"},{"question":"What does drained mean in this story?","options":["Water passed through the soil and ran out","The plants were moved into the shed","The pots were left on a sunny shelf","The chart was coloured in two shades"],"correctAnswer":"Water passed through the soil and ran out","explanation":"Lila tested how quickly the water drained, meaning how fast it flowed through each sample.","supportingSentence":"She mixed each sample with water and tested how quickly it drained.","skill":"vocabulary"}],"wordCount":103,"questionCount":5}$q64308$::jsonb,
  '1dd69c51041d04f8b55da9cc62550fa6807864ada861b087dfb9040b3797e45f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'd32ce076-9b0e-4ddf-a8da-265772fb2cd7'::uuid,
  'reading',
  'B2',
  'text',
  $q5481${"topic":"economy_finance","wordCount":103,"questionCount":5}$q5481$::jsonb,
  $q54728${"mode":"reading","level":"B2","format":"text","topic":"Economy / Finance","title":"Sharing a Workshop Deposit","story":"Three friends booked a weekend photography workshop and split the deposit evenly. A week later Callum lost his weekend job and asked to drop out. The studio rules said the deposit could not be returned, so the cost had to be shared again. Mina checked the receipt and worked out the new amount for each remaining person. She showed the figures before anyone argued. Callum offered to pay his original share anyway, because the booking had been his idea. Mina refused that and suggested he pay only a smaller part. They wrote the agreement in a message so nobody would remember it differently.","dialogue":[],"vocabulary":[{"word":"deposit","definition":"Money paid in advance to hold a booking."},{"word":"receipt","definition":"A written record of what was paid."},{"word":"figures","definition":"Numbers used to work out an amount."},{"word":"original","definition":"The first version, before a later change."},{"word":"agreement","definition":"A decision that the people involved accept."},{"word":"studio","definition":"The business that organised the workshop."}],"quiz":[{"question":"Why did Callum ask to leave the workshop?","options":["He lost his weekend job","Mina told him his share was too small","He disliked the photography teacher","The studio moved the course to another city"],"correctAnswer":"He lost his weekend job","explanation":"A week later Callum lost his weekend job and asked to drop out.","supportingSentence":"A week later Callum lost his weekend job and asked to drop out.","skill":"detail"},{"question":"What does showing the figures first suggest about Mina?","options":["She hid the receipt from her friends","She wanted the new split based on numbers before anyone quarrelled","She refused to calculate anyone's share","She told Callum to pay for the whole weekend"],"correctAnswer":"She wanted the new split based on numbers before anyone quarrelled","explanation":"She shows the figures before anyone argues, so she wants the facts to lead the talk.","supportingSentence":"She showed the figures before anyone argued.","skill":"inference"},{"question":"Why could the friends not get the deposit back?","options":["Mina had lost the receipt","The workshop had been cancelled by the friends","Callum had already spent it on a camera","The studio rules said it could not be returned"],"correctAnswer":"The studio rules said it could not be returned","explanation":"The studio rules said the deposit could not be returned, so the cost had to be shared again.","supportingSentence":"The studio rules said the deposit could not be returned, so the cost had to be shared again.","skill":"detail"},{"question":"What does Mina's refusal suggest?","options":["She cancelled the photography workshop","She thought his full original share was too heavy after the job loss","She believed the studio had sent the money back","She wanted Callum to pay more than the others"],"correctAnswer":"She thought his full original share was too heavy after the job loss","explanation":"She refuses his offer to pay the original share and suggests a smaller part, which fits the fact that he has lost his job.","supportingSentence":"Mina refused that and suggested he pay only a smaller part.","skill":"inference"},{"question":"What is the deposit in this story?","options":["Money paid ahead of time to book the workshop","The camera each friend had to bring","A fine for missing a weekend class","The message that recorded their agreement"],"correctAnswer":"Money paid ahead of time to book the workshop","explanation":"The friends split the deposit when they booked, so it is the advance payment for the place.","supportingSentence":"Three friends booked a weekend photography workshop and split the deposit evenly.","skill":"vocabulary"}],"wordCount":103,"questionCount":5}$q54728$::jsonb,
  'd32ce0769b0e4ddfa8da265772fb2cd76e189cd0a502f3aa401bea4103ecfe2e',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '68deb17e-2bee-4e36-addb-22d4bf79517d'::uuid,
  'reading',
  'B2',
  'text',
  $q5486${"topic":"economy_finance","wordCount":108,"questionCount":5}$q5486$::jsonb,
  $q82362${"mode":"reading","level":"B2","format":"text","topic":"Economy / Finance","title":"The Short Cash Tin","story":"Before the market opened, Ruth counted the float in the cash tin and found it short by several notes. She almost accused her assistant, then remembered that she had paid the baker from the same tin the night before and had forgotten to replace the money. The assistant, Sam, had arrived early and had already arranged the fruit. Ruth apologised at once and put the missing amount back from her purse. She also started a small notebook for money that left the tin outside market hours. Sam said he was glad she had checked the memory before the blame. By midmorning the notebook already had its first line.","dialogue":[],"vocabulary":[{"word":"float","definition":"A small amount of cash kept so a seller can give change."},{"word":"accused","definition":"Said that someone had done something wrong."},{"word":"assistant","definition":"A person who helps with the work."},{"word":"purse","definition":"A small bag for carrying money."},{"word":"notebook","definition":"A book used to write records in."},{"word":"blame","definition":"Responsibility placed on someone for a fault."}],"quiz":[{"question":"What did Ruth remember about the short tin?","options":["The baker had refused to sell any bread","The notebook already showed a perfect total","She had paid the baker from it and forgotten to replace the money","Sam had taken the notes home the night before"],"correctAnswer":"She had paid the baker from it and forgotten to replace the money","explanation":"She remembered paying the baker from the tin and forgetting to put the money back.","supportingSentence":"She almost accused her assistant, then remembered that she had paid the baker from the same tin the night before and had forgotten to replace the money.","skill":"detail"},{"question":"What does almost accusing Sam suggest?","options":["The baker had accused Ruth before the market opened","She remembered that the tin had never held any cash","She nearly blamed him for a shortage she herself had caused","Sam had already confessed to taking the notes"],"correctAnswer":"She nearly blamed him for a shortage she herself had caused","explanation":"She almost accuses her assistant and only then remembers her own forgotten repayment.","supportingSentence":"She almost accused her assistant, then remembered that she had paid the baker from the same tin the night before and had forgotten to replace the money.","skill":"inference"},{"question":"What new record did Ruth start?","options":["A list of customers who preferred apples","A letter of apology to the baker","A notebook for money leaving the tin outside market hours","A second cash tin for Sam alone"],"correctAnswer":"A notebook for money leaving the tin outside market hours","explanation":"She started a small notebook for money that left the tin outside market hours.","supportingSentence":"She also started a small notebook for money that left the tin outside market hours.","skill":"detail"},{"question":"What does Sam's reply suggest mattered to him?","options":["He was glad the fruit had been left in the van","He wanted the baker blamed in front of customers","He would rather be judged on the facts than suspected immediately","He hoped Ruth would close the stall at once"],"correctAnswer":"He would rather be judged on the facts than suspected immediately","explanation":"He is glad she checked her memory before the blame, so a fair check matters more to him than a quick accusation.","supportingSentence":"Sam said he was glad she had checked the memory before the blame.","skill":"inference"},{"question":"What does float mean in this story?","options":["The fruit Sam arranged before opening","A notebook of unpaid bills","Cash kept in the tin for giving change","A boat used to carry fruit to market"],"correctAnswer":"Cash kept in the tin for giving change","explanation":"Ruth counts the float in the cash tin and finds notes missing, so the float is the stall's change money.","supportingSentence":"Before the market opened, Ruth counted the float in the cash tin and found it short by several notes.","skill":"vocabulary"}],"wordCount":108,"questionCount":5}$q82362$::jsonb,
  '68deb17e2bee3e366ddb22d4bf79517d57b5fb8c1a1420cfcd06945a11a687fe',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '8e5115d2-7cd1-4e80-a87c-dcebdda4867b'::uuid,
  'reading',
  'B2',
  'text',
  $q4694${"topic":"mystery","wordCount":100,"questionCount":5}$q4694$::jsonb,
  $q48565${"mode":"reading","level":"B2","format":"text","topic":"Mystery","title":"Blue Ink on the Roster","story":"The cafe roster on the fridge had been rewritten in unfamiliar handwriting, and Jo's early shift had become a closing one. Nobody had mentioned a change. She asked the manager, who said the printed copy was different. They compared the lists. Only the fridge copy moved Jo to the evening, on a day when she had a class. A smudge on the staff pen matched the new numbers. The pen belonged to a new staff member who wanted Jo's morning shift but had been too shy to ask. The manager restored the original hours and talked quietly about asking directly.","dialogue":[],"vocabulary":[{"word":"roster","definition":"A list showing who works, and when."},{"word":"unfamiliar","definition":"Not recognised; strange to the reader."},{"word":"smudge","definition":"A dirty mark left by ink."},{"word":"restored","definition":"Put back the way it was before."},{"word":"shy","definition":"Nervous about speaking up."},{"word":"directly","definition":"In an open way, without hiding the point."}],"quiz":[{"question":"What had happened to Jo's early shift on the fridge?","options":["It had been changed into a closing shift","It matched the printed copy exactly","It had moved to a day when she had no class","It had been rubbed out with no replacement"],"correctAnswer":"It had been changed into a closing shift","explanation":"The rewritten fridge roster had turned Jo's early shift into a closing one.","supportingSentence":"The cafe roster on the fridge had been rewritten in unfamiliar handwriting, and Jo's early shift had become a closing one.","skill":"detail"},{"question":"Who most likely rewrote the fridge roster?","options":["The new staff member who wanted Jo's morning shift","A customer who had borrowed a pen","Jo herself, so she could sleep in","The manager, who wanted Jo to miss class"],"correctAnswer":"The new staff member who wanted Jo's morning shift","explanation":"The pen that matches the new numbers belongs to a new staff member who wanted Jo's morning shift but was too shy to ask.","supportingSentence":"The pen belonged to a new staff member who wanted Jo's morning shift but had been too shy to ask.","skill":"inference"},{"question":"What did the manager say about the printed copy?","options":["It had been thrown away","It used the same handwriting as the fridge","It was different from the fridge list","It gave Jo the evening shift as well"],"correctAnswer":"It was different from the fridge list","explanation":"The manager said the printed copy was different, so the official list had not been changed in the same way.","supportingSentence":"She asked the manager, who said the printed copy was different.","skill":"detail"},{"question":"What does the manager's quiet talk suggest?","options":["The handwritten list should replace the printed hours","Staff should ask for a change instead of secretly rewriting the list","Jo should skip class whenever the fridge says so","Blue pens should be banned from the cafe"],"correctAnswer":"Staff should ask for a change instead of secretly rewriting the list","explanation":"After restoring the hours, the manager talks about asking directly, so the real lesson is to request a change openly.","supportingSentence":"The manager restored the original hours and talked quietly about asking directly.","skill":"inference"},{"question":"What does smudge mean in this story?","options":["A mark of ink on the staff pen","A spoken request to the manager","A shift that starts in the evening","A clean printed page"],"correctAnswer":"A mark of ink on the staff pen","explanation":"A smudge on the staff pen matched the new numbers, so the word means an ink mark.","supportingSentence":"A smudge on the staff pen matched the new numbers.","skill":"vocabulary"}],"wordCount":100,"questionCount":5}$q48565$::jsonb,
  '8e5115d27cd1de80987cdcebdda4867b2579e335e865353103a8c2ea18cfed0f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f79c504a-4b46-47d7-a424-63fc534e018a'::uuid,
  'reading',
  'B2',
  'text',
  $q4695${"topic":"mystery","wordCount":110,"questionCount":5}$q4695$::jsonb,
  $q49764${"mode":"reading","level":"B2","format":"text","topic":"Mystery","title":"Sketches in the Boathouse","story":"The rowing club kept the boathouse locked, yet the caretaker saw a light there on two rainy nights. Nothing was missing, and the boats were where the list said they should be. On the third night he waited by the path. A teenager slipped inside with a small lamp and a notebook, then started drawing the stored boats. It was the caretaker's grandson, who did not have a quiet place at home. He had copied the spare key weeks earlier. The caretaker did not shout. He switched on the main light, looked at the careful sketches, and said the boy could draw there if he signed the visitor book first.","dialogue":[],"vocabulary":[{"word":"boathouse","definition":"A building where boats are stored."},{"word":"caretaker","definition":"A person who looks after a building."},{"word":"slipped","definition":"Went in quietly, hoping not to be noticed."},{"word":"sketches","definition":"Drawings made quickly."},{"word":"copied","definition":"Made a copy of something."},{"word":"visitor","definition":"Someone who comes to a place but is not on the staff."}],"quiz":[{"question":"How had the boy been getting into the boathouse?","options":["He climbed through a broken window","A club member invited him each night","He had copied the spare key weeks earlier","The caretaker had left the door open"],"correctAnswer":"He had copied the spare key weeks earlier","explanation":"The boy had copied the spare key weeks earlier, which is how he got in.","supportingSentence":"He had copied the spare key weeks earlier.","skill":"detail"},{"question":"What did the state of the boats suggest?","options":["The list said every boat was missing","The light was only a reflection on the water","The night visitor had probably not come to steal","The boats had all been sold that day"],"correctAnswer":"The night visitor had probably not come to steal","explanation":"Nothing was missing and the boats were where the list said, so theft is an unlikely reason for the light.","supportingSentence":"Nothing was missing, and the boats were where the list said they should be.","skill":"inference"},{"question":"Why did the grandson need a place like the boathouse?","options":["He wanted to take a boat out in the rain","He did not have a quiet place at home","The caretaker had asked him to guard the door","He was repairing the stored boats"],"correctAnswer":"He did not have a quiet place at home","explanation":"The boy was the caretaker's grandson, who did not have a quiet place at home.","supportingSentence":"It was the caretaker's grandson, who did not have a quiet place at home.","skill":"detail"},{"question":"What does the caretaker's decision suggest?","options":["He wanted the boy to take a boat home","He would allow the drawing if the boy followed a rule","He signed the visitor book and then locked the boy out","He shouted and banned every future visit"],"correctAnswer":"He would allow the drawing if the boy followed a rule","explanation":"He looks at the sketches and says the boy may draw there if he signs the visitor book first.","supportingSentence":"He switched on the main light, looked at the careful sketches, and said the boy could draw there if he signed the visitor book first.","skill":"inference"},{"question":"What does slipped mean in this story?","options":["Went inside quietly, without wanting to be seen","Locked the door and walked away","Fell over on the wet path","Shouted for the caretaker to come"],"correctAnswer":"Went inside quietly, without wanting to be seen","explanation":"The teenager slipped inside at night with a small lamp, which means he entered quietly.","supportingSentence":"A teenager slipped inside with a small lamp and a notebook, then started drawing the stored boats.","skill":"vocabulary"}],"wordCount":110,"questionCount":5}$q49764$::jsonb,
  'f79c504a4b4687d7d42463fc534e018a9d7199e1a0ba7589c810b82740da9bd4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'a9ab9b30-25b5-4939-a135-cfaee4ebbecd'::uuid,
  'reading',
  'B2',
  'text',
  $q4879${"topic":"adventure","wordCount":108,"questionCount":5}$q4879$::jsonb,
  $q27318${"mode":"reading","level":"B2","format":"text","topic":"Adventure","title":"Around the Fallen Tree","story":"The walking club meant to meet their minibus at the valley car park at four. A fallen tree blocked the direct lane, and the sky was dim. Their guide, Nia, chose a farm track above the blockage. It was longer, but the ground was firm. Two members wanted to climb the tree, because the car park looked close. Nia pointed at the wet branches and the slope beyond them. A slip would leave someone below the lane with no easy way back. The group took the farm track in single file. They arrived muddy and twenty minutes late. The driver had waited, and nobody had to be rescued.","dialogue":[],"vocabulary":[{"word":"minibus","definition":"A small bus used to carry a group."},{"word":"dim","definition":"Not bright."},{"word":"blockage","definition":"Something that stops people getting through."},{"word":"slope","definition":"Ground that rises or falls at an angle."},{"word":"guide","definition":"The person leading the group."},{"word":"rescued","definition":"Saved from danger."}],"quiz":[{"question":"Where had the club agreed to meet the minibus?","options":["Below the lane, beside the slope","At the start of the walk at noon","At the valley car park at four","On the farm track above the tree"],"correctAnswer":"At the valley car park at four","explanation":"The walking club meant to meet their minibus at the valley car park at four.","supportingSentence":"The walking club meant to meet their minibus at the valley car park at four.","skill":"detail"},{"question":"What does the warning about a slip suggest was most important to Nia?","options":["Proving that the farm track was blocked too","Getting someone rescued from under the tree","Keeping people from a fall, ahead of saving time","Arriving earlier than the minibus"],"correctAnswer":"Keeping people from a fall, ahead of saving time","explanation":"She points out that a slip would leave someone below the lane, so safety outweighs the shorter climb.","supportingSentence":"A slip would leave someone below the lane with no easy way back.","skill":"inference"},{"question":"Why did two members want to climb the tree?","options":["The driver had told them to","The farm track was under water","The car park looked close","Nia had lost the map"],"correctAnswer":"The car park looked close","explanation":"Two members wanted to climb the tree because the car park looked close.","supportingSentence":"Two members wanted to climb the tree, because the car park looked close.","skill":"detail"},{"question":"What does the ending suggest about the longer route?","options":["A walker had to be rescued from the tree","The extra time was worth it because nobody needed rescuing","The driver left before the group arrived","The farm track was shorter than the blocked lane"],"correctAnswer":"The extra time was worth it because nobody needed rescuing","explanation":"They arrive late, the driver has waited, and nobody has to be rescued, so the safer route did its job.","supportingSentence":"The driver had waited, and nobody had to be rescued.","skill":"inference"},{"question":"What is the blockage in this story?","options":["A river across the farm track","Fog that hid the valley car park","The fallen tree that shut the direct lane","The minibus that arrived too early"],"correctAnswer":"The fallen tree that shut the direct lane","explanation":"A fallen tree blocks the direct lane, and Nia chooses a track above that blockage.","supportingSentence":"Their guide, Nia, chose a farm track above the blockage.","skill":"vocabulary"}],"wordCount":108,"questionCount":5}$q27318$::jsonb,
  'a9ab9b3025b5a939b135cfaee4ebbecd3c96ae38c7886ce57abf2d75bd77b764',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '585675e1-e2ea-47c9-aec5-95acf0979d49'::uuid,
  'reading',
  'B2',
  'text',
  $q4872${"topic":"adventure","wordCount":110,"questionCount":5}$q4872$::jsonb,
  $q40420${"mode":"reading","level":"B2","format":"text","topic":"Adventure","title":"A Stick in the Current","story":"The path crossed a stream by stepping stones, but overnight rain had covered them. Nadia and her cousin stood on the bank with a bus to catch in the next village. Crossing quickly was tempting, because the water looked only knee deep. Nadia tested a stick against the current and felt it pulled sideways. She remembered a ranger saying that moving water was stronger than it looked. They climbed to a higher track, which added an hour and a scratchy slope. The bus was gone when they arrived. A shopkeeper let them wait inside, and the next bus came before dark. Nadia was late, but both of them were dry.","dialogue":[],"vocabulary":[{"word":"overnight","definition":"During the night."},{"word":"tempting","definition":"Attractive to try, even if it may be unwise."},{"word":"current","definition":"The moving force of water in a stream."},{"word":"ranger","definition":"A person who looks after a stretch of countryside."},{"word":"slope","definition":"Ground that goes upward at an angle."},{"word":"shopkeeper","definition":"A person who runs a shop."}],"quiz":[{"question":"What had happened to the stepping stones?","options":["Overnight rain had covered them","The shopkeeper had removed them","Nadia had carried them to the higher track","A ranger had painted them so they showed clearly"],"correctAnswer":"Overnight rain had covered them","explanation":"The path used stepping stones, but overnight rain had covered them.","supportingSentence":"The path crossed a stream by stepping stones, but overnight rain had covered them.","skill":"detail"},{"question":"What did the stick test suggest about the stream?","options":["The current was stronger than a quick look suggested","The stepping stones were easy to see again","The water was still and safe to cross at once","The stick floated across without being pulled"],"correctAnswer":"The current was stronger than a quick look suggested","explanation":"The stick is pulled sideways, which shows the current is forceful even if the stream looks shallow.","supportingSentence":"Nadia tested a stick against the current and felt it pulled sideways.","skill":"inference"},{"question":"What did the higher track add to the journey?","options":["A shorter walk to the same bus","An hour and a scratchy slope","A dry crossing over the stepping stones","A bridge the ranger had just built"],"correctAnswer":"An hour and a scratchy slope","explanation":"The higher track added an hour and a scratchy slope.","supportingSentence":"They climbed to a higher track, which added an hour and a scratchy slope.","skill":"detail"},{"question":"What does the ending suggest about their decision?","options":["They caught the first bus they had hoped for","Missing that bus was safer than crossing the water","The shopkeeper carried them across the stream","They stayed dry because they waded through quickly"],"correctAnswer":"Missing that bus was safer than crossing the water","explanation":"Nadia is late, but both of them are dry, so refusing the crossing kept them safe.","supportingSentence":"Nadia was late, but both of them were dry.","skill":"inference"},{"question":"What does tempting mean in this story?","options":["Impossible to attempt","Attractive to try, though it may be unsafe","Already finished before they arrived","Forbidden by the shopkeeper"],"correctAnswer":"Attractive to try, though it may be unsafe","explanation":"Crossing quickly was tempting because the water looked shallow, even though that choice was risky.","supportingSentence":"Crossing quickly was tempting, because the water looked only knee deep.","skill":"vocabulary"}],"wordCount":110,"questionCount":5}$q40420$::jsonb,
  '585675e1e2ea47c99ec595acf0979d49e5bf654707935a0c9b774dbc2e7a0bb4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '62750a54-2a7f-4573-a2b4-f4a2ca502c66'::uuid,
  'reading',
  'B2',
  'text',
  $q4656${"topic":"fantasy","wordCount":110,"questionCount":5}$q4656$::jsonb,
  $q32386${"mode":"reading","level":"B2","format":"text","topic":"Fantasy","title":"The Well at Pell","story":"In the village of Pell, a round well kept coins that were offered for someone else and returned coins that were offered for oneself. Tessa dropped in a coin and wished for a new coat. The coin landed back on the moss beside her shoe. She tried again, wishing for her brother's exam to go calmly, and that coin stayed in the dark water. Tessa sat on the wall and laughed at her own first attempt. She told her brother only that the well was particular. On the exam morning she left another coin for his steady hands. The well made no sound, which, in Pell, counted as a yes.","dialogue":[],"vocabulary":[{"word":"offered","definition":"Given for a purpose, here with a wish."},{"word":"returned","definition":"Sent back to the giver."},{"word":"moss","definition":"A soft green plant that grows in damp places."},{"word":"particular","definition":"Hard to please, and accepting only certain things."},{"word":"calmly","definition":"In a quiet, untroubled way."},{"word":"attempt","definition":"One try at doing something."}],"quiz":[{"question":"What happened to the coin Tessa wished on for a coat?","options":["It landed back on the moss beside her shoe","It stayed deep in the water","Her brother caught it before it fell","It turned into a second coin"],"correctAnswer":"It landed back on the moss beside her shoe","explanation":"After she wished for a new coat, the coin landed back on the moss beside her shoe.","supportingSentence":"The coin landed back on the moss beside her shoe.","skill":"detail"},{"question":"Why does Tessa laugh at her first attempt?","options":["She sees that a wish for herself was the wrong kind","The exam had already been cancelled","Her brother had bought the coat already","Every coin in the village came back at the same moment"],"correctAnswer":"She sees that a wish for herself was the wrong kind","explanation":"The well returns wishes made for oneself, and she laughs at that first attempt once she has understood.","supportingSentence":"Tessa sat on the wall and laughed at her own first attempt.","skill":"inference"},{"question":"What happened to the coin for her brother's exam?","options":["It stayed in the dark water","It was returned the same afternoon","It bounced back onto the wall","It paid for a new coat"],"correctAnswer":"It stayed in the dark water","explanation":"When she wished for her brother's exam to go calmly, that coin stayed in the dark water.","supportingSentence":"She tried again, wishing for her brother's exam to go calmly, and that coin stayed in the dark water.","skill":"detail"},{"question":"What does the limited thing she told her brother suggest?","options":["She said the well had cracked and dried","She kept the well's full rule to herself","She described every returned coin in detail","She refused to speak to him at all"],"correctAnswer":"She kept the well's full rule to herself","explanation":"She tells him only that the well is particular, so she withholds the rest of what she has learned.","supportingSentence":"She told her brother only that the well was particular.","skill":"inference"},{"question":"What does particular mean in this story?","options":["Broken, and unable to hold water","Loud enough for the whole village to hear","Accepting only certain kinds of wishes","Willing to grant any wish at all"],"correctAnswer":"Accepting only certain kinds of wishes","explanation":"Tessa calls the well particular because it keeps some offerings and sends others back.","supportingSentence":"She told her brother only that the well was particular.","skill":"vocabulary"}],"wordCount":110,"questionCount":5}$q32386$::jsonb,
  '62750a542a7f257352b4f4a2ca502c6638f10b9b5e07b4b11f75b3853e260fae',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '13e6caa0-ffdb-487c-a8cd-4680799fb5d3'::uuid,
  'reading',
  'B2',
  'text',
  $q4656${"topic":"fantasy","wordCount":101,"questionCount":5}$q4656$::jsonb,
  $q34411${"mode":"reading","level":"B2","format":"text","topic":"Fantasy","title":"The Cloak on the Errand","story":"The market witch lent cloaks that changed with the wearer's mood, though she avoided the word magic near officials. Bram borrowed one for a mountain errand. While he told himself the journey was only for glory, the cloak grew heavy and hot. When he admitted he was carrying medicine for a sick neighbour, the cloth cooled and the wind helped him. He reached the cottage before the snow thickened. On the way down he boasted in the square, and the cloak became damp at once. Bram stopped. The witch said the garment listened badly to lies and well to plain reasons.","dialogue":[],"vocabulary":[{"word":"errand","definition":"A journey made in order to carry out a task."},{"word":"glory","definition":"Praise and fame for yourself."},{"word":"admitted","definition":"Said openly something you had not fully owned."},{"word":"thickened","definition":"Became denser or heavier."},{"word":"boasted","definition":"Talked with too much pride about yourself."},{"word":"garment","definition":"A piece of clothing."}],"quiz":[{"question":"What was Bram carrying for someone else?","options":["A letter from the market officials","A second cloak for the witch","Snow from the cottage roof","Medicine for a sick neighbour"],"correctAnswer":"Medicine for a sick neighbour","explanation":"He admitted he was carrying medicine for a sick neighbour.","supportingSentence":"When he admitted he was carrying medicine for a sick neighbour, the cloth cooled and the wind helped him.","skill":"detail"},{"question":"What does the heavy, hot cloak suggest?","options":["The snow had already soaked it before he started","Officials had filled the pockets with stones","Thinking of glory made the cloth light and cool","A reason that was only about glory was one the cloak resisted"],"correctAnswer":"A reason that was only about glory was one the cloak resisted","explanation":"While he tells himself the journey is only for glory, the cloak grows heavy and hot, so that reason does not suit it.","supportingSentence":"While he told himself the journey was only for glory, the cloak grew heavy and hot.","skill":"inference"},{"question":"Who lent Bram the cloak?","options":["The owner of the high cottage","His sick neighbour","An official in the square","The market witch"],"correctAnswer":"The market witch","explanation":"The market witch lent cloaks that changed with the wearer's mood.","supportingSentence":"The market witch lent cloaks that changed with the wearer's mood, though she avoided the word magic near officials.","skill":"detail"},{"question":"What does the damp cloak in the square suggest?","options":["The cottage roof had fallen on him","The witch had already taken the cloak away","He had dropped the medicine in the square","Boasting was another reason the cloak would not accept"],"correctAnswer":"Boasting was another reason the cloak would not accept","explanation":"As soon as he boasts, the cloak becomes damp, which fits its dislike of showy, untrue reasons.","supportingSentence":"On the way down he boasted in the square, and the cloak became damp at once.","skill":"inference"},{"question":"What does garment mean in this story?","options":["The mountain path to the cottage","The bottle of medicine","The official who heard the word magic","The cloak Bram had borrowed"],"correctAnswer":"The cloak Bram had borrowed","explanation":"The witch is talking about the cloak when she calls it a garment that listens badly to lies.","supportingSentence":"The witch said the garment listened badly to lies and well to plain reasons.","skill":"vocabulary"}],"wordCount":101,"questionCount":5}$q34411$::jsonb,
  '13e6caa0ffdb387c08cd4680799fb5d367aca66916ca010f9bfca036f23e58bc',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '65488e58-8596-4e03-a23f-62ff93cbafc2'::uuid,
  'reading',
  'B2',
  'text',
  $q4884${"topic":"daily life","wordCount":108,"questionCount":5}$q4884$::jsonb,
  $q46885${"mode":"reading","level":"B2","format":"text","topic":"Daily Life","title":"A Pact above the Kettle","story":"The flatmates argued about the kettle, the shower, and a phone alarm that rang three times. Finally they made a simple pact. Rafi would shower first, and Leah would use the kitchen first, so neither would wait in the hall. Alarms would live in bedrooms, not in the shared room. For four days it worked. On Friday Rafi forgot and set the loud alarm beside the sofa. Leah left it there and went to make tea, which made him more ashamed than a complaint would have. He moved the phone and wrote the pact above the kettle. The next week was not perfect, but the mornings were calmer.","dialogue":[],"vocabulary":[{"word":"flatmates","definition":"People who share a flat."},{"word":"pact","definition":"An agreement about how people will act."},{"word":"alarm","definition":"A phone signal meant to wake someone."},{"word":"ashamed","definition":"Sorry and uncomfortable about something you did."},{"word":"complaint","definition":"A criticism spoken when something displeases you."},{"word":"calmer","definition":"More peaceful, with less tension."}],"quiz":[{"question":"What morning order did the pact set?","options":["Leah would shower first, and Rafi would cook first","The alarms would stay in the shared room","Both of them would use the kitchen at the same moment","Rafi would shower first, and Leah would use the kitchen first"],"correctAnswer":"Rafi would shower first, and Leah would use the kitchen first","explanation":"The pact said Rafi would shower first and Leah would use the kitchen first.","supportingSentence":"Rafi would shower first, and Leah would use the kitchen first, so neither would wait in the hall.","skill":"detail"},{"question":"What does writing the pact above the kettle suggest?","options":["Rafi wanted the agreement in a place they would see every morning","He was moving out of the flat that night","He wanted Leah to stop using the kitchen","He had decided to throw the kettle away"],"correctAnswer":"Rafi wanted the agreement in a place they would see every morning","explanation":"He writes the pact above the kettle, a spot used in the morning routine, so it will stay visible.","supportingSentence":"He moved the phone and wrote the pact above the kettle.","skill":"inference"},{"question":"Where were the alarms supposed to stay?","options":["In the bedrooms, not in the shared room","In the bathroom during every shower","Beside the sofa in the shared room","Above the kettle with the pact"],"correctAnswer":"In the bedrooms, not in the shared room","explanation":"They agreed that alarms would live in bedrooms, not in the shared room.","supportingSentence":"Alarms would live in bedrooms, not in the shared room.","skill":"detail"},{"question":"What does the following week suggest about the pact?","options":["They took the written pact down at once","The mornings became perfect on the first day","The flatmates went back to the same daily quarrel","It made mornings easier without ending every slip"],"correctAnswer":"It made mornings easier without ending every slip","explanation":"The next week was not perfect, but the mornings were calmer, so the pact helped without removing every mistake.","supportingSentence":"The next week was not perfect, but the mornings were calmer.","skill":"inference"},{"question":"What does pact mean in this story?","options":["A broken phone alarm","A lock on the bathroom door","A complaint about the tea","A shared agreement about how the mornings will work"],"correctAnswer":"A shared agreement about how the mornings will work","explanation":"The flatmates make a pact that sets who uses the shower and the kitchen first.","supportingSentence":"Finally they made a simple pact.","skill":"vocabulary"}],"wordCount":108,"questionCount":5}$q46885$::jsonb,
  '65488e5885964e03a23f62ff93cbafc2360f42b6d931eddb514d4528b7163fe0',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '6788593a-4ce2-43af-aa2c-70da757002c5'::uuid,
  'reading',
  'B2',
  'text',
  $q5372${"topic":"school_college","wordCount":110,"questionCount":5}$q5372$::jsonb,
  $q41692${"mode":"reading","level":"B2","format":"text","topic":"School / College","title":"Closing the Notebook","story":"Every Thursday the college ran a language exchange in the canteen. Denis wanted to practise speaking, but he kept preparing speeches and then reading them. His partner, Hana, asked him to close the notebook and describe his morning instead. The first attempt was full of pauses. Hana waited without filling every gap, which felt strange and then useful. Denis started again and managed a short story about missing the bus. Hana corrected only one verb, then told her own story and asked him to retell it. By the end of the hour he had spoken more than he had written. He left the notebook in his bag the following week.","dialogue":[],"vocabulary":[{"word":"exchange","definition":"A session where people practise a language together."},{"word":"speeches","definition":"Prepared talks, often written out to be read."},{"word":"pauses","definition":"Short stops while someone is speaking."},{"word":"retell","definition":"To tell a story again in your own words."},{"word":"verb","definition":"A word that names an action."},{"word":"canteen","definition":"The college place where people eat."}],"quiz":[{"question":"What was Denis doing instead of speaking freely?","options":["Leaving his notebook in the canteen","Retelling Hana's story before she spoke","Preparing speeches and then reading them","Correcting Hana's verbs for the whole hour"],"correctAnswer":"Preparing speeches and then reading them","explanation":"He wanted to practise speaking, but he kept preparing speeches and then reading them.","supportingSentence":"Denis wanted to practise speaking, but he kept preparing speeches and then reading them.","skill":"detail"},{"question":"What does Hana's silence during the pauses suggest?","options":["She hoped he would open the notebook again","She refused to listen to his morning","She wanted Denis to find the words himself","She had forgotten the language they were practising"],"correctAnswer":"She wanted Denis to find the words himself","explanation":"She waits instead of filling every gap, and that wait becomes useful, so she is giving him room to speak.","supportingSentence":"Hana waited without filling every gap, which felt strange and then useful.","skill":"inference"},{"question":"How much of his language did Hana correct?","options":["Every verb in both stories","Nothing at all","Only one verb","The whole notebook of speeches"],"correctAnswer":"Only one verb","explanation":"Hana corrected only one verb before she told her own story.","supportingSentence":"Hana corrected only one verb, then told her own story and asked him to retell it.","skill":"detail"},{"question":"What does leaving the notebook in his bag suggest?","options":["He wanted Hana to write his speeches","He had dropped out of the Thursday exchange","He intended to speak without reading a prepared text","He planned to read a longer speech next time"],"correctAnswer":"He intended to speak without reading a prepared text","explanation":"After speaking more than he wrote, he leaves the notebook in his bag, so he is choosing speech over a script.","supportingSentence":"He left the notebook in his bag the following week.","skill":"inference"},{"question":"What does pauses mean in this story?","options":["Corrections of every verb","Stories about missing a bus","Short silences while someone is trying to speak","Prepared speeches kept in a notebook"],"correctAnswer":"Short silences while someone is trying to speak","explanation":"The first attempt was full of pauses, meaning short stops while Denis searched for words.","supportingSentence":"The first attempt was full of pauses.","skill":"vocabulary"}],"wordCount":110,"questionCount":5}$q41692$::jsonb,
  '6788593a4ce223af7a2c70da757002c52df3933b920f74009272a254b17a2df5',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '617d549e-4719-4bfe-a600-491eb3bdeece'::uuid,
  'reading',
  'B2',
  'text',
  $q4555${"topic":"travel","wordCount":104,"questionCount":5}$q4555$::jsonb,
  $q32397${"mode":"reading","level":"B2","format":"text","topic":"Travel","title":"Shoes by the Homestay Door","story":"Elena's homestay note asked guests to leave shoes by the door and to join breakfast, even for tea. On the first morning she forgot and stepped into the kitchen. The host, Farid, pointed to the mat without raising his voice. Elena apologised and noticed the other guests had lined their shoes up neatly. At the table people passed plates before serving themselves. She had planned to eat quickly and leave for a museum. Instead she stayed, asked about the bread, and got directions clearer than her app. The rule had felt strict. By evening she saw it as a way to share the house.","dialogue":[],"vocabulary":[{"word":"homestay","definition":"A stay in the home of a local host."},{"word":"host","definition":"The person who welcomes a guest into a home."},{"word":"apologised","definition":"Said that she was sorry."},{"word":"neatly","definition":"In a tidy order."},{"word":"directions","definition":"Instructions that explain how to get somewhere."},{"word":"strict","definition":"Firm about a rule being followed."}],"quiz":[{"question":"What did the homestay note ask guests to do?","options":["Wear shoes at the table","Eat in their rooms and avoid the kitchen","Leave shoes by the door and join breakfast","Skip breakfast if they only wanted tea"],"correctAnswer":"Leave shoes by the door and join breakfast","explanation":"The note asked guests to leave shoes by the door and to join breakfast, even for tea.","supportingSentence":"Elena's homestay note asked guests to leave shoes by the door and to join breakfast, even for tea.","skill":"detail"},{"question":"What does Farid's quiet gesture suggest?","options":["He could not speak because of an injury","He ordered her to leave the house at once","He corrected the mistake without trying to shame her","He wanted shoes worn inside the kitchen"],"correctAnswer":"He corrected the mistake without trying to shame her","explanation":"He points to the mat without raising his voice, so the correction is calm rather than humiliating.","supportingSentence":"The host, Farid, pointed to the mat without raising his voice.","skill":"inference"},{"question":"What had Elena planned to do at breakfast?","options":["Cook for the other guests","Stay all morning and skip the museum","Eat quickly and leave for a museum","Ask Farid to cancel the shoe rule"],"correctAnswer":"Eat quickly and leave for a museum","explanation":"She had planned to eat quickly and leave for a museum.","supportingSentence":"She had planned to eat quickly and leave for a museum.","skill":"detail"},{"question":"What can we infer from the directions she received?","options":["She left for the museum without eating","The bread was served only to the host","Joining breakfast gave her help that rushing away would not","Her app was clearer than anything the household told her"],"correctAnswer":"Joining breakfast gave her help that rushing away would not","explanation":"She stays, talks about the bread, and gets directions clearer than her app, so taking part helps her.","supportingSentence":"Instead she stayed, asked about the bread, and got directions clearer than her app.","skill":"inference"},{"question":"What does strict mean in this story?","options":["Firm about a rule being obeyed","Unsure where the shoes should go","Happy to ignore every house custom","Ready to cancel breakfast"],"correctAnswer":"Firm about a rule being obeyed","explanation":"The rule felt strict at first, meaning it seemed firm and demanding.","supportingSentence":"The rule had felt strict.","skill":"vocabulary"}],"wordCount":104,"questionCount":5}$q32397$::jsonb,
  '617d549e47193bfee600491eb3bdeece54189ec48c5a65309109ee0fcccb5c5a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'edbeb2f8-f541-4736-a224-9f01a2faf8b9'::uuid,
  'reading',
  'B2',
  'text',
  $q4631${"topic":"hobbies","wordCount":102,"questionCount":5}$q4631$::jsonb,
  $q46993${"mode":"reading","level":"B2","format":"text","topic":"Hobbies","title":"A Daisy from the Park","story":"Chris pressed wildflowers on country walks, partly to give the walks a purpose. He carried a heavy book, tissue paper, and a pencil for names he could only guess. At home he checked a field guide before writing a label, because a wrong name had embarrassed him once. His niece asked if the dry flowers were sad. Chris said they were a record of where he had been, and he showed her a page from a windy cliff. She pressed a park daisy herself. The hobby stayed simple, but Chris grew patient, since the flowers needed weeks before they would not curl.","dialogue":[],"vocabulary":[{"word":"wildflowers","definition":"Flowers growing on their own, not planted in a garden."},{"word":"tissue","definition":"Thin soft paper."},{"word":"label","definition":"A name written so a specimen can be identified."},{"word":"embarrassed","definition":"Made uncomfortable by a mistake."},{"word":"patient","definition":"Able to wait without becoming cross."},{"word":"curl","definition":"Bend out of a flat shape."}],"quiz":[{"question":"Why did Chris check a field guide before writing a name?","options":["His niece had hidden the pencil","A wrong name had embarrassed him once","The guide told him not to press daisies","The cliff page had no flowers on it"],"correctAnswer":"A wrong name had embarrassed him once","explanation":"He checked the field guide before writing a label because a wrong name had embarrassed him once.","supportingSentence":"At home he checked a field guide before writing a label, because a wrong name had embarrassed him once.","skill":"detail"},{"question":"What does the pencil for guessed names suggest?","options":["He could already name every flower without help","He noted uncertain names instead of trusting a first guess","He used the pencil only to draw the cliff","He refused to carry any paper on the walk"],"correctAnswer":"He noted uncertain names instead of trusting a first guess","explanation":"He carries a pencil for names he can only guess, so those notes are provisional until he checks them.","supportingSentence":"He carried a heavy book, tissue paper, and a pencil for names he could only guess.","skill":"inference"},{"question":"How long did the flowers need before they would stay flat?","options":["Weeks, or they might curl","Only until his niece chose a daisy","Until the next country walk","A single afternoon"],"correctAnswer":"Weeks, or they might curl","explanation":"The flowers needed weeks before they could be trusted not to curl.","supportingSentence":"The hobby stayed simple, but Chris grew patient, since the flowers needed weeks before they would not curl.","skill":"detail"},{"question":"What does the niece's daisy suggest?","options":["She already owned a complete field guide","She wanted to try the hobby after hearing what the flowers meant","She threw the heavy book away","She thought the dry flowers were only rubbish"],"correctAnswer":"She wanted to try the hobby after hearing what the flowers meant","explanation":"After he shows her a page and calls the flowers a record of places, she presses a daisy herself.","supportingSentence":"She pressed a park daisy herself.","skill":"inference"},{"question":"What is a label in this story?","options":["The heavy book used to press the flowers","A page torn from a newspaper","The name written for a flower after it has been checked","A wrong turning on a country walk"],"correctAnswer":"The name written for a flower after it has been checked","explanation":"He checks a guide before writing a label, so the label is the name he gives the flower.","supportingSentence":"At home he checked a field guide before writing a label, because a wrong name had embarrassed him once.","skill":"vocabulary"}],"wordCount":102,"questionCount":5}$q46993$::jsonb,
  'edbeb2f8f541973652249f01a2faf8b932d922271ad96e40d3fb658e7b205937',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '5461e088-a982-423e-a240-b8c1425f2948'::uuid,
  'reading',
  'B2',
  'text',
  $q4884${"topic":"daily life","wordCount":153,"questionCount":5}$q4884$::jsonb,
  $q8666${"mode":"reading","level":"B2","format":"text","topic":"Daily Life","title":"The Morning Bathroom Timer","story":"Every weekday the flat was loud between seven and eight, because three people needed the bathroom before work. Lena showered first, her father shaved while the kettle boiled, and her younger brother complained that the mirror was always fogged. One Tuesday the brother missed his bus after waiting outside the door for twelve minutes. Lena suggested a simple limit. Each person would have ten minutes, and a kitchen timer would sit on the shelf where everyone could see it. Her father worried that a timer would make the morning feel like a race. Lena said the point was to stop guessing and to leave the room before the next person knocked. The brother still sang, but he came out when the bell rang, and he wiped the mirror with the towel on the hook. Nobody missed a bus. By Friday the timer felt ordinary, and the hallway was quiet enough for a goodbye.","dialogue":[],"vocabulary":[{"word":"fogged","definition":"Covered with steam and hard to see through."},{"word":"complained","definition":"Said that you are unhappy about something."},{"word":"timer","definition":"A tool that marks when a set time has ended."},{"word":"guessing","definition":"Deciding something without a clear sign."},{"word":"ordinary","definition":"Normal, and no longer unusual."},{"word":"hallway","definition":"The passage inside a home between the rooms."}],"quiz":[{"question":"What happened to the brother on Tuesday morning?","options":["He missed the bus after waiting outside the door","He wiped the mirror and caught the bus at once","He locked the bathroom and left the flat early","He broke the shelf where the kettle was kept"],"correctAnswer":"He missed the bus after waiting outside the door","explanation":"He waited outside the door for twelve minutes and missed his bus.","supportingSentence":"One Tuesday the brother missed his bus after waiting outside the door for twelve minutes.","skill":"detail"},{"question":"What limit did Lena want for the bathroom?","options":["One shared shower after everybody had caught the bus","As long as the father wanted, with no bell at all","Twenty minutes for the brother and none for Lena","Ten minutes each, with the timer left in plain sight"],"correctAnswer":"Ten minutes each, with the timer left in plain sight","explanation":"Each person would have ten minutes, and the timer would sit where everyone could see it.","supportingSentence":"Each person would have ten minutes, and a kitchen timer would sit on the shelf where everyone could see it.","skill":"detail"},{"question":"Why was the bathroom mirror a problem for the brother?","options":["Steam from the earlier shower was still covering the glass","The towel on the hook had cracked the glass","He preferred to shave before the kettle had boiled","The kitchen timer was stored in front of the mirror"],"correctAnswer":"Steam from the earlier shower was still covering the glass","explanation":"Lena showered first, and her brother complained that the mirror was always fogged.","supportingSentence":"Lena showered first, her father shaved while the kettle boiled, and her younger brother complained that the mirror was always fogged.","skill":"inference"},{"question":"What does Friday morning show about the new limit?","options":["It had forced everyone to stop speaking in the flat","It had settled in, and the family could still say goodbye","It had moved every shower to the evening after work","It had made the brother miss the bus again"],"correctAnswer":"It had settled in, and the family could still say goodbye","explanation":"The timer felt ordinary, and the hallway was quiet enough for a goodbye.","supportingSentence":"By Friday the timer felt ordinary, and the hallway was quiet enough for a goodbye.","skill":"inference"},{"question":"What does fogged mean in this story?","options":["Covered with steam so the glass was hard to see in","Wiped dry and hung back on the hook","Left open so the bus would not be missed","Marked with a list of morning jobs"],"correctAnswer":"Covered with steam so the glass was hard to see in","explanation":"The brother complained that the mirror was fogged after the shower, so the glass was covered with steam.","supportingSentence":"Lena showered first, her father shaved while the kettle boiled, and her younger brother complained that the mirror was always fogged.","skill":"vocabulary"}],"wordCount":153,"questionCount":5}$q8666$::jsonb,
  '5461e088a982a23e0240b8c1425f2948e31e6727a989491e656b70a9a5d90268',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'ca346c0d-ae20-422d-a6e0-59141f21f1d0'::uuid,
  'reading',
  'B2',
  'text',
  $q5379${"topic":"school_college","wordCount":153,"questionCount":5}$q5379$::jsonb,
  $q95925${"mode":"reading","level":"B2","format":"text","topic":"School / College","title":"A Voice Lost before Friday","story":"The history group was due to present on Friday, and each student had prepared one section. On Thursday night Amir sent a message saying he had lost his voice and could not speak in class. Sofia offered to read his section as well as her own, but she asked the group to shorten the ending so the talk would still fit the time allowed. Denis moved the map earlier, because the notes explained the route of an old canal and the class needed that picture before the dates. They left the jokes out, since a written joke can fall flat when another person reads it aloud. In the morning Amir sat at the side and nodded when Sofia reached his title card. The teacher allowed the change once she heard why Amir could not speak. She later said the talk was clear and asked to see the notes he had prepared at home.","dialogue":[],"vocabulary":[{"word":"section","definition":"One part of a longer piece of work."},{"word":"shorten","definition":"To make something shorter."},{"word":"canal","definition":"A channel of water made by people."},{"word":"aloud","definition":"In a voice that other people can hear."},{"word":"nodded","definition":"Moved the head to show agreement or readiness."},{"word":"allowed","definition":"Said that something was acceptable."}],"quiz":[{"question":"How did Sofia keep the group talk inside the time allowed?","options":["She cancelled the talk and sent the teacher home","She moved the jokes to the start of the lesson","She asked Amir to shout his notes from the corridor","She read his section too and asked for a shorter ending"],"correctAnswer":"She read his section too and asked for a shorter ending","explanation":"Sofia offered to read his section as well as her own, and she asked the group to shorten the ending.","supportingSentence":"Sofia offered to read his section as well as her own, but she asked the group to shorten the ending so the talk would still fit the time allowed.","skill":"detail"},{"question":"Why did Denis move the map to an earlier point?","options":["The class needed the canal picture before the dates","The title card was too large for the final slide","Amir wanted the jokes to come before any picture","The teacher had banned every map from the room"],"correctAnswer":"The class needed the canal picture before the dates","explanation":"The notes explained an old canal route, and the class needed that picture before the dates.","supportingSentence":"Denis moved the map earlier, because the notes explained the route of an old canal and the class needed that picture before the dates.","skill":"detail"},{"question":"What does Amir do during the talk itself?","options":["He refuses to look at the title card","He stays involved by signalling when his part begins","He recovers his voice and reads the whole talk","He leaves the room before Sofia starts"],"correctAnswer":"He stays involved by signalling when his part begins","explanation":"He sat at the side and nodded when Sofia reached his title card, so he was still taking part.","supportingSentence":"In the morning Amir sat at the side and nodded when Sofia reached his title card.","skill":"inference"},{"question":"Why were Amir's jokes removed from the talk?","options":["A joke can fail when a different person reads it out","The teacher had already told those jokes","The canal map left no space for any words","Sofia wanted the talk to fill the whole day"],"correctAnswer":"A joke can fail when a different person reads it out","explanation":"They left the jokes out because a written joke can fall flat when another person reads it aloud.","supportingSentence":"They left the jokes out, since a written joke can fall flat when another person reads it aloud.","skill":"inference"},{"question":"What does canal mean in this story?","options":["A list of dates in a history talk","A joke told out loud to a class","A card held up beside the speaker","A water channel made by people"],"correctAnswer":"A water channel made by people","explanation":"The notes explained the route of an old canal, which is a water channel people made.","supportingSentence":"Denis moved the map earlier, because the notes explained the route of an old canal and the class needed that picture before the dates.","skill":"vocabulary"}],"wordCount":153,"questionCount":5}$q95925$::jsonb,
  'ca346c0dae20d22d26e059141f21f1d045f8b5ec0fb03eae222ec2bb77e829cd',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'a6f53b2c-ea2c-4306-a816-7664a300f1e4'::uuid,
  'reading',
  'B2',
  'text',
  $q4559${"topic":"travel","wordCount":153,"questionCount":5}$q4559$::jsonb,
  $q74939${"mode":"reading","level":"B2","format":"text","topic":"Travel","title":"Soup on the Later Platform","story":"Rafi reached the harbour station with his ticket in his coat and a few minutes to spare. The board then showed that his train had been cancelled because of a fault on the line. A clerk said the next direct service would leave from another platform in nearly two hours. He stayed inside in case the board changed, bought a cheap bowl of soup, and kept his paper map ready. While he waited, he checked that the guesthouse would still hold his room if he arrived after dark. The owner replied that a coded box by the door would hold the key, and that the street was quiet but well lit. Rafi sent his sister the new time so she would not worry. When the later train came, he boarded with an empty cup and the map folded the right way up. The delay had cost him daylight, but he was still going.","dialogue":[],"vocabulary":[{"word":"cancelled","definition":"Stopped from happening as planned."},{"word":"fault","definition":"A problem that stops something working."},{"word":"platform","definition":"The area in a station where people board a train."},{"word":"guesthouse","definition":"A small place where travellers pay to sleep."},{"word":"delay","definition":"Time lost when something happens later than planned."},{"word":"boarded","definition":"Got onto a train or other vehicle."}],"quiz":[{"question":"Why did Rafi's first train not leave?","options":["It was cancelled because of a problem on the line","He had left his ticket at home","The soup stall was blocking the doors","The guesthouse had closed before dark"],"correctAnswer":"It was cancelled because of a problem on the line","explanation":"The board showed that his train had been cancelled because of a fault on the line.","supportingSentence":"The board then showed that his train had been cancelled because of a fault on the line.","skill":"detail"},{"question":"What did the clerk tell him about the next direct train?","options":["It had already gone with his map on board","It was cancelled until the next morning","It would stop at the guesthouse door","It would leave from another platform in nearly two hours"],"correctAnswer":"It would leave from another platform in nearly two hours","explanation":"The clerk said the next direct service would leave from another platform in nearly two hours.","supportingSentence":"A clerk said the next direct service would leave from another platform in nearly two hours.","skill":"detail"},{"question":"Why did Rafi stay inside the station?","options":["He did not want to miss a further change on the board","He had already boarded the cancelled train","The coded box was kept in the station cafe","His sister was bringing him a second ticket"],"correctAnswer":"He did not want to miss a further change on the board","explanation":"He stayed inside in case the board changed, so he would see any new information.","supportingSentence":"He stayed inside in case the board changed, bought a cheap bowl of soup, and kept his paper map ready.","skill":"inference"},{"question":"What was the result of the wait for his trip?","options":["He gave up and went home for the week","He had to walk the whole way along the tracks","He lost some daylight, but he continued the journey","The guesthouse cancelled the room at once"],"correctAnswer":"He lost some daylight, but he continued the journey","explanation":"The delay cost him daylight, but he was still going, so the trip continued.","supportingSentence":"The delay had cost him daylight, but he was still going.","skill":"inference"},{"question":"What does fault mean in this story?","options":["A problem that stopped the line from working","A box with a code for a room key","A paper map folded for a walk","The price of a bowl of soup"],"correctAnswer":"A problem that stopped the line from working","explanation":"The train was cancelled because of a fault on the line, meaning something was wrong with the line.","supportingSentence":"The board then showed that his train had been cancelled because of a fault on the line.","skill":"vocabulary"}],"wordCount":153,"questionCount":5}$q74939$::jsonb,
  'a6f53b2cea2cd30658167664a300f1e4600b663b3b2a6e316d5bf4235258340a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '68d383f4-9eaf-4766-a9cb-1190a8f56538'::uuid,
  'reading',
  'B2',
  'text',
  $q4561${"topic":"travel","wordCount":146,"questionCount":5}$q4561$::jsonb,
  $q77845${"mode":"reading","level":"B2","format":"text","topic":"Travel","title":"As Far as the Barrier","story":"The airport bus left Elena at the edge of the old town, where the streets rose steeply towards her hotel. Her suitcase had a broken wheel, and each step on the cobbles made a dull knock. A taxi waited by the fountain, but the driver warned that the upper road was closed for a market and that cars had to stop at a barrier. She looked at the hill and asked for a ride as far as that barrier, plus a route that avoided the steps. The driver agreed, carried the suitcase to the barrier, and did not add a fee. A hotel porter had seen the taxi stop and came down with a small cart. Elena reached the desk out of breath but before check-in closed. She wrote the closed road in her notebook so she would leave extra time on the morning she departed.","dialogue":[],"vocabulary":[{"word":"steeply","definition":"At a sharp slope, rising or falling quickly."},{"word":"cobbles","definition":"Rounded stones used to surface an old street."},{"word":"barrier","definition":"Something placed to stop people or vehicles passing."},{"word":"porter","definition":"A hotel worker who helps carry luggage."},{"word":"suitcase","definition":"A travelling bag with a handle."},{"word":"departed","definition":"Left at the start of a journey."}],"quiz":[{"question":"Why could cars not reach the hotel door?","options":["The upper road was closed and they had to stop at a barrier","The porter had locked every street in the town","The airport bus had blocked the fountain all day","Elena refused to ride with any driver"],"correctAnswer":"The upper road was closed and they had to stop at a barrier","explanation":"The driver warned that the upper road was closed for a market and cars had to stop at a barrier.","supportingSentence":"A taxi waited by the fountain, but the driver warned that the upper road was closed for a market and that cars had to stop at a barrier.","skill":"detail"},{"question":"What did the driver do when they reached the stopping point?","options":["He asked the desk to close early","He carried the suitcase there and charged no extra fee","He sent Elena back to the airport","He added a market fee to the ride"],"correctAnswer":"He carried the suitcase there and charged no extra fee","explanation":"He carried the suitcase to the barrier and did not add a fee.","supportingSentence":"The driver agreed, carried the suitcase to the barrier, and did not add a fee.","skill":"detail"},{"question":"Why would walking the whole way have been difficult?","options":["The bag's wheel was broken and the stone street was rough","The market was giving away free wheels","The hotel desk had closed before she landed","The airport bus had already taken the suitcase"],"correctAnswer":"The bag's wheel was broken and the stone street was rough","explanation":"A broken wheel and a knock on every cobble show that dragging the bag up the hill would be hard.","supportingSentence":"Her suitcase had a broken wheel, and each step on the cobbles made a dull knock.","skill":"inference"},{"question":"Why did the porter come down the hill?","options":["He was closing the road for the market","He wanted Elena to return to the airport","He had come to collect an extra fee","He had seen the taxi stop and brought a cart for the bag"],"correctAnswer":"He had seen the taxi stop and brought a cart for the bag","explanation":"He had seen the taxi stop and came down with a cart, so he was coming to help with the luggage.","supportingSentence":"A hotel porter had seen the taxi stop and came down with a small cart.","skill":"inference"},{"question":"What does departed mean in this story?","options":["Paid a fee at the market barrier","Closed the hotel desk for the night","Left on the next part of the journey","Broke the wheel of a travelling bag"],"correctAnswer":"Left on the next part of the journey","explanation":"She noted the closed road so she would allow extra time on the morning she departed, meaning when she left.","supportingSentence":"She wrote the closed road in her notebook so she would leave extra time on the morning she departed.","skill":"vocabulary"}],"wordCount":146,"questionCount":5}$q77845$::jsonb,
  '68d383f49eaf776619cb1190a8f56538f8def06acefa4924e573a0eb2d2bb910',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'b64276dd-85c1-454e-a7f2-7cc4eb4a2fef'::uuid,
  'reading',
  'B2',
  'text',
  $q4637${"topic":"hobbies","wordCount":153,"questionCount":5}$q4637$::jsonb,
  $q53288${"mode":"reading","level":"B2","format":"text","topic":"Hobbies","title":"Ink on Thick Paper","story":"On Saturday mornings the community workshop opened its letterpress room to anyone who had booked a slot. Helen had come to print invitations for her sister's spring lunch, using metal type rather than a home printer. The tutor showed her how to lock the letters into a chase so they would not shift under the roller. Her first sheet came out faint because the ink was too thin. The second was blotched because the ink was too heavy. On the third try the tutor told her to listen for an even sound as the roller passed, which meant the pressure was steady. Helen printed twenty cards and spoiled only two. She liked the slight dent the letters left in the thick paper. Before she left, she cleaned the type with solvent and returned every letter to its tray. The tutor said that care with the tools mattered as much as the cards themselves.","dialogue":[],"vocabulary":[{"word":"letterpress","definition":"Printing made by pressing metal letters into paper."},{"word":"invitations","definition":"Cards asking people to come to an event."},{"word":"chase","definition":"A frame that holds metal printing letters steady."},{"word":"blotched","definition":"Marked with uneven spots of ink."},{"word":"solvent","definition":"A liquid used to wash ink away."},{"word":"dent","definition":"A small hollow pressed into a surface."}],"quiz":[{"question":"How many cards did Helen spoil?","options":["Every sheet from the first try","Two cards out of the twenty she printed","None, because the first sheet was perfect","The whole tray of metal letters"],"correctAnswer":"Two cards out of the twenty she printed","explanation":"She printed twenty cards and spoiled only two.","supportingSentence":"Helen printed twenty cards and spoiled only two.","skill":"detail"},{"question":"Why did the second sheet look bad?","options":["There was too much ink on it","The tutor had already washed it clean","The paper was too thick to hold any mark","The letters were still in the tray"],"correctAnswer":"There was too much ink on it","explanation":"The second sheet was blotched because the ink was too heavy.","supportingSentence":"The second was blotched because the ink was too heavy.","skill":"detail"},{"question":"What did Helen like about the finished cards?","options":["A faint look with heavy spots of ink","The speed of an ordinary home printer","The smell of the cleaning liquid","The pressed mark the metal letters left in the paper"],"correctAnswer":"The pressed mark the metal letters left in the paper","explanation":"She liked the slight dent the letters left in the thick paper, so the pressed mark mattered to her.","supportingSentence":"She liked the slight dent the letters left in the thick paper.","skill":"inference"},{"question":"What point does the tutor make at the end?","options":["Looking after the tools matters as much as the cards","Twenty cards are too many for one morning","A home printer is always the better choice","Spoiled sheets are better than clean ones"],"correctAnswer":"Looking after the tools matters as much as the cards","explanation":"The tutor said that care with the tools mattered as much as the cards themselves.","supportingSentence":"The tutor said that care with the tools mattered as much as the cards themselves.","skill":"inference"},{"question":"What does blotched mean in this story?","options":["Locked safely inside a printing frame","Marked with uneven patches of heavy ink","Folded and sent to the guests","Printed too lightly to read"],"correctAnswer":"Marked with uneven patches of heavy ink","explanation":"The sheet was blotched because the ink was too heavy, so the word describes uneven ink marks.","supportingSentence":"The second was blotched because the ink was too heavy.","skill":"vocabulary"}],"wordCount":153,"questionCount":5}$q53288$::jsonb,
  'b64276dd85c1154e47f27cc4eb4a2fef0b4b659f69d8525fb5d72226a36b2153',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '3b7674f6-3b66-4c53-a661-423767f874bd'::uuid,
  'reading',
  'B2',
  'text',
  $q4637${"topic":"hobbies","wordCount":153,"questionCount":5}$q4637$::jsonb,
  $q65016${"mode":"reading","level":"B2","format":"text","topic":"Hobbies","title":"A Heron in the Margin","story":"Marc took his sketchbook to the river path when the light was soft. He was drawing the footbridge when rain began in heavy drops. The paper wrinkled at one corner, and a nearly finished drawing of the arches started to blur. A woman under the bridge offered him a plastic sleeve from her shopping bag. Marc slid the book inside and admitted he usually forgot any cover. They waited while the shower passed. He explained that he preferred pencil outdoors, because a drawing in pencil can stop and start without waiting for colour to dry. The woman said she walked that path to watch birds, and she pointed to a heron that had stayed still in the rain. When the sky cleared, Marc added the bird in a few lines and wrote the date beneath it. He went home with one damaged page and a drawing the shower had interrupted but not ruined.","dialogue":[],"vocabulary":[{"word":"sketchbook","definition":"A book of blank pages used for drawing."},{"word":"wrinkled","definition":"Creased, so a surface is no longer smooth."},{"word":"blur","definition":"To become unclear around the edges."},{"word":"sleeve","definition":"A cover that protects whatever is put inside it."},{"word":"heron","definition":"A tall bird that often stands in shallow water."},{"word":"interrupted","definition":"Stopped for a time before the end."}],"quiz":[{"question":"What did the woman offer Marc in the rain?","options":["A ride home before the shower","A plastic sleeve from her shopping bag","A finished painting of the footbridge","A dry set of coloured paints"],"correctAnswer":"A plastic sleeve from her shopping bag","explanation":"She offered him a plastic sleeve from her shopping bag.","supportingSentence":"A woman under the bridge offered him a plastic sleeve from her shopping bag.","skill":"detail"},{"question":"What did Marc add after the sky cleared?","options":["The woman's shopping list","A second bridge drawn in colour","A few lines for the bird, and the date","A note that the book was ruined"],"correctAnswer":"A few lines for the bird, and the date","explanation":"When the sky cleared, he added the bird in a few lines and wrote the date beneath it.","supportingSentence":"When the sky cleared, Marc added the bird in a few lines and wrote the date beneath it.","skill":"detail"},{"question":"What does Marc admit about his usual habit?","options":["He always carries a plastic sleeve in his coat","He prefers heavy rain to a dry path","He had borrowed the book from the woman","He often goes drawing without anything to cover the book"],"correctAnswer":"He often goes drawing without anything to cover the book","explanation":"He admitted he usually forgot any cover, so the book was often unprotected.","supportingSentence":"Marc slid the book inside and admitted he usually forgot any cover.","skill":"inference"},{"question":"What was the state of the work he took home?","options":["The rain had broken into it, but the drawing survived","He gave the finished book to the woman","He refused to keep the damaged page","The shower had washed every line away"],"correctAnswer":"The rain had broken into it, but the drawing survived","explanation":"He went home with one damaged page and a drawing the shower had interrupted but not ruined.","supportingSentence":"He went home with one damaged page and a drawing the shower had interrupted but not ruined.","skill":"inference"},{"question":"What is a heron in this story?","options":["A date written under a drawing","A tall bird the woman pointed out in the rain","A plastic cover for a sketchbook","A stone arch of the footbridge"],"correctAnswer":"A tall bird the woman pointed out in the rain","explanation":"She pointed to a heron that had stayed still in the rain, and a heron is a tall waterside bird.","supportingSentence":"The woman said she walked that path to watch birds, and she pointed to a heron that had stayed still in the rain.","skill":"vocabulary"}],"wordCount":153,"questionCount":5}$q65016$::jsonb,
  '3b7674f63b665c53c661423767f874bd31be6c0177d95b429f528748a36a83c3',
  true
) on conflict (content_hash) do nothing;

