  'B2',
  'text',
  $q4835${"topic":"daily life","wordCount":62,"questionCount":5}$q4835$::jsonb,
  $q27103${"mode":"reading","level":"B2","format":"text","topic":"Daily Life","title":"The Empty Key Envelope","story":"Lena kept a spare key in an envelope behind the hall clock, but the envelope was empty when she came home. Her brother admitted he had borrowed it, then left it in his coat. She asked him to return it that evening and to send a message whenever he used it. He agreed, because the missing key had already made her late.","dialogue":[],"vocabulary":[{"word":"spare","definition":"Kept for use if the usual one is not available."},{"word":"envelope","definition":"A paper cover used to hold a letter or a small object."},{"word":"admitted","definition":"Said that something was true, often unwillingly."},{"word":"borrowed","definition":"Took something for a time, planning to give it back."},{"word":"whenever","definition":"At any time that something happens."},{"word":"missing","definition":"Not in the place where it should be."}],"quiz":[{"question":"Where did Lena normally keep the extra key?","options":["In her brother’s coat pocket","At work, beside her desk","With the neighbour who was waiting","In an envelope behind the hall clock"],"correctAnswer":"In an envelope behind the hall clock","explanation":"The story says she kept the spare key in an envelope behind the hall clock.","supportingSentence":"Lena kept a spare key in an envelope behind the hall clock, but the envelope was empty when she came home.","skill":"detail"},{"question":"What does the empty envelope show about her arrival?","options":["Her brother was still locked outside","A new envelope had just been delivered","The spare key was not in its usual place","The hall clock had stopped that morning"],"correctAnswer":"The spare key was not in its usual place","explanation":"She came home to an empty envelope, so the key was no longer where she kept it.","supportingSentence":"Lena kept a spare key in an envelope behind the hall clock, but the envelope was empty when she came home.","skill":"inference"},{"question":"Why did her brother accept the request for a message?","options":["He wanted to keep the key in his coat","He could see that taking the key had already caused trouble","He hoped to move the clock the next day","A neighbour had told him to text every night"],"correctAnswer":"He could see that taking the key had already caused trouble","explanation":"He agreed because the missing key had already made Lena late.","supportingSentence":"He agreed, because the missing key had already made her late.","skill":"inference"},{"question":"What does admitted mean in this story?","options":["Said that something was true","Wrote a short message","Locked a door from outside","Put an object back at once"],"correctAnswer":"Said that something was true","explanation":"Her brother admitted he had borrowed the key, meaning he said that this had happened.","supportingSentence":"Her brother admitted he had borrowed it, then left it in his coat.","skill":"vocabulary"},{"question":"Why does Lena want a message when the key is used?","options":["She wants her brother to buy a new clock","She wants the coat to stay at work","She wants to throw the envelope away","She wants to know that the spare key is away from its place"],"correctAnswer":"She wants to know that the spare key is away from its place","explanation":"A message whenever he uses the key would tell her that it has been taken.","supportingSentence":"She asked him to return it that evening and to send a message whenever he used it.","skill":"intent"}],"wordCount":62,"questionCount":5}$q27103$::jsonb,
  'c4bb88e79d3848c69cd576a9b5664828e7577041c0de49930ac16ac2d2aad46a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '2f0ef54a-b6e9-4969-a0ff-b49aaec1a17f'::uuid,
  'reading',
  'B2',
  'text',
  $q4838${"topic":"daily life","wordCount":65,"questionCount":5}$q4838$::jsonb,
  $q40075${"mode":"reading","level":"B2","format":"text","topic":"Daily Life","title":"Bins before Breakfast","story":"The bin lorry usually passed before Omar left for work, yet this week the street was still full when he opened the door. He dragged the containers to the pavement and warned his housemate that a late collection meant an earlier start. They agreed to set a shared alarm on collection day. By Friday the pavement was clear before either of them had finished breakfast.","dialogue":[],"vocabulary":[{"word":"usually","definition":"On most occasions, rather than every single time."},{"word":"containers","definition":"Large bins used for holding rubbish."},{"word":"pavement","definition":"The path for people along the side of a street."},{"word":"housemate","definition":"A person who lives in the same home."},{"word":"collection","definition":"The scheduled pickup of the bins."},{"word":"clear","definition":"Empty of the things that were there before."}],"quiz":[{"question":"What did Omar do with the containers?","options":["He loaded them onto the lorry himself","He hid them behind the house","He dragged them out to the pavement","He left them inside the kitchen"],"correctAnswer":"He dragged them out to the pavement","explanation":"Omar dragged the containers to the pavement before warning his housemate.","supportingSentence":"He dragged the containers to the pavement and warned his housemate that a late collection meant an earlier start.","skill":"detail"},{"question":"Why was the street still full when Omar opened the door?","options":["Omar had forgotten to close the front door","The new alarm had woken the whole street","His housemate had filled the road with boxes","The bins had not been collected at the usual time"],"correctAnswer":"The bins had not been collected at the usual time","explanation":"The lorry normally passed before he left, so a full street means the pickup had not happened yet.","supportingSentence":"The bin lorry usually passed before Omar left for work, yet this week the street was still full when he opened the door.","skill":"inference"},{"question":"What does the clear pavement on Friday suggest?","options":["The containers had gone out early enough to be collected","They had cancelled the shared alarm","The lorry had stopped visiting their street","Breakfast was being served outside"],"correctAnswer":"The containers had gone out early enough to be collected","explanation":"The pavement was clear before breakfast, which shows the bins were no longer waiting in the street.","supportingSentence":"By Friday the pavement was clear before either of them had finished breakfast.","skill":"inference"},{"question":"What does collection mean in this story?","options":["A meeting of every housemate","The scheduled pickup of the bins","A day off from work","A box kept for breakfast"],"correctAnswer":"The scheduled pickup of the bins","explanation":"A late collection is the reason they would need to start earlier with the bins.","supportingSentence":"He dragged the containers to the pavement and warned his housemate that a late collection meant an earlier start.","skill":"vocabulary"},{"question":"Why did they decide to set a shared alarm?","options":["So Omar could stay at home on Friday","So the containers could remain indoors","So they would be up in time on collection day","So the lorry would arrive later in the week"],"correctAnswer":"So they would be up in time on collection day","explanation":"A late pickup meant an earlier start, so the alarm was meant to get them up for it.","supportingSentence":"He dragged the containers to the pavement and warned his housemate that a late collection meant an earlier start.","skill":"intent"}],"wordCount":65,"questionCount":5}$q40075$::jsonb,
  '2f0ef54ab6e9996900ffb49aaec1a17fc5c861280d67d703cb63e7c6c40fec7b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'acf9a713-a4f6-499d-ad01-159d0be89f43'::uuid,
  'reading',
  'B2',
  'text',
  $q5329${"topic":"school_college","wordCount":61,"questionCount":5}$q5329$::jsonb,
  $q36774${"mode":"reading","level":"B2","format":"text","topic":"School / College","title":"The Postponed Seminar","story":"Priya arrived for the afternoon seminar and found a notice on the classroom door. The tutor had postponed the session until Thursday because the projector was being repaired. Students who needed the recording could collect a link from the office before closing time. Priya copied the new time into her planner and texted her project partner, who had already left campus.","dialogue":[],"vocabulary":[{"word":"seminar","definition":"A class in which a small group discusses a subject."},{"word":"notice","definition":"A short written message put where people can read it."},{"word":"postponed","definition":"Moved to a later time."},{"word":"projector","definition":"A machine that throws an image onto a screen."},{"word":"recording","definition":"A saved copy of a class that can be watched later."},{"word":"planner","definition":"A book or tool used to keep track of dates and tasks."}],"quiz":[{"question":"Why was the afternoon session moved?","options":["The office had closed for the month","The classroom door had been removed","The projector was being repaired","Her partner had already left campus"],"correctAnswer":"The projector was being repaired","explanation":"The tutor postponed the session because the projector was being repaired.","supportingSentence":"The tutor had postponed the session until Thursday because the projector was being repaired.","skill":"detail"},{"question":"What problem did the door notice save Priya from?","options":["Repairing the projector by herself","Missing a recording that was due that morning","Waiting for a class that was not happening that day","Teaching the seminar with no partner"],"correctAnswer":"Waiting for a class that was not happening that day","explanation":"The session had been moved to Thursday, so the afternoon class she came for was not on.","supportingSentence":"The tutor had postponed the session until Thursday because the projector was being repaired.","skill":"inference"},{"question":"Why was a text more useful than the door notice for her partner?","options":["The partner had already left and would not see the door","The office had asked her to send the recording","The planner could not store a new time","The partner was busy repairing the projector"],"correctAnswer":"The partner had already left and would not see the door","explanation":"Her project partner had already left campus, so he would not read the notice on the door.","supportingSentence":"Priya copied the new time into her planner and texted her project partner, who had already left campus.","skill":"inference"},{"question":"What does postponed mean in this story?","options":["Cancelled and never repeated","Copied into a planner","Filmed for the office","Moved to a later time"],"correctAnswer":"Moved to a later time","explanation":"The session was postponed until Thursday, so it was delayed rather than cancelled.","supportingSentence":"The tutor had postponed the session until Thursday because the projector was being repaired.","skill":"vocabulary"},{"question":"Why does the notice tell students about a link?","options":["So Priya will leave campus early","So the tutor can sell the projector","So anyone who needs the recording can still get it","So the classroom door can stay shut"],"correctAnswer":"So anyone who needs the recording can still get it","explanation":"The link from the office is for students who needed the recording of the session.","supportingSentence":"Students who needed the recording could collect a link from the office before closing time.","skill":"intent"}],"wordCount":61,"questionCount":5}$q36774$::jsonb,
  'acf9a713a4f6599d7d01159d0be89f43489127743147475332b1a1fc1d283c3a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '9d346a24-2c40-4c34-ada7-1841b079eee8'::uuid,
  'reading',
  'B2',
  'text',
  $q5332${"topic":"school_college","wordCount":64,"questionCount":5}$q5332$::jsonb,
  $q18793${"mode":"reading","level":"B2","format":"text","topic":"School / College","title":"A Note on the Essay","story":"Andre expected a marked essay on his desk, but he found only a short note from his tutor. She wanted him to clarify two claims and resubmit the work by Monday. The note also said his examples were relevant, so the delay was about precision rather than the topic. He booked a brief meeting and started a list of the sentences he would rewrite.","dialogue":[],"vocabulary":[{"word":"marked","definition":"Read by a teacher and given a result or comments."},{"word":"clarify","definition":"Make an idea clearer and easier to understand."},{"word":"resubmit","definition":"Hand a piece of work in again."},{"word":"relevant","definition":"Connected in a useful way to the subject."},{"word":"precision","definition":"The quality of being exact."},{"word":"rewrite","definition":"Write something again in order to improve it."}],"quiz":[{"question":"When did the tutor want the work handed in again?","options":["By Monday","After the long holiday","The same afternoon","Only if the meeting was cancelled"],"correctAnswer":"By Monday","explanation":"She asked him to resubmit the work by Monday.","supportingSentence":"She wanted him to clarify two claims and resubmit the work by Monday.","skill":"detail"},{"question":"What does a note, instead of a marked essay, suggest?","options":["The tutor had lost the essay","The essay was not ready for a final mark","The desk belonged to another student","Andre had already rewritten every line"],"correctAnswer":"The essay was not ready for a final mark","explanation":"He expected a marked essay and found only a note, so the work had not been finally graded.","supportingSentence":"Andre expected a marked essay on his desk, but he found only a short note from his tutor.","skill":"inference"},{"question":"What does Andre’s list suggest about his plan?","options":["He will throw the note away unread","He will give the essay a mark himself","He will change parts of this essay rather than start a new one","He will skip the meeting with his tutor"],"correctAnswer":"He will change parts of this essay rather than start a new one","explanation":"A list of sentences to rewrite shows he is revising this essay, not abandoning it.","supportingSentence":"He booked a brief meeting and started a list of the sentences he would rewrite.","skill":"inference"},{"question":"What does clarify mean in this story?","options":["Hand work in for the first time","Book a long meeting","Give a piece of work a mark","Make something clearer"],"correctAnswer":"Make something clearer","explanation":"The tutor asked him to clarify two claims, meaning those points needed to be clearer.","supportingSentence":"She wanted him to clarify two claims and resubmit the work by Monday.","skill":"vocabulary"},{"question":"What is the tutor’s aim in asking for the work again?","options":["She wants the two claims to be clearer","She wants the examples removed","She wants him to choose a new topic","She wants the meeting to replace the essay"],"correctAnswer":"She wants the two claims to be clearer","explanation":"She asked him to clarify two claims and then resubmit the essay.","supportingSentence":"She wanted him to clarify two claims and resubmit the work by Monday.","skill":"intent"}],"wordCount":64,"questionCount":5}$q18793$::jsonb,
  '9d346a242c40ec340da71841b079eee834814ed150fcc7778fff633c45aca3b3',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e32ff257-0078-4f7b-acb0-f84a0f85f4e6'::uuid,
  'reading',
  'B2',
  'text',
  $q4513${"topic":"travel","wordCount":65,"questionCount":5}$q4513$::jsonb,
  $q10780${"mode":"reading","level":"B2","format":"text","topic":"Travel","title":"Six Minutes to Platform Nine","story":"The departure board changed while Nadia was buying water, and her train moved from platform four to platform nine. She had six minutes and a heavy suitcase, so she asked a member of staff which stairs were closest. He pointed to a lift at the far end and said it would be quicker than the crowded steps. She reached the doors just as they opened.","dialogue":[],"vocabulary":[{"word":"departure","definition":"The moment when a train leaves."},{"word":"platform","definition":"The area in a station where people get on a train."},{"word":"suitcase","definition":"A large bag with a handle, used for travel."},{"word":"crowded","definition":"Full of people, with little room to move."},{"word":"lift","definition":"A machine that carries people from one floor to another."},{"word":"reached","definition":"Arrived at a place."}],"quiz":[{"question":"Which platform did Nadia’s train move to?","options":["The station shop","The crowded steps","Platform nine","Platform four"],"correctAnswer":"Platform nine","explanation":"The board showed that her train had moved from platform four to platform nine.","supportingSentence":"The departure board changed while Nadia was buying water, and her train moved from platform four to platform nine.","skill":"detail"},{"question":"Why did the nearest route matter so much to Nadia?","options":["She wanted to buy a second bottle","She worked for the station","She had already missed the train","She had very little time and a heavy bag"],"correctAnswer":"She had very little time and a heavy bag","explanation":"With six minutes and a heavy suitcase, she needed the closest way to the train.","supportingSentence":"She had six minutes and a heavy suitcase, so she asked a member of staff which stairs were closest.","skill":"inference"},{"question":"How much time did Nadia have when she reached the train?","options":["Almost none, because the doors were just opening","None, because the train had already left","A full hour on the old platform","Enough to go back and buy more water"],"correctAnswer":"Almost none, because the doors were just opening","explanation":"She reached the doors just as they opened, so she had almost no time to spare.","supportingSentence":"She reached the doors just as they opened.","skill":"inference"},{"question":"What does crowded mean in this story?","options":["Quicker than a lift","Full of people","Far from the train","Closed for repairs"],"correctAnswer":"Full of people","explanation":"The steps are called crowded, and the lift is offered as a quicker choice.","supportingSentence":"He pointed to a lift at the far end and said it would be quicker than the crowded steps.","skill":"vocabulary"},{"question":"Why did Nadia ask which stairs were closest?","options":["She hoped to move the train back","She was looking for a place to sit","She needed the fastest way to the new platform","She wanted someone to carry her water"],"correctAnswer":"She needed the fastest way to the new platform","explanation":"She asked which stairs were closest because she had only six minutes to reach the train.","supportingSentence":"She had six minutes and a heavy suitcase, so she asked a member of staff which stairs were closest.","skill":"intent"}],"wordCount":65,"questionCount":5}$q10780$::jsonb,
  'e32ff25700783f7b5cb0f84a0f85f4e6c8c9ca29a6a92bf013960c9a78f98e18',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '5c861e4f-7687-493d-acf8-08d7f7026e7b'::uuid,
  'reading',
  'B2',
  'text',
  $q4510${"topic":"travel","wordCount":62,"questionCount":5}$q4510$::jsonb,
  $q18149${"mode":"reading","level":"B2","format":"text","topic":"Travel","title":"The Wrong Hostel Locker","story":"Rafael opened the hostel locker and found a camera that was not his. The tag showed a room number on the floor above, so he took the camera to reception instead of leaving a note. The clerk matched it to a guest who had used the wrong key the night before. Rafael collected his own bag and still caught the afternoon bus.","dialogue":[],"vocabulary":[{"word":"locker","definition":"A small cupboard that can be locked for personal things."},{"word":"tag","definition":"A small label attached to an object."},{"word":"reception","definition":"The desk where staff help guests."},{"word":"clerk","definition":"A member of staff who deals with records and guests."},{"word":"matched","definition":"Found the person or record that fitted."},{"word":"collected","definition":"Went and picked something up."}],"quiz":[{"question":"What did Rafael find in the locker?","options":["A note from the clerk","The key to the afternoon bus","His own bag, ready for the bus","A camera that was not his"],"correctAnswer":"A camera that was not his","explanation":"When he opened the hostel locker, he found a camera that was not his.","supportingSentence":"Rafael opened the hostel locker and found a camera that was not his.","skill":"detail"},{"question":"Why was reception a better choice than a note?","options":["The bus was leaving from the front desk","His own bag was already on the floor above","The tag gave a room number that staff could use","He wanted to keep the camera for the trip"],"correctAnswer":"The tag gave a room number that staff could use","explanation":"The tag showed a room number, so the desk could trace the owner instead of waiting for a note.","supportingSentence":"The tag showed a room number on the floor above, so he took the camera to reception instead of leaving a note.","skill":"inference"},{"question":"What does catching the afternoon bus show?","options":["He left the camera inside the locker","The locker problem did not make him miss his departure","His own bag was still on the floor above","The clerk drove the afternoon bus"],"correctAnswer":"The locker problem did not make him miss his departure","explanation":"He still caught the afternoon bus after dealing with the camera and collecting his bag.","supportingSentence":"Rafael collected his own bag and still caught the afternoon bus.","skill":"inference"},{"question":"What does reception mean in this story?","options":["The desk where staff help guests","A label tied to a camera","A key that opens every locker","The stop where the bus departs"],"correctAnswer":"The desk where staff help guests","explanation":"Rafael takes the camera to reception, where the clerk can match it to a guest.","supportingSentence":"The tag showed a room number on the floor above, so he took the camera to reception instead of leaving a note.","skill":"vocabulary"},{"question":"Why did Rafael take the camera to the desk?","options":["He wanted to hide it in his own bag","He wanted a room on the floor above","He wanted to catch an earlier bus","He wanted the staff to get it back to the right guest"],"correctAnswer":"He wanted the staff to get it back to the right guest","explanation":"He took the camera to reception so the staff could deal with it, rather than leaving a note.","supportingSentence":"The tag showed a room number on the floor above, so he took the camera to reception instead of leaving a note.","skill":"intent"}],"wordCount":62,"questionCount":5}$q18149$::jsonb,
  '5c861e4f7687593dacf808d7f7026e7bbe95c62a60bd3a027191ddbbf59746c4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '56805b36-bd8c-4ab6-aeff-6198f4d4b0a4'::uuid,
  'reading',
  'B2',
  'text',
  $q4592${"topic":"hobbies","wordCount":66,"questionCount":5}$q4592$::jsonb,
  $q87670${"mode":"reading","level":"B2","format":"text","topic":"Hobbies","title":"Glazing a Small Bowl","story":"Hana had shaped the bowl on Tuesday, but she waited until it was fully dry before glazing it. The pale coat looked thin, so she brushed a second layer around the rim and left the base clear. Her instructor said the clear base would stop the bowl from sticking in the kiln. She wrote the firing date on a card and set it on the shelf.","dialogue":[],"vocabulary":[{"word":"glazing","definition":"Putting a glassy coat on clay before it is fired."},{"word":"pale","definition":"Light in colour, not deep or strong."},{"word":"rim","definition":"The edge around the top of a bowl."},{"word":"instructor","definition":"A teacher who guides a practical skill."},{"word":"kiln","definition":"A very hot oven used to harden clay."},{"word":"firing","definition":"Baking clay at a very high temperature."}],"quiz":[{"question":"On which day had Hana shaped the bowl?","options":["After the second layer dried","While the kiln was heating","On the day of the firing","On Tuesday"],"correctAnswer":"On Tuesday","explanation":"The story says Hana had shaped the bowl on Tuesday.","supportingSentence":"Hana had shaped the bowl on Tuesday, but she waited until it was fully dry before glazing it.","skill":"detail"},{"question":"Why did Hana brush on a second layer?","options":["The card had marked the rim","The kiln had already been switched on","The first coat looked too thin","The instructor told her to soak the bowl"],"correctAnswer":"The first coat looked too thin","explanation":"The pale coat looked thin, so she added another layer around the rim.","supportingSentence":"The pale coat looked thin, so she brushed a second layer around the rim and left the base clear.","skill":"inference"},{"question":"What risk would a glazed base create?","options":["The rim would stay pale forever","The bowl might stick inside the kiln","The clay would never dry","The date card would fall off"],"correctAnswer":"The bowl might stick inside the kiln","explanation":"A clear base is what stops the bowl from sticking, so glaze on the base would risk that problem.","supportingSentence":"Her instructor said the clear base would stop the bowl from sticking in the kiln.","skill":"inference"},{"question":"What does kiln mean in this story?","options":["A very hot oven for clay","The top edge of a bowl","A thin coat of colour","A card used for dates"],"correctAnswer":"A very hot oven for clay","explanation":"The bowl goes into the kiln, which is where clay is fired.","supportingSentence":"Her instructor said the clear base would stop the bowl from sticking in the kiln.","skill":"vocabulary"},{"question":"Why did the instructor want the base left clear?","options":["To hide the firing date","To keep Hana from shaping clay","To make the rim look thinner","To stop the bowl sticking while it was fired"],"correctAnswer":"To stop the bowl sticking while it was fired","explanation":"The instructor said a clear base would stop the bowl from sticking in the kiln.","supportingSentence":"Her instructor said the clear base would stop the bowl from sticking in the kiln.","skill":"intent"}],"wordCount":66,"questionCount":5}$q87670$::jsonb,
  '56805b36bd8cdab6eeff6198f4d4b0a47b269c8d05809d6d400505b6765fb7c5',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e0d400f5-0cb1-4725-a72d-6b443ab9afee'::uuid,
  'reading',
  'B2',
  'text',
  $q4587${"topic":"hobbies","wordCount":61,"questionCount":5}$q4587$::jsonb,
  $q13029${"mode":"reading","level":"B2","format":"text","topic":"Hobbies","title":"A Sketchbook on the Train","story":"Leo used the evening train to fill a page of his sketchbook, drawing the station roof before the carriage moved. A passenger beside him asked whether the picture was for a class. Leo said it was only practice, though he hoped to enter a small exhibition in spring. He added the date and closed the book when his stop was announced.","dialogue":[],"vocabulary":[{"word":"sketchbook","definition":"A book of plain pages used for drawing."},{"word":"carriage","definition":"One of the connected sections of a train."},{"word":"passenger","definition":"A person travelling in a vehicle who is not driving it."},{"word":"practice","definition":"Repeated work done in order to improve."},{"word":"exhibition","definition":"A public show of art."},{"word":"announced","definition":"Said publicly so that people will hear."}],"quiz":[{"question":"What did Leo draw before the train moved?","options":["The station roof","The passenger beside him","A poster for the spring show","A map of the stops"],"correctAnswer":"The station roof","explanation":"He drew the station roof before the carriage moved.","supportingSentence":"Leo used the evening train to fill a page of his sketchbook, drawing the station roof before the carriage moved.","skill":"detail"},{"question":"What does Leo’s hope suggest about these drawings?","options":["He plans to stop drawing after this journey","He needs the date for a ticket refund","He may one day show work like this in public","He is teaching the passenger to draw"],"correctAnswer":"He may one day show work like this in public","explanation":"Hoping to enter an exhibition means he may show drawings publicly in spring.","supportingSentence":"Leo said it was only practice, though he hoped to enter a small exhibition in spring.","skill":"inference"},{"question":"Why did Leo close the sketchbook when he did?","options":["The exhibition had already closed","The station roof was too dark to see","His stop had been called, so he needed to get ready","The passenger told him to stop drawing"],"correctAnswer":"His stop had been called, so he needed to get ready","explanation":"He closed the book when his stop was announced, which is the moment to prepare to get off.","supportingSentence":"He added the date and closed the book when his stop was announced.","skill":"inference"},{"question":"What does exhibition mean in this story?","options":["A page in a sketchbook","A spoken station message","A daily train journey","A public show of art"],"correctAnswer":"A public show of art","explanation":"Leo hopes to enter an exhibition, meaning a show where art is displayed.","supportingSentence":"Leo said it was only practice, though he hoped to enter a small exhibition in spring.","skill":"vocabulary"},{"question":"Why did Leo use the evening train in this way?","options":["He wanted the journey time for drawing","He wanted to change his stop","He wanted to sell the sketchbook","He wanted a lesson from the passenger"],"correctAnswer":"He wanted the journey time for drawing","explanation":"He used the evening train to fill a page of his sketchbook.","supportingSentence":"Leo used the evening train to fill a page of his sketchbook, drawing the station roof before the carriage moved.","skill":"intent"}],"wordCount":61,"questionCount":5}$q13029$::jsonb,
  'e0d400f50cb1f725472d6b443ab9afee6d62dddcc8058a0a3a90295ef27b1bdc',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
