  'text',
  $q5263${"topic":"health_sports","wordCount":61,"questionCount":5}$q5263$::jsonb,
  $q79468${"mode":"reading","level":"B2","format":"text","topic":"Health & Sports","title":"The Ankle after Practice","story":"After practice, Noor’s ankle swelled, so the coach stopped her from joining the final drill. The team medic wrapped it and told her to rest, raise the foot, and cool it for short periods. Noor wanted to play on Saturday, but the medic said a proper check came first. She booked a morning appointment and sent the coach her updated availability.","dialogue":[],"vocabulary":[{"word":"swelled","definition":"Became larger, usually because of an injury."},{"word":"drill","definition":"A repeated exercise used in training."},{"word":"medic","definition":"A person who gives medical help, especially at a sports session."},{"word":"wrapped","definition":"Covered and fastened with a bandage."},{"word":"appointment","definition":"A time booked to see someone."},{"word":"availability","definition":"The times when a person is able to take part."}],"quiz":[{"question":"What did the coach keep Noor out of?","options":["The final drill","Wrapping her own ankle","Sending a message","The morning appointment"],"correctAnswer":"The final drill","explanation":"The coach stopped her from joining the final drill after her ankle swelled.","supportingSentence":"After practice, Noor’s ankle swelled, so the coach stopped her from joining the final drill.","skill":"detail"},{"question":"Why was Noor taken out of the last part of practice?","options":["The medic wanted her to coach the others","Saturday’s match had been cancelled","She had already booked the morning visit","Her ankle had swollen and was not ready for more work"],"correctAnswer":"Her ankle had swollen and was not ready for more work","explanation":"Her ankle swelled, and that is why the coach stopped her from joining the final drill.","supportingSentence":"After practice, Noor’s ankle swelled, so the coach stopped her from joining the final drill.","skill":"inference"},{"question":"What does the updated availability suggest?","options":["She may not play at the time first expected","She has been made captain of the team","The medic will play in her place","The swelling had gone before she left"],"correctAnswer":"She may not play at the time first expected","explanation":"Sending an updated availability means her ability to play is no longer certain.","supportingSentence":"She booked a morning appointment and sent the coach her updated availability.","skill":"inference"},{"question":"What does swelled mean in this story?","options":["Was covered with a bandage","Was cooled for a short time","Became larger after an injury","Was checked by a doctor"],"correctAnswer":"Became larger after an injury","explanation":"Noor’s ankle swelled after practice, meaning it grew larger from the injury.","supportingSentence":"After practice, Noor’s ankle swelled, so the coach stopped her from joining the final drill.","skill":"vocabulary"},{"question":"Why did the medic say a check had to come first?","options":["Saturday’s game should wait until the ankle is assessed","The coach should stop the whole team","Rest was no longer needed","Noor should cancel the appointment"],"correctAnswer":"Saturday’s game should wait until the ankle is assessed","explanation":"Noor wanted to play on Saturday, but the medic said a proper check came first.","supportingSentence":"Noor wanted to play on Saturday, but the medic said a proper check came first.","skill":"intent"}],"wordCount":61,"questionCount":5}$q79468$::jsonb,
  'eff89dc5c071fd3fa51410f297b2390a5b1ae2fd09198fdeb96e5317c16251d2',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '3c7621af-34e5-47a4-a847-b674f85c6357'::uuid,
  'reading',
  'B2',
  'text',
  $q5266${"topic":"health_sports","wordCount":64,"questionCount":5}$q5266$::jsonb,
  $q32105${"mode":"reading","level":"B2","format":"text","topic":"Health & Sports","title":"A Slower Training Week","story":"Malik’s plan said he should run five kilometres, yet his knee felt stiff after the first lap. He cut the session short and walked the rest of the route rather than pushing through the pain. That evening he replaced speed work with gentle cycling and noted the change in his log. His coach agreed that a careful week was better than a long injury.","dialogue":[],"vocabulary":[{"word":"kilometres","definition":"Units used to measure a long distance."},{"word":"stiff","definition":"Hard to bend and a little painful."},{"word":"session","definition":"One period of exercise."},{"word":"pushing","definition":"Forcing yourself to continue."},{"word":"gentle","definition":"Soft and not forceful."},{"word":"injury","definition":"Physical harm to the body."}],"quiz":[{"question":"How did Malik finish the rest of the route?","options":["He ran it faster than planned","He skipped it without telling anyone","He walked it","He cycled it immediately"],"correctAnswer":"He walked it","explanation":"After cutting the run short, he walked the rest of the route.","supportingSentence":"He cut the session short and walked the rest of the route rather than pushing through the pain.","skill":"detail"},{"question":"Why did Malik stop running so early?","options":["His knee hurt and he refused to force it","He had already finished five kilometres","The coach had ordered a morning cycle","The log said the route was closed"],"correctAnswer":"His knee hurt and he refused to force it","explanation":"His knee felt stiff, and he chose not to push through the pain.","supportingSentence":"He cut the session short and walked the rest of the route rather than pushing through the pain.","skill":"inference"},{"question":"What does the coach’s remark suggest about this week?","options":["Malik should ignore stiffness next time","A long injury has already happened","Speed work must happen every evening","Doing less now is wiser than risking a long injury"],"correctAnswer":"Doing less now is wiser than risking a long injury","explanation":"The coach agreed that a careful week was better than a long injury.","supportingSentence":"His coach agreed that a careful week was better than a long injury.","skill":"inference"},{"question":"What does stiff mean in this story?","options":["Hard to move comfortably","Written down in a book","Easy and gentle on the body","Very fast for a short distance"],"correctAnswer":"Hard to move comfortably","explanation":"Malik’s knee felt stiff after one lap, meaning it was uncomfortable to keep running on.","supportingSentence":"Malik’s plan said he should run five kilometres, yet his knee felt stiff after the first lap.","skill":"vocabulary"},{"question":"Why did Malik note the change in his log?","options":["So the coach would add more speed work","So the route would grow longer","So there was a record of the altered session","So he could forget the pain"],"correctAnswer":"So there was a record of the altered session","explanation":"He noted the change after replacing speed work with gentle cycling.","supportingSentence":"That evening he replaced speed work with gentle cycling and noted the change in his log.","skill":"intent"}],"wordCount":64,"questionCount":5}$q32105$::jsonb,
  '3c7621af34e597a43847b674f85c6357f42be7bab61521cc50dbe22f9dcd28de',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '3ac13c3e-113f-41fc-a57e-c3efd4d6cecd'::uuid,
  'reading',
  'B2',
  'text',
  $q5145${"topic":"culture_food","wordCount":60,"questionCount":5}$q5145$::jsonb,
  $q47002${"mode":"reading","level":"B2","format":"text","topic":"Culture & Food","title":"Bread at the Night Market","story":"The night market opened at dusk, and Amira’s stall sold warm flatbread with a herb sauce her aunt had taught her. She reduced the salt after regular customers said last week’s batch was too sharp. A tray of samples let people taste the milder version before they ordered. By the time the square filled, the first batch was already gone.","dialogue":[],"vocabulary":[{"word":"dusk","definition":"The time in the evening when daylight fades."},{"word":"flatbread","definition":"A thin, flat kind of bread."},{"word":"reduced","definition":"Made smaller in amount."},{"word":"sharp","definition":"Strong and slightly harsh in taste."},{"word":"samples","definition":"Small amounts offered so people can try something."},{"word":"batch","definition":"A quantity made at the same time."}],"quiz":[{"question":"Who had taught Amira to make the sauce?","options":["Her aunt","The owner of the next stall","A cook in the square","A regular customer"],"correctAnswer":"Her aunt","explanation":"The herb sauce was one her aunt had taught her.","supportingSentence":"The night market opened at dusk, and Amira’s stall sold warm flatbread with a herb sauce her aunt had taught her.","skill":"detail"},{"question":"Why did Amira change the amount of salt?","options":["The market was opening after dusk","Her aunt had asked her to close","The square stayed empty all evening","Customers had found the earlier bread too strong"],"correctAnswer":"Customers had found the earlier bread too strong","explanation":"Regular customers said the last batch was too sharp, so she reduced the salt.","supportingSentence":"She reduced the salt after regular customers said last week’s batch was too sharp.","skill":"inference"},{"question":"What does the missing first batch suggest?","options":["She added more salt during the evening","Nobody stopped to taste a sample","People bought the new bread quickly","The market failed to open"],"correctAnswer":"People bought the new bread quickly","explanation":"The first batch was already gone by the time the square filled, which shows it sold fast.","supportingSentence":"By the time the square filled, the first batch was already gone.","skill":"inference"},{"question":"What does batch mean in this story?","options":["A tray used only for tasting","A quantity made at one time","A person who buys food often","The square where a market is held"],"correctAnswer":"A quantity made at one time","explanation":"Last week’s batch is one lot of bread she had made, and the first batch is another lot.","supportingSentence":"She reduced the salt after regular customers said last week’s batch was too sharp.","skill":"vocabulary"},{"question":"Why did Amira put samples on a tray?","options":["So people could taste the milder bread before buying","So the first batch would remain unsold","So her aunt could cook in the square","So she could increase the salt again"],"correctAnswer":"So people could taste the milder bread before buying","explanation":"The samples let people taste the milder version before they ordered.","supportingSentence":"A tray of samples let people taste the milder version before they ordered.","skill":"intent"}],"wordCount":60,"questionCount":5}$q47002$::jsonb,
  '3ac13c3e113f91fcc57ec3efd4d6cecddc6b900098c475528a7f11c7d086008d',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '4438879a-263c-4daa-a143-0c2d1571e5c4'::uuid,
  'reading',
  'B2',
  'text',
  $q5149${"topic":"culture_food","wordCount":64,"questionCount":5}$q5149$::jsonb,
  $q14816${"mode":"reading","level":"B2","format":"text","topic":"Culture & Food","title":"One Stew for the Festival","story":"For the street festival, three families agreed to cook one large stew instead of separate dishes. Rosa wrote down the recipe so the quantities would stay consistent, and she marked which spices were optional. On the morning of the event they tasted the pot and added lemon, not more salt. Visitors returned for a second bowl, which told the cooks the balance was right.","dialogue":[],"vocabulary":[{"word":"stew","definition":"A dish cooked slowly in liquid."},{"word":"quantities","definition":"The amounts of each ingredient."},{"word":"consistent","definition":"Staying the same each time."},{"word":"spices","definition":"Strong seeds or powders used to flavour food."},{"word":"optional","definition":"Able to be left out."},{"word":"balance","definition":"A pleasing mix in which no flavour is too strong."}],"quiz":[{"question":"What did the three families agree to cook?","options":["A second festival on another street","One large stew together","Three dishes, one from each family","Lemon sweets for the visitors"],"correctAnswer":"One large stew together","explanation":"They agreed to cook one large stew instead of separate dishes.","supportingSentence":"For the street festival, three families agreed to cook one large stew instead of separate dishes.","skill":"detail"},{"question":"What choice does the written recipe leave open?","options":["The quantities can be ignored","Every spice must be used in the same amount","Some spices can be left out","Each family must cook a separate dish"],"correctAnswer":"Some spices can be left out","explanation":"Rosa marked which spices were optional, so those ones do not have to be included.","supportingSentence":"Rosa wrote down the recipe so the quantities would stay consistent, and she marked which spices were optional.","skill":"inference"},{"question":"What were the cooks adjusting that morning?","options":["The size of the festival crowd","The list of families who would cook","The day on which the event would happen","The flavour, by adding lemon rather than salt"],"correctAnswer":"The flavour, by adding lemon rather than salt","explanation":"They tasted the pot and added lemon, not more salt, so they were correcting the taste.","supportingSentence":"On the morning of the event they tasted the pot and added lemon, not more salt.","skill":"inference"},{"question":"What does optional mean in this story?","options":["Able to be left out","Written after the festival","Tasting strongly of lemon","Required in every pot"],"correctAnswer":"Able to be left out","explanation":"Optional spices are the ones the cooks are allowed to skip.","supportingSentence":"Rosa wrote down the recipe so the quantities would stay consistent, and she marked which spices were optional.","skill":"vocabulary"},{"question":"Why did they taste the pot on the morning of the event?","options":["They wanted to add salt and nothing else","They wanted to adjust the flavour before people ate","They wanted to cancel the festival","They wanted to hide the recipe"],"correctAnswer":"They wanted to adjust the flavour before people ate","explanation":"They tasted the stew that morning and then added lemon, which changed the flavour before serving.","supportingSentence":"On the morning of the event they tasted the pot and added lemon, not more salt.","skill":"intent"}],"wordCount":64,"questionCount":5}$q14816$::jsonb,
  '4438879a263c5daa61430c2d1571e5c4cd57119a46560fe01bcdd98588c990f5',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'dfc101d0-e630-4e53-a40f-7771689edd6d'::uuid,
  'reading',
  'B2',
  'text',
  $q4941${"topic":"technology","wordCount":63,"questionCount":5}$q4941$::jsonb,
  $q71321${"mode":"reading","level":"B2","format":"text","topic":"Technology","title":"The Password under the Keyboard","story":"The office printer rejected Jonah’s password, and he found the old one written on a sticky note under the keyboard. He signed in once, then deleted the note and stored a new password in the password manager. A colleague warned that shared machines were the reason the account had been locked before. Jonah also turned on a logout reminder for the shared machine.","dialogue":[],"vocabulary":[{"word":"rejected","definition":"Refused to accept."},{"word":"deleted","definition":"Removed something so that it was gone."},{"word":"colleague","definition":"A person you work with."},{"word":"shared","definition":"Used by more than one person."},{"word":"locked","definition":"Closed so that the usual person cannot get in."},{"word":"reminder","definition":"A message that tells you to do something."}],"quiz":[{"question":"Where did Jonah find the old password?","options":["On a sticky note under the keyboard","Inside the password manager from the start","On the screen of the printer","In a warning from his colleague"],"correctAnswer":"On a sticky note under the keyboard","explanation":"He found the old password written on a sticky note under the keyboard.","supportingSentence":"The office printer rejected Jonah’s password, and he found the old one written on a sticky note under the keyboard.","skill":"detail"},{"question":"What risk did the sticky note create?","options":["The printer could store the note more safely","A reminder cannot work without a keyboard","Someone could find and read the password","His colleague would be unable to warn him"],"correctAnswer":"Someone could find and read the password","explanation":"The old password was written on a note under the keyboard, where another person could see it.","supportingSentence":"The office printer rejected Jonah’s password, and he found the old one written on a sticky note under the keyboard.","skill":"inference"},{"question":"What is the logout reminder meant to stop?","options":["A later user staying inside Jonah’s session","His colleague buying a private machine","The password manager deleting the account","The printer asking for a new keyboard"],"correctAnswer":"A later user staying inside Jonah’s session","explanation":"A logout reminder on a shared machine is there so the next person does not continue in his session.","supportingSentence":"Jonah also turned on a logout reminder for the shared machine.","skill":"inference"},{"question":"What does rejected mean in this story?","options":["Wrote down on paper","Warned a colleague","Stored in a safe list","Refused to accept"],"correctAnswer":"Refused to accept","explanation":"The printer rejected the password, meaning it would not accept it.","supportingSentence":"The office printer rejected Jonah’s password, and he found the old one written on a sticky note under the keyboard.","skill":"vocabulary"},{"question":"Why did Jonah store the new password in a manager?","options":["So the sticky note could be shared","So the printer would remain locked","So it would be kept without being left in sight","So the account would be locked again"],"correctAnswer":"So it would be kept without being left in sight","explanation":"He deleted the note and stored the new password in the manager instead of leaving it written down.","supportingSentence":"He signed in once, then deleted the note and stored a new password in the password manager.","skill":"intent"}],"wordCount":63,"questionCount":5}$q71321$::jsonb,
  'dfc101d0e6308e53e40f7771689edd6ddf7946e695f79eba2a2040d172af9439',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'fa522054-8623-455d-a2ef-0d00a636ddd8'::uuid,
  'reading',
  'B2',
  'text',
  $q4940${"topic":"technology","wordCount":62,"questionCount":5}$q4940$::jsonb,
  $q35849${"mode":"reading","level":"B2","format":"text","topic":"Technology","title":"Two Names in One Slot","story":"The clinic calendar showed two patients in the same slot, so Leila checked the booking tool before calling either of them. One appointment had been moved online, but the change had never reached the wall screen. She updated the display and added a note asking staff to refresh it after every edit. The second patient was offered a later time and accepted.","dialogue":[],"vocabulary":[{"word":"calendar","definition":"A plan that shows days and booked times."},{"word":"slot","definition":"A particular time kept for an appointment."},{"word":"booking","definition":"An arrangement to see someone at a set time."},{"word":"display","definition":"A screen that shows information."},{"word":"refresh","definition":"Load the newest information again."},{"word":"accepted","definition":"Said yes to an offer."}],"quiz":[{"question":"What did Leila check before calling the patients?","options":["The lock on the clinic door","An online shop for screens","A later time for both of them","The booking tool"],"correctAnswer":"The booking tool","explanation":"She checked the booking tool before calling either patient.","supportingSentence":"The clinic calendar showed two patients in the same slot, so Leila checked the booking tool before calling either of them.","skill":"detail"},{"question":"Why did the wall screen still show a clash?","options":["Leila had offered them one later time already","The staff had refreshed it after every edit","A change in the booking tool had not been copied onto it","Both patients had walked in at the same moment"],"correctAnswer":"A change in the booking tool had not been copied onto it","explanation":"One appointment had been moved, but that change had never reached the wall screen.","supportingSentence":"One appointment had been moved online, but the change had never reached the wall screen.","skill":"inference"},{"question":"What did the second patient’s answer do to the clash?","options":["It left both patients in the same slot","It removed the clash by moving that patient","It cancelled the online appointment","It forced the wall screen to stay wrong"],"correctAnswer":"It removed the clash by moving that patient","explanation":"The second patient accepted a later time, so that person was no longer in the shared slot.","supportingSentence":"The second patient was offered a later time and accepted.","skill":"inference"},{"question":"What does slot mean in this story?","options":["A booked time space","The clinic’s wall screen","A note left for the staff","A patient who arrives late"],"correctAnswer":"A booked time space","explanation":"Two patients appear in the same slot, meaning the same appointment time.","supportingSentence":"The clinic calendar showed two patients in the same slot, so Leila checked the booking tool before calling either of them.","skill":"vocabulary"},{"question":"Why did Leila ask staff to refresh the display after edits?","options":["So every visit would move online","So the second patient would refuse a new time","So patients would be called before any check","So the wall screen would show the latest bookings"],"correctAnswer":"So the wall screen would show the latest bookings","explanation":"Refreshing after every edit would stop the display from missing a change again.","supportingSentence":"She updated the display and added a note asking staff to refresh it after every edit.","skill":"intent"}],"wordCount":62,"questionCount":5}$q35849$::jsonb,
  'fa5220548623055d22ef0d00a636ddd82945b569e98322d61a1e0f10963b815c',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'c4e21628-c928-4f7e-a68a-f1019bbf92af'::uuid,
  'reading',
  'B2',
  'text',
  $q4590${"topic":"science","wordCount":66,"questionCount":5}$q4590$::jsonb,
  $q2860${"mode":"reading","level":"B2","format":"text","topic":"Science","title":"Two Pots on the Windowsill","story":"The class compared two pots of basil on the same windowsill, giving one extra water and leaving the other on the usual schedule. After ten days the wetter plant had yellow leaves, while the other stayed green. Their teacher said too much water can harm roots just as dryness can. The students recorded both results and agreed the next test should give both pots equal light.","dialogue":[],"vocabulary":[{"word":"compared","definition":"Looked at two things to see how they differed."},{"word":"windowsill","definition":"The flat shelf along the bottom of a window."},{"word":"schedule","definition":"A planned pattern for when something is done."},{"word":"wetter","definition":"Containing more water."},{"word":"harm","definition":"Cause damage."},{"word":"roots","definition":"The parts of a plant that grow under the soil."}],"quiz":[{"question":"How many pots of basil did the class compare?","options":["Two","One","Four","Ten"],"correctAnswer":"Two","explanation":"The class compared two pots of basil on the same windowsill.","supportingSentence":"The class compared two pots of basil on the same windowsill, giving one extra water and leaving the other on the usual schedule.","skill":"detail"},{"question":"What do the yellow leaves suggest about the extra water?","options":["The wetter plant needed still more water","The windowsill was too dry for both pots","The green plant had been kept in the dark","The extra water was bad for that plant"],"correctAnswer":"The extra water was bad for that plant","explanation":"The plant that got extra water turned yellow, while the other stayed green.","supportingSentence":"After ten days the wetter plant had yellow leaves, while the other stayed green.","skill":"inference"},{"question":"Why keep the light equal in the next test?","options":["So the class can stop writing results","So one pot can sit in a dark cupboard","So light will not be the reason for any difference","So both pots can be given extra water"],"correctAnswer":"So light will not be the reason for any difference","explanation":"Equal light means a later difference cannot be blamed on one pot getting more light.","supportingSentence":"The students recorded both results and agreed the next test should give both pots equal light.","skill":"inference"},{"question":"What does harm mean in this story?","options":["Stay green and healthy","Cause damage","Give an equal amount","Write a result down"],"correctAnswer":"Cause damage","explanation":"The teacher says too much water can harm roots, meaning it can damage them.","supportingSentence":"Their teacher said too much water can harm roots just as dryness can.","skill":"vocabulary"},{"question":"Why did the students write down both results?","options":["So they would have a record of what each pot did","So the teacher would add more water","So the usual schedule would stay secret","So they could throw the green plant away"],"correctAnswer":"So they would have a record of what each pot did","explanation":"They recorded both results in order to keep what they had observed.","supportingSentence":"The students recorded both results and agreed the next test should give both pots equal light.","skill":"intent"}],"wordCount":66,"questionCount":5}$q2860$::jsonb,
  'c4e21628c9289f7ec68af1019bbf92aff952813b1cddb90054adaf2a8b2b75da',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '4ad46eb7-da6e-42cb-a662-dc08b6913bfc'::uuid,
  'reading',
  'B2',
  'text',
  $q4586${"topic":"science","wordCount":62,"questionCount":5}$q4586$::jsonb,
  $q31236${"mode":"reading","level":"B2","format":"text","topic":"Science","title":"Colder beside the Hedge","story":"Each dawn, Sofia read the thermometer in the school garden and entered the number in a shared sheet. For three mornings the reading was lower beside the hedge than in the open bed. She realised the hedge was blocking early sun, so those plants stayed colder. The group moved the tender seedlings to the brighter spot and kept recording for another week.","dialogue":[],"vocabulary":[{"word":"dawn","definition":"The early morning, when the first light appears."},{"word":"thermometer","definition":"A tool that measures temperature."},{"word":"hedge","definition":"A line of bushes that forms a barrier."},{"word":"blocking","definition":"Stopping something from passing."},{"word":"tender","definition":"Easily hurt, especially by cold."},{"word":"seedlings","definition":"Very young plants."}],"quiz":[{"question":"Where was the morning reading lower?","options":["Beside the hedge","At the brighter spot after the move","Only on the shared sheet","In the open bed"],"correctAnswer":"Beside the hedge","explanation":"For three mornings the reading was lower beside the hedge than in the open bed.","supportingSentence":"For three mornings the reading was lower beside the hedge than in the open bed.","skill":"detail"},{"question":"Why were the plants by the hedge colder?","options":["The thermometer was broken every morning","The open bed was in deeper shade","The seedlings had already been moved","The hedge was keeping the early sun off them"],"correctAnswer":"The hedge was keeping the early sun off them","explanation":"Sofia realised the hedge was blocking the early sun, so those plants stayed colder.","supportingSentence":"She realised the hedge was blocking early sun, so those plants stayed colder.","skill":"inference"},{"question":"What does moving the seedlings show about the group?","options":["They wanted the young plants to stay cold","They decided to stop recording temperatures","They acted on Sofia’s explanation of the cold spot","They thought the open bed was too bright to use"],"correctAnswer":"They acted on Sofia’s explanation of the cold spot","explanation":"After she explained the cold hedge, the group moved the seedlings to the brighter spot.","supportingSentence":"The group moved the tender seedlings to the brighter spot and kept recording for another week.","skill":"inference"},{"question":"What does tender mean in this story?","options":["Measured only at noon","Easily hurt by cold","Brighter than a hedge","Written on a shared sheet"],"correctAnswer":"Easily hurt by cold","explanation":"The tender seedlings are the young plants they move away from the colder spot.","supportingSentence":"The group moved the tender seedlings to the brighter spot and kept recording for another week.","skill":"vocabulary"},{"question":"Why did the group keep recording for another week?","options":["They wanted to see the temperatures after the move","They wanted the dawn numbers kept secret","They wanted to stop using the thermometer","They wanted the hedge to block more sun"],"correctAnswer":"They wanted to see the temperatures after the move","explanation":"They kept recording after moving the seedlings, so they could follow what happened next.","supportingSentence":"The group moved the tender seedlings to the brighter spot and kept recording for another week.","skill":"intent"}],"wordCount":62,"questionCount":5}$q31236$::jsonb,
  '4ad46eb7da6e62cb9662dc08b6913bfcbda2ef07e62e4de7baf0802721e7c2c5',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'fd490470-467d-46b5-a112-2946e36d6e09'::uuid,
  'reading',
  'B2',
  'text',
  $q5436${"topic":"economy_finance","wordCount":61,"questionCount":5}$q5436$::jsonb,
  $q22462${"mode":"reading","level":"B2","format":"text","topic":"Economy / Finance","title":"The Float That Looked Short","story":"Before the craft market opened, Elise counted the float and compared it with the notebook. The cash was lower than the written total by the price of two mugs. She found a Friday sale that had been entered twice, which made the book too high. She corrected the entry and wrote the true starting amount on a fresh page for Saturday.","dialogue":[],"vocabulary":[{"word":"float","definition":"The starting cash a seller keeps in order to give change."},{"word":"total","definition":"The full amount when numbers are added together."},{"word":"entered","definition":"Written into a record."},{"word":"twice","definition":"Two times."},{"word":"corrected","definition":"Made right after a mistake."},{"word":"amount","definition":"A quantity of money."}],"quiz":[{"question":"By how much did the cash seem lower than the book?","options":["By the price of two mugs","By the cost of a fresh page","By the whole of Friday’s market","By the price of the notebook"],"correctAnswer":"By the price of two mugs","explanation":"The cash was lower than the written total by the price of two mugs.","supportingSentence":"The cash was lower than the written total by the price of two mugs.","skill":"detail"},{"question":"What does the double entry explain?","options":["Two mugs had been stolen before opening","Friday’s market had never taken place","The float had been spent on a new notebook","The book was too high, while the cash was really there"],"correctAnswer":"The book was too high, while the cash was really there","explanation":"A sale entered twice made the book too high, so the gap came from the record.","supportingSentence":"She found a Friday sale that had been entered twice, which made the book too high.","skill":"inference"},{"question":"Why is the fresh page useful for Saturday?","options":["It starts the day from the corrected figure","It raises the price of the mugs","It hides every Friday sale","It takes the cash out of the tin"],"correctAnswer":"It starts the day from the corrected figure","explanation":"She wrote the true starting amount on a fresh page after correcting the mistake.","supportingSentence":"She corrected the entry and wrote the true starting amount on a fresh page for Saturday.","skill":"inference"},{"question":"What does float mean in this story?","options":["A book of old sales","Starting cash kept for giving change","A page that has never been used","A mug sold on Friday"],"correctAnswer":"Starting cash kept for giving change","explanation":"Elise counts the float before opening, which is the cash the stall starts with.","supportingSentence":"Before the craft market opened, Elise counted the float and compared it with the notebook.","skill":"vocabulary"},{"question":"Why did Elise correct the notebook entry?","options":["So the written total would match the real cash","So Saturday could begin with no figure","So the float would shrink by two more mugs","So Friday would disappear from the records"],"correctAnswer":"So the written total would match the real cash","explanation":"She corrected the entry that had made the book too high, then wrote the true amount.","supportingSentence":"She corrected the entry and wrote the true starting amount on a fresh page for Saturday.","skill":"intent"}],"wordCount":61,"questionCount":5}$q22462$::jsonb,
  'fd490470467dd6b5d1122946e36d6e09fd8911f6fb49b34ac42215de8035e94f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'afa53015-022f-4faf-a2be-bf11817dc225'::uuid,
  'reading',
  'B2',
  'text',
  $q4652${"topic":"mystery","wordCount":61,"questionCount":5}$q4652$::jsonb,
  $q98636${"mode":"reading","level":"B2","format":"text","topic":"Mystery","title":"A Lamp Still Lit","story":"After closing, the librarian saw a lamp still lit in the stacks, though every reader had signed out. A damp coat hung on a chair, and a book about local tunnels lay open at a map. She called the caretaker instead of searching alone. Together they found a student who had fallen asleep behind the last shelf and missed the bell.","dialogue":[],"vocabulary":[{"word":"librarian","definition":"A person who works in a library."},{"word":"stacks","definition":"The shelves where a library keeps its books."},{"word":"damp","definition":"Slightly wet."},{"word":"tunnels","definition":"Underground passages."},{"word":"caretaker","definition":"A person who looks after a building."},{"word":"shelf","definition":"A flat board used for storing books."}],"quiz":[{"question":"Who did the librarian ask to come with her?","options":["A reader who had already signed out","The caretaker","Nobody, because she searched alone","The person who drew the map"],"correctAnswer":"The caretaker","explanation":"She called the caretaker instead of searching alone.","supportingSentence":"She called the caretaker instead of searching alone.","skill":"detail"},{"question":"What do the lit lamp and the signed-out list suggest?","options":["Someone may still be inside despite the list","The stacks were being painted that night","Every reader took a lamp home","The map showed an open exit"],"correctAnswer":"Someone may still be inside despite the list","explanation":"A lamp was still lit even though every reader had signed out, which suggests someone remained.","supportingSentence":"After closing, the librarian saw a lamp still lit in the stacks, though every reader had signed out.","skill":"inference"},{"question":"What was the student most likely doing before falling asleep?","options":["Signing other readers out at the desk","Calling the caretaker for help","Hanging new lamps in the stacks","Reading the open book about local tunnels"],"correctAnswer":"Reading the open book about local tunnels","explanation":"A book about tunnels lay open at a map, and the student was later found asleep nearby.","supportingSentence":"A damp coat hung on a chair, and a book about local tunnels lay open at a map.","skill":"inference"},{"question":"What does stacks mean in this story?","options":["A bell that marks closing time","A person who looks after a building","The shelves where books are kept","A coat left on a chair"],"correctAnswer":"The shelves where books are kept","explanation":"The lamp is lit in the stacks, the part of the library where the books stand.","supportingSentence":"After closing, the librarian saw a lamp still lit in the stacks, though every reader had signed out.","skill":"vocabulary"},{"question":"Why did she call the caretaker instead of going alone?","options":["She wanted him to sign the readers out","She did not want to search the stacks by herself","She thought the map was enough","She wanted the lamp switched off from home"],"correctAnswer":"She did not want to search the stacks by herself","explanation":"She called the caretaker instead of searching alone.","supportingSentence":"She called the caretaker instead of searching alone.","skill":"intent"}],"wordCount":61,"questionCount":5}$q98636$::jsonb,
  'afa53015022f8faf82bebf11817dc225cc83793430a0250dd0ef53fa988ef7e5',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '4bd85ffb-fd26-465d-a198-98b2735ecc5e'::uuid,
  'reading',
  'B2',
  'text',
  $q4833${"topic":"adventure","wordCount":65,"questionCount":5}$q4833$::jsonb,
  $q15256${"mode":"reading","level":"B2","format":"text","topic":"Adventure","title":"The Ledge before Dark","story":"The path narrowed to a ledge just as the light began to fade, so Idris stopped the group and checked each harness. One walker was shaking, and Idris had her clip onto his own line before they continued. They moved slowly, facing the rock, until the ledge widened into a shelf. Only then did he allow a short rest and a count of every person.","dialogue":[],"vocabulary":[{"word":"ledge","definition":"A narrow flat strip along a steep side."},{"word":"fade","definition":"Grow weaker until it nearly disappears."},{"word":"harness","definition":"A set of straps that secures a person."},{"word":"clip","definition":"Fasten something with a metal catch."},{"word":"widened","definition":"Became wider."},{"word":"allow","definition":"Permit something to happen."}],"quiz":[{"question":"What did Idris check before the group moved on?","options":["The walker’s spare boots","Each harness","Only the width of the shelf","A map of the whole valley"],"correctAnswer":"Each harness","explanation":"He stopped the group and checked each harness.","supportingSentence":"The path narrowed to a ledge just as the light began to fade, so Idris stopped the group and checked each harness.","skill":"detail"},{"question":"Why was this a dangerous moment to continue quickly?","options":["The path was narrower and the light was failing","Every harness had broken","The shelf was already wide enough for a rest","The group had finished the route"],"correctAnswer":"The path was narrower and the light was failing","explanation":"The path had narrowed to a ledge just as the light began to fade, so he stopped them.","supportingSentence":"The path narrowed to a ledge just as the light began to fade, so Idris stopped the group and checked each harness.","skill":"inference"},{"question":"Why was the shaking walker joined to his line?","options":["She was leading the group onto the shelf","She wanted to rest before the ledge","She had been left out of the count","She was unsteady and needed the extra link"],"correctAnswer":"She was unsteady and needed the extra link","explanation":"She was shaking, so Idris had her clip onto his line before they went on.","supportingSentence":"One walker was shaking, and Idris had her clip onto his own line before they continued.","skill":"inference"},{"question":"What does harness mean in this story?","options":["Straps that secure a person","The rock face beside a ledge","A short rest after danger","A wide place in the path"],"correctAnswer":"Straps that secure a person","explanation":"Idris checks each harness before the group continues along the ledge.","supportingSentence":"The path narrowed to a ledge just as the light began to fade, so Idris stopped the group and checked each harness.","skill":"vocabulary"},{"question":"Why did Idris count every person after the ledge?","options":["He wanted to start the narrow section again","He wanted to be sure nobody had been left behind","He wanted to remove every harness","He wanted the group to face the rock"],"correctAnswer":"He wanted to be sure nobody had been left behind","explanation":"He allowed a count of every person once the ledge had widened, to check that all were there.","supportingSentence":"Only then did he allow a short rest and a count of every person.","skill":"intent"}],"wordCount":65,"questionCount":5}$q15256$::jsonb,
  '4bd85ffbfd26b65de19898b2735ecc5e043cbd65884e3b183bdf7b472bb48452',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f25abaab-2cdf-4204-ae76-1743c2aebc76'::uuid,
  'reading',
  'B2',
  'text',
  $q4617${"topic":"fantasy","wordCount":65,"questionCount":5}$q4617$::jsonb,
  $q7231${"mode":"reading","level":"B2","format":"text","topic":"Fantasy","title":"The Unlit Lantern Gate","story":"The stone gate in the orchard opened only at dusk, and only when someone arrived with an unlit lantern. Mira carried hers carefully, because a flame would keep the gate shut. On the far side she found a garden where the fruit glowed faintly and a path repaired itself behind her. She picked one pear, left a ribbon, and stepped back before the stones closed.","dialogue":[],"vocabulary":[{"word":"orchard","definition":"A piece of land where fruit trees grow."},{"word":"dusk","definition":"The time when daylight is fading."},{"word":"unlit","definition":"Not burning, with no flame."},{"word":"flame","definition":"The bright burning part of a fire."},{"word":"faintly","definition":"In a way that is soft and weak."},{"word":"repaired","definition":"Mended so that it was whole again."}],"quiz":[{"question":"At what time of day could the stone gate open?","options":["Whenever a flame was near","After the stones had closed","Only at dusk","Only at dawn"],"correctAnswer":"Only at dusk","explanation":"The gate opened only at dusk, and only for someone with an unlit lantern.","supportingSentence":"The stone gate in the orchard opened only at dusk, and only when someone arrived with an unlit lantern.","skill":"detail"},{"question":"What was Mira avoiding by carrying the lantern so carefully?","options":["A path that would push her back outside","A ribbon that would close the stones early","Fruit that would stop glowing if she hurried","A flame that would stop the gate from opening"],"correctAnswer":"A flame that would stop the gate from opening","explanation":"She carried the lantern carefully because a flame would keep the gate shut.","supportingSentence":"Mira carried hers carefully, because a flame would keep the gate shut.","skill":"inference"},{"question":"Why did Mira step back when she did?","options":["She needed to leave before the gate shut her in","She had forgotten to bring the ribbon","She wanted to pick a second pear","She wanted a flame to light the garden"],"correctAnswer":"She needed to leave before the gate shut her in","explanation":"She stepped back before the stones closed, so she would not be shut on the far side.","supportingSentence":"She picked one pear, left a ribbon, and stepped back before the stones closed.","skill":"inference"},{"question":"What does unlit mean in this story?","options":["Closed until morning","Not burning","Carried in both hands","Shining with a strong light"],"correctAnswer":"Not burning","explanation":"An unlit lantern has no flame, which is the condition the gate requires.","supportingSentence":"The stone gate in the orchard opened only at dusk, and only when someone arrived with an unlit lantern.","skill":"vocabulary"},{"question":"Why did Mira arrive with an unlit lantern?","options":["She wanted the stones to close at once","She hoped to hide the glowing fruit","She was meeting the condition that opens the gate","She was trying to set the orchard alight"],"correctAnswer":"She was meeting the condition that opens the gate","explanation":"The gate opens only for someone who arrives with an unlit lantern, and that is what she carries.","supportingSentence":"The stone gate in the orchard opened only at dusk, and only when someone arrived with an unlit lantern.","skill":"intent"}],"wordCount":65,"questionCount":5}$q7231$::jsonb,
  'f25abaab2cdf92044e761743c2aebc76bccfc05e5c784ffbd53f032795e34eee',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f59045fc-6563-4f67-a46d-5444b46d0dbb'::uuid,
  'reading',
  'C1',
  'text',
  $q4884${"topic":"daily life","wordCount":108,"questionCount":5}$q4884$::jsonb,
  $q26700${"mode":"reading","level":"C1","format":"text","topic":"Daily Life","title":"A Code Instead of a Spare Key","story":"When the committee retired the old lockbox, Nia refused to leave a spare key with the porter. She trusted him, yet a key several people could reach was no longer private. Her sister, who watered the plants on trips, needed entry without a copy she might lose. Nia chose a timed code for the new lock, changed it after each absence, and wrote the digits in a notebook her sister kept at home. The porter could accept a parcel, but he could not open the door. Neighbours called the arrangement fussy. Nia called it a way to help her family without letting more people enter while she slept.","dialogue":[],"vocabulary":[{"word":"lockbox","definition":"A shared box that used to hold spare keys"},{"word":"private","definition":"Limited to the people who are meant to have it"},{"word":"absence","definition":"A time when someone is away"},{"word":"parcel","definition":"A package delivered for someone"},{"word":"fussy","definition":"Too particular about small details"},{"word":"arrangement","definition":"A way of organising something"}],"quiz":[{"question":"What did Nia refuse to leave with the porter?","options":["A spare key","Her sister's notebook","A parcel from upstairs","The retired lockbox"],"correctAnswer":"A spare key","explanation":"She refused to leave a spare key with the porter.","supportingSentence":"When the committee retired the old lockbox, Nia refused to leave a spare key with the porter.","skill":"detail"},{"question":"Where were the digits for the lock written down?","options":["On a card inside the old lockbox","On the outside of a parcel","In a notebook her sister kept at home","In a message sent to the porter"],"correctAnswer":"In a notebook her sister kept at home","explanation":"Nia wrote the digits in a notebook her sister kept at home.","supportingSentence":"Nia chose a timed code for the new lock, changed it after each absence, and wrote the digits in a notebook her sister kept at home.","skill":"detail"},{"question":"What is Nia limiting if she still trusts the porter?","options":["How many people can enter the flat","How often the committee meets","Which plants need water on trips","Whether her sister is willing to travel"],"correctAnswer":"How many people can enter the flat","explanation":"She objects to a key that several people could reach, even though she trusts the porter.","supportingSentence":"She trusted him, yet a key several people could reach was no longer private.","skill":"inference"},{"question":"What do the neighbours suggest by calling the arrangement fussy?","options":["That it costs more than the old lock","That it leaves the plants dry","That it breaks the fire rules","That it is needlessly particular"],"correctAnswer":"That it is needlessly particular","explanation":"Fussy means they find the arrangement too particular.","supportingSentence":"Neighbours called the arrangement fussy.","skill":"vocabulary"},{"question":"Why does the passage close with Nia's own description?","options":["To set her purpose against the neighbours' complaint","To announce that the porter chose the code","To admit that her sister lost the notebook","To explain how a parcel is weighed"],"correctAnswer":"To set her purpose against the neighbours' complaint","explanation":"Her description answers the charge of fussiness with the reason she chose the code.","supportingSentence":"Nia called it a way to help her family without letting more people enter while she slept.","skill":"intent"}],"wordCount":108,"questionCount":5}$q26700$::jsonb,
  'f59045fc6563af67b46d5444b46d0dbb52586025569ee00ffe41db596d188b00',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '6a3e524d-d377-4882-aa87-b378649d2ff3'::uuid,
  'reading',
  'C1',
  'text',
  $q5375${"topic":"school_college","wordCount":104,"questionCount":5}$q5375$::jsonb,
  $q37784${"mode":"reading","level":"C1","format":"text","topic":"School / College","title":"The Source That Could Not Be Cited","story":"The seminar required a footnote for every claim, yet Samir's best source sat in a private archive that forbade quotation. He could paraphrase the argument in his own words, but he could not point a reader to the page. His partner wanted the claim removed, because an uncheckable sentence looked like ornament. Samir wanted it kept, because removal would make the essay neater and less true. The tutor allowed the sentence only beside a note that the source could not be consulted. She marked the paper on whether that limit was shown honestly. A hidden advantage, she said, was worse than a visible gap.","dialogue":[],"vocabulary":[{"word":"footnote","definition":"A note telling a reader where a claim comes from"},{"word":"archive","definition":"A store of records that is not open to everyone"},{"word":"paraphrase","definition":"To retell an idea in your own words"},{"word":"ornament","definition":"Decoration that adds little real substance"},{"word":"consulted","definition":"Looked at in order to check something"},{"word":"advantage","definition":"A benefit that puts someone in a stronger position"}],"quiz":[{"question":"On what condition could Samir's sentence stay?","options":["Only if his partner signed every footnote","Only after the archive lifted its ban","Only once the claim had been deleted","Beside a note that the source could not be consulted"],"correctAnswer":"Beside a note that the source could not be consulted","explanation":"The tutor allowed the sentence only beside a note that the source could not be consulted.","supportingSentence":"The tutor allowed the sentence only beside a note that the source could not be consulted.","skill":"detail"},{"question":"What did the partner want done with the uncheckable claim?","options":["Removed from the essay","Checked against a public copy","Moved into another seminar","Printed as a long quotation"],"correctAnswer":"Removed from the essay","explanation":"The partner wanted the claim removed.","supportingSentence":"His partner wanted the claim removed, because an uncheckable sentence looked like ornament.","skill":"detail"},{"question":"What did Samir think a neater essay would lose?","options":["His partner's name on the cover","Part of what was true","Every footnote in the seminar","Entry to the private archive"],"correctAnswer":"Part of what was true","explanation":"He believed removal would make the essay neater and less true.","supportingSentence":"Samir wanted it kept, because removal would make the essay neater and less true.","skill":"inference"},{"question":"What does paraphrase mean in Samir's case?","options":["Saying the idea in his own words","Deleting the sentence before marking","Copying an archive page in full","Asking the tutor to invent a source"],"correctAnswer":"Saying the idea in his own words","explanation":"Paraphrase is paired with retelling the argument in his own words.","supportingSentence":"He could paraphrase the argument in his own words, but he could not point a reader to the page.","skill":"vocabulary"},{"question":"Why does the passage end by ranking a hidden advantage against a visible gap?","options":["To admit the archive ban had been lifted","To show the partner changed his mind","To list claims that needed no footnote","To state the standard she would mark by"],"correctAnswer":"To state the standard she would mark by","explanation":"The closing comparison is the standard behind marking the paper for honesty.","supportingSentence":"A hidden advantage, she said, was worse than a visible gap.","skill":"intent"}],"wordCount":104,"questionCount":5}$q37784$::jsonb,
  '6a3e524dd377b8825a87b378649d2ff30555ea51878985a91f77ca18eadebd7f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'b08e1247-c47a-4a56-a2f1-653d2e9ca6e8'::uuid,
  'reading',
  'C1',
  'text',
  $q4559${"topic":"travel","wordCount":108,"questionCount":5}$q4559$::jsonb,
  $q39546${"mode":"reading","level":"C1","format":"text","topic":"Travel","title":"Choosing the Later Mountain Coach","story":"The agent offered Mara a seat on the early coach through the mountains, with a tight connection at the river station. She read the board, saw how little room a delay would leave, and asked for the later coach that reached the same town after dark. That ticket cost more, and the early seat was easier to sell, so the agent hesitated. Mara was not chasing comfort. She was buying time between the two legs, enough to recover if the first road closed. A missed link would have meant a night in a town where she knew nobody. Arriving late, with the plan intact, seemed the smaller risk.","dialogue":[],"vocabulary":[{"word":"connection","definition":"A later vehicle that must be caught in time"},{"word":"delay","definition":"A hold-up that makes something late"},{"word":"hesitated","definition":"Paused before agreeing"},{"word":"comfort","definition":"Physical ease during a journey"},{"word":"intact","definition":"Still whole and undamaged"},{"word":"agent","definition":"A person who sells and arranges tickets"}],"quiz":[{"question":"Which coach did Mara request after reading the board?","options":["The early one, with a rush at the river","A seat another traveller had already bought","The later one, reaching town after dark","A boat that replaced both coaches"],"correctAnswer":"The later one, reaching town after dark","explanation":"She asked for the later coach that reached the same town after dark.","supportingSentence":"She read the board, saw how little room a delay would leave, and asked for the later coach that reached the same town after dark.","skill":"detail"},{"question":"What made the agent pause over her request?","options":["A higher fare and an early seat that sold easily","A mountain road that was already closed","News that she had missed the station","A board that showed no coach after dark"],"correctAnswer":"A higher fare and an early seat that sold easily","explanation":"The later ticket cost more, and the early seat was easier to sell.","supportingSentence":"That ticket cost more, and the early seat was easier to sell, so the agent hesitated.","skill":"detail"},{"question":"What danger is the extra cost meant to shrink?","options":["A noisier seat than the early coach","A return to the agent's office","A fine charged at the river station","A night stranded if the first road closes"],"correctAnswer":"A night stranded if the first road closes","explanation":"She buys time so a closed road does not leave her overnight in an unknown town.","supportingSentence":"She was buying time between the two legs, enough to recover if the first road closed.","skill":"inference"},{"question":"What does connection mean on this journey?","options":["The onward coach she has to reach in time","A friend waiting in the destination","The fee for changing a ticket","A discount offered beside the river"],"correctAnswer":"The onward coach she has to reach in time","explanation":"A connection here is the onward coach waiting at the river station.","supportingSentence":"The agent offered Mara a seat on the early coach through the mountains, with a tight connection at the river station.","skill":"vocabulary"},{"question":"Why state that Mara was not chasing comfort?","options":["To complain that night roads are colder","To describe the meals on the early coach","To frame the later coach as a choice about risk","To hint that the agent refused her"],"correctAnswer":"To frame the later coach as a choice about risk","explanation":"The remark stops the reader from taking the later coach as a wish for ease.","supportingSentence":"Mara was not chasing comfort.","skill":"intent"}],"wordCount":108,"questionCount":5}$q39546$::jsonb,
  'b08e1247c47a5a5672f1653d2e9ca6e81517e108ad52603a72c029069926a4db',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '51398e79-eb47-4fcc-ae71-9ffcb3fd72c5'::uuid,
  'reading',
  'C1',
  'text',
  $q4596${"topic":"hobbies","wordCount":97,"questionCount":5}$q4596$::jsonb,
  $q24702${"mode":"reading","level":"C1","format":"text","topic":"Hobbies","title":"Leaving the Hard Bar Unplayed","story":"Elena practised the difficult passage until her hands knew the notes, then stopped midway and marked the page. The others wanted a full run before the visitor arrived. She argued that a clean performance would hide the bar where the rhythm still slipped. They would hear success and remember the wrong shape. Leaving the passage unfinished forced the next rehearsal to begin at the weak point, not at the opening where everyone felt safe. The visitor could wait a week. The group grumbled. A habit of skipping the hard bar, she said, would outlast any single performance.","dialogue":[],"vocabulary":[{"word":"passage","definition":"A section of a piece of music"},{"word":"rhythm","definition":"The pattern of beats in the music"},{"word":"slipped","definition":"Failed to stay steady"},{"word":"rehearsal","definition":"A practice session before a performance"},{"word":"unfinished","definition":"Stopped before the end"},{"word":"performance","definition":"Playing the piece for listeners"}],"quiz":[{"question":"At what point did Elena stop playing?","options":["After the visitor had left the room","On the final bar of the whole piece","Before her hands knew any notes","Midway through the difficult passage"],"correctAnswer":"Midway through the difficult passage","explanation":"She stopped midway through the passage.","supportingSentence":"Elena practised the difficult passage until her hands knew the notes, then stopped midway and marked the page.","skill":"detail"},{"question":"What did the rest of the group hope to do that day?","options":["Rewrite the hard bar in a new key","Ask the visitor to lead them","Play the whole piece before the visitor came","Cancel practice until the next month"],"correctAnswer":"Play the whole piece before the visitor came","explanation":"The others wanted a full run before the visitor arrived.","supportingSentence":"The others wanted a full run before the visitor arrived.","skill":"detail"},{"question":"What false memory would a clean full run plant?","options":["That the visitor had joined the group","That the weak bar was already secure","That practice should move to another room","That the pencil marks could not be read"],"correctAnswer":"That the weak bar was already secure","explanation":"They would hear success and remember the wrong shape of the weak bar.","supportingSentence":"They would hear success and remember the wrong shape.","skill":"inference"},{"question":"What does slipped say about the rhythm?","options":["It was not yet steady","It belonged to a different piece","The visitor had chosen it","It was louder than the other bars"],"correctAnswer":"It was not yet steady","explanation":"Slipped means the rhythm was still failing to hold steady.","supportingSentence":"She argued that a clean performance would hide the bar where the rhythm still slipped.","skill":"vocabulary"},{"question":"Why include the remark that a habit would outlast a performance?","options":["To prove the visitor cancelled the concert","To explain how the music was printed","To suggest the group should split up","To show she is protecting later practice, not this visit"],"correctAnswer":"To show she is protecting later practice, not this visit","explanation":"The remark shifts the decision from one performance to a habit that would last.","supportingSentence":"A habit of skipping the hard bar, she said, would outlast any single performance.","skill":"intent"}],"wordCount":97,"questionCount":5}$q24702$::jsonb,
  '51398e79eb47efccee719ffcb3fd72c55794656f325d2ebdd50e996463814e82',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '14dfa9ad-5a67-4491-a9f8-c5ffe9dca320'::uuid,
  'reading',
  'C1',
  'text',
  $q5312${"topic":"health_sports","wordCount":107,"questionCount":5}$q5312$::jsonb,
  $q51237${"mode":"reading","level":"C1","format":"text","topic":"Health & Sports","title":"Ending the Session for Form","story":"The coach stopped the track session when Tomas's stride shortened, though the watch still showed time left on the plan. Teammates wanted the last repeats, because a public chart recorded only work that was finished. Tomas said he could complete the set. The coach pointed to his changing form, not to the clock. Repeats run with a collapsing stride would train him to accept a poor pattern, and the chart would call that success. They logged the session as cut short for form, and the repeats moved to the next morning, when he was fresh. A finished list, the coach said, was a poor guide to recovery.","dialogue":[],"vocabulary":[{"word":"stride","definition":"The length and shape of a running step"},{"word":"repeats","definition":"Set pieces of the session done again"},{"word":"chart","definition":"A public record of completed work"},{"word":"pattern","definition":"A way of moving that can become a habit"},{"word":"logged","definition":"Written down in the record"},{"word":"recovery","definition":"Getting back to a state ready for good work"}],"quiz":[{"question":"What change brought the session to a stop?","options":["A teammate walked off the track","Tomas's running stride grew shorter","The watch battery went dead","The public chart was switched off"],"correctAnswer":"Tomas's running stride grew shorter","explanation":"The coach stopped the session when Tomas's stride shortened.","supportingSentence":"The coach stopped the track session when Tomas's stride shortened, though the watch still showed time left on the plan.","skill":"detail"},{"question":"When were the unfinished repeats given a new slot?","options":["A weekend race in another town","That same evening, after a team vote","The next morning, once he was fresh","The opening minute of the same session"],"correctAnswer":"The next morning, once he was fresh","explanation":"The repeats moved to the next morning, when he was fresh.","supportingSentence":"They logged the session as cut short for form, and the repeats moved to the next morning, when he was fresh.","skill":"detail"},{"question":"Why is a completed set still a poor result here?","options":["The watch was set up for a different sport","Another club had booked the track","Tomas had already raced that morning","Bad form would be trained and then recorded as success"],"correctAnswer":"Bad form would be trained and then recorded as success","explanation":"Finishing with a collapsing stride would teach a poor pattern and still look complete on the chart.","supportingSentence":"Repeats run with a collapsing stride would train him to accept a poor pattern, and the chart would call that success.","skill":"inference"},{"question":"What does recovery mean in the coach's last remark?","options":["Becoming ready to train well again","A vote taken by teammates","The last lap saved on the watch","A public list of finished repeats"],"correctAnswer":"Becoming ready to train well again","explanation":"Recovery means getting ready for sound training, which a finished list does not measure.","supportingSentence":"A finished list, the coach said, was a poor guide to recovery.","skill":"vocabulary"},{"question":"Why mention a chart that counts only finished work?","options":["To prove Tomas was the fastest runner","To show the pressure that makes an early stop look like failure","To announce that the chart was abolished","To name the maker of the watch"],"correctAnswer":"To show the pressure that makes an early stop look like failure","explanation":"The chart explains why teammates treat a stopped session as a failure.","supportingSentence":"Teammates wanted the last repeats, because a public chart recorded only work that was finished.","skill":"intent"}],"wordCount":107,"questionCount":5}$q51237$::jsonb,
  '14dfa9ad5a67349199f8c5ffe9dca320fd7c318757f57656e4d860fd0bc28151',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'a0788b76-2194-4b92-af91-fd7c00ff7382'::uuid,
  'reading',
  'C1',
  'text',
  $q5156${"topic":"culture_food","wordCount":98,"questionCount":5}$q5156$::jsonb,
  $q34998${"mode":"reading","level":"C1","format":"text","topic":"Culture & Food","title":"Four Pots, Not One Boiler","story":"The parish hall asked Rosa to cook her grandmother's broth for a festival crowd. The recipe lived in proportions, not in a multiplied list: a clay pot, a low flame, and bones that barely simmered until the surface cleared. Rosa refused to tip those quantities into the hall's wide boiler. Heat would reach the edges before the centre, and the cloudy result would be a different dish that only shared the name. She cooked four small pots in sequence and held them over warm water. Guests waited longer. What they received was the broth the family actually recognised.","dialogue":[],"vocabulary":[{"word":"broth","definition":"A savoury liquid dish cooked slowly"},{"word":"proportions","definition":"The relations between amounts in a recipe"},{"word":"simmered","definition":"Cooked just below boiling"},{"word":"boiler","definition":"A large pot used to heat a big quantity"},{"word":"sequence","definition":"One after another, in order"},{"word":"recognised","definition":"Known as the real familiar dish"}],"quiz":[{"question":"How did Rosa produce enough broth for the hall?","options":["In four small pots, cooked one after another","By doubling every measure in one huge pot","By buying a finished soup from a shop","In the hall's wide boiler on a high flame"],"correctAnswer":"In four small pots, cooked one after another","explanation":"She cooked four small pots in sequence.","supportingSentence":"She cooked four small pots in sequence and held them over warm water.","skill":"detail"},{"question":"What did the guests have to put up with?","options":["A new name for the family dish","A cold hall with nowhere to sit","A recipe written only as numbers","A longer wait before they were served"],"correctAnswer":"A longer wait before they were served","explanation":"The guests waited longer.","supportingSentence":"Guests waited longer.","skill":"detail"},{"question":"Why would the wide boiler have spoiled the dish?","options":["The crowd had asked only for pudding","The hall had banned every clay pot","Uneven heat would make something the family would not know as theirs","The grandmother had never used bones"],"correctAnswer":"Uneven heat would make something the family would not know as theirs","explanation":"Heat at the edges would turn the broth into a different dish that only shared the name.","supportingSentence":"Heat would reach the edges before the centre, and the cloudy result would be a different dish that only shared the name.","skill":"inference"},{"question":"What does proportions mean for this recipe?","options":["A hotter flame at the rim","Relations between amounts, rather than one multiplied list","A ticket printed for each guest","The paint colour of the hall"],"correctAnswer":"Relations between amounts, rather than one multiplied list","explanation":"The recipe lives in proportions, which the sentence sets against a multiplied list.","supportingSentence":"The recipe lived in proportions, not in a multiplied list: a clay pot, a low flame, and bones that barely simmered until the surface cleared.","skill":"vocabulary"},{"question":"Why mention that the guests waited longer?","options":["To show familiar taste was chosen over speed","To describe only the shape of the clay pot","To hint that the four pots were stolen","To blame the guests for coming early"],"correctAnswer":"To show familiar taste was chosen over speed","explanation":"The wait shows she accepted delay so the broth would stay the one the family knew.","supportingSentence":"Guests waited longer.","skill":"intent"}],"wordCount":98,"questionCount":5}$q34998$::jsonb,
  'a0788b762194fb927f91fd7c00ff73824ecb860969a19de199f2ea5155c88ff4',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '211d9ca1-74d1-4773-a93e-83319559652b'::uuid,
  'reading',
  'C1',
  'text',
  $q4982${"topic":"technology","wordCount":101,"questionCount":5}$q4982$::jsonb,
  $q49252${"mode":"reading","level":"C1","format":"text","topic":"Technology","title":"An Alert the Night Learned to Ignore","story":"The building sensor sent an alert whenever the cleaners ran hot water, so the night manager learned to swipe the message away. The system was not broken. Its threshold had been set for an empty pipe, and ordinary use now crossed that line. When a real drip started behind a cupboard, the same alert appeared and was dismissed with the others. By morning the plaster had softened. A technician raised the threshold, added a second warning if the alert lasted, and required a named person to close it. An alarm that cannot separate routine from harm trains people to ignore both.","dialogue":[],"vocabulary":[{"word":"alert","definition":"A warning message from the sensor"},{"word":"threshold","definition":"The level at which the sensor decides to warn"},{"word":"dismissed","definition":"Closed and set aside without action"},{"word":"technician","definition":"A specialist who adjusts the system"},{"word":"routine","definition":"Ordinary activity that happens regularly"},{"word":"plaster","definition":"The wall surface that softened in the leak"}],"quiz":[{"question":"What everyday event was enough to trigger a warning?","options":["A power cut across the building","Plaster falling before dawn","The night manager leaving early","Cleaners running hot water"],"correctAnswer":"Cleaners running hot water","explanation":"The sensor sent an alert whenever the cleaners ran hot water.","supportingSentence":"The building sensor sent an alert whenever the cleaners ran hot water, so the night manager learned to swipe the message away.","skill":"detail"},{"question":"Who had to close an alert under the revised rule?","options":["A named person","The sensor, after one beep","A visitor standing in the lobby","Any cleaner on the night shift"],"correctAnswer":"A named person","explanation":"The technician required a named person to close an alert.","supportingSentence":"A technician raised the threshold, added a second warning if the alert lasted, and required a named person to close it.","skill":"detail"},{"question":"What habit let the real drip go unanswered?","options":["Asking the technician to unplug the sensor","Moving the cupboard away from the wall","Treating that alert as something to swipe away","Banning hot water after midnight"],"correctAnswer":"Treating that alert as something to swipe away","explanation":"The manager had learned to swipe the same alert, so the real drip was dismissed with the rest.","supportingSentence":"When a real drip started behind a cupboard, the same alert appeared and was dismissed with the others.","skill":"inference"},{"question":"What does threshold name in this sensor?","options":["A cloth kept beside the cupboard","The night manager's job title","The set level that makes it send a warning","The morning note about the wall"],"correctAnswer":"The set level that makes it send a warning","explanation":"The threshold is the level set for an empty pipe, and crossing it sends the alert.","supportingSentence":"Its threshold had been set for an empty pipe, and ordinary use now crossed that line.","skill":"vocabulary"},{"question":"What is the closing generalisation doing?","options":["Telling readers to swipe away every future message","Advertising one make of wall sensor","Blaming the cleaners for starting the drip","Casting the episode as a design that taught people to ignore warnings"],"correctAnswer":"Casting the episode as a design that taught people to ignore warnings","explanation":"The last sentence turns the incident into a lesson about alarms that mix routine with harm.","supportingSentence":"An alarm that cannot separate routine from harm trains people to ignore both.","skill":"intent"}],"wordCount":101,"questionCount":5}$q49252$::jsonb,
  '211d9ca174d18773993e83319559652be72d2c0387505b7790a7c8593273500f',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '41acaad2-af9e-4170-ac3e-95501710df81'::uuid,
  'reading',
  'C1',
  'text',
  $q4628${"topic":"science","wordCount":101,"questionCount":5}$q4628$::jsonb,
  $q52781${"mode":"reading","level":"C1","format":"text","topic":"Science","title":"A Bottle Marked as Void","story":"The field team reached the mudflat as the tide returned, though the protocol required water that had rested on the sediment through the low. Priya filled a bottle anyway and labelled it with the minute plus a note that the condition had not been met. A colleague wanted the note removed so the folder would look complete. Priya refused. A tidy file would let a later paper treat a late sample as a true match. They entered the bottle as void and planned a return at the next suitable low. Missing data, she said, was more honest than a tidy lie.","dialogue":[],"vocabulary":[{"word":"protocol","definition":"The rules for how the sample must be taken"},{"word":"sediment","definition":"Matter settled on the bottom of the flat"},{"word":"labelled","definition":"Marked with information about the sample"},{"word":"colleague","definition":"A person working on the same team"},{"word":"void","definition":"Recorded as not usable"},{"word":"honest","definition":"Truthful, even when the record looks incomplete"}],"quiz":[{"question":"What extra remark went on the bottle's label?","options":["A note that the required condition had not been met","A signature approving the sample","A claim that the tide stayed out all day","A statement that the bottle matched the others"],"correctAnswer":"A note that the required condition had not been met","explanation":"She labelled the bottle with a note that the condition had not been met.","supportingSentence":"Priya filled a bottle anyway and labelled it with the minute plus a note that the condition had not been met.","skill":"detail"},{"question":"How did the team record that bottle?","options":["As a figure ready for the paper","As void, with a return planned for a proper low","As the best sample of the week","As a copy of an older bottle"],"correctAnswer":"As void, with a return planned for a proper low","explanation":"They entered the bottle as void and planned a return at the next suitable low.","supportingSentence":"They entered the bottle as void and planned a return at the next suitable low.","skill":"detail"},{"question":"What future mistake is Priya trying to prevent?","options":["A paper treating a late sample as if it matched the rules","The tide failing to return the next week","The folder deleting the whole study","The closure of the mudflat to every team"],"correctAnswer":"A paper treating a late sample as if it matched the rules","explanation":"She fears a later paper would lean on a late sample as though it were a true match.","supportingSentence":"A tidy file would let a later paper treat a late sample as a true match.","skill":"inference"},{"question":"What does protocol refer to in this fieldwork?","options":["The name of the shared folder","A boat used to cross the flat","The minute written on the label","The rules for how a sample must be taken"],"correctAnswer":"The rules for how a sample must be taken","explanation":"The protocol is the required way of taking the sample, which this bottle missed.","supportingSentence":"The field team reached the mudflat as the tide returned, though the protocol required water that had rested on the sediment through the low.","skill":"vocabulary"},{"question":"Why bring in a colleague who wants the note deleted?","options":["To show the pressure to make the set look complete","To prove the tide never reached the flat","To reveal that the colleague took the sample alone","To explain how glass bottles are made"],"correctAnswer":"To show the pressure to make the set look complete","explanation":"The colleague supplies the temptation to hide the failed condition for the sake of a complete-looking folder.","supportingSentence":"A colleague wanted the note removed so the folder would look complete.","skill":"intent"}],"wordCount":101,"questionCount":5}$q52781$::jsonb,
  '41acaad2af9ee170cc3e95501710df811f0d2e2a490fa8dffddef68d21a3cac5',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'f408b46a-ed91-403e-a097-dd90de7ddbb5'::uuid,
  'reading',
  'C1',
  'text',
  $q5486${"topic":"economy_finance","wordCount":108,"questionCount":5}$q5486$::jsonb,
  $q75364${"mode":"reading","level":"C1","format":"text","topic":"Economy / Finance","title":"Half a Deposit, Reserve Untouched","story":"The landlord wanted the full winter deposit before the heating contract could start. The cafe reserve could cover it, but that fund was for a broken oven or a quiet month, not for a cost the season would bring anyway. Jonah offered half now and half when the first cold orders arrived, and he showed weekly takings rather than a bare promise. The landlord agreed, provided a missed second payment restored the full demand at once. Jonah accepted because the reserve stayed ready for a shock. Spending emergency money on a predictable bill would have left the cafe confident on paper and fragile on the week something failed.","dialogue":[],"vocabulary":[{"word":"deposit","definition":"Money paid up front before a service starts"},{"word":"reserve","definition":"Money kept back for an unexpected blow"},{"word":"takings","definition":"Money received from customers"},{"word":"shock","definition":"A sudden problem the cafe did not schedule"},{"word":"predictable","definition":"Expected, because it belongs to the season"},{"word":"fragile","definition":"Easy to damage when something goes wrong"}],"quiz":[{"question":"What payment pattern did Jonah suggest?","options":["Nothing until the spring menu changed","The price of a replacement oven","Half at once and half when cold orders came","The entire deposit before any heating began"],"correctAnswer":"Half at once and half when cold orders came","explanation":"Jonah offered half now and half when the first cold orders arrived.","supportingSentence":"Jonah offered half now and half when the first cold orders arrived, and he showed weekly takings rather than a bare promise.","skill":"detail"},{"question":"What did a missed second payment trigger?","options":["Purchase of a new oven from the reserve","Cancellation of every winter booking","Closure of the cafe on that day","An immediate return of the demand for the full sum"],"correctAnswer":"An immediate return of the demand for the full sum","explanation":"A missed second payment restored the full demand at once.","supportingSentence":"The landlord agreed, provided a missed second payment restored the full demand at once.","skill":"detail"},{"question":"Why leave the reserve out of this bill?","options":["A known seasonal cost would spend money saved for a shock","The weekly takings were too large to show","The landlord had already cancelled the deposit","The heating contract had already ended"],"correctAnswer":"A known seasonal cost would spend money saved for a shock","explanation":"The reserve is for a broken oven or a quiet month, not for a bill the season was always going to bring.","supportingSentence":"The cafe reserve could cover it, but that fund was for a broken oven or a quiet month, not for a cost the season would bring anyway.","skill":"inference"},{"question":"What does reserve mean in these accounts?","options":["The list of cold-weather dishes","Money held back for an unexpected blow","A discount on the second half","The landlord's heating contract"],"correctAnswer":"Money held back for an unexpected blow","explanation":"The reserve is the fund kept for a shock, not for an ordinary seasonal bill.","supportingSentence":"The cafe reserve could cover it, but that fund was for a broken oven or a quiet month, not for a cost the season would bring anyway.","skill":"vocabulary"},{"question":"What point does the final contrast make?","options":["The landlord deserves praise for charging more","The cafe's best drinks ought to be listed","The plan should be judged by what remains when something fails","The oven broke on the afternoon of the deal"],"correctAnswer":"The plan should be judged by what remains when something fails","explanation":"The contrast weighs paper confidence against how fragile the cafe would be in a real failure.","supportingSentence":"Spending emergency money on a predictable bill would have left the cafe confident on paper and fragile on the week something failed.","skill":"intent"}],"wordCount":108,"questionCount":5}$q75364$::jsonb,
  'f408b46aed91703ef097dd90de7ddbb549ac9dea72b8b98ff979ecf482040b9b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '2a108601-c62a-406a-a070-cb058be1ce5f'::uuid,
  'reading',
  'C1',
  'text',
  $q5485${"topic":"economy_finance","wordCount":107,"questionCount":5}$q5485$::jsonb,
  $q72493${"mode":"reading","level":"C1","format":"text","topic":"Economy / Finance","title":"Three Months Instead of an Average","story":"The draft budget used last year's average attendance to predict ticket income. Hana replaced that average with three figures: a poor month, a typical month, and a festival month. An average, she argued, hid the poor month inside the festival and made February look safer than the cash would be. The treasurer wanted one number, because a single line was easier to defend at the public meeting. Hana kept the three and added a rule that spending plans must survive the poor month without borrowing. The festival windfall could repair the roof afterwards. It could not be spent early as if the weak month were already saved.","dialogue":[],"vocabulary":[{"word":"attendance","definition":"The number of people who come"},{"word":"predict","definition":"To say what income is likely to be"},{"word":"average","definition":"A single figure that blends different months"},{"word":"treasurer","definition":"The person who looks after the money"},{"word":"borrowing","definition":"Taking money that must be paid back"},{"word":"windfall","definition":"Extra income that arrives in a strong month"}],"quiz":[{"question":"Which figures replaced the single average?","options":["Only the festival, counted as the whole year","A loan large enough to cover February","Last year's average copied out three times","A poor month, a typical month, and a festival month"],"correctAnswer":"A poor month, a typical month, and a festival month","explanation":"Hana replaced the average with a poor month, a typical month, and a festival month.","supportingSentence":"Hana replaced that average with three figures: a poor month, a typical month, and a festival month.","skill":"detail"},{"question":"What test did new spending plans have to pass?","options":["They had to spend the festival money in advance","They had to match last year's average exactly","They had to survive the poor month without borrowing","They had to be the treasurer's single favourite line"],"correctAnswer":"They had to survive the poor month without borrowing","explanation":"Spending plans had to survive the poor month without borrowing.","supportingSentence":"Hana kept the three and added a rule that spending plans must survive the poor month without borrowing.","skill":"detail"},{"question":"Why can one average mislead this hall?","options":["It forces the building to close in February","A busy festival can hide how little a poor month leaves","It forbids any talk of the roof","It doubles the ticket price of every event"],"correctAnswer":"A busy festival can hide how little a poor month leaves","explanation":"The average hides the poor month inside the festival and makes February look safer than the cash.","supportingSentence":"An average, she argued, hid the poor month inside the festival and made February look safer than the cash would be.","skill":"inference"},{"question":"What does windfall mean beside the festival?","options":["Extra income that comes in a strong month","A tax the public meeting must pay","Tickets that go missing in February","A loan signed in the weak month"],"correctAnswer":"Extra income that comes in a strong month","explanation":"The festival windfall is extra money from the strong month, available after that month rather than before it.","supportingSentence":"The festival windfall could repair the roof afterwards.","skill":"vocabulary"},{"question":"Why note that a single line was easier in public?","options":["To suggest Hana hid the three figures","To describe how the tickets are printed","To prove the public meeting was cancelled","To show the pressure for a simpler figure at the meeting"],"correctAnswer":"To show the pressure for a simpler figure at the meeting","explanation":"The treasurer's wish shows the social pressure Hana resists by keeping three figures.","supportingSentence":"The treasurer wanted one number, because a single line was easier to defend at the public meeting.","skill":"intent"}],"wordCount":107,"questionCount":5}$q72493$::jsonb,
  '2a108601c62a106a1070cb058be1ce5f9234e8b7b436e09f61e5c5d468402192',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1e007f89-3ab3-4d68-ae60-3063369339c5'::uuid,
  'reading',
  'C1',
  'text',
  $q4703${"topic":"mystery","wordCount":109,"questionCount":5}$q4703$::jsonb,
  $q45153${"mode":"reading","level":"C1","format":"text","topic":"Mystery","title":"Prints That Stopped at the Cupboard","story":"The reading room closed clean, yet by dawn mud marked the service stairs and a folio was gone from its shelf. The night guard insisted the main door had stayed shut. Leah believed that, then studied the prints rather than the lock. They were small, dry at the edges, and they ended at the cupboard where cloths were kept. One cloth was missing, and the folio lay under a trolley, wrapped as if someone had started to wipe the shelf and been startled. Nothing had left the building. Hurry, not a plan to steal, had arranged the scene, so the guard's account and the gap could both be true.","dialogue":[],"vocabulary":[{"word":"folio","definition":"A volume that had stood on the shelf"},{"word":"prints","definition":"Marks left by shoes"},{"word":"cupboard","definition":"A cabinet where cleaning cloths were stored"},{"word":"trolley","definition":"A wheeled cart in the reading room"},{"word":"startled","definition":"Suddenly frightened into stopping"},{"word":"guard","definition":"The person on duty at the door overnight"}],"quiz":[{"question":"Where did the muddy prints come to an end?","options":["At the cupboard where cloths were kept","On the shelf the folio had left","At the main door the guard watched","In the street beyond the hall"],"correctAnswer":"At the cupboard where cloths were kept","explanation":"The prints ended at the cupboard where cloths were kept.","supportingSentence":"They were small, dry at the edges, and they ended at the cupboard where cloths were kept.","skill":"detail"},{"question":"Where did the missing volume turn up?","options":["In the guard's coat pocket","Under a trolley, wrapped as if for wiping","Inside a case that was still locked","On the steps outside the main door"],"correctAnswer":"Under a trolley, wrapped as if for wiping","explanation":"The folio lay under a trolley, wrapped as if someone had started to wipe the shelf.","supportingSentence":"One cloth was missing, and the folio lay under a trolley, wrapped as if someone had started to wipe the shelf and been startled.","skill":"detail"},{"question":"How can the guard be right while the shelf was empty at dawn?","options":["The book never left, so the main door need not have opened","The building has no service stairs","The guard carried the volume home","The prints had been painted on the stairs"],"correctAnswer":"The book never left, so the main door need not have opened","explanation":"Nothing left the building, so a shut main door can sit beside an empty shelf.","supportingSentence":"Nothing had left the building.","skill":"inference"},{"question":"What does folio refer to in this room?","options":["The guard's written night report","A cloth used on the stairs","The lock on the main door","The volume that had stood on the shelf"],"correctAnswer":"The volume that had stood on the shelf","explanation":"The folio is the volume that was gone from its shelf and later found under the trolley.","supportingSentence":"The reading room closed clean, yet by dawn mud marked the service stairs and a folio was gone from its shelf.","skill":"vocabulary"},{"question":"Why emphasise that the prints stopped at the cupboard?","options":["To point toward interrupted cleaning rather than a theft","To show the mud came from the volume itself","To prove the guard left the main door open","To suggest the stairs had just been painted"],"correctAnswer":"To point toward interrupted cleaning rather than a theft","explanation":"Ending the prints at the cloth cupboard steers the reader away from a thief heading out.","supportingSentence":"They were small, dry at the edges, and they ended at the cupboard where cloths were kept.","skill":"intent"}],"wordCount":109,"questionCount":5}$q45153$::jsonb,
  '1e007f893ab32d688e603063369339c50c58e9be5d5d4021e1c6cfce6d6d9d32',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '6dd85cef-c9aa-451a-ac5b-ed7ac10aeeb5'::uuid,
  'reading',
  'C1',
  'text',
  $q4702${"topic":"mystery","wordCount":108,"questionCount":5}$q4702$::jsonb,
  $q23233${"mode":"reading","level":"C1","format":"text","topic":"Mystery","title":"A Name That Was Never Entered","story":"The inn ledger listed every guest except the woman in the blue coat, though the cook remembered her soup and the stable hand remembered her horse. That night's page was full, with no scraped erasure and no crowded extra line. Cora compared the ink. Every other name had been written with the house pen, which skipped on the downstroke. The woman's name had not been written and rubbed away. It had never been entered. Someone had taken cash and kept her off the page, while the staff who served her had no reason to invent her. The puzzle was not a vanished guest. It was a deliberate omission.","dialogue":[],"vocabulary":[{"word":"ledger","definition":"The book in which guests are listed"},{"word":"erasure","definition":"A rubbed-out mark where writing was removed"},{"word":"downstroke","definition":"The downward movement of the pen"},{"word":"entered","definition":"Written into the record"},{"word":"omission","definition":"Something left out on purpose"},{"word":"deliberate","definition":"Done on purpose, not by accident"}],"quiz":[{"question":"Who recalled the animal she left at the inn?","options":["The stable hand","A guest already written on the page","The pen that skipped","The cook who remembered soup"],"correctAnswer":"The stable hand","explanation":"The stable hand remembered her horse.","supportingSentence":"The inn ledger listed every guest except the woman in the blue coat, though the cook remembered her soup and the stable hand remembered her horse.","skill":"detail"},{"question":"Which habit of the house pen did Cora use?","options":["It wrote only in blue ink","It belonged to the woman in the coat","It erased a line without a mark","It skipped on the downstroke"],"correctAnswer":"It skipped on the downstroke","explanation":"The house pen skipped on the downstroke.","supportingSentence":"Every other name had been written with the house pen, which skipped on the downstroke.","skill":"detail"},{"question":"What does a full page with no scrape imply?","options":["The cook invented the bowl of soup","She never came to the inn at all","Her name was left out from the start, not removed later","The stable hand stole the ledger"],"correctAnswer":"Her name was left out from the start, not removed later","explanation":"No erasure and ink that was never applied mean the name was never written.","supportingSentence":"That night's page was full, with no scraped erasure and no crowded extra line.","skill":"inference"},{"question":"What does omission name in the last line?","options":["A horse kept in the stable overnight","Ink that skips on a downstroke","A purposeful leaving-out from the record","A line crowded with extra names"],"correctAnswer":"A purposeful leaving-out from the record","explanation":"An omission here is the deliberate act of leaving her name off the page.","supportingSentence":"It was a deliberate omission.","skill":"vocabulary"},{"question":"Why point out the lack of a scraped erasure?","options":["To rule out a name that was written and later removed","To prove the cook could not write","To show the inn had no guests that night","To describe the colour of her coat"],"correctAnswer":"To rule out a name that was written and later removed","explanation":"The missing scrape closes the explanation that someone rubbed a written name away.","supportingSentence":"That night's page was full, with no scraped erasure and no crowded extra line.","skill":"intent"}],"wordCount":108,"questionCount":5}$q23233$::jsonb,
  '6dd85cefc9aaa51a8c5bed7ac10aeeb5ded53ee3a12e4361541f3fed10fd35c0',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'b68b6775-f42b-4f90-a9b4-5b291b9c3417'::uuid,
  'reading',
  'C1',
  'text',
  $q4880${"topic":"adventure","wordCount":109,"questionCount":5}$q4880$::jsonb,
  $q37731${"mode":"reading","level":"C1","format":"text","topic":"Adventure","title":"Turning the Party below the Ridge","story":"The party reached the last scree below the ridge as the wind began to throw ice. The map promised an hour to the hut, and the stronger walkers wanted to push on before darkness caught them on the slope. Noor watched the person at the rear rather than the skyline. His steps had shortened and his hands were slow on the poles. The hour assumed a pace the group no longer had. She turned them while they could still place their feet with care, and they regained the trees before the squall. The hut could wait until morning. A tired mistake on that slope would not have been forgiven.","dialogue":[],"vocabulary":[{"word":"scree","definition":"A slope of loose stones"},{"word":"ridge","definition":"The high crest they had not yet reached"},{"word":"poles","definition":"Sticks used to steady a walker"},{"word":"pace","definition":"The speed at which the group was moving"},{"word":"squall","definition":"A sudden violent burst of wind and weather"},{"word":"slope","definition":"The inclined ground under their feet"}],"quiz":[{"question":"Whose movement told Noor more than the skyline?","options":["The hut keeper on the ridge","The person at the rear","A guide waiting among the trees","Only the strongest walker"],"correctAnswer":"The person at the rear","explanation":"Noor watched the person at the rear rather than the skyline.","supportingSentence":"Noor watched the person at the rear rather than the skyline.","skill":"detail"},{"question":"What did the stronger walkers want to do?","options":["Send Noor down the ridge alone","Camp on the stones until dawn","Push on before darkness caught them on the slope","Leave the map with the last walker"],"correctAnswer":"Push on before darkness caught them on the slope","explanation":"They wanted to push on before darkness caught them on the slope.","supportingSentence":"The map promised an hour to the hut, and the stronger walkers wanted to push on before darkness caught them on the slope.","skill":"detail"},{"question":"Why does the map's hour stop being a safe guide?","options":["It shows a hut that was never built","It was drawn for travel by boat","It forbids anyone to turn around","It assumes a speed the tired group has already lost"],"correctAnswer":"It assumes a speed the tired group has already lost","explanation":"The hour assumed a pace the group no longer had, so the map's timing no longer fits.","supportingSentence":"The hour assumed a pace the group no longer had.","skill":"inference"},{"question":"What does squall mean as they turn downhill?","options":["A sudden violent burst of weather","A stick used on loose stone","The band of trees below","The hut marked on the map"],"correctAnswer":"A sudden violent burst of weather","explanation":"A squall is a sudden violent burst of weather, and they reach the trees before it arrives.","supportingSentence":"She turned them while they could still place their feet with care, and they regained the trees before the squall.","skill":"vocabulary"},{"question":"Why mention the wish to beat the darkness?","options":["To prove the hut had already collapsed","To argue that the party should divide","To set up the hurry she rejects once the rear walker slows","To blame the rear walker for carrying no map"],"correctAnswer":"To set up the hurry she rejects once the rear walker slows","explanation":"The wish establishes the pressure that the slowed rear walker then makes unsafe.","supportingSentence":"The map promised an hour to the hut, and the stronger walkers wanted to push on before darkness caught them on the slope.","skill":"intent"}],"wordCount":109,"questionCount":5}$q37731$::jsonb,
  'b68b6775f42baf90b9b45b291b9c341701aed521d7e0322e7108629191e6712b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '7ae99258-c90a-408e-adf0-788e00970ae8'::uuid,
  'reading',
  'C1',
  'text',
  $q4874${"topic":"adventure","wordCount":103,"questionCount":5}$q4874$::jsonb,
  $q5027${"mode":"reading","level":"C1","format":"text","topic":"Adventure","title":"The Chart Did Not Mention the Rope","story":"The boathouse chart showed clear water between the rock and the landing chain. When Idris rowed out, the gap was real, but the guiding rope fell short of his hand. His cousin offered to jump for the chain. Idris refused, because a leap from a moving boat into cold water would become a rescue. He beached the boat and walked the shore with a longer line. The chart had not lied about the gap. It said nothing about a rope that had frayed and been retied too short. Trusting a drawing for a fact it never claimed is how simple crossings turn risky.","dialogue":[],"vocabulary":[{"word":"chart","definition":"A drawing of the water and the landing"},{"word":"gap","definition":"The stretch of clear water"},{"word":"leap","definition":"A jump off the boat"},{"word":"beached","definition":"Brought the boat onto the shore"},{"word":"frayed","definition":"Worn until the fibres gave way"},{"word":"retied","definition":"Tied again after it had worn"}],"quiz":[{"question":"What fell short of his hand in the gap?","options":["His cousin's spare oar","The guiding rope","The chart on the boathouse wall","A bridge across the whole bay"],"correctAnswer":"The guiding rope","explanation":"The guiding rope fell short of his hand.","supportingSentence":"When Idris rowed out, the gap was real, but the guiding rope fell short of his hand.","skill":"detail"},{"question":"What risky move did the cousin offer?","options":["To cut the rope and leave it","To redraw the chart that evening","To jump from the boat toward the chain","To swim back for a meal"],"correctAnswer":"To jump from the boat toward the chain","explanation":"The cousin offered to jump for the chain.","supportingSentence":"His cousin offered to jump for the chain.","skill":"detail"},{"question":"Why is the chart incomplete rather than untrue?","options":["The landing chain had been carried far inland","The water was warmer than any drawing showed","The sheet was only a child's sketch","The water gap was real, but the rope length was never on it"],"correctAnswer":"The water gap was real, but the rope length was never on it","explanation":"The gap matched the chart, and the chart never described the shortened rope.","supportingSentence":"The chart had not lied about the gap.","skill":"inference"},{"question":"What does frayed reveal about the rope?","options":["Its fibres had worn away","It reached across the whole bay","It belonged to the cousin","It was copied in ink on the chart"],"correctAnswer":"Its fibres had worn away","explanation":"Frayed means the rope's fibres had worn, which is why it was retied too short.","supportingSentence":"It said nothing about a rope that had frayed and been retied too short.","skill":"vocabulary"},{"question":"What is the point of saying the chart told the truth about the gap?","options":["To explain how wooden boats are built","To put the mistake on an assumption the drawing never made","To admit the gap had closed since morning","To praise the cousin for jumping"],"correctAnswer":"To put the mistake on an assumption the drawing never made","explanation":"Saying the chart did not lie moves the fault onto trusting it for a fact it never claimed.","supportingSentence":"The chart had not lied about the gap.","skill":"intent"}],"wordCount":103,"questionCount":5}$q5027$::jsonb,
  '7ae99258c90a908eedf0788e00970ae81fb09c841e3435e1bc03d3ccc9621e69',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'c238f19d-43df-4b34-a33c-374d97ce6291'::uuid,
  'reading',
  'C1',
  'text',
  $q4663${"topic":"fantasy","wordCount":108,"questionCount":5}$q4663$::jsonb,
  $q22919${"mode":"reading","level":"C1","format":"text","topic":"Fantasy","title":"What the Orchard Gate Kept","story":"The gate in the orchard wall opened only for a memory the traveller did not want to keep. Sera offered her name, then the name of her city, and the stones stayed shut. A warden explained that the gate was not testing identity. It asked whether she could leave a recollection behind, because anything carried through would take root on the far side, where strangers might walk into it. She gave up the memory of a kitchen on a winter morning, small and wholly hers. The gate opened. Beyond it the grass was ordinary, and the kitchen was gone even from thought. Passage, she understood, was a trade.","dialogue":[],"vocabulary":[{"word":"identity","definition":"Who a person is, such as a name or city"},{"word":"recollection","definition":"A memory that can be left behind"},{"word":"strangers","definition":"People who do not know her"},{"word":"warden","definition":"The keeper who explains the gate"},{"word":"ordinary","definition":"Plain and everyday, without magic in it"},{"word":"passage","definition":"The act of going through"}],"quiz":[{"question":"What did Sera try before naming her city?","options":["A winter kitchen","A loose stone from the wall","The warden's childhood","Her own name"],"correctAnswer":"Her own name","explanation":"She offered her name, then the name of her city.","supportingSentence":"Sera offered her name, then the name of her city, and the stones stayed shut.","skill":"detail"},{"question":"Which memory finally opened the gate?","options":["A kitchen on a winter morning","The warden's warning","The path back through the trees","The name of her city"],"correctAnswer":"A kitchen on a winter morning","explanation":"She gave up the memory of a kitchen on a winter morning, and the gate opened.","supportingSentence":"She gave up the memory of a kitchen on a winter morning, small and wholly hers.","skill":"detail"},{"question":"Why do a name and a city fail at this gate?","options":["The stones open only after midnight","The orchard has no far side","It wants a memory she will lose, not proof of who she is","The warden must walk through first"],"correctAnswer":"It wants a memory she will lose, not proof of who she is","explanation":"The warden says the gate is not testing identity, but whether she can leave a memory behind.","supportingSentence":"A warden explained that the gate was not testing identity.","skill":"inference"},{"question":"What does recollection mean in the warden's explanation?","options":["A memory she is able to leave behind","A stone loose in the wall","A stranger walking in the grass","The public name of a city"],"correctAnswer":"A memory she is able to leave behind","explanation":"A recollection is the memory the gate asks her to leave behind.","supportingSentence":"It asked whether she could leave a recollection behind, because anything carried through would take root on the far side, where strangers might walk into it.","skill":"vocabulary"},{"question":"Why show that the kitchen is gone even from thought?","options":["To suggest the kitchen was never real","To describe the grass as loud and bright","To show the warden followed her","To make the cost of crossing concrete"],"correctAnswer":"To make the cost of crossing concrete","explanation":"Losing the kitchen even in thought shows that passage takes something she cannot keep.","supportingSentence":"Beyond it the grass was ordinary, and the kitchen was gone even from thought.","skill":"intent"}],"wordCount":108,"questionCount":5}$q22919$::jsonb,
  'c238f19d43dfbb34c33c374d97ce62916e1cf219b7b0addc6f49c5569b3beadb',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1e7a2aa0-b0cd-484a-a7e4-9a62a8bb8825'::uuid,
  'reading',
  'C1',
  'text',
  $q4662${"topic":"fantasy","wordCount":107,"questionCount":5}$q4662$::jsonb,
  $q27995${"mode":"reading","level":"C1","format":"text","topic":"Fantasy","title":"A Bridge Made of Owed Attention","story":"The bridge over the dry canal appeared only for a debt of attention. Pell had looked away when a neighbour's roof failed, and at dusk the planks were under his feet, gone again by morning. Each crossing asked for an hour on a task he had postponed: stacking tiles, reading to a child at the school gate, then facing minutes of a meeting he had skipped. The bridge did not shout. It existed only while the debt was being paid. When the tasks ended, the canal was ordinary dust. Pell could still cross elsewhere. He could no longer pretend he had not known where he was needed.","dialogue":[],"vocabulary":[{"word":"debt","definition":"Something owed, here a duty of attention"},{"word":"attention","definition":"Notice and care given to other people"},{"word":"postponed","definition":"Put off until a later time"},{"word":"planks","definition":"The boards that formed the bridge"},{"word":"dusk","definition":"The time of day when daylight is fading"},{"word":"pretend","definition":"Act as if something were true when it is not"}],"quiz":[{"question":"At which time of day did Pell find the planks?","options":["At dusk","Only in the morning","During a school parade","At noon"],"correctAnswer":"At dusk","explanation":"At dusk the planks were under his feet.","supportingSentence":"Pell had looked away when a neighbour's roof failed, and at dusk the planks were under his feet, gone again by morning.","skill":"detail"},{"question":"Which chore came first among the crossings?","options":["Painting the dry canal","Building a second bridge of stone","Closing the school for the season","Stacking the neighbour's tiles"],"correctAnswer":"Stacking the neighbour's tiles","explanation":"The first task named is stacking tiles.","supportingSentence":"Each crossing asked for an hour on a task he had postponed: stacking tiles, reading to a child at the school gate, then facing minutes of a meeting he had skipped.","skill":"detail"},{"question":"What does ordinary dust after the tasks reveal?","options":["The oddity was the duty, not the landscape","The canal has filled with water at last","The neighbour's roof was never damaged","The child has left the town for good"],"correctAnswer":"The oddity was the duty, not the landscape","explanation":"Once the debt is paid the canal is ordinary dust, so the strange part was the obligation.","supportingSentence":"When the tasks ended, the canal was ordinary dust.","skill":"inference"},{"question":"What does postponed say about those tasks?","options":["They were paid for in coins","The whole town had forgotten them","They had been put off until later","They were carved into the canal"],"correctAnswer":"They had been put off until later","explanation":"Postponed means the tasks had been put off, which is why the bridge now demands them.","supportingSentence":"Each crossing asked for an hour on a task he had postponed: stacking tiles, reading to a child at the school gate, then facing minutes of a meeting he had skipped.","skill":"vocabulary"},{"question":"Why say the bridge did not shout?","options":["To present the demand as quiet rather than as a loud penalty","To argue that Pell stole money","To explain how the boards were nailed","To show the town beats drums on the planks"],"correctAnswer":"To present the demand as quiet rather than as a loud penalty","explanation":"Denying a shout frames the bridge as a quiet path that exists only while the debt is paid.","supportingSentence":"The bridge did not shout.","skill":"intent"}],"wordCount":107,"questionCount":5}$q27995$::jsonb,
  '1e7a2aa0b0cdb84a17e49a62a8bb88257703795235733d422ef9421d1ee9d008',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'ac2d9db8-b601-4c13-aab2-d818db01c179'::uuid,
  'reading',
  'C1',
  'text',
  $q4881${"topic":"daily life","wordCount":105,"questionCount":5}$q4881$::jsonb,
  $q22097${"mode":"reading","level":"C1","format":"text","topic":"Daily Life","title":"A Rota That Left the Weekend Free","story":"Four flats shared one washing line, and the old habit gave it to whoever arrived first. After two quarrels about sheets left wet overnight, Amina posted a rota that gave each flat one weekday and left the weekend blank. Neighbours called a laundry timetable absurd. Amina was not trying to police spare hours. She was ending a race that favoured anyone who worked at home and could hang clothes at noon. The weekend stayed open because guests and emergencies happen. A rule for every hour would have been resented, rightly. The narrower rule lasted because it corrected the unfair part and left the rest alone.","dialogue":[],"vocabulary":[{"word":"quarrels","definition":"Angry disagreements"},{"word":"rota","definition":"A written turn-taking schedule"},{"word":"favoured","definition":"Gave an advantage to"},{"word":"emergencies","definition":"Urgent unexpected needs"},{"word":"resented","definition":"Felt with bitterness"},{"word":"narrower","definition":"Covering less, on purpose"}],"quiz":[{"question":"What share of the week did each flat receive?","options":["The entire weekend","Two nights for wet sheets","One weekday","Every noon hour"],"correctAnswer":"One weekday","explanation":"The rota gave each flat one weekday.","supportingSentence":"After two quarrels about sheets left wet overnight, Amina posted a rota that gave each flat one weekday and left the weekend blank.","skill":"detail"},{"question":"Why was the weekend left blank?","options":["Amina worked only on Saturdays","The line was removed every Friday","Guests and emergencies still happen","Wet sheets were banned after noon"],"correctAnswer":"Guests and emergencies still happen","explanation":"The weekend stayed open because guests and emergencies happen.","supportingSentence":"The weekend stayed open because guests and emergencies happen.","skill":"detail"},{"question":"Who had the advantage before the rota?","options":["Guests who arrived only on Mondays","A clerk who rented the line out","Neighbours who never did laundry","People at home by day, who could take the line at noon"],"correctAnswer":"People at home by day, who could take the line at noon","explanation":"The old race favoured anyone who worked at home and could hang clothes at noon.","supportingSentence":"She was ending a race that favoured anyone who worked at home and could hang clothes at noon.","skill":"inference"},{"question":"What does resented mean for a rule covering every hour?","options":["People would feel bitter about it","It would dry clothes faster","It would erase the weekend from the calendar","It would be printed in larger type"],"correctAnswer":"People would feel bitter about it","explanation":"Resented means people would bitterly dislike a rule that covered every hour.","supportingSentence":"A rule for every hour would have been resented, rightly.","skill":"vocabulary"},{"question":"Why add that resentment of a total rule would be proper?","options":["To name one soap for every flat","To justify stopping short of controlling every hour","To admit the rota was torn down at once","To blame the guests for both quarrels"],"correctAnswer":"To justify stopping short of controlling every hour","explanation":"Calling that resentment rightful defends the choice to leave some time unregulated.","supportingSentence":"A rule for every hour would have been resented, rightly.","skill":"intent"}],"wordCount":105,"questionCount":5}$q22097$::jsonb,
  'ac2d9db8b6017c131ab2d818db01c179a2b7ec62477986d3050fc9f9897e94ee',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '33b06633-29a3-490d-ac58-7b163d6df798'::uuid,
  'reading',
  'C1',
  'text',
  $q5379${"topic":"school_college","wordCount":108,"questionCount":5}$q5379$::jsonb,
  $q67392${"mode":"reading","level":"C1","format":"text","topic":"School / College","title":"Silence with a Purpose on the Form","story":"Final-year students could remain after the library doors closed, but only in the downstairs carrels, and only after signing for the sources they still needed. Harun signed, then spent the hour sorting notes instead of opening the archive boxes he had named. The librarian did not scold the mismatch. The next week she checked the after-hours list against materials requested from the desk. The privilege existed to finish research the daytime crowd made hard, not to supply a quiet room for work that could happen anywhere. Harun stayed, and he ordered the boxes first. The library would protect that silence only when the form was telling the truth.","dialogue":[],"vocabulary":[{"word":"carrels","definition":"Small individual study desks"},{"word":"archive","definition":"The stored collection he was meant to open"},{"word":"mismatch","definition":"A gap between what he signed for and what he did"},{"word":"privilege","definition":"Special permission to stay after closing"},{"word":"requested","definition":"Asked for from the desk"},{"word":"silence","definition":"The quiet of the closed library"}],"quiz":[{"question":"Which part of the library stayed available after the doors shut?","options":["Only the front steps","The whole building, including the roof store","The downstairs carrels","A classroom across the street"],"correctAnswer":"The downstairs carrels","explanation":"Students could remain only in the downstairs carrels.","supportingSentence":"Final-year students could remain after the library doors closed, but only in the downstairs carrels, and only after signing for the sources they still needed.","skill":"detail"},{"question":"What did staff begin to compare with the after-hours list?","options":["Novels read only for pleasure","Materials requested from the desk","How many notes each student typed","How long the daytime crowd stayed"],"correctAnswer":"Materials requested from the desk","explanation":"She checked the list against materials requested from the desk.","supportingSentence":"The next week she checked the after-hours list against materials requested from the desk.","skill":"detail"},{"question":"Why did sorting notes miss the point of staying late?","options":["That work did not need a closed library the way the archive did","The boxes contained no paper at all","The librarian wanted the building empty by noon","Notes were forbidden at every desk"],"correctAnswer":"That work did not need a closed library the way the archive did","explanation":"The late permission is for research the daytime crowd makes hard, not for work possible anywhere.","supportingSentence":"The privilege existed to finish research the daytime crowd made hard, not to supply a quiet room for work that could happen anywhere.","skill":"inference"},{"question":"What does privilege refer to here?","options":["A fine for a false signature","A box stored in the archive","The crowd that fills the daytime rooms","Permission to remain after closing"],"correctAnswer":"Permission to remain after closing","explanation":"The privilege is the special permission to stay after the doors closed.","supportingSentence":"The privilege existed to finish research the daytime crowd made hard, not to supply a quiet room for work that could happen anywhere.","skill":"vocabulary"},{"question":"Why show Harun ordering the boxes before he did anything else?","options":["His notes had been stolen from the desk","Late access had just been cancelled","He lined the visit up with the use the library would defend","Every title on the first sheet was false"],"correctAnswer":"He lined the visit up with the use the library would defend","explanation":"Ordering the boxes first shows he accepted the purpose for which the quiet would be protected.","supportingSentence":"Harun stayed, and he ordered the boxes first.","skill":"intent"}],"wordCount":108,"questionCount":5}$q67392$::jsonb,
  '33b0663329a3990d5c587b163d6df7987217711ca4e6f5753c371b9436edb866',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '829b37c3-98ec-4113-a9fc-c922ff926a2d'::uuid,
  'reading',
  'C1',
  'text',
  $q4560${"topic":"travel","wordCount":109,"questionCount":5}$q4560$::jsonb,
  $q44420${"mode":"reading","level":"C1","format":"text","topic":"Travel","title":"The Room beside the Kitchen","story":"The booking confirmed a room for Thursday, but a rail strike moved Lena to Friday, and her message never reached the pension. On arrival the owner had let the room to a couple in the hall, which was allowed once the night had started without the guest. He did not disguise that. He offered the small room beside the kitchen, usually kept for staff, at the same price, with breakfast as an apology. Lena accepted. Searching a strange town after dark, with the roads in disorder, was worse. A perfect match would have been better. An honest smaller room was better than a polite story that sent her outside.","dialogue":[],"vocabulary":[{"word":"booking","definition":"The reservation of the room"},{"word":"strike","definition":"A stoppage that kept the trains from running"},{"word":"pension","definition":"A small lodging house"},{"word":"disguise","definition":"To hide the real situation"},{"word":"apology","definition":"A gesture meant to express regret"},{"word":"disorder","definition":"A confused, disrupted state"}],"quiz":[{"question":"For which night had the room first been confirmed?","options":["Friday","Sunday","Saturday","Thursday"],"correctAnswer":"Thursday","explanation":"The booking confirmed a room for Thursday.","supportingSentence":"The booking confirmed a room for Thursday, but a rail strike moved Lena to Friday, and her message never reached the pension.","skill":"detail"},{"question":"What charge did the owner set for the room by the kitchen?","options":["The price already agreed for the booking","A sum paid directly to the couple","Nothing, because the trains had stopped","Twice the usual nightly rate"],"correctAnswer":"The price already agreed for the booking","explanation":"He offered the small room at the same price.","supportingSentence":"He offered the small room beside the kitchen, usually kept for staff, at the same price, with breakfast as an apology.","skill":"detail"},{"question":"Why does she take the room beside the kitchen?","options":["Breakfast was the only meal served all week","Searching an unfamiliar town after dark was the worse risk","The couple invited her to share the room they had taken","The strike ended while she stood in the hall"],"correctAnswer":"Searching an unfamiliar town after dark was the worse risk","explanation":"She accepts because searching a strange town after dark, with the roads in disorder, was worse.","supportingSentence":"Searching a strange town after dark, with the roads in disorder, was worse.","skill":"inference"},{"question":"What does pension mean in this stopover?","options":["The couple's home in another city","A retirement payment from the railway","The small lodging house where she had booked","A meal served only to the staff"],"correctAnswer":"The small lodging house where she had booked","explanation":"The pension is the lodging house that held her booking and later offered another room.","supportingSentence":"The booking confirmed a room for Thursday, but a rail strike moved Lena to Friday, and her message never reached the pension.","skill":"vocabulary"},{"question":"What judgment does the final contrast ask for?","options":["Lena should be blamed for arriving on Thursday","The full rail timetable should be copied out","The owner secretly hid the couple","An honest lesser room beats a story that would send her out"],"correctAnswer":"An honest lesser room beats a story that would send her out","explanation":"The close ranks a truthful smaller room above a polite fiction that would put her back outside.","supportingSentence":"An honest smaller room was better than a polite story that sent her outside.","skill":"intent"}],"wordCount":109,"questionCount":5}$q44420$::jsonb,
  '829b37c398ecd11319fcc922ff926a2d2f09fff5cb7bd9abe23ee7d1e55d172e',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '910357ae-00e5-4c09-a222-4db284e38306'::uuid,
  'reading',
  'C1',
  'text',
  $q4630${"topic":"hobbies","wordCount":101,"questionCount":5}$q4630$::jsonb,
  $q35969${"mode":"reading","level":"C1","format":"text","topic":"Hobbies","title":"The Glaze That Crawled","story":"Nils drew the bowl from the kiln and saw the glaze had crawled, leaving a ring of bare clay. Classmates told him to stop, because the flaw looked planned to anyone who had not seen the sketch. He mixed a second coat and fired again, knowing extra heat might slump the foot. Stopping at an attractive accident would teach his hands to prize luck over the form he intended. The second firing held. The ring vanished and the foot stayed true. He kept a photograph of the flaw as a record of when he nearly let a mistake set the standard.","dialogue":[],"vocabulary":[{"word":"kiln","definition":"The oven used to fire pottery"},{"word":"glaze","definition":"The glassy coating on the bowl"},{"word":"crawled","definition":"Drew back, leaving clay uncovered"},{"word":"slump","definition":"Lose its shape under too much heat"},{"word":"firing","definition":"A spell of baking in the kiln"},{"word":"photograph","definition":"A picture kept of the flawed bowl"}],"quiz":[{"question":"What did Nils see on the bowl fresh from the kiln?","options":["A foot that had already slumped","A crack that split the bowl in two","A photograph stuck to the rim","A ring of bare clay where the glaze had crawled"],"correctAnswer":"A ring of bare clay where the glaze had crawled","explanation":"The glaze had crawled, leaving a ring of bare clay.","supportingSentence":"Nils drew the bowl from the kiln and saw the glaze had crawled, leaving a ring of bare clay.","skill":"detail"},{"question":"What danger did the extra heat carry?","options":["It might slump the foot","It might cool the kiln at once","It might decorate the other pots","It might erase the clay itself"],"correctAnswer":"It might slump the foot","explanation":"He knew the extra heat might slump the foot.","supportingSentence":"He mixed a second coat and fired again, knowing extra heat might slump the foot.","skill":"detail"},{"question":"Why does the class treat the bowl as possibly finished?","options":["The kiln had no power left for another try","He had promised the class he would stop","Someone who missed the sketch could take the flaw as intentional","The foot had already collapsed"],"correctAnswer":"Someone who missed the sketch could take the flaw as intentional","explanation":"They say the flaw looked planned to anyone who had not seen the sketch.","supportingSentence":"Classmates told him to stop, because the flaw looked planned to anyone who had not seen the sketch.","skill":"inference"},{"question":"What does crawled describe in the kiln?","options":["The coating drew back and left clay showing","The bowl walked across the floor","The surface matched the sketch exactly","The oven cooled before it was lit"],"correctAnswer":"The coating drew back and left clay showing","explanation":"Crawled describes the glaze pulling back and leaving bare clay.","supportingSentence":"Nils drew the bowl from the kiln and saw the glaze had crawled, leaving a ring of bare clay.","skill":"vocabulary"},{"question":"Why save a picture of the flaw and still not treat it as the piece?","options":["To sell the picture in place of the bowl","To teach the class to copy the bare ring","To prove the second firing failed","To remember the temptation without letting it become the goal"],"correctAnswer":"To remember the temptation without letting it become the goal","explanation":"The photograph records the moment he nearly let a mistake set the standard, without becoming the work itself.","supportingSentence":"He kept a photograph of the flaw as a record of when he nearly let a mistake set the standard.","skill":"intent"}],"wordCount":101,"questionCount":5}$q35969$::jsonb,
  '910357ae00e56c09e2224db284e383062bc19760f6495fe579ee9f5c6790d842',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '9c330f8d-6a7c-4944-ac80-41c6b134c2f3'::uuid,
  'reading',
  'C1',
  'text',
  $q4882${"topic":"daily life","wordCount":151,"questionCount":5}$q4882$::jsonb,
  $q76319${"mode":"reading","level":"C1","format":"text","topic":"Daily Life","title":"The Spare Laundry Key","story":"The building rota stipulated a two-hour laundry window for each flat. When Lena's Thursday turn began, the drum was still turning and residual water had reached the corridor. She deferred calling the caretaker and pushed a measured note upstairs. Mateo, whose cycle had overrun, brought the spare key down the next evening and apologised for his late shift. He had started after midnight on the tacit assumption that the room would be empty until morning. Lena needed the machine before work, because the launderette shut too early for her. They rewrote the rota on the damp sheet. Mateo would keep Thursday but finish by nine, and Lena would take the Friday hour he rarely used. She insisted the spare key stay with the caretaker, so the next overrun could be stopped without formal recourse. The concession was tighter than either wanted, yet the floor stayed dry and the machine stayed shared.","dialogue":[],"vocabulary":[{"word":"stipulated","definition":"Set down as a requirement."},{"word":"residual","definition":"Left behind after the main thing has gone."},{"word":"deferred","definition":"Put off until later."},{"word":"tacit","definition":"Understood without being said aloud."},{"word":"recourse","definition":"A formal step you can take to get help."},{"word":"concession","definition":"Something given up so an agreement can be reached."}],"quiz":[{"question":"When must Mateo finish his Thursday wash under the new rota?","options":["By nine","On Sunday afternoon","Before dawn on Monday","At midnight"],"correctAnswer":"By nine","explanation":"The rewritten rota lets him keep Thursday only if he finishes by nine.","supportingSentence":"Mateo would keep Thursday but finish by nine, and Lena would take the Friday hour he rarely used.","skill":"detail"},{"question":"Where did Lena insist the spare key should stay?","options":["Inside the washing drum","At the launderette","In Mateo's coat","With the caretaker"],"correctAnswer":"With the caretaker","explanation":"She wanted the caretaker to hold the key so the next overrun could be stopped.","supportingSentence":"She insisted the spare key stay with the caretaker, so the next overrun could be stopped without formal recourse.","skill":"detail"},{"question":"What does the final arrangement show about Lena and Mateo?","options":["Both gave ground so the shared machine could keep working","Lena agreed to use only the launderette from then on","Mateo was banned from the laundry for a month","The caretaker replaced the machine that night"],"correctAnswer":"Both gave ground so the shared machine could keep working","explanation":"The concession was tighter than either wanted, but the machine stayed shared and the floor stayed dry.","supportingSentence":"The concession was tighter than either wanted, yet the floor stayed dry and the machine stayed shared.","skill":"inference"},{"question":"What does recourse mean in this passage?","options":["A spare key cut for one neighbour","A note written on a damp sheet","A formal step taken to get a problem put right","A two-hour turn on the washing machine"],"correctAnswer":"A formal step taken to get a problem put right","explanation":"Lena wants the key held by the caretaker so they need not turn to formal recourse.","supportingSentence":"She insisted the spare key stay with the caretaker, so the next overrun could be stopped without formal recourse.","skill":"vocabulary"},{"question":"Why does the writer mention the launderette?","options":["To prove that Mateo worked at that shop","To explain why the caretaker owned the building","To show Lena had no practical place to wash before work","To advertise a cheaper laundry across the square"],"correctAnswer":"To show Lena had no practical place to wash before work","explanation":"The launderette shut too early, which is why Lena needed the building machine before work.","supportingSentence":"Lena needed the machine before work, because the launderette shut too early for her.","skill":"intent"}],"wordCount":151,"questionCount":5}$q76319$::jsonb,
  '9c330f8d6a7c7944ec8041c6b134c2f38e66a734c16e638b8b907e1ac20ea34a',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '6f0de49a-983d-4d20-ad9b-2c0c8b0af5ab'::uuid,
  'reading',
  'C1',
  'text',
  $q5379${"topic":"school_college","wordCount":153,"questionCount":5}$q5379$::jsonb,
  $q96630${"mode":"reading","level":"C1","format":"text","topic":"School / College","title":"The Delayed Field Chapter","story":"Nadia brought her supervisor a chapter that lacked the March interviews. Professor Adeyemi refused to treat the missing voices as a small gap. Ethics approval had arrived late, and two participants had withdrawn after reading the consent form, leaving notes from only four of eight people. Nadia wanted to fill the space with published studies and keep the original date. Adeyemi said that substitution would change the chapter's claim, which had promised firsthand accounts of night-shift cleaners. A later deadline was possible if Nadia narrowed the group and stated the limit openly. They agreed the chapter would rest on the four completed interviews, plus a section explaining the absences. Nadia would send that section by Friday and the full chapter three weeks later. The extension was real, yet conditional on honesty about the reduced sample. A literature review could not disguise the absence of the people the project had set out to hear.","dialogue":[],"vocabulary":[{"word":"withdrawn","definition":"Taken back or pulled out of an agreement."},{"word":"substitution","definition":"Putting one thing in place of another."},{"word":"firsthand","definition":"Coming from direct experience, not from other books."},{"word":"narrowed","definition":"Made smaller in scope."},{"word":"conditional","definition":"Granted only if a stated condition is met."},{"word":"disguise","definition":"Hide the true nature of something."}],"quiz":[{"question":"How many completed interviews would the chapter rest on?","options":["Four completed interviews","Only studies already published","All eight people originally named","Notes kept by the ethics board"],"correctAnswer":"Four completed interviews","explanation":"They agreed the chapter would rest on the four completed interviews.","supportingSentence":"They agreed the chapter would rest on the four completed interviews, plus a section explaining the absences.","skill":"detail"},{"question":"When was the section about the absences due?","options":["Before any ethics approval","By Friday","Three weeks after the meeting","On the original March date"],"correctAnswer":"By Friday","explanation":"Nadia had to send the section explaining the absences by Friday, and the full chapter later.","supportingSentence":"Nadia would send that section by Friday and the full chapter three weeks later.","skill":"detail"},{"question":"Why were published studies a poor stand-in for the missing interviews?","options":["They would replace the direct accounts the chapter had promised","They were already printed in the consent form","They removed any need for ethics approval","They had been written by the night-shift cleaners"],"correctAnswer":"They would replace the direct accounts the chapter had promised","explanation":"Adeyemi said substitution would change a claim that had promised firsthand accounts.","supportingSentence":"Adeyemi said that substitution would change the chapter's claim, which had promised firsthand accounts of night-shift cleaners.","skill":"inference"},{"question":"What does conditional mean for this extension?","options":["Cancelled by the ethics board","Shorter than a single week","Issued with no supervisor involved","Granted only if a stated condition is met"],"correctAnswer":"Granted only if a stated condition is met","explanation":"The extension is real only if Nadia is honest about the smaller sample.","supportingSentence":"The extension was real, yet conditional on honesty about the reduced sample.","skill":"vocabulary"},{"question":"Why does the writer mention the participants who withdrew?","options":["To explain how the planned set of voices shrank","To show that Adeyemi interviewed the cleaners herself","To argue that night-shift work should be banned","To prove the consent form was never opened"],"correctAnswer":"To explain how the planned set of voices shrank","explanation":"Two withdrawals, after a late ethics approval, left Nadia with only four of eight people.","supportingSentence":"Ethics approval had arrived late, and two participants had withdrawn after reading the consent form, leaving notes from only four of eight people.","skill":"intent"}],"wordCount":153,"questionCount":5}$q96630$::jsonb,
  '6f0de49a983dcd202d9b2c0c8b0af5ab6e3942a2b810a8623d825ff5584ff254',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'ae438c4e-4866-4989-a563-0a4b79df76b9'::uuid,
  'reading',
  'C1',
  'text',
  $q4559${"topic":"travel","wordCount":153,"questionCount":5}$q4559$::jsonb,
  $q73685${"mode":"reading","level":"C1","format":"text","topic":"Travel","title":"A Seat above the Quay","story":"The noon bus passed Idris without stopping, because roadworks had removed any safe place for a request stop at Maren Quay. His ticket named a guesthouse that would hold his room only until dusk. The later driver's sheet already listed every seat as taken. A supervisor radioed ahead and learned that a passenger had relinquished one seat in the town before the headland. The seat was his only if he accepted a drop at the crossroads above the quay, not at the harbour gate, and then walked for twenty minutes. Idris accepted, because a refusal meant a night in the hut and a forfeited first night at the guesthouse. The driver validated the old ticket and annotated the new drop in the margin. He kept that ticket in case the guesthouse asked why he had arrived on foot and after dark. The compromise cost him a downhill walk, yet it preserved the booking.","dialogue":[],"vocabulary":[{"word":"relinquished","definition":"Given up so someone else could have it."},{"word":"forfeited","definition":"Lost because a condition was not met."},{"word":"validated","definition":"Officially accepted as still usable."},{"word":"annotated","definition":"Added a short written note to a document."},{"word":"margin","definition":"The blank edge of a page."},{"word":"compromise","definition":"An agreement in which each side gives something up."}],"quiz":[{"question":"Where did Idris agree to leave the later bus?","options":["At the crossroads above the quay","In the town before the headland","Inside the supervisor's hut","At the harbour gate"],"correctAnswer":"At the crossroads above the quay","explanation":"The only free seat required him to get off at the crossroads above the quay.","supportingSentence":"The seat was his only if he accepted a drop at the crossroads above the quay, not at the harbour gate, and then walked for twenty minutes.","skill":"detail"},{"question":"What did the driver write in the margin of the old ticket?","options":["A full cash refund","The guesthouse telephone number","A complaint about the roadworks","The new drop"],"correctAnswer":"The new drop","explanation":"The driver annotated the new drop in the margin after validating the ticket.","supportingSentence":"The driver validated the old ticket and annotated the new drop in the margin.","skill":"detail"},{"question":"Why could a late arrival put the room booking at risk?","options":["Paper tickets were wiped clean at noon","Walking on the quay was banned after sunset","The guesthouse had to hold the room only until dusk","The hut refused every guest who carried a case"],"correctAnswer":"The guesthouse had to hold the room only until dusk","explanation":"The ticket said the room would be held only until dusk, so a later arrival was unprotected.","supportingSentence":"His ticket named a guesthouse that would hold his room only until dusk.","skill":"inference"},{"question":"What does forfeited mean in this passage?","options":["Locked inside the hut until morning","Lost because a required condition was missed","Moved into a room beside the harbour","Paid for a second time by the driver"],"correctAnswer":"Lost because a required condition was missed","explanation":"Refusing the seat would have meant losing the first night at the guesthouse.","supportingSentence":"Idris accepted, because a refusal meant a night in the hut and a forfeited first night at the guesthouse.","skill":"vocabulary"},{"question":"Why does the writer mention the roadworks?","options":["To explain why the noon bus could not stop for him","To prove the guesthouse had moved inland","To show that Idris was repairing the road","To recommend a different coast for a holiday"],"correctAnswer":"To explain why the noon bus could not stop for him","explanation":"The roadworks had removed any safe place for the noon bus to stop.","supportingSentence":"The noon bus passed Idris without stopping, because roadworks had removed any safe place for a request stop at Maren Quay.","skill":"intent"}],"wordCount":153,"questionCount":5}$q73685$::jsonb,
  'ae438c4e4866c98935630a4b79df76b987e1a2579448e08298e361c70829e654',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'c81a411d-b894-4c9b-a9b1-a2578fc1b122'::uuid,
  'reading',
  'C1',
  'text',
  $q4559${"topic":"travel","wordCount":153,"questionCount":5}$q4559$::jsonb,
  $q82385${"mode":"reading","level":"C1","format":"text","topic":"Travel","title":"The Annex beyond the Courtyard","story":"The clerk apologised before Soraya gave her name. A wedding party had stayed on, and the booked room was still occupied, although her confirmation said otherwise. The only bed in the main house was a narrow cot beside the kitchen passage. The clerk offered instead a quiet annex beyond the courtyard, usually kept for staff, with its own lock. Breakfast there was later, and she would have to cross the courtyard. The annex was free that night as a remedy for the error, but the wedding would continue until eleven. Soraya asked if the annex key opened the side gate, because she meant to leave before the kitchen did. The key opened the gate. She accepted, with the stipulation that her own room be released the next afternoon and that the promise be written on the confirmation. A free plain room was acceptable. Losing the second night without a record was not acceptable.","dialogue":[],"vocabulary":[{"word":"occupied","definition":"Already being used by someone else."},{"word":"confirmation","definition":"A written message saying a booking is held."},{"word":"annex","definition":"A smaller building attached to a main one."},{"word":"courtyard","definition":"An open space enclosed by buildings."},{"word":"remedy","definition":"Something done to correct a mistake."},{"word":"stipulation","definition":"A condition that must be part of an agreement."}],"quiz":[{"question":"Why was the room Soraya had booked unavailable?","options":["A wedding party had not yet left it","The annex had been sold to the kitchen","She had come a full day early","The side-gate key was lost on the way"],"correctAnswer":"A wedding party had not yet left it","explanation":"A wedding party had stayed on, so the booked room was still occupied.","supportingSentence":"A wedding party had stayed on, and the booked room was still occupied, although her confirmation said otherwise.","skill":"detail"},{"question":"Until what time would the wedding continue?","options":["Until breakfast","Until eleven","Until the clerk went home","Until the next afternoon"],"correctAnswer":"Until eleven","explanation":"The clerk said the wedding would continue until eleven.","supportingSentence":"The annex was free that night as a remedy for the error, but the wedding would continue until eleven.","skill":"detail"},{"question":"What does Soraya treat as more important than a free night?","options":["A lock normally kept for the staff","An apology delivered before she gives her name","A written promise that her own room returns the next day","Breakfast served later beside the kitchen"],"correctAnswer":"A written promise that her own room returns the next day","explanation":"She accepts the free annex only with a written promise that her own room is released the next afternoon.","supportingSentence":"She accepted, with the stipulation that her own room be released the next afternoon and that the promise be written on the confirmation.","skill":"inference"},{"question":"What does remedy mean when the annex is offered free?","options":["An extra bill for the second night","A bus ticket back to the station","A narrow bed beside the kitchen passage","A way of making up for the booking mistake"],"correctAnswer":"A way of making up for the booking mistake","explanation":"The free night is offered as a remedy for the error over her room.","supportingSentence":"The annex was free that night as a remedy for the error, but the wedding would continue until eleven.","skill":"vocabulary"},{"question":"Why does the writer mention the narrow cot?","options":["To show the only main-house bed was a poor option","To prove Soraya preferred to sleep by the kitchen","To explain how the wedding meal was cooked","To show that staff were banned from every annex"],"correctAnswer":"To show the only main-house bed was a poor option","explanation":"The remaining bed in the main house is only a narrow cot beside the kitchen, which makes the annex the real offer.","supportingSentence":"The only bed in the main house was a narrow cot beside the kitchen passage.","skill":"intent"}],"wordCount":153,"questionCount":5}$q82385$::jsonb,
  'c81a411db894bc9b79b1a2578fc1b1225fc284795581b370c668eb92b59851ca',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '62f74514-b785-4c5c-a47b-5420bd6bcc64'::uuid,
  'reading',
  'C1',
  'text',
  $q4633${"topic":"hobbies","wordCount":140,"questionCount":5}$q4633$::jsonb,
  $q53800${"mode":"reading","level":"C1","format":"text","topic":"Hobbies","title":"Waiting for Fresh Fixer","story":"The darkroom allotted each member ninety minutes, and Sunday's sheet was full when Helen arrived with a river roll. The fixing tray was cloudy because the chemical was exhausted, and no fresh bottle remained. Rui said a delivery would come on Tuesday. Helen could use the weak fixer and risk stained prints, or she could wait. She waited, because the negatives were the sole record of a bridge scheduled for demolition. Rui let her reserve the first Sunday after the delivery and wrote her name in ink so the slot could not be quietly taken. He taught her a precaution: test a tray with a strip of film before trusting it with a real roll. A ruined roll could not be restored by enthusiasm. Helen left the canister on the hold shelf and went home with no prints at all.","dialogue":[],"vocabulary":[{"word":"allotted","definition":"Given out as each person's share."},{"word":"exhausted","definition":"Used up and no longer effective."},{"word":"demolition","definition":"The planned knocking-down of a structure."},{"word":"reserve","definition":"To keep a place for a particular person."},{"word":"precaution","definition":"A step taken in advance to avoid harm."},{"word":"restored","definition":"Brought back to its earlier good condition."}],"quiz":[{"question":"When did Rui expect the replacement chemical to arrive?","options":["That same Sunday","On Tuesday","Once Helen had made a print","After the bridge came down"],"correctAnswer":"On Tuesday","explanation":"Rui said the delivery would come on Tuesday.","supportingSentence":"Rui said a delivery would come on Tuesday.","skill":"detail"},{"question":"Where did Helen leave the canister before going home?","options":["On the hold shelf","In Rui's delivery bag","In the cloudy fixing tray","Beside the river"],"correctAnswer":"On the hold shelf","explanation":"She left the canister on the hold shelf and went home without prints.","supportingSentence":"Helen left the canister on the hold shelf and went home with no prints at all.","skill":"detail"},{"question":"What does Helen's choice to wait suggest about her priority?","options":["She expected the town to record the bridge","She wanted the finished prints to look stained","She had decided to give up photography","Protecting the only pictures of the bridge mattered more than speed"],"correctAnswer":"Protecting the only pictures of the bridge mattered more than speed","explanation":"She waited because those negatives were the only record of a bridge due for demolition.","supportingSentence":"She waited, because the negatives were the sole record of a bridge scheduled for demolition.","skill":"inference"},{"question":"What does exhausted mean when it describes the chemical?","options":["Held back for another member","Locked away in an office cupboard","Used up and no longer strong enough","Mixed fresh on that same morning"],"correctAnswer":"Used up and no longer strong enough","explanation":"The tray was cloudy because the chemical was exhausted and no fresh bottle remained.","supportingSentence":"The fixing tray was cloudy because the chemical was exhausted, and no fresh bottle remained.","skill":"vocabulary"},{"question":"Why does the writer include the test with a strip of film?","options":["To prove Helen had already spoiled three rolls","To show how to check a tray before risking a real roll","To argue that walking should replace printing","To explain why the darkroom was closing forever"],"correctAnswer":"To show how to check a tray before risking a real roll","explanation":"Rui's precaution is a test strip, so a weak tray can be caught before a real roll is ruined.","supportingSentence":"He taught her a precaution: test a tray with a strip of film before trusting it with a real roll.","skill":"intent"}],"wordCount":140,"questionCount":5}$q53800$::jsonb,
  '62f74514b7856c5c247b5420bd6bcc64d1092cc819f4ab9b944385476ee9b9ca',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'cdd4e343-0767-4926-aa0a-6d8fdc0b6f37'::uuid,
  'reading',
  'C1',
  'text',
  $q4638${"topic":"hobbies","wordCount":136,"questionCount":5}$q4638$::jsonb,
  $q68672${"mode":"reading","level":"C1","format":"text","topic":"Hobbies","title":"A Note on the Early Entry","story":"The piano recorder caught Sunday's trio, including the bar where Lewis entered early and pulled the others off the beat. Priya wanted the recording on the club website because visitors rarely heard the group. Lewis asked for a cut. A public file, he said, would present an inadvertent slip as if it were their standard. Priya replied that cutting the bar would damage the integrity of a live evening. Their compromise was precise. The journal would publish the recording with a note calling the bar an early entry, not a feature of the piece. Lewis would approve the wording first. In return, he would not demand a second take weeks later, when the room and the audience could not be reassembled. The recording stayed whole. The note stopped a mistake from being mistaken for an intention.","dialogue":[],"vocabulary":[{"word":"trio","definition":"A group of three musicians."},{"word":"inadvertent","definition":"Done by accident, not on purpose."},{"word":"integrity","definition":"The quality of staying whole and honest."},{"word":"compromise","definition":"A middle agreement between two proposals."},{"word":"wording","definition":"The exact words chosen for a note."},{"word":"reassembled","definition":"Brought back together again."}],"quiz":[{"question":"How would the journal's note describe the early bar?","options":["As a reason to shut the journal","As a studio take made the next week","As an early entry, not a feature of the piece","As a new solo written for the website"],"correctAnswer":"As an early entry, not a feature of the piece","explanation":"The note would call the bar an early entry, not a feature of the piece.","supportingSentence":"The journal would publish the recording with a note calling the bar an early entry, not a feature of the piece.","skill":"detail"},{"question":"What did Lewis agree not to demand?","options":["A written apology from Priya","Removal of the whole slow movement","A replacement piano for the club","A second take weeks later"],"correctAnswer":"A second take weeks later","explanation":"In return he would not demand a second take weeks later, when the room could not be reassembled.","supportingSentence":"In return, he would not demand a second take weeks later, when the room and the audience could not be reassembled.","skill":"detail"},{"question":"What might listeners assume if that note were left off?","options":["That Lewis had meant to enter at that point","That Priya had composed a different piece","That the Sunday concert had never happened","That the website would play a single bar"],"correctAnswer":"That Lewis had meant to enter at that point","explanation":"The note exists so a mistake is not mistaken for an intention.","supportingSentence":"The note stopped a mistake from being mistaken for an intention.","skill":"inference"},{"question":"What does integrity mean in Priya's reply?","options":["A faster speed for every movement","An honest and complete account of the live evening","The count of people who press play","A signed contract with the website"],"correctAnswer":"An honest and complete account of the live evening","explanation":"Cutting the bar would damage the integrity of a live evening by hiding what happened.","supportingSentence":"Priya replied that cutting the bar would damage the integrity of a live evening.","skill":"vocabulary"},{"question":"Why does the writer say visitors rarely heard the group?","options":["To explain why Priya wanted the recording made public","To argue that club journals should avoid music","To prove Lewis refused to perform for people","To show the hall had banned every listener"],"correctAnswer":"To explain why Priya wanted the recording made public","explanation":"Priya wanted the recording online because visitors rarely heard the group.","supportingSentence":"Priya wanted the recording on the club website because visitors rarely heard the group.","skill":"intent"}],"wordCount":136,"questionCount":5}$q68672$::jsonb,
  'cdd4e3430767d926ba0a6d8fdc0b6f37239bc58c2443f82151a7a5a55c810db9',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '40caa9f2-d53e-4bdc-a954-9211fc961dfa'::uuid,
  'reading',
  'C1',
  'text',
  $q5313${"topic":"health_sports","wordCount":153,"questionCount":5}$q5313$::jsonb,
  $q66723${"mode":"reading","level":"C1","format":"text","topic":"Health & Sports","title":"No Start from the Block","story":"Coach Rahman kept Leah in the slow lane after the six weeks the clinic had set. Her shoulder no longer woke her, and the catch that had ended her season was gone. She asked to rejoin the pace group on Thursday. Rahman refused, not because pain was obvious, but because the clinic note allowed endurance work and still prohibited racing starts. A start from the block would load the joint as the injury had. Leah said she felt ready and that the final was in a fortnight. Feeling ready, Rahman answered, was not the same as being cleared. He would add one length each session and review the note after two weeks. If the shoulder stayed quiet, he would ask the clinic to reconsider starts. Leah could still train, but she could not chase a place in the final. The limit frustrated her, and it kept a return from becoming a second injury.","dialogue":[],"vocabulary":[{"word":"endurance","definition":"The ability to keep working for a long time."},{"word":"prohibited","definition":"Officially not allowed."},{"word":"joint","definition":"The place where bones meet and move."},{"word":"cleared","definition":"Officially allowed to return to an activity."},{"word":"reconsider","definition":"To think about a decision again."},{"word":"frustrated","definition":"Upset because you are being held back."}],"quiz":[{"question":"What did the clinic note still prohibit?","options":["Any movement of the shoulder","Speaking with the coach","Every minute spent in the pool","Racing starts"],"correctAnswer":"Racing starts","explanation":"The note allowed endurance work and still prohibited racing starts.","supportingSentence":"Rahman refused, not because pain was obvious, but because the clinic note allowed endurance work and still prohibited racing starts.","skill":"detail"},{"question":"When would Rahman look at the clinic note again?","options":["After another six months","Only if Leah left the club","After two weeks","On the night of the final"],"correctAnswer":"After two weeks","explanation":"He would add one length each session and review the note after two weeks.","supportingSentence":"He would add one length each session and review the note after two weeks.","skill":"detail"},{"question":"Why does Rahman refuse to treat Leah's confidence as enough?","options":["The slow lane was closed for the whole month","Personal confidence is not the same as medical clearance","The club final had been moved to another city","Leah had refused to describe the original injury"],"correctAnswer":"Personal confidence is not the same as medical clearance","explanation":"Rahman says feeling ready is not the same as being cleared.","supportingSentence":"Feeling ready, Rahman answered, was not the same as being cleared.","skill":"inference"},{"question":"What does prohibited mean in the clinic note?","options":["Officially not allowed","Likely to happen by pure chance","Strongly advised for a quick recovery","Written only in the club accounts"],"correctAnswer":"Officially not allowed","explanation":"The note still prohibited racing starts, so those starts remained forbidden.","supportingSentence":"Rahman refused, not because pain was obvious, but because the clinic note allowed endurance work and still prohibited racing starts.","skill":"vocabulary"},{"question":"Why does the writer say the shoulder no longer woke Leah?","options":["To explain why the clinic cancelled the six-week plan","To show that Rahman examined her while she slept","To prove that training at night caused the injury","To show that continuing pain was not the reason for the refusal"],"correctAnswer":"To show that continuing pain was not the reason for the refusal","explanation":"The shoulder no longer wakes her, and Rahman refuses for a different reason than obvious pain.","supportingSentence":"Her shoulder no longer woke her, and the catch that had ended her season was gone.","skill":"intent"}],"wordCount":153,"questionCount":5}$q66723$::jsonb,
  '40caa9f2d53e5bdc49549211fc961dfae8eb0819740d23686547b5755144cacd',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '47ede976-a96b-4591-a181-65a1c2c3f9e3'::uuid,
  'reading',
  'C1',
  'text',
  $q5310${"topic":"health_sports","wordCount":141,"questionCount":5}$q5310$::jsonb,
  $q85939${"mode":"reading","level":"C1","format":"text","topic":"Health & Sports","title":"Heat Rules for the Road Club","story":"Heavy heat made Ibarra rewrite the road club's Sunday loop rather than cancel it. The full circuit would have kept riders on the exposed ridge at the hottest hour, with one water stop and no shade. Her revision cut the ridge, started an hour earlier, and added a second stop under the trees by the canal. Riders who needed a shorter day could turn back there without being marked absent. Anyone who felt dizzy, stopped sweating, or developed a headache had to tell a marshal and get off the bike. Jonah, training for a personal best, called the shorter route pointless. Ibarra replied that a personal best in those conditions would measure recklessness, not fitness. Times could wait for a cooler weekend. The amended ride still put people on the road, and it refused to treat heat as a minor detail.","dialogue":[],"vocabulary":[{"word":"exposed","definition":"Open to the weather, with little shelter."},{"word":"revision","definition":"A changed version of an earlier plan."},{"word":"dizzy","definition":"Feeling unsteady, as if about to fall."},{"word":"marshal","definition":"A person who watches safety during an event."},{"word":"recklessness","definition":"Lack of care about an obvious danger."},{"word":"amended","definition":"Changed in order to make it safer or better."}],"quiz":[{"question":"Where did the revised ride add its second stop?","options":["Under the trees by the canal","Inside the clubhouse after the ride","At the office that issued the forecast","On the exposed ridge at the hottest hour"],"correctAnswer":"Under the trees by the canal","explanation":"The revision added a second stop under the trees by the canal.","supportingSentence":"Her revision cut the ridge, started an hour earlier, and added a second stop under the trees by the canal.","skill":"detail"},{"question":"What must a rider do after developing a headache?","options":["Ride faster until the feeling passes","Stay silent so the group will not stop","Finish the ridge before taking a drink","Tell a marshal and get off the bike"],"correctAnswer":"Tell a marshal and get off the bike","explanation":"A headache meant the rider had to tell a marshal and get off the bike.","supportingSentence":"Anyone who felt dizzy, stopped sweating, or developed a headache had to tell a marshal and get off the bike.","skill":"detail"},{"question":"Why does a personal best that day fail to count as fitness for Ibarra?","options":["It would show dangerous risk-taking rather than fitness","Jonah was using a bike that was far too small","The canal stop had removed every uphill section","Fast times were written down only in winter"],"correctAnswer":"It would show dangerous risk-taking rather than fitness","explanation":"Ibarra says a personal best in that heat would measure recklessness, not fitness.","supportingSentence":"Ibarra replied that a personal best in those conditions would measure recklessness, not fitness.","skill":"inference"},{"question":"What does recklessness mean in Ibarra's reply?","options":["Careful practice spread across many months","The shaded part of the path by the canal","Ignoring a clear danger in order to continue","A written report filed by a marshal"],"correctAnswer":"Ignoring a clear danger in order to continue","explanation":"She uses recklessness for the choice to chase a fast time in dangerous heat.","supportingSentence":"Ibarra replied that a personal best in those conditions would measure recklessness, not fitness.","skill":"vocabulary"},{"question":"Why does the writer describe the original full circuit?","options":["To show why that plan was unsafe in heavy heat","To prove that the canal path had dried up","To explain why every Sunday ride was cancelled","To praise the ridge as the club's favourite view"],"correctAnswer":"To show why that plan was unsafe in heavy heat","explanation":"The original circuit kept riders on an exposed ridge at the hottest hour, with little water and no shade.","supportingSentence":"The full circuit would have kept riders on the exposed ridge at the hottest hour, with one water stop and no shade.","skill":"intent"}],"wordCount":141,"questionCount":5}$q85939$::jsonb,
  '47ede976a96b2591b18165a1c2c3f9e33516f2e2461e42381fd9da8f716162cf',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'fa5fa8df-a0c6-4b8b-ab95-45d120e5a88b'::uuid,
  'reading',
  'C1',
  'text',
  $q5199${"topic":"culture_food","wordCount":138,"questionCount":5}$q5199$::jsonb,
  $q27119${"mode":"reading","level":"C1","format":"text","topic":"Culture & Food","title":"The Card That Named the Nut","story":"The food fair required every stall to list allergens on a card. Nia had printed one for her pepper stew, then forgotten the walnut she had ground into the base. Her cousin tasted the sauce on Saturday and named the nut. Walnut had been omitted from the card. Dropping the pot would leave the stall bare, but serving the old card would break the rule and put a visitor at risk. Nia rewrote the card in large letters and moved the pot forward so the nut line was obvious. The steward noted the change and brought a printed symbol to fix beside the handwriting. Two customers thanked her and chose the rice dish instead. She kept the new card in place. A missed ingredient was a kitchen error, while hiding it would have been a breach of trust.","dialogue":[],"vocabulary":[{"word":"allergens","definition":"Substances that can cause a harmful reaction."},{"word":"omitted","definition":"Left out of something written."},{"word":"steward","definition":"A person who helps run an event."},{"word":"symbol","definition":"A simple sign that stands for a warning."},{"word":"ingredient","definition":"One item that goes into a dish."},{"word":"breach","definition":"A breaking of a rule or of trust."}],"quiz":[{"question":"Which ingredient had been left off the printed card?","options":["Rice","Walnut","Honey","Milk"],"correctAnswer":"Walnut","explanation":"Walnut had been omitted from the card after Nia forgot it was in the base.","supportingSentence":"Walnut had been omitted from the card.","skill":"detail"},{"question":"What did the steward fix beside the new handwriting?","options":["A printed symbol","A second pot with no nuts","A refund for every bowl","A ban on the rice dish"],"correctAnswer":"A printed symbol","explanation":"The steward brought a printed symbol to fix beside the handwriting.","supportingSentence":"The steward noted the change and brought a printed symbol to fix beside the handwriting.","skill":"detail"},{"question":"When would Nia's mistake become a breach of trust?","options":["If a cousin tasted the sauce before noon","If two customers chose the rice instead","If the allergen card was very small","If she served the stew while hiding the walnut"],"correctAnswer":"If she served the stew while hiding the walnut","explanation":"A missed ingredient is called a kitchen error, while hiding it would be a breach of trust.","supportingSentence":"A missed ingredient was a kitchen error, while hiding it would have been a breach of trust.","skill":"inference"},{"question":"What does omitted mean in this passage?","options":["Given away free to the steward","Written again in larger letters","Left out of the written list","Heated for a second time"],"correctAnswer":"Left out of the written list","explanation":"Walnut had been omitted from the card, meaning it was missing from the written list.","supportingSentence":"Walnut had been omitted from the card.","skill":"vocabulary"},{"question":"Why does the writer begin with the fair's card rule?","options":["To suggest the fair sold blank cards as food","To show that listing allergens was already required","To explain why her cousin was in charge","To prove Nia had never cooked a stew"],"correctAnswer":"To show that listing allergens was already required","explanation":"The opening rule shows every stall already had to list allergens, which is the standard Nia then meets.","supportingSentence":"The food fair required every stall to list allergens on a card.","skill":"intent"}],"wordCount":138,"questionCount":5}$q27119$::jsonb,
  'fa5fa8dfa0c67b8b5b9545d120e5a88bfcd52f269c1d35cc7191706aca7f2b82',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'e86e3559-3821-4128-acc3-4215376e2a9e'::uuid,
  'reading',
  'C1',
  'text',
  $q5195${"topic":"culture_food","wordCount":152,"questionCount":5}$q5195$::jsonb,
  $q88049${"mode":"reading","level":"C1","format":"text","topic":"Culture & Food","title":"A Glossary on the Seats","story":"Three local poets were reading at the harbour hall, and Imani's longest poem was in the dialect of the fishing families. Tomas, the organiser, feared inland visitors would find the evening difficult rather than welcoming. He asked her to drop that poem and read two shorter pieces in standard speech. Imani refused to treat the dialect as a barrier to be removed. She offered a glossary, a single sheet with each unusual word and a plain gloss beside it. Tomas feared the rustle of paper, but Imani said a confused silence would break the mood more surely. They placed the glossary on the seats beforehand, and she would pause only once, at the first unfamiliar word, to show how the sheet worked. The poem stayed. The sheet did not replace her speech with safer language. It gave listeners a way in without asking her to leave her own voice at the door.","dialogue":[],"vocabulary":[{"word":"dialect","definition":"A form of a language used by a particular community."},{"word":"barrier","definition":"Something that blocks understanding or entry."},{"word":"glossary","definition":"A list of difficult words with short explanations."},{"word":"gloss","definition":"A brief explanation written beside a word."},{"word":"rustle","definition":"A light dry sound, such as paper moving."},{"word":"unfamiliar","definition":"Not known or not recognised."}],"quiz":[{"question":"What change did Tomas first ask Imani to make?","options":["Allow only fishing families into the room","Give out the poem and not perform it","Drop the dialect poem for two shorter standard pieces","Cancel the reading at the harbour hall"],"correctAnswer":"Drop the dialect poem for two shorter standard pieces","explanation":"He asked her to drop that poem and read two shorter pieces in standard speech.","supportingSentence":"He asked her to drop that poem and read two shorter pieces in standard speech.","skill":"detail"},{"question":"Where was the glossary put for the audience?","options":["Sold at the door after the event","Sent to inland towns the next day","Read aloud instead of the poem","On the seats before the reading"],"correctAnswer":"On the seats before the reading","explanation":"They placed the glossary on the seats beforehand.","supportingSentence":"They placed the glossary on the seats beforehand, and she would pause only once, at the first unfamiliar word, to show how the sheet worked.","skill":"detail"},{"question":"Why is Imani less worried about rustling paper than Tomas is?","options":["Confused listeners would disturb the mood even more","The hall had forbidden every printed page","Tomas had never stayed for a live poem","The inland visitors had already gone home"],"correctAnswer":"Confused listeners would disturb the mood even more","explanation":"Imani says a confused silence would break the mood more surely than the rustle of paper.","supportingSentence":"Tomas feared the rustle of paper, but Imani said a confused silence would break the mood more surely.","skill":"inference"},{"question":"What does barrier mean when Imani speaks about the dialect?","options":["The price charged at the harbour door","Something that would block people from the poem","A prize given for the shortest poem","A solid wall set between the seats"],"correctAnswer":"Something that would block people from the poem","explanation":"She refuses to treat the dialect as a barrier, meaning something that would keep listeners out.","supportingSentence":"Imani refused to treat the dialect as a barrier to be removed.","skill":"vocabulary"},{"question":"What is the purpose of the final sentence?","options":["To admit that the glossary replaced the poem","To complain that the seats faced away from her","To show help was offered without silencing her voice","To announce that the reading had moved inland"],"correctAnswer":"To show help was offered without silencing her voice","explanation":"The ending says listeners get a way in without the poet having to leave her own voice at the door.","supportingSentence":"It gave listeners a way in without asking her to leave her own voice at the door.","skill":"intent"}],"wordCount":152,"questionCount":5}$q88049$::jsonb,
  'e86e355938219128fcc34215376e2a9e0cb18a5430dccf5bdbb7fb6a2503ddd6',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'cacdc039-89ab-4008-a9f7-6a91c4763f0e'::uuid,
  'reading',
  'C1',
  'text',
  $q4990${"topic":"technology","wordCount":136,"questionCount":5}$q4990$::jsonb,
  $q40593${"mode":"reading","level":"C1","format":"text","topic":"Technology","title":"Priority and the Wet Gutter","story":"On Saturday the tool-library app confirmed the same ladder for two different homes. Amira had booked it on Monday for a gutter before evening rain. Owen's morning booking, for a stairwell, was created by a glitch that ignored the earlier hold. Leila could see both records and the overlap. She rang Owen, explained the clash, and offered a step platform that suited his job. Amira kept the ladder, because priority belonged to the first hold. Owen accepted once he heard the platform was free and already in the store. Leila then rectified the rule so a confirmed hold could not be offered twice. She posted the corrected rule in the app that afternoon. A convenient error for Owen would have left Amira on a wet gutter. The principle was easy to state and costly to ignore.","dialogue":[],"vocabulary":[{"word":"glitch","definition":"A fault in a system that produces a wrong result."},{"word":"overlap","definition":"Two claims covering the same thing at once."},{"word":"clash","definition":"A conflict between two plans."},{"word":"priority","definition":"The right to come before someone else."},{"word":"rectified","definition":"Corrected so that it works properly."},{"word":"principle","definition":"A basic rule about what is fair."}],"quiz":[{"question":"Who was allowed to keep the ladder?","options":["Leila","The weather service","Amira","Owen"],"correctAnswer":"Amira","explanation":"Amira kept the ladder because priority belonged to the first hold.","supportingSentence":"Amira kept the ladder, because priority belonged to the first hold.","skill":"detail"},{"question":"What did Leila offer Owen for the stairwell?","options":["A payment in cash","A lift to the gutter","The tall ladder","A step platform"],"correctAnswer":"A step platform","explanation":"She offered him a step platform that suited his stairwell job.","supportingSentence":"She rang Owen, explained the clash, and offered a step platform that suited his job.","skill":"detail"},{"question":"What harm would have followed if Owen had kept the ladder?","options":["Amira would have been left on a wet gutter","Work in stairwells would have been banned","The app would have shut down in every town","Leila would have had to build new ladders"],"correctAnswer":"Amira would have been left on a wet gutter","explanation":"Giving Owen the ladder would have left Amira on a wet gutter before the evening rain.","supportingSentence":"A convenient error for Owen would have left Amira on a wet gutter.","skill":"inference"},{"question":"What does glitch mean in this account?","options":["A paper form signed by both neighbours","A fault in the app that created a wrong booking","A report of rain later that day","A ladder with one broken rung"],"correctAnswer":"A fault in the app that created a wrong booking","explanation":"Owen's booking was created by a glitch that ignored Amira's earlier hold.","supportingSentence":"Owen's morning booking, for a stairwell, was created by a glitch that ignored the earlier hold.","skill":"vocabulary"},{"question":"Why does the writer note that the platform was already in the store?","options":["To explain why the forecast rain never fell","To show that Amira was employed in the store","To show Owen could take a workable substitute at once","To prove the store had lacked ladders for years"],"correctAnswer":"To show Owen could take a workable substitute at once","explanation":"He accepts when he hears the platform is free and already in the store, so the alternative is immediate.","supportingSentence":"Owen accepted once he heard the platform was free and already in the store.","skill":"intent"}],"wordCount":136,"questionCount":5}$q40593$::jsonb,
  'cacdc03989ab400899f76a91c4763f0e4045c678ac5cab5433069710cb397258',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '5050c94d-f651-4e34-ab20-8bcec1b9461f'::uuid,
  'reading',
  'C1',
  'text',
  $q4993${"topic":"technology","wordCount":139,"questionCount":5}$q4993$::jsonb,
  $q57600${"mode":"reading","level":"C1","format":"text","topic":"Technology","title":"The Unread Appointment Text","story":"In May the clinic stopped printing appointment slips and sent text reminders instead. Most patients adapted without trouble. Okonkwo did not, because his handset stayed in a drawer and he still expected a card. He missed a blood-pressure review and learned of it only when a nurse rang to ask why the chair was empty. The system had marked the reminder delivered, which meant the network had received it, not that he had read it. Nurse Adewale recorded a contact problem rather than a failure to attend. She booked a fresh slot by telephone and had him write the time on a kitchen calendar. She added a file note: do not rely on text alone. A delivered message, for him, was not a message that had been seen. The file note stopped that difference from being mistaken for indifference.","dialogue":[],"vocabulary":[{"word":"adapted","definition":"Changed habits to fit a new system."},{"word":"handset","definition":"A telephone you can hold."},{"word":"delivered","definition":"Received by the network, whether or not it was read."},{"word":"review","definition":"A planned check of a health condition."},{"word":"rely","definition":"To depend on something."},{"word":"indifference","definition":"A lack of concern."}],"quiz":[{"question":"How did Okonkwo find out that he had missed the review?","options":["A printed slip arrived the next morning","A notice was pinned to his front door","His handset lit up inside the drawer","A nurse rang to ask about the empty chair"],"correctAnswer":"A nurse rang to ask about the empty chair","explanation":"He learned of the miss only when a nurse rang to ask why the chair was empty.","supportingSentence":"He missed a blood-pressure review and learned of it only when a nurse rang to ask why the chair was empty.","skill":"detail"},{"question":"What instruction did Adewale add to his file?","options":["Do not rely on text alone","Charge a fee for an empty chair","Stop all messages to every patient","Cancel every future health check"],"correctAnswer":"Do not rely on text alone","explanation":"She added a file note saying not to rely on text alone.","supportingSentence":"She added a file note: do not rely on text alone.","skill":"detail"},{"question":"What wrong conclusion did the file note prevent?","options":["That the nurse had removed his handset","That he missed the visit because he did not care","That the clinic had closed its doors in May","That printed slips had been made illegal"],"correctAnswer":"That he missed the visit because he did not care","explanation":"The note stops the gap between a sent text and a seen text from being mistaken for indifference.","supportingSentence":"The file note stopped that difference from being mistaken for indifference.","skill":"inference"},{"question":"What does delivered mean about the reminder in this passage?","options":["Printed on a card and posted","Read out loud by the patient","Accepted by the phone network","Copied by hand onto a calendar"],"correctAnswer":"Accepted by the phone network","explanation":"Marked delivered meant the network had received the reminder, not that Okonkwo had read it.","supportingSentence":"The system had marked the reminder delivered, which meant the network had received it, not that he had read it.","skill":"vocabulary"},{"question":"Why does the writer say that most patients adapted?","options":["To prove paper slips had never been used","To claim every patient stored a phone in a drawer","To blame Okonkwo for building the system","To show the new messages worked for many people"],"correctAnswer":"To show the new messages worked for many people","explanation":"Most patients adapted without trouble, so the failure is particular to Okonkwo rather than universal.","supportingSentence":"Most patients adapted without trouble.","skill":"intent"}],"wordCount":139,"questionCount":5}$q57600$::jsonb,
  '5050c94df6510e341b208bcec1b9461f1c833431094cb379a9bea5fa32c50825',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'ddd0cc59-12db-4e67-a625-3fe7d604c3ab'::uuid,
  'reading',
  'C1',
  'text',
  $q4639${"topic":"science","wordCount":139,"questionCount":5}$q4639$::jsonb,
  $q90077${"mode":"reading","level":"C1","format":"text","topic":"Science","title":"The Sample That Spoiled the Graph","story":"For a month the allotment trial gave steady nitrogen readings, until Thursday's sample from bed four came back far higher. Ivo wanted to drop it as contamination from a dirty tool. Sen told him not to discard a result merely because it spoiled a tidy graph. The bed stood by the compost gate, so a spill was possible, but possibility was not proof. The sampling notes said bed four had been taken last, with the same washed tool used on the earlier beds. They also recorded a manure pile against the fence that morning. The high reading could therefore be real. Ivo took a second sample and logged the pile. If the two results matched, the trial would treat bed four as genuinely richer, not as an error. Science, Sen said, begins by trying to disprove the convenient explanation.","dialogue":[],"vocabulary":[{"word":"nitrogen","definition":"A nutrient in soil that this trial measured."},{"word":"contamination","definition":"Unwanted material that spoils a result."},{"word":"discard","definition":"Throw out and ignore."},{"word":"sampling","definition":"Collecting material so it can be tested."},{"word":"genuinely","definition":"Truly, and not only in appearance."},{"word":"disprove","definition":"Show that an explanation is wrong."}],"quiz":[{"question":"What did the sampling notes say about the tool used on bed four?","options":["The tool had been left overnight in the compost","The tool was used for the first time on Friday","The tool belonged to a different laboratory","The same washed tool had been used on the earlier beds"],"correctAnswer":"The same washed tool had been used on the earlier beds","explanation":"The notes said bed four was taken last with the same washed tool used on the earlier beds.","supportingSentence":"The sampling notes said bed four had been taken last, with the same washed tool used on the earlier beds.","skill":"detail"},{"question":"What must the trial do if the second result matches the first?","options":["Treat bed four as truly richer soil","Blame the other beds for readings that are too low","Remove Thursday from the project entirely","Close the allotment for the rest of the season"],"correctAnswer":"Treat bed four as truly richer soil","explanation":"A match would mean the trial must treat bed four as genuinely richer, not as an error.","supportingSentence":"If the two results matched, the trial would treat bed four as genuinely richer, not as an error.","skill":"detail"},{"question":"Why does a possible spill fail to settle the high reading by itself?","options":["Sen had already published the Thursday figure","Bed four had been removed before Thursday","A possible cause is not the same thing as proof","Manure is unable to change any soil test"],"correctAnswer":"A possible cause is not the same thing as proof","explanation":"A spill beside the compost gate was possible, but the story says possibility was not proof.","supportingSentence":"The bed stood by the compost gate, so a spill was possible, but possibility was not proof.","skill":"inference"},{"question":"What does discard mean when Sen talks about the odd result?","options":["Throw it out and pay it no further attention","Copy it onto a second page of the log","Water the bed before taking the next test","Set it beside a chart of rainfall"],"correctAnswer":"Throw it out and pay it no further attention","explanation":"Sen tells Ivo not to discard the result, meaning not to throw it out, just because it spoils the graph.","supportingSentence":"Sen told him not to discard a result merely because it spoiled a tidy graph.","skill":"vocabulary"},{"question":"Why does the writer mention the manure pile?","options":["To prove Ivo spilled manure on the lab bench","To show that bed four no longer held any soil","To explain why an artist drew the graph","To show a real event that could explain the high reading"],"correctAnswer":"To show a real event that could explain the high reading","explanation":"The notes record manure against the fence that morning, which could make the high reading real.","supportingSentence":"They also recorded a manure pile against the fence that morning.","skill":"intent"}],"wordCount":139,"questionCount":5}$q90077$::jsonb,
  'ddd0cc5912dbee6746253fe7d604c3aba0af143daf669e71c23b0d849bdb270d',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '060c2372-038e-4e0a-ad28-1da44e8f0f73'::uuid,
  'reading',
  'C1',
  'text',
  $q4633${"topic":"science","wordCount":151,"questionCount":5}$q4633$::jsonb,
  $q73561${"mode":"reading","level":"C1","format":"text","topic":"Science","title":"Nets Down before the Squall","story":"The ringing team opened the nets at dawn, and the catch stayed steady until the wind turned. Hale felt the ropes thrum as a dark cloud crossed the marsh. Protocol said nets come down when wind could harm a bird or tangle a wing beyond a quick release. Esme wanted ten more minutes so the total would not sit below the figure she hoped to log. Hale refused. An impressive total was not a reason to stretch a rule written for the birds' sake. They closed the nets and released every bird already caught before the hard drops began. Esme then asked to estimate the birds the lost minutes might have brought. Hale said an estimate presented as a count would invent data. The log would record the closing time and the reason, and the morning would stand at the number actually handled. Incomplete, he told her, was an honest result.","dialogue":[],"vocabulary":[{"word":"thrum","definition":"Vibrate with a low continuous sound."},{"word":"protocol","definition":"An agreed set of rules for a procedure."},{"word":"tangle","definition":"Twist together so that freeing something is hard."},{"word":"estimate","definition":"A figure based on guesswork rather than a full count."},{"word":"invent","definition":"Make up something that was not observed."},{"word":"incomplete","definition":"Not whole, because something is missing."}],"quiz":[{"question":"When did the ringing team open the nets?","options":["At dawn","After the hard rain","On a night with no wind","At noon"],"correctAnswer":"At dawn","explanation":"The team opened the nets at dawn along the reed bed.","supportingSentence":"The ringing team opened the nets at dawn, and the catch stayed steady until the wind turned.","skill":"detail"},{"question":"What two facts would the log record about stopping early?","options":["A guessed total for the lost minutes","The figure Esme had hoped to reach","The name of every cloud over the marsh","The closing time and the reason"],"correctAnswer":"The closing time and the reason","explanation":"The log would record the closing time and the reason, and keep the number actually handled.","supportingSentence":"The log would record the closing time and the reason, and the morning would stand at the number actually handled.","skill":"detail"},{"question":"What does Hale treat as more important than a larger morning total?","options":["The welfare of the birds the rule was written to protect","Ringing extra birds once the heavy rain starts","Beating a team working on the next marsh","Letting Esme replace the written rules herself"],"correctAnswer":"The welfare of the birds the rule was written to protect","explanation":"An impressive total is not a reason to stretch a rule written for the birds' sake.","supportingSentence":"An impressive total was not a reason to stretch a rule written for the birds' sake.","skill":"inference"},{"question":"What does estimate mean when Esme talks about the lost minutes?","options":["A metal ring placed on a bird's leg","A dark cloud crossing the reed bed","A guessed number for birds they never handled","A rope that holds a net against the wind"],"correctAnswer":"A guessed number for birds they never handled","explanation":"She wants to estimate birds the lost minutes might have brought, which would be a guess rather than a count.","supportingSentence":"Esme then asked to estimate the birds the lost minutes might have brought.","skill":"vocabulary"},{"question":"Why does the writer mention the ropes beginning to thrum?","options":["To show the wind was rising enough to take seriously","To show that Esme had cut the ropes","To explain why the dawn catch had been empty","To prove the nets were built entirely of metal"],"correctAnswer":"To show the wind was rising enough to take seriously","explanation":"Hale feels the ropes thrum as cloud crosses the marsh, which signals the wind the protocol is about.","supportingSentence":"Hale felt the ropes thrum as a dark cloud crossed the marsh.","skill":"intent"}],"wordCount":151,"questionCount":5}$q73561$::jsonb,
  '060c2372038e7e0a4d281da44e8f0f73d9a765ab8633fd10d8386fccb8748668',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'd50acf51-4d6e-47f4-a0ad-a66ce9c9f320'::uuid,
  'reading',
  'C1',
  'text',
  $q5489${"topic":"economy_finance","wordCount":138,"questionCount":5}$q5489$::jsonb,
  $q50728${"mode":"reading","level":"C1","format":"text","topic":"Economy / Finance","title":"A Waiver with a Date","story":"Lila's invoice for the menu drawings had sat unpaid for six weeks. The contract allowed a late fee after thirty days, as a small share of the balance, and it allowed her to pause new work. Farid wrote that a kitchen refit had emptied the week's takings and asked for time. Lila still wanted the autumn menu, so she did not add the fee. She set the balance due within ten days, warned that the fee would follow if that date slipped, and refused to start the autumn drawings until the invoice was cleared. The waiver was limited and written down. His letter explained the gap, but it did not erase the debt. Farid paid on the ninth day. Lila kept the exchange, because a friendly concession without a date would have been difficult to rely on later.","dialogue":[],"vocabulary":[{"word":"invoice","definition":"A bill that asks to be paid for work done."},{"word":"balance","definition":"The amount of money still owed."},{"word":"takings","definition":"Money received from customers."},{"word":"cleared","definition":"Fully paid, so nothing remains owed."},{"word":"waiver","definition":"A choice not to use a right the contract allows."},{"word":"concession","definition":"Something you give up to help reach an agreement."}],"quiz":[{"question":"How soon did Lila require the unpaid balance to be paid?","options":["Within ten days","When the autumn menu was printed","After another six weeks","When the kitchen refit ended"],"correctAnswer":"Within ten days","explanation":"She set the balance due within ten days.","supportingSentence":"She set the balance due within ten days, warned that the fee would follow if that date slipped, and refused to start the autumn drawings until the invoice was cleared.","skill":"detail"},{"question":"When did Farid actually pay the invoice?","options":["On the day the bill was first written","On the ninth day","After the autumn drawings were delivered","Six weeks after the new deadline"],"correctAnswer":"On the ninth day","explanation":"Farid paid on the ninth day.","supportingSentence":"Farid paid on the ninth day.","skill":"detail"},{"question":"Why does Lila keep the written exchange?","options":["The late fee could be settled only in coins","The kitchen refit had ended the contract","An undated kindness would be hard to depend on later","Farid had asked her to draw a second cafe"],"correctAnswer":"An undated kindness would be hard to depend on later","explanation":"She keeps the exchange because a friendly concession without a date would be difficult to rely on later.","supportingSentence":"Lila kept the exchange, because a friendly concession without a date would have been difficult to rely on later.","skill":"inference"},{"question":"What does waiver mean in this passage?","options":["A drawing of the dishes on the menu","Money that arrived on the ninth day","A new kitchen finished before autumn","A choice not to apply a fee the contract allowed"],"correctAnswer":"A choice not to apply a fee the contract allowed","explanation":"The contract allowed a late fee, and her decision not to add it is the limited waiver she wrote down.","supportingSentence":"The waiver was limited and written down.","skill":"vocabulary"},{"question":"Why does the writer mention the kitchen refit?","options":["To give Farid's reason for needing more time","To prove the menu drawings were never delivered","To show that Lila designed the new kitchen","To argue that cafes should stop serving food"],"correctAnswer":"To give Farid's reason for needing more time","explanation":"Farid writes that the refit emptied the week's takings, which is why he asks for time.","supportingSentence":"Farid wrote that a kitchen refit had emptied the week's takings and asked for time.","skill":"intent"}],"wordCount":138,"questionCount":5}$q50728$::jsonb,
  'd50acf514d6e67f460ada66ce9c9f320e306fa3f1bdd94926f04fd523e8e2823',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  'c64e369b-140d-44ed-a87f-14f0e6960c2d'::uuid,
  'reading',
  'C1',
  'text',
  $q5489${"topic":"economy_finance","wordCount":147,"questionCount":5}$q5489$::jsonb,
  $q87091${"mode":"reading","level":"C1","format":"text","topic":"Economy / Finance","title":"The Weight Promised on the Board","story":"A spring notice said each bowl of stew would contain the stated weight, and that the price would be printed on the board. When the supplier raised the cost of lamb, Hannah wanted to keep the price and shrink the portion. Malik, the treasurer, said a lighter bowl at the old price would breach the notice. A higher price would be unpopular, but it would keep the promise. A cheaper cut would also need a new line, because the notice named lamb and not a substitute. Hannah said regulars cared about a full bowl, not wording. Malik answered that regulars were exactly the people who would compare this week with last week. The committee raised the price, left the weight unchanged, and rewrote the board before service. The notice had looked like a small formality. It was the rule that stopped a quiet change in the bowl.","dialogue":[],"vocabulary":[{"word":"supplier","definition":"A business that sells goods to the stall."},{"word":"portion","definition":"The amount of food served to one person."},{"word":"breach","definition":"Break a rule or a posted promise."},{"word":"substitute","definition":"Something used in place of another thing."},{"word":"unchanged","definition":"Left the same, not altered."},{"word":"formality","definition":"A rule that looks like mere paperwork."}],"quiz":[{"question":"What did the committee change before service?","options":["The meat, from lamb to a cheaper cut","The price, while the weight stayed the same","The treasurer, who was replaced that morning","The notice, so a lighter bowl became allowed"],"correctAnswer":"The price, while the weight stayed the same","explanation":"The committee raised the price, left the weight unchanged, and rewrote the board.","supportingSentence":"The committee raised the price, left the weight unchanged, and rewrote the board before service.","skill":"detail"},{"question":"What did the spring notice promise about each bowl?","options":["A stated weight and a printed price","A free second helping for regular customers","Stew served only to members of the committee","A lower price whenever the supplier charged more"],"correctAnswer":"A stated weight and a printed price","explanation":"The notice said each bowl would contain the stated weight and that the price would be printed on the board.","supportingSentence":"A spring notice said each bowl of stew would contain the stated weight, and that the price would be printed on the board.","skill":"detail"},{"question":"Why does Malik expect regular customers to notice a lighter bowl?","options":["A cheaper cut tastes the same as lamb","A treasurer can cancel a notice by speaking","A busy crowd makes every notice optional","They compare one week with the week before"],"correctAnswer":"They compare one week with the week before","explanation":"Malik says regulars are exactly the people who would compare this week with last week.","supportingSentence":"Malik answered that regulars were exactly the people who would compare this week with last week.","skill":"inference"},{"question":"What does breach mean when Malik talks about the notice?","options":["Push the supplier's bill higher on purpose","Serve stew only to the committee","Break the promise that was posted","Paint a fresh board for the stall"],"correctAnswer":"Break the promise that was posted","explanation":"A lighter bowl at the old price would breach the notice, meaning it would break that posted promise.","supportingSentence":"Malik, the treasurer, said a lighter bowl at the old price would breach the notice.","skill":"vocabulary"},{"question":"What is the purpose of the final sentence?","options":["To announce that the stall closed before service","To claim that lamb had become the cheapest meat","To show the notice stopped a quiet change in the bowl","To admit the committee ignored the stated weight"],"correctAnswer":"To show the notice stopped a quiet change in the bowl","explanation":"The final sentence says the notice was the rule that stopped a quiet change in the bowl.","supportingSentence":"It was the rule that stopped a quiet change in the bowl.","skill":"intent"}],"wordCount":147,"questionCount":5}$q87091$::jsonb,
  'c64e369b140da4ed787f14f0e6960c2d53831ded0c4e61f5b9327a5bda63a48b',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '1df79871-e72d-41e6-ab5e-fc536def0a78'::uuid,
  'reading',
  'C1',
  'text',
  $q4700${"topic":"mystery","wordCount":142,"questionCount":5}$q4700$::jsonb,
  $q55903${"mode":"reading","level":"C1","format":"text","topic":"Mystery","title":"The Score inside the Bench","story":"The rehearsal score was on the piano at nine and missing when the quartet returned from tea. The log said the room had stayed locked, and the clerk said the spare key had not moved. Searches of folders, pockets, and the cabinet found nothing. Keisha stayed to shut the windows and heard paper shift when she moved the bench. The score was inside the locked bench. It was rolled rather than folded as she had left it. A locked room and a locked bench implied someone with a key, yet the clerk's account named nobody. Keisha did not accuse anyone. She photographed the roll, put the score back on the stand, and asked the clerk to sign a note of the time and of the locked seat. Everyone in the quartet needed the music, so need alone could not name a culprit.","dialogue":[],"vocabulary":[{"word":"rehearsal","definition":"A practice session before a performance."},{"word":"quartet","definition":"A group of four musicians."},{"word":"implied","definition":"Suggested a conclusion without stating it outright."},{"word":"accuse","definition":"Say that a particular person did wrong."},{"word":"photographed","definition":"Made a picture of something as a record."},{"word":"culprit","definition":"The person who did the hidden act."}],"quiz":[{"question":"Where did Keisha find the missing score?","options":["In a folder on top of the cabinet","Inside the locked bench","In the clerk's coat","On the table where they had tea"],"correctAnswer":"Inside the locked bench","explanation":"The score was inside the locked bench.","supportingSentence":"The score was inside the locked bench.","skill":"detail"},{"question":"What did Keisha ask the clerk to sign?","options":["A new score for the following concert","A statement that he had taken the spare key","A note of the time and of the locked seat","A receipt for the tea break"],"correctAnswer":"A note of the time and of the locked seat","explanation":"She asked the clerk to sign a note of the time and of the locked seat.","supportingSentence":"She photographed the roll, put the score back on the stand, and asked the clerk to sign a note of the time and of the locked seat.","skill":"detail"},{"question":"What does the change from folded to rolled suggest?","options":["The paper had been bought earlier that morning","A draught had unlocked the piano bench","The quartet had never played from written music","Someone handled the score after Keisha left it"],"correctAnswer":"Someone handled the score after Keisha left it","explanation":"It was rolled rather than folded as she had left it, so the paper had been handled.","supportingSentence":"It was rolled rather than folded as she had left it.","skill":"inference"},{"question":"What does implied mean in the account of the locked bench?","options":["Pointed toward a conclusion without naming a person","Belonged to the clerk who kept the office","Made a sound when the seat was moved","Opened by itself once the tea was over"],"correctAnswer":"Pointed toward a conclusion without naming a person","explanation":"The locks implied someone with a key, while the clerk's account named nobody.","supportingSentence":"A locked room and a locked bench implied someone with a key, yet the clerk's account named nobody.","skill":"vocabulary"},{"question":"Why does the writer say that everyone in the quartet needed the music?","options":["To explain why the tea break lasted all night","To show that need alone cannot identify who hid it","To prove the clerk performed with the quartet","To show the score had no value as music"],"correctAnswer":"To show that need alone cannot identify who hid it","explanation":"Everyone needed the music, so need alone could not name a culprit.","supportingSentence":"Everyone in the quartet needed the music, so need alone could not name a culprit.","skill":"intent"}],"wordCount":142,"questionCount":5}$q55903$::jsonb,
  '1df79871e72db1e63b5efc536def0a78f1cab99bb1e7ed747b26778229700f49',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '3d1cbe4b-71cf-4d36-acaf-14934d20e524'::uuid,
  'reading',
  'C1',
  'text',
  $q4701${"topic":"mystery","wordCount":152,"questionCount":5}$q4701$::jsonb,
  $q62714${"mode":"reading","level":"C1","format":"text","topic":"Mystery","title":"A Loop in the Hostel Log","story":"The hostel log said the guest in bed four had signed out at ten, yet his grey coat still hung beneath the stairs. Amina remembered a quiet man who had asked about the early bus and carried no bag. His signature matched the line above it, including a strange loop the earlier guest, a courier, used on every parcel slip. Someone had copied that signature into the next space, so the book looked complete while a person remained unaccounted for. Amina did not raise an alarm in the corridor. She locked the front door, woke the manager, and checked the room. The bed was empty, the window latch was open, and a timetable on the blanket had the dawn departure circled. A forgotten coat could be explained. A copied signature could not be dismissed as a mistake. The tidy line had turned a departure into a record somebody wanted to look finished.","dialogue":[],"vocabulary":[{"word":"signature","definition":"A person's name written in their own hand."},{"word":"courier","definition":"A person whose work is delivering parcels."},{"word":"unaccounted","definition":"Not explained by the existing record."},{"word":"latch","definition":"A fastening that keeps a window or door shut."},{"word":"circled","definition":"Marked by drawing a circle around it."},{"word":"record","definition":"An official written account of what happened."}],"quiz":[{"question":"What belonging was still beneath the stairs?","options":["A parcel slip","The marked bus timetable","His grey coat","The key to the front door"],"correctAnswer":"His grey coat","explanation":"His grey coat still hung beneath the stairs even though the log said he had signed out.","supportingSentence":"The hostel log said the guest in bed four had signed out at ten, yet his grey coat still hung beneath the stairs.","skill":"detail"},{"question":"What time was circled on the timetable in the room?","options":["The dawn departure","The clerk's midday break","A train at noon","The courier's delivery hour"],"correctAnswer":"The dawn departure","explanation":"The timetable on the blanket had the dawn departure circled.","supportingSentence":"The bed was empty, the window latch was open, and a timetable on the blanket had the dawn departure circled.","skill":"detail"},{"question":"What was wrong with the log even though it looked finished?","options":["Amina had written every line that morning","Bed four had been unused for a month","The courier had bought the whole hostel","A person was still left unexplained"],"correctAnswer":"A person was still left unexplained","explanation":"The copied signature made the book look complete while a person remained unaccounted for.","supportingSentence":"Someone had copied that signature into the next space, so the book looked complete while a person remained unaccounted for.","skill":"inference"},{"question":"What does courier mean in this passage?","options":["The guest who left a grey coat","A bus that leaves at dawn","A person who delivers parcels","The manager on duty at night"],"correctAnswer":"A person who delivers parcels","explanation":"The earlier guest is a courier who used that strange loop on every parcel slip.","supportingSentence":"His signature matched the line above it, including a strange loop the earlier guest, a courier, used on every parcel slip.","skill":"vocabulary"},{"question":"Why does the writer say Amina did not raise an alarm in the corridor?","options":["To prove the hostel had no guests that night","To show she began with a quiet, controlled check","To explain why the grey coat had been sold","To show the manager was already out in the street"],"correctAnswer":"To show she began with a quiet, controlled check","explanation":"She does not raise an alarm, and instead locks the door, wakes the manager, and checks the room.","supportingSentence":"Amina did not raise an alarm in the corridor.","skill":"intent"}],"wordCount":152,"questionCount":5}$q62714$::jsonb,
  '3d1cbe4b71cf6d367caf14934d20e5245a3e042380f9235ce917e04fea29648e',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '5d065e89-012d-45ce-aba3-ee215b591655'::uuid,
  'reading',
  'C1',
  'text',
  $q4877${"topic":"adventure","wordCount":151,"questionCount":5}$q4877$::jsonb,
  $q64509${"mode":"reading","level":"C1","format":"text","topic":"Adventure","title":"Daylight on the Longer Ridge","story":"A rockfall had closed the marked canyon path, and the group reached the barrier tape while dust still hung in the air. The ranger post was two hours back, and the radio had no signal between the walls. Cloud was filling the upper cleft, and a night on the canyon floor would mean cold rock and no water beyond what they carried. Sera proposed the old ridge, longer and exposed, but still in daylight if they left at once. It rejoined the marked route above the fall. She had last used that cairn the previous spring. Two people wanted to wait for a ranger. Sera pointed out that nobody knew they had chosen the canyon, so no rescue was already coming. They took the ridge and reached the cairn while the slope below was still visible. The choice added wind and distance. It also kept them out of a darkening canyon.","dialogue":[],"vocabulary":[{"word":"rockfall","definition":"A collapse of rock onto a path."},{"word":"barrier","definition":"Something placed so people cannot pass."},{"word":"cleft","definition":"A narrow opening or crack in the rock."},{"word":"exposed","definition":"Open to wind and weather, with little shelter."},{"word":"rejoined","definition":"Met up with a route again."},{"word":"cairn","definition":"A small pile of stones used as a marker."}],"quiz":[{"question":"Where did the old ridge meet the marked route again?","options":["At the ranger post","Back at the barrier tape","Above the fall","On the canyon floor after dark"],"correctAnswer":"Above the fall","explanation":"The ridge rejoined the marked route above the fall.","supportingSentence":"It rejoined the marked route above the fall.","skill":"detail"},{"question":"Why was a rescue not already coming to meet them?","options":["No rescuer had been told they chose the canyon","The ranger post was closed for the whole year","The radio was already speaking with a rescue team","The falling rock had burned their only map"],"correctAnswer":"No rescuer had been told they chose the canyon","explanation":"Sera says nobody knew they had chosen the canyon, so no rescue was already coming.","supportingSentence":"Sera pointed out that nobody knew they had chosen the canyon, so no rescue was already coming.","skill":"detail"},{"question":"Why does waiting for a ranger carry a danger of its own?","options":["Sera had never walked during daylight","The barrier tape led directly up to the cairn","The ridge path was shorter than the canyon route","Night in the canyon would be cold and short of water"],"correctAnswer":"Night in the canyon would be cold and short of water","explanation":"A night on the canyon floor would mean cold rock and no water beyond what they carried.","supportingSentence":"Cloud was filling the upper cleft, and a night on the canyon floor would mean cold rock and no water beyond what they carried.","skill":"inference"},{"question":"What does exposed mean in the description of the ridge?","options":["Open to the weather, with little shelter","Hidden under the floor of the canyon","Kept only for rangers who carry radios","Closed by rocks that had just fallen"],"correctAnswer":"Open to the weather, with little shelter","explanation":"Sera calls the ridge longer and exposed, meaning open to the weather.","supportingSentence":"Sera proposed the old ridge, longer and exposed, but still in daylight if they left at once.","skill":"vocabulary"},{"question":"Why does the writer mention the previous spring?","options":["To explain why the canyon was shut the year before","To show a ranger shifted the tape in spring","To show Sera had already used that cairn","To prove the group had camped there all winter"],"correctAnswer":"To show Sera had already used that cairn","explanation":"She had last used that cairn the previous spring, so the meeting point is known to her.","supportingSentence":"She had last used that cairn the previous spring.","skill":"intent"}],"wordCount":151,"questionCount":5}$q64509$::jsonb,
  '5d065e89012d65ceaba3ee215b591655a91ad58a18a083bd3c2b3aebac5107af',
  true
) on conflict (content_hash) do nothing;

insert into public.exercise_bank (
  id, kind, level, exercise_type, dimensions, payload, content_hash, active
) values (
  '7811bdb7-ed30-46a3-a8bd-99ba85288e0a'::uuid,
  'reading',
  'C1',
  'text',
  $q4668${"topic":"fantasy","wordCount":149,"questionCount":5}$q4668$::jsonb,
  $q81017${"mode":"reading","level":"C1","format":"text","topic":"Fantasy","title":"The Name That Held at Dusk","story":"In Velin a borrowed name stayed on a doorplate only while its promise was kept. At dusk the letters loosened, and by full dark an unmet name fell off and returned to the drawer as loose type. Mara had borrowed a river pilot's name for one crossing and had agreed to bring the ferry log back before sunset. The tide made her late, and three letters were already gone from the pilot's door. Clerk Osian would not hammer them back. A name restored after dark, he said, stuck crooked and brought the wrong memories into the house. Mara set the log on the counter before the last letter fell. Osian pressed the type into the plate while the day's ink was still receptive. The name held. A minute later it would have spent the night in the drawer, and the river would have had nobody to answer to it.","dialogue":[],"vocabulary":[{"word":"doorplate","definition":"A small nameplate fixed to a door."},{"word":"loosened","definition":"Became loose and ready to fall away."},{"word":"type","definition":"A metal letter used to print a word."},{"word":"restored","definition":"Put back into its earlier place."},{"word":"crooked","definition":"Bent or sitting unevenly, not straight."},{"word":"receptive","definition":"Ready to take something in."}],"quiz":[{"question":"What had Mara agreed to bring back with the borrowed name?","options":["A new door for the clerk's house","Three loose letters from another town","A tide chart after full dark","The ferry log before sunset"],"correctAnswer":"The ferry log before sunset","explanation":"She had agreed to bring the ferry log back before sunset.","supportingSentence":"Mara had borrowed a river pilot's name for one crossing and had agreed to bring the ferry log back before sunset.","skill":"detail"},{"question":"What did Osian do to the plate once the log arrived in time?","options":["He pressed the type back into the plate","He gave the pilot's door a different name","He locked the drawer until winter","He sent Mara across the river again"],"correctAnswer":"He pressed the type back into the plate","explanation":"Osian pressed the type into the plate while the day's ink was still receptive.","supportingSentence":"Osian pressed the type into the plate while the day's ink was still receptive.","skill":"detail"},{"question":"What would a delay of one more minute have meant?","options":["The tide would have given the town a new name","The pilot's name would have spent the night in the drawer","The ferry itself would have turned into loose type","Osian would have kept the pilot's name for himself"],"correctAnswer":"The pilot's name would have spent the night in the drawer","explanation":"A minute later the name would have spent the night in the drawer, with nobody to answer to it.","supportingSentence":"A minute later it would have spent the night in the drawer, and the river would have had nobody to answer to it.","skill":"inference"},{"question":"What does crooked mean for a name put back after dark?","options":["Paid for with a second ferry log","Spoken aloud by the river pilot","Fixed unevenly, not sitting straight","Brighter than it had been at noon"],"correctAnswer":"Fixed unevenly, not sitting straight","explanation":"Osian says a name restored after dark stuck crooked, meaning it would sit unevenly.","supportingSentence":"A name restored after dark, he said, stuck crooked and brought the wrong memories into the house.","skill":"vocabulary"},{"question":"Why does the writer mention wrong memories in the house?","options":["To show that Mara had forgotten the way to the river","To prove the clerk sold other people's memories","To explain why the ferry log had no writing","To explain the harm of forcing a name back after dark"],"correctAnswer":"To explain the harm of forcing a name back after dark","explanation":"A name restored after dark would stick crooked and bring the wrong memories into the house, which is why Osian will not force it.","supportingSentence":"A name restored after dark, he said, stuck crooked and brought the wrong memories into the house.","skill":"intent"}],"wordCount":149,"questionCount":5}$q81017$::jsonb,
  '7811bdb7ed3056a388bd99ba85288e0a97aeb113bed9d2c32c43678a5d87a8c2',
  true
) on conflict (content_hash) do nothing;

